INSERT INTO `brands` (`id`, `name`, `slug`, `logo_path`, `website_url`, `desc`, `category`, `landing_config`, `image`, `thumbnail`, `is_featured`, `created_at`, `updated_at`) VALUES
(1, 'Logitech', 'logi', NULL, 'https://www.logitech.com', 'Logitech adalah brand global penyedia solusi video conferencing, audio, dan perangkat kolaborasi profesional untuk ruang meeting modern.', 'Video Conferencing', '{\"hero\":{\"enabled\":true,\"eyebrow\":\"Elite Partner Indonesia\",\"title\":\"Authorized Logitech Elite Partner\",\"subtitle\":\"Conference Camera & Video Collaboration Solutions\",\"desc\":\"ACTiV sebagai Logitech Elite Partner Indonesia menyediakan solusi Logitech untuk ruang meeting, hybrid workspace, dan kolaborasi digital.\",\"cta_label\":\"Kontak Sales\",\"cta_url\":\"https:\\/\\/api.whatsapp.com\\/send?phone=6285162994602&text=Halo%20ACTiV,%20saya%20ingin%20konsultasi%20solusi%20Logitech%20untuk%20meeting%20room\",\"cta_whatsapp\":null,\"cta_whatsapp_message\":null,\"background_image\":\"brands\\/logi\\/hero\\/logi-hero-rally-ai-camera-pro-key-feature-easy-to-manage-activ-teknologi-2026-0108.webp\"},\"solutions\":{\"enabled\":true,\"title\":\"Logitech Solution\"},\"categories\":{\"enabled\":true,\"title\":null},\"showcase\":{\"enabled\":false,\"title\":null,\"items\":[]},\"products\":{\"enabled\":true,\"title\":null,\"count\":null},\"partner\":{\"enabled\":true,\"modal_title\":\"Logitech Elite Partner\",\"modal_subtitle\":\"ACTiV is an official Logitech Elite Partner in Indonesia\",\"modal_description\":\"<p>ACTiV is an official Logitech Elite Partner in Indonesia and recipient of the Logitech Partner Connect Program 2024 awards, including:<\\/p><ul><li><p><strong>Elite Partner Level<\\/strong><\\/p><\\/li><li><p><strong>Partner of the Year<\\/strong><\\/p><\\/li><li><p><strong>Marketing Excellence Award<\\/strong><\\/p><\\/li><\\/ul>\",\"guarantees\":[\"Original products with official warranty\",\"Competitive corporate pricing\"]},\"awards\":[]}', 'brands/logi/logitech.svg', NULL, 1, '2026-01-21 19:54:32', '2026-02-22 20:04:51'),
(2, 'Zoom', 'zoom', NULL, 'https://zoom.us', 'Zoom adalah platform video conference dan kolaborasi berbasis cloud yang mendukung meeting, webinar, dan komunikasi hybrid.', 'Cloud Meeting', '{\"hero\":{\"enabled\":true,\"eyebrow\":\"Authorized Zoom Gold Partner\",\"title\":\"AI-Powered Work Platform\",\"subtitle\":\"Your AI companion at work\",\"desc\":\"PT Alfa Cipta Teknologi Virtual merupakan Authorized Partner resmi Zoom di Indonesia yang menyediakan layanan penjualan, implementasi, serta dukungan teknis lokal. Selain melayani kebutuhan enterprise, ACTiV juga berkomitmen mengembangkan sektor pendidikan melalui solusi Zoom untuk pembelajaran jarak jauh dan kolaborasi digital.\",\"cta_label\":\"Kontak Sales\",\"cta_url\":\"https:\\/\\/api.whatsapp.com\\/send?phone=6285162994602&text=Halo%20ACTiV,%20saya%20ingin%20informasi%20layanan%20Zoom%20untuk%20perusahaan\",\"cta_whatsapp\":null,\"cta_whatsapp_message\":null,\"background_image\":\"brands\\/zoom\\/hero\\/zoom-hero-zoom-ai-companion-activ-teknologi-2026-1550.webp\"},\"solutions\":{\"enabled\":false,\"title\":null},\"categories\":{\"enabled\":false,\"title\":null},\"showcase\":{\"enabled\":false,\"title\":null,\"items\":[]},\"products\":{\"enabled\":false,\"title\":null,\"count\":null},\"partner\":{\"enabled\":false,\"modal_title\":null,\"modal_subtitle\":null,\"modal_description\":\"<p><\\/p>\",\"guarantees\":[]},\"awards\":[]}', NULL, NULL, 1, '2026-02-10 03:17:02', '2026-02-23 21:18:25'),
(3, 'Yealink', 'yealink', NULL, 'https://www.yealink.com', 'Yealink menyediakan perangkat komunikasi unified seperti video conference, IP phone, dan solusi meeting room profesional.', 'Unified Communication', '{\"hero\":{\"enabled\":true,\"eyebrow\":\"Unified Communication Partner\",\"title\":\"Authorized Yealink Partner\",\"subtitle\":\"Unified Communication & Meeting Room Solutions\",\"desc\":\"PT Alfa Cipta Teknologi Virtual merupakan partner resmi Yealink di Indonesia yang menyediakan solusi video conference, IP Phone, dan unified communication untuk mendukung komunikasi bisnis yang modern dan efisien.\",\"cta_label\":\"Kontak Sales\",\"cta_url\":\"https:\\/\\/api.whatsapp.com\\/send?phone=6285162994602&text=Halo%20ACTiV,%20saya%20ingin%20konsultasi%20produk%20Yealink\",\"background_image\":null,\"awards\":[]},\"solutions\":{\"enabled\":false,\"title\":null},\"categories\":{\"enabled\":false,\"title\":null},\"showcase\":{\"enabled\":false,\"title\":null,\"items\":[]},\"products\":{\"enabled\":false,\"title\":null,\"count\":null}}', 'brands/yealink/yealink.svg', NULL, 1, '2026-02-10 03:17:02', '2026-02-10 03:52:02'),
(4, 'Jabra', 'jabra', NULL, 'https://www.jabra.com', 'Jabra adalah brand audio profesional untuk headset, speakerphone, dan solusi komunikasi bisnis modern.', 'Audio Solution', '{\"hero\":{\"enabled\":true,\"eyebrow\":\"Workplace Audio Technology\",\"title\":\"Authorized Jabra Partner\",\"subtitle\":\"Professional Audio & Collaboration Devices\",\"desc\":\"PT Alfa Cipta Teknologi Virtual merupakan partner resmi Jabra di Indonesia yang menyediakan solusi headset dan audio profesional untuk meeting, call center, dan kebutuhan komunikasi bisnis hybrid.\",\"cta_label\":\"Kontak Sales\",\"cta_url\":\"https:\\/\\/api.whatsapp.com\\/send?phone=6285162994602&text=Halo%20ACTiV,%20saya%20ingin%20konsultasi%20solusi%20audio%20Jabra\",\"background_image\":null,\"awards\":[]},\"solutions\":{\"enabled\":false,\"title\":null},\"categories\":{\"enabled\":false,\"title\":null},\"showcase\":{\"enabled\":false,\"title\":null,\"items\":[]},\"products\":{\"enabled\":false,\"title\":null,\"count\":null}}', 'brands/jabra/jabra.svg', NULL, 1, '2026-02-10 03:17:02', '2026-02-10 03:52:02'),
(5, 'Maxhub', 'maxhub', NULL, 'https://www.maxhub.com', 'Maxhub menyediakan interactive flat panel dan solusi display kolaborasi untuk ruang meeting dan pendidikan.', 'Interactive Display', '{\"hero\":{\"enabled\":true,\"eyebrow\":\"Smart Collaboration Display\",\"title\":\"Authorized Maxhub Partner\",\"subtitle\":\"Interactive Flat Panel & Smart Collaboration Display\",\"desc\":\"PT Alfa Cipta Teknologi Virtual merupakan partner resmi Maxhub di Indonesia yang menyediakan solusi interactive flat panel dan display kolaborasi untuk ruang meeting, command center, dan smart classroom.\",\"cta_label\":\"Kontak Sales\",\"cta_url\":\"https:\\/\\/api.whatsapp.com\\/send?phone=6285162994602&text=Halo%20ACTiV,%20saya%20ingin%20konsultasi%20produk%20Maxhub\",\"background_image\":null,\"awards\":[]},\"solutions\":{\"enabled\":false,\"title\":null},\"categories\":{\"enabled\":false,\"title\":null},\"showcase\":{\"enabled\":false,\"title\":null,\"items\":[]},\"products\":{\"enabled\":false,\"title\":null,\"count\":null}}', 'brands/maxhub/maxhub.svg', NULL, 1, '2026-02-10 03:17:02', '2026-02-10 03:52:02'),
(6, 'TrueConf', 'trueconf', NULL, 'https://trueconf.com', 'TrueConf adalah platform video conferencing dan team collaboration untuk komunikasi internal yang aman dan on-premise.', 'Cloud Meeting', '{\"hero\":{\"enabled\":true,\"eyebrow\":\"On-Premise Collaboration\",\"title\":\"Authorized TrueConf Partner\",\"subtitle\":\"Enterprise Video Conferencing & Team Collaboration\",\"desc\":\"PT Alfa Cipta Teknologi Virtual merupakan partner resmi TrueConf di Indonesia yang menyediakan solusi video conferencing dan team collaboration untuk kebutuhan komunikasi internal perusahaan dan institusi dengan sistem on-premise maupun hybrid.\",\"cta_label\":\"Kontak Sales\",\"cta_url\":\"https:\\/\\/api.whatsapp.com\\/send?phone=6285162994602&text=Halo%20ACTiV,%20saya%20ingin%20konsultasi%20solusi%20TrueConf\",\"background_image\":null,\"awards\":[]},\"solutions\":{\"enabled\":false,\"title\":null},\"categories\":{\"enabled\":false,\"title\":null},\"showcase\":{\"enabled\":false,\"title\":null,\"items\":[]},\"products\":{\"enabled\":false,\"title\":null,\"count\":null}}', 'brands/trueconf/trueconf.svg', NULL, 0, '2026-02-10 03:17:02', '2026-02-10 03:52:02');
