(37, 9, 'legal_section', 1, 1, '{\"title\":\"Syarat & Ketentuan Penggunaan\",\"subtitle\":\"Legal ACTiV\",\"last_updated\":\"23 February 2026\",\"contact_email\":\"sales@activ.co.id\",\"sections\":[{\"slug\":\"pengantar\",\"title\":\"Pengantar\",\"icon\":\"fa-regular fa-file-lines\",\"content\":\"Selamat datang di situs web PT Alfa Cipta Teknologi Virtual (ACTiV). Dengan mengakses atau menggunakan layanan kami, Anda setuju untuk terikat oleh Syarat dan Ketentuan ini.\"},{\"slug\":\"definisi\",\"title\":\"Definisi\",\"icon\":\"fa-regular fa-book\",\"content\":\"<ul><li><strong>ACTiV:<\\/strong> PT Alfa Cipta Teknologi Virtual sebagai penyedia layanan ICT.<\\/li><li><strong>Layanan:<\\/strong> Meliputi rental hardware, penjualan software, konsultasi IT, dan platform Accommerce.id.<\\/li><li><strong>Pengguna:<\\/strong> Individu atau korporasi yang menggunakan layanan ACTiV.<\\/li><\\/ul>\"},{\"slug\":\"layanan-ict\",\"title\":\"Layanan & Sewa Perangkat\",\"icon\":\"fa-regular fa-laptop-code\",\"content\":\"Layanan penyewaan perangkat keras mengikuti durasi kontrak yang disepakati. Pengguna bertanggung jawab penuh atas keamanan fisik perangkat selama masa sewa.\",\"callout\":\"Setiap kerusakan yang disebabkan oleh kelalaian penggunaan akan dikenakan biaya penggantian sesuai harga pasar yang berlaku.\"},{\"slug\":\"pembayaran\",\"title\":\"Transaksi & Pembayaran\",\"icon\":\"fa-regular fa-credit-card\",\"content\":\"Pembayaran dilakukan melalui saluran resmi yang ditunjuk ACTiV atau melalui platform Accommerce.id. Untuk proyek kustom, berlaku ketentuan DP 50% sebelum pengerjaan dimulai.\"},{\"slug\":\"hukum\",\"title\":\"Hukum yang Berlaku\",\"icon\":\"fa-regular fa-gavel\",\"content\":\"Syarat dan Ketentuan ini diatur oleh hukum Republik Indonesia. Perselisihan akan diselesaikan melalui musyawarah atau di Pengadilan Negeri Jakarta Selatan.\"}]}', '2026-02-23 00:51:02', '2026-02-23 00:51:02'),
(38, 10, 'legal_section', 1, 1, '{\"title\":\"Kebijakan Privasi\",\"subtitle\":\"Privasi Anda\",\"last_updated\":\"23 February 2026\",\"contact_email\":\"sales@activ.co.id\",\"sections\":[{\"slug\":\"informasi-dikumpulkan\",\"title\":\"Data yang Kami Kumpulkan\",\"icon\":\"fa-regular fa-database\",\"content\":\"Kami mengumpulkan data profil perusahaan dan kontak personal untuk keperluan administrasi layanan ICT dan verifikasi transaksi di Accommerce.id.\"},{\"slug\":\"penggunaan-data\",\"title\":\"Cara Kami Menggunakan Data\",\"icon\":\"fa-regular fa-shield-halved\",\"content\":\"Data Anda digunakan secara eksklusif untuk penyediaan layanan, pemrosesan pesanan, dan peningkatan kualitas solusi IT kami.\",\"callout\":\"ACTiV tidak pernah menjual data pelanggan kepada pihak ketiga mana pun.\"}]}', '2026-02-23 00:51:02', '2026-02-23 00:51:02'),
(39, 11, 'partnership_hero', 0, 1, '{\"id\":\"section-39\",\"className\":\"\",\"title\":\"Bangun Kemitraan Strategis Bersama ACTiV\",\"subtitle\":\"Kolaborasi Tanpa Batas\",\"button_text\":\"Ajukan Kemitraan\",\"button_url\":\"\",\"use_whatsapp\":true,\"button_url_rel\":\"noopener noreferrer\",\"description\":\"Bergabunglah dengan ekosistem teknologi terdepan untuk menghadirkan solusi ICT dan Edukasi yang inovatif bagi klien Anda.\"}', '2026-02-23 00:51:02', '2026-02-23 01:28:25'),
(40, 11, 'partnership_details', 1, 1, '{\"id\":\"section-40\",\"className\":\"\",\"title\":\"Bagian dari Ekosistem Digital ACTiV\",\"subtitle\":\"\\ud83c\\udf10 Official Online Sales Platform\",\"description\":\"Sebagai bagian dari transformasi digital ACTiV, Accommerce.id memperluas akses pelanggan terhadap berbagai produk teknologi, perangkat keras, serta aksesori profesional melalui platform online yang terstruktur dan terpercaya.<br><br>Platform ini menjadi perpanjangan resmi layanan penjualan ACTiV untuk mendukung kebutuhan perusahaan, institusi, dan individu di seluruh Indonesia.\",\"partner_name\":\"Accommerce.id\",\"partner_logo\":\"\\/assets\\/img\\/partners\\/accommerceid.webp\",\"partner_url\":\"https:\\/\\/accommerce.id\",\"partner_description\":\"Accommerce.id merupakan platform resmi penjualan online dari PT Alfa Cipta Teknologi Virtual (ACTiV) yang menghadirkan solusi pembelian hardware dan lisensi software secara profesional, cepat, dan aman.<br><br>Dirancang sebagai marketplace resmi milik ACTiV, Accommerce memberikan kemudahan transaksi dengan sistem checkout instan serta dukungan purna jual bersertifikat.\",\"feature_title\":\"\\ud83d\\ude80 Keunggulan Platform\",\"features\":[{\"title\":\"Official Online Sales Channel\",\"text\":\"Kanal penjualan digital resmi dan terintegrasi dengan sistem ACTiV.\",\"icon\":\"fa-solid fa-shop\"},{\"title\":\"Transaksi Aman\",\"text\":\"Sistem pembayaran terpercaya dengan keamanan data terenkripsi.\",\"icon\":\"fa-solid fa-lock\"},{\"title\":\"Tracking Pesanan\",\"text\":\"Pelanggan dapat memantau status pengiriman secara real-time.\",\"icon\":\"fa-solid fa-truck-fast\"},{\"title\":\"Layanan Pelanggan 24\\/7\",\"text\":\"Dukungan responsif untuk kebutuhan pre-sales dan after-sales.\",\"icon\":\"fa-solid fa-headset\"},{\"title\":\"Ketersediaan Stok Real-time\",\"text\":\"Informasi stok akurat dan transparan.\",\"icon\":\"fa-solid fa-boxes-stacked\"}],\"steps\":[{\"title\":\"Pendaftaran\",\"description\":\"Isi formulir pengajuan kemitraan melalui situs resmi kami.\"},{\"title\":\"Verifikasi\",\"description\":\"Tim kemitraan kami akan meninjau profil bisnis Anda.\"},{\"title\":\"Onboarding\",\"description\":\"Dapatkan akses ke dashboard partner dan resource teknologi.\"}],\"partner_url_rel\":\"noopener noreferrer nofollow\",\"partner_title\":\"\"}', '2026-02-23 00:51:02', '2026-02-23 01:28:25');
INSERT INTO `products` (`id`, `service_id`, `brand_id`, `name`, `slug`, `description`, `image_path`, `thumbnail_path`, `price`, `link_accommerce`, `whatsapp_note`, `sku`, `solution_type`, `datasheet_url`, `tags`, `specs`, `specification_text`, `features`, `features_text`, `is_active`, `is_featured`, `is_new`, `created_at`, `updated_at`) VALUES
(1, 1, 1, 'Logitech 100W USB-C Charger', 'logitech-100w-usb-c-charger', '<h4>Deskripsi Produk</h4><p>Logitech 100W USB-C Charger adalah adaptor daya tugas berat yang dirancang khusus untuk mendukung ekosistem konferensi video Logitech. Perangkat ini sangat krusial untuk memberikan daya yang stabil ke perangkat laptop atau seluler yang terhubung melalui sistem Logitech Extend. Dengan desain yang ringkas, charger ini memastikan perangkat pengguna tetap terisi daya penuh saat melakukan presentasi atau rapat BYOD (Bring Your Own Device) tanpa perlu mencari colokan listrik tambahan di bawah meja.</p><h4>Fitur Utama</h4><ul><li><strong>Daya Tinggi 100W:</strong> Mampu mengisi daya laptop performa tinggi dengan cepat dan efisien.</li><li><strong>Kompatibilitas Sistem:</strong> Dirancang untuk bekerja mulus dengan Logitech Extend Table Side (TX) Box.</li><li><strong>Desain Rapi:</strong> Dimensi yang pas untuk dipasang di bawah meja atau di dalam kotak manajemen kabel.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Output: 5.0A / 100W Max</li><li>Input: 100-240V</li><li>Konektor: USB-C</li><li>Dimensi: 100 x 63 x 25 mm</li></ul>', 'products/logitech-100w-usb-c-charger/logitech-100w-usb-c-charger-2026-1771574648.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000268', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/100w-usb-c-charger-datasheet.pdf', '[\"100W charger\",\"USB-C charger\",\"Logitech Extend\",\"video conferencing\",\"BYOD\",\"conference room\",\"power supply\"]', '{\"Dimensi\":{\"Tinggi\":\"25 mm\",\"Lebar\":\"100 mm\",\"Tebal\":\"63 mm\"},\"Persyaratan Sistem\":{\"Kompatibilitas\":\"Logitech Extend\"},\"Listrik & Lingkungan\":{\"Input daya\":\"100-240V; 50\\/60Hz; 1,5A\",\"Output maks\":\"5,0A 100W\",\"Kabel AC\":\"0,89 m\"},\"Konektivitas\":{\"Jenis koneksi\":\"USB-C ke Logitech Extend Table Side (TX) Box\"},\"Garansi\":\"Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Pengisi daya 100W ini terhubung ke Logitech Extend, solusi untuk menjalankan rapat di ruang konferensi berbasis Android atau BYOD menggunakan satu koneksi kabel USB-C.</p>', '[{\"name\":\"Pengisi daya 100W\",\"value\":\"Memberikan daya ke perangkat melalui satu kabel USB-C.\",\"additional\":\"\"},{\"name\":\"Konektivitas\",\"value\":\"Mendukung Logitech Extend untuk koneksi BYOD.\",\"additional\":\"\"},{\"name\":\"Desain Kompak\",\"value\":\"Mudah dipasang di bawah meja.\",\"additional\":\"\"},{\"name\":\"Kabel AC\",\"value\":\"Dilengkapi dengan kabel AC sepanjang 0,89 m.\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Tambahkan pengisi daya 100W ke Logitech Extend untuk memberi daya pada perangkat dan meng-host koneksi BYOD menggunakan satu kabel USB-C.</p>', 1, 0, 0, '2026-02-20 01:04:08', '2026-02-20 01:04:08'),
(2, 1, 1, 'Logitech Kabel USB Aktif', 'logitech-kabel-usb-aktif', '<h4>Deskripsi Produk</h4><p>Logitech Active USB Cable adalah kabel USB-C aktif yang mendukung bandwidth tinggi untuk menghubungkan kamera dan periferal konferensi video ke komputer host. Berbeda dengan kabel pasif biasa, kabel ini memiliki chip penguat sinyal yang memungkinkan transmisi data super cepat dan stabil dalam jarak yang lebih panjang. Ini adalah solusi ideal untuk menghubungkan Logitech MeetUp 2 atau Rally Board 65 dalam skenario BYOD satu kabel.</p><h4>Fitur Utama</h4><ul><li><strong>Kecepatan Super:</strong> Mendukung USB 3.1 Gen 2 dengan kecepatan transfer hingga 10 Gbps.</li><li><strong>Daya Tahan Tinggi:</strong> Diperkuat dengan aramid untuk ketahanan tarikan dan cocok untuk instalasi di dinding atau pleno.</li><li><strong>Koneksi Stabil:</strong> Menjamin transmisi video 4K dan audio jernih tanpa latensi.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Tipe Konektor: USB-C to USB-C</li><li>Kecepatan Data: Up to 10 Gbps</li><li>Panjang: Tersedia dalam varian 5m, 10m, 25m (tergantung stok)</li></ul>', 'products/logitech-kabel-usb-aktif/logitech-kabel-usb-aktif-2026-1771574648.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000195', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/strong-usb-accessory.pdf', '[\"kabel usb\",\"logitech\",\"video conferencing\",\"meetUp 2\",\"rally board 65\",\"BYOD\",\"USB 3.1\"]', '{\"Dimensi\":{\"Panjang Bantalan\":\"5 m\"},\"Spesifikasi Teknis\":{\"Ikhtisar\":[\"USB 3.1 Gen 2\",\"USB-C ke USB-C\",\"Mendukung DP Alt Mode\"],\"Perangkat Terverifikasi\":[\"MeetUp 2\",\"Rally Board 65\"],\"Garansi\":\"Hardware Terbatas 2 Tahun\"}}', '<h4>Spesifikasi Utama</h4><p>Kabel USB Aktif mendukung koneksi BYOD satu kabel untuk MeetUp 2 dan Rally Board 65 dengan transfer data super cepat.</p>', '[{\"name\":\"Koneksi\",\"value\":\"BYOD satu kabel\",\"additional\":\"Menghubungkan MeetUp 2 atau Rally Board 65 ke laptop\"},{\"name\":\"Transfer Data\",\"value\":\"Super cepat\",\"additional\":\"Mendukung USB 3.1 Gen 2\"},{\"name\":\"Panjang Kabel\",\"value\":\"5 meter\",\"additional\":\"Memberikan fleksibilitas yang lebih baik di ruang pertemuan kecil\"}]', '<h4>Fitur Unggulan</h4><p>Kabel sepanjang 5 meter ini cukup panjang untuk memberikan fleksibilitas di ruang pertemuan kecil.</p>', 1, 0, 0, '2026-02-20 01:04:08', '2026-02-20 01:04:08'),
(3, 1, 1, 'Logitech BCC950 ConferenceCam', 'logitech-bcc950-conferencecam', '<h4>Deskripsi Produk</h4><p>Logitech BCC950 adalah solusi konferensi video \"All-in-One\" yang dirancang khusus untuk ruang rapat kecil (huddle room) atau kantor pribadi. Perangkat ini menggabungkan webcam HD berkualitas tinggi dengan speakerphone omni-directional dalam satu unit kompak. Desain uniknya menggunakan stem (tangkai) peninggi bermotor, memungkinkan kamera berada sejajar dengan mata peserta rapat untuk sudut pandang yang lebih natural dan profesional.</p><h4>Fitur Utama</h4><ul><li><strong>Desain All-in-One:</strong> Integrasi audio dan video plug-and-play yang hemat tempat.</li><li><strong>Motorized Pan/Tilt/Zoom:</strong> Kamera dapat digerakkan menggunakan remote control untuk cakupan luas.</li><li><strong>Stem Extender:</strong> Tangkai peninggi 22 cm untuk mendapatkan eye-level view.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Resolusi: Full HD 1080p/30fps</li><li>Field of View (FoV): 78 derajat diagonal</li><li>Audio: Speakerphone full duplex dengan noise cancellation</li><li>Zoom: 1.2x HD Zoom</li></ul>', 'products/logitech-bcc950-conferencecam/logitech-bcc950-conferencecam-2026-1771574648.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-000939', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/bcc950datasheet.pdf', '[\"webcam\",\"video conference\",\"speakerphone\",\"logitech bcc950\",\"HD video\",\"plug-and-play\",\"business communication\"]', '{\"Dimensi\":{\"Tinggi\":\"154 mm\",\"Lebar\":\"150 mm\",\"Tebal\":\"104 mm\",\"Tinggi dengan perpanjangan\":\"345 mm\"},\"Berat\":\"568 g\",\"Persyaratan Sistem\":{\"Windows\":\"7, 8.1, 10\",\"macOS\":\"10.10 or later\"},\"Kompatibilitas dan Sertifikasi\":{\"Konektivitas\":\"USB plug-and-play\",\"Sertifikasi\":[\"Skype for Business\",\"Teams\",\"Zoom\",\"Fuze\",\"Google Meet\",\"Cisco Jabber\",\"WebEX\",\"BlueJeans\",\"BroadSoft\",\"GoToMeeting\",\"Vidyo\"]},\"Daya\":{\"Adaptor daya\":\"AC\",\"Kabel daya\":\"2,4 m\",\"Kabel USB\":\"2,4 m\"},\"Lingkungan\":{\"Suhu Operasional\":\"0\\u00b0C hingga 40\\u00b0C\",\"Kelembapan\":\"10% hingga 90%\"}}', '<h4>Spesifikasi Utama</h4><p>Logitech BCC950 adalah solusi video conferencing all-in-one yang ideal untuk tim kecil, dengan kualitas video HD dan audio jernih.</p>', '[{\"name\":\"Kamera\",\"value\":\"Panggilan video Full HD 1080p (hingga 1920 x 1080 piksel); panggilan video 720p HD (hingga 1280 x 720 piksel) dengan klien yang didukung\",\"additional\":\"Teknologi RightLight\\u2122 2 untuk kejernihan dalam berbagai lingkungan pencahayaan\"},{\"name\":\"Speakerphone\",\"value\":\"Speakerphone full duplex terintegrasi dengan echo dan noise cancellation\",\"additional\":\"Kontrol untuk menjawab\\/mengakhiri panggilan, mute, dan pergerakan kamera\"},{\"name\":\"Mikrofon\",\"value\":\"Mikrofon omnidirectional dengan jangkauan diameter 2,4 m\",\"additional\":\"Respons Frekuensi: 200Hz \\u2013 8KHz\"},{\"name\":\"Remote Control\",\"value\":\"Jangkauan IR 3 m\",\"additional\":\"Baterai CR2032 (disertakan)\"},{\"name\":\"Optik\",\"value\":\"1.2x HD zoom\",\"additional\":\"Pan (miring) 180\\u00b0 ke seluruh sisi ruangan\"},{\"name\":\"Suara\",\"value\":\"Teknologi noise canceling dan acoustic echo cancellation\",\"additional\":\"Suara yang memenuhi seluruh ruangan dari full-range speaker\"},{\"name\":\"Konektivitas\",\"value\":\"Tanpa memerlukan software, pelatihan, atau pemeliharaan khusus\",\"additional\":\"Pasangkan saja BCC950 ke PC atau Mac\"}]', '<h4>Fitur Unggulan</h4><p>Dengan desain plug-and-play, BCC950 memudahkan video conference kapan pun dan di mana pun.</p>', 1, 0, 0, '2026-02-20 01:04:08', '2026-02-20 01:04:08'),
(4, 1, 1, 'Logitech BRIO 305', 'logitech-brio-305', '<h4>Deskripsi Produk</h4><p>Logitech Brio 305 adalah webcam bisnis entry-level yang andal, dirancang untuk penyebaran massal di perusahaan. Menawarkan kualitas video 1080p yang jernih, webcam ini dilengkapi teknologi koreksi cahaya otomatis (RightLight 2) untuk memastikan pengguna terlihat profesional bahkan dalam kondisi pencahayaan buruk. Dilengkapi dengan konektivitas USB-C modern dan penutup privasi terintegrasi yang mudah digunakan.</p><h4>Fitur Utama</h4><ul><li><strong>RightLight 2:</strong> Menyeimbangkan kecerahan secara otomatis dan mengurangi bayangan wajah.</li><li><strong>Mikrofon Noise-Reducing:</strong> Mikrofon mono yang meredam kebisingan latar belakang kantor.</li><li><strong>Privacy Shutter:</strong> Penutup lensa fisik putar untuk keamanan privasi instan.</li><li><strong>Sertifikasi:</strong> Kompatibel dengan Microsoft Teams, Zoom, dan Google Meet.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Resolusi: 1080p/30fps</li><li>Field of View: 70 derajat (Fixed)</li><li>Koneksi: USB-C Plug-and-Play</li><li>Mikrofon: Mono (jarak jemput hingga 1.22m)</li></ul>', 'products/logitech-brio-305/logitech-brio-305-2026-1771574648.webp', NULL, NULL, 'https://accommerce.id/product/logitech-brio-305/', 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001472', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/brio-305-datasheet.pdf', '[\"webcam 1080p\",\"logitech brio\",\"video conference\",\"usb-c webcam\",\"noise-cancelling microphone\",\"streaming camera\",\"business webcam\"]', '{\"Dimensi\":{\"Tinggi\":\"65,63 mm\",\"Lebar\":\"53,1 mm\",\"Tebal\":\"45 mm\"},\"Berat\":\"74,6 g, termasuk mount clip & kabel\",\"Panjang Kabel\":\"1,5 m\",\"Resolusi\":{\"1080p\":\"30fps (1920x1080 piksel)\",\"720p\":\"30fps (1280x720 piksel)\"},\"Megapiksel\":\"2MP\",\"Bidang Pandang Diagonal\":\"70\\u00b0\",\"Zoom\":\"1x Digital zoom\",\"Fokus\":\"fixed focus\",\"Shutter Privasi\":\"terintegrasi\",\"Konektivitas\":\"plug-and-play USB-C\",\"Dukungan\":\"Didukung di Logi Tune\",\"Mikrofon\":{\"Tipe\":\"Mikrofon mono\",\"Jangkauan\":\"Maksimal 1,22 m\"},\"Koreksi Cahaya\":\"RightLight 2 secara otomatis menyeimbangkan kecerahan\"}', '<h4>Spesifikasi Utama</h4><p>Webcam Brio 305 menawarkan resolusi 1080p dengan auto light correction dan mikrofon noise-reducing, ideal untuk pertemuan video yang jelas dan profesional.</p>', '[{\"name\":\"Auto Light Correction\",\"value\":\"RightLight 2\",\"additional\":\"Menyesuaikan kontras dan mengimbangi lingkungan cahaya yang menantang\"},{\"name\":\"Mikrofon Noise Cancelling\",\"value\":\"Satu mikrofon\",\"additional\":\"Menangkap suara dengan jelas melalui peredaman noise di latar belakang\"},{\"name\":\"Konektivitas\",\"value\":\"USB-C\",\"additional\":\"Plug-and-play\"},{\"name\":\"Kompatibilitas\",\"value\":\"Windows, macOS, ChromeOS\",\"additional\":\"Disertifikasi untuk Microsoft Teams, Zoom, Google Meet\"}]', '<h4>Fitur Unggulan</h4><p>Dengan konektivitas USB-C dan dukungan untuk platform video conferencing terkemuka, Brio 305 adalah pilihan sempurna untuk kolaborasi yang lebih baik.</p>', 1, 0, 0, '2026-02-20 01:04:08', '2026-02-22 20:34:59'),
(5, 1, 1, 'Logitech BRIO 4K', 'logitech-brio-4k', '<h4>Deskripsi Produk</h4><p>Logitech Brio 4K Ultra HD Pro adalah standar emas untuk kolaborasi video profesional. Webcam ini dilengkapi fitur premium seperti HDR (High Dynamic Range), dukungan Windows Hello (pengenalan wajah), dan kemampuan streaming 4K. Sangat cocok untuk eksekutif, kreator konten, atau profesional yang membutuhkan detail gambar terbaik dan warna akurat dalam segala kondisi pencahayaan.</p><h4>Fitur Utama</h4><ul><li><strong>4K Ultra HD & HDR:</strong> Detail luar biasa dengan teknologi RightLight 3 untuk kontras terbaik.</li><li><strong>Windows Hello:</strong> Login komputer instan dan aman menggunakan pengenalan wajah.</li><li><strong>Adjustable FoV:</strong> Sudut pandang yang bisa diatur (65, 78, atau 90 derajat).</li><li><strong>5x HD Zoom:</strong> Zoom digital tanpa pecah untuk pembingkaian sempurna.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Resolusi: 4K/30fps atau 1080p/60fps</li><li>Lensa: Kaca dengan autofocus canggih</li><li>Mikrofon: Dual omni-directional mics</li></ul>', 'products/logitech-brio-4k/logitech-brio-4k-2026-1771574648.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001723', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/brio-datasheet.pdf', '[\"webcam 4k\",\"logitech brio\",\"video conference\",\"windows hello\",\"hdr webcam\",\"streaming camera\",\"business webcam\"]', '{\"Dimensi\":{\"Webcam\":{\"Tinggi\":\"27 mm\",\"Lebar\":\"102 mm\",\"Tebal\":\"26,5 mm\",\"Panjang kabel\":\"1,5 m\",\"Berat\":\"65 g\"},\"Mounting Clip\":{\"Tinggi\":\"23,8 mm\",\"Lebar\":\"36,3 mm\",\"Tebal\":\"62,7 mm\",\"Berat\":\"69,2 g\"},\"Kemasan\":{\"Panjang\":\"13,9 cm\",\"Lebar\":\"7,1 cm\",\"Tebal\":\"13,4 cm\",\"Berat\":\"300 g\"}},\"Spesifikasi Teknis\":{\"Kamera\":{\"Beberapa resolusi\":\"4K\\/30 fps (hingga 4096 x 2160 piksel), 1080p\\/60 fps (hingga 1920x1080 piksel) atau 720p\\/90 fps (hingga 1280x720 piksel)\",\"Sensor gambar\":\"13MP\",\"Bidang pandang diagonal (dFoV)\":\"90\\u00b0\\/78\\u00b0\\/65\\u00b0\",\"Digital zoom\":\"5x\",\"Jenis fokus\":\"Autofocus\",\"Jenis lensa\":\"Kaca\",\"RightLight 3\":\"untuk gambar yang jernih dalam berbagai lingkungan pencahayaan mulai dari cahaya redup hingga sinar matahari langsung\",\"Teknologi sensor inframerah\":\"untuk Windows Hello\"},\"Audio\":{\"Mikrofon\":\"internal segala arah ganda dengan jangkauan hingga 1,2 m\"},\"Konektivitas\":{\"USB\":\"USB-A atau USB-C plug-and-play\"},\"Shutter privasi\":\"Fleksibel\",\"Opsi mounting\":\"Klip pemasangan universal yang dapat dilepas cocok untuk monitor, layar LCD, dan laptop\\u00bc\\u201d ulir untuk pemasangan tripod.\",\"Dukungan Software\":\"Download Logi Tune di www.logitech.com\\/tune untuk menyesuaikan warna dan kecerahan.\",\"Penggunaan dan pengelolaan\":\"Logitech Sync mendukung penggunaan di seluruh perusahaan dalam skala besar.\"},\"SPESIFIKASI KEBERLANJUTAN\":{\"Plastik\":\"38% bahan Post Consumer Recycled (PCR)\",\"Kasing kamera\":\"Aluminium berkarbon rendah\",\"Kemasan Kertas\":\"Bersertifikasi FSH\",\"Jejak karbon produk\":\"12,97 kg CO2e\"}}', '<h4>Spesifikasi Utama</h4><p>Brio 4K adalah webcam bisnis ultra HD profesional dengan dukungan Windows Hello dan teknologi canggih untuk pertemuan video yang lebih baik.</p>', '[{\"name\":\"Resolusi\",\"value\":\"4K Ultra HD 2160p \\/30fps, Full HD 1080p \\/60fps, HD 720p\\/90fps\",\"additional\":\"\"},{\"name\":\"Bidang Pandang Diagonal\",\"value\":\"90\\u00b0\\/78\\u00b0\\/65\\u00b0\",\"additional\":\"\"},{\"name\":\"Kemampuan Zoom\",\"value\":\"5x\",\"additional\":\"\"},{\"name\":\"Autofocus\",\"value\":\"Ya\",\"additional\":\"\"},{\"name\":\"Auto Light Correction\",\"value\":\"RightLight 3\",\"additional\":\"\"},{\"name\":\"Mikrofon Noise Cancelling\",\"value\":\"Dua mikrofon omnidirectional\",\"additional\":\"\"},{\"name\":\"Koneksi\",\"value\":\"USB-C plug-and-play\",\"additional\":\"\"},{\"name\":\"Panjang Kabel\",\"value\":\"1,5 m\",\"additional\":\"\"},{\"name\":\"Shutter Privasi\",\"value\":\"Internal\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Brio 4K menampilkan resolusi tinggi, autofocus, dan teknologi RightLight 3 untuk pencahayaan optimal.</p>', 1, 0, 0, '2026-02-20 01:04:08', '2026-02-20 01:04:09'),
(6, 1, 1, 'Logitech BRIO 505', 'logitech-brio-505', '<h4>Deskripsi Produk</h4><p>Logitech Brio 505 adalah webcam kelas menengah modern dengan desain silinder unik dan fitur pintar untuk tenaga kerja hibrida. Webcam ini menonjol dengan fitur Show Mode yang inovatif, memungkinkan pengguna memiringkan kamera ke bawah untuk menampilkan sketsa atau dokumen fisik di meja mereka secara otomatis. Juga dilengkapi auto-framing dasar untuk menjaga pengguna tetap di tengah layar.</p><h4>Fitur Utama</h4><ul><li><strong>Show Mode:</strong> Memudahkan presentasi dokumen fisik di meja dengan membalik orientasi gambar.</li><li><strong>Auto-Framing (RightSight):</strong> Secara otomatis memusatkan kamera pada wajah pengguna saat bergerak.</li><li><strong>Dual Noise-Reducing Mics:</strong> Memastikan suara terdengar jelas dari kebisingan kantor.</li><li><strong>Privacy Shutter:</strong> Mekanisme putar di sisi lensa yang mudah dijangkau.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Resolusi: 1080p/30fps</li><li>Field of View: 90 derajat diagonal</li><li>Koneksi: USB-C</li><li>Mounting: Klip monitor yang dapat disesuaikan</li></ul>', 'products/logitech-brio-505/logitech-brio-505-2026-1771574649.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001461', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/brio-505-datasheet.pdf', '[\"webcam 1080p\",\"logitech brio\",\"video conference\",\"microsoft teams\",\"zoom\",\"google meet\",\"streaming camera\"]', '{\"Dimensi\":{\"Webcam saja\":{\"Tinggi\":\"31,5 mm\",\"Lebar\":\"110 mm\",\"Tebal\":\"31,5 mm\"},\"Webcam + Mount\":{\"Tinggi\":\"51,5 mm\",\"Lebar\":\"110 mm\",\"Tebal\":\"45 mm termasuk mount clip\"},\"Mounting Clip\":{\"Tinggi\":\"25 mm\",\"Lebar\":\"45,8 mm\",\"Tebal\":\"65,1 mm\",\"Berat\":\"40 g\"},\"Berat\":\"121 g, termasuk mount clip & kabel\",\"Panjang Kabel yang terpasang\":\"1,5 m\"},\"Spesifikasi Teknis\":{\"Resolusi\":{\"1080p\":\"30fps (1920x1080 piksel)\",\"720p\":\"60fps (1280x720 piksel)\"},\"Megapiksel kamera\":\"4MP\",\"Bidang pandang diagonal (dFoV)\":\"90\\u00b0\\/78\\u00b0\\/65\\u00b0\",\"Zoom hardware\":\"4X digital zoom\",\"Jenis fokus\":\"Autofocus\",\"Jenis lensa\":\"Kaca\",\"Jenis Mikrofon Internal\":\"Mikrofon stereo\",\"Jangkauan mikrofon\":\"Maksimal 1,22 m\",\"Konektivitas USB\":\"USB-C colokkan-dan-gunakan\",\"Shutter privasi\":\"Terintegrasi\"},\"Kompatibilitas\":{\"Memerlukan\":\"Port USB-C yang kosong\",\"Kompatibel Dengan\":\"Windows, macOS, atau ChromeOS dan hampir semua platform panggilan video populer.\",\"Disertifikasi untuk\":\"Microsoft Teams, Zoom, Google Meet, Works With Chromebook\"}}', '<h4>Spesifikasi Utama</h4><p>Webcam Brio 505 menawarkan resolusi Full HD 1080p dengan fitur auto-framing dan light correction untuk pengalaman video meeting yang lebih baik.</p>', '[{\"name\":\"Auto Light Correction\",\"value\":\"Rightlight 4 dengan HDR untuk gambar yang jelas dalam berbagai lingkungan pencahayaan mulai dari cahaya redup hingga sinar matahari langsung.\",\"additional\":\"\"},{\"name\":\"Kualitas Gambar Terbaik\",\"value\":\"Resolusi Full HD 1080p dan koreksi gambar wajah berbasis AI menghadirkan kualitas gambar yang tajam.\",\"additional\":\"\"},{\"name\":\"Dual Mikrofon Noise-Reducing\",\"value\":\"Brio 505 meningkatkan kualitas suara karyawan dengan menyaring suara latar belakang.\",\"additional\":\"\"},{\"name\":\"Shutter Privasi Terintegrasi\",\"value\":\"Shutter privasi terintegrasi yang mudah digunakan untuk sepenuhnya menutup kamera.\",\"additional\":\"\"},{\"name\":\"Show Mode\",\"value\":\"Karyawan dapat menyertakan benda fisik di panggilan video dengan memiringkan kamera.\",\"additional\":\"\"},{\"name\":\"Auto Framing\",\"value\":\"RightSight auto-framing menjaga kamera menyorot ke tengah.\",\"additional\":\"Memerlukan pengguna untuk men-download dan menggunakan Logi Tune.\"}]', '<h4>Fitur Unggulan</h4><p>Dengan teknologi terbaru, Brio 505 memberikan kualitas gambar yang tajam dan suara yang jernih, ideal untuk pertemuan hibrida.</p>', 1, 0, 0, '2026-02-20 01:04:09', '2026-02-20 01:04:09'),
(7, 1, 1, 'Logitech Cat5e Kit', 'logitech-cat5e-kit', '<h4>Deskripsi Produk</h4><p>Logitech Cat5e Kit adalah solusi konektivitas berbasis jaringan yang dirancang untuk perangkat Logitech Tap di ruang meeting profesional. Kit ini memungkinkan koneksi jarak jauh antara Tap dan komputer ruang rapat menggunakan kabel Cat5e standar, memberikan fleksibilitas instalasi yang lebih besar serta manajemen kabel yang lebih rapi dan aman.</p><h4>Fitur Utama</h4><ul><li><strong>Koneksi Jarak Jauh:</strong> Menggunakan kabel Cat5e untuk menghubungkan Tap hingga jarak yang lebih fleksibel dibanding USB standar.</li><li><strong>Instalasi Profesional:</strong> Cocok untuk instalasi di dalam dinding atau melalui conduit kabel.</li><li><strong>Manajemen Kabel Rapi:</strong> Mengurangi kabel panjang di atas meja meeting.</li><li><strong>Kompatibilitas Khusus:</strong> Dirancang untuk Logitech Tap (versi USB).</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Koneksi: Cat5e (Ethernet-based extension)</li><li>Kompatibilitas: Logitech Tap (USB)</li><li>Instalasi: Mendukung penarikan kabel melalui dinding/plenum</li><li>Paket Termasuk: Transmitter dan Receiver Kit</li></ul>', 'products/logitech-cat5e-kit/logitech-cat5e-kit-2026-1771574649.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000019', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/cat5e-kit-datasheet.pdf', '[\"cat5e kit\",\"logitech tap\",\"video conferencing\",\"data cable\",\"power over ethernet\",\"flexible cabling\",\"meeting room solutions\"]', '{\"Dimensi\":{\"Receiver Logitech Tap\":{\"Tinggi\":\"29 mm\",\"Lebar\":\"83 mm\",\"Tebal\":\"85 mm\"},\"Dongle Transceiver\":{\"Tinggi\":\"22,5 mm\",\"Lebar\":\"31,0 mm\",\"Tebal\":\"83,7 mm\",\"Panjang kabel\":\"500 mm\"},\"Catu daya\":{\"Tinggi\":\"91,0 mm\",\"Lebar\":\"60,2 mm\",\"Tebal\":\"36,3 mm\"},\"Termasuk Penataan Kabel\":{\"Panjang 1\":\"2.97 m\",\"Panjang 2\":\"7.0 m\"}},\"Spesifikasi Teknis\":{\"Umum\":{\"Jenis Kabel\":\"Cat5e SF\\/UTP AWG26 atau versi terbaru\",\"Catu daya\":\"Catu daya auto-switching 100-240V dengan set adaptor internasional\"},\"Kompatibilitas\":{\"Touch Controller\":\"Logitech Tap\",\"Komputer Ruang Rapat\":\"USB 2.0\"}},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Cat5e Kit memungkinkan penataan kabel yang lebih rapi dan sederhana dengan daya dan data melalui kabel category.</p>', '[{\"name\":\"Pengaturan Kabel\",\"value\":\"Sederhana untuk Logitech Tap\",\"additional\":\"Letakkan Tap hingga maksimal 40 meter dari komputer\"},{\"name\":\"Data dan Daya\",\"value\":\"Melalui kabel category\",\"additional\":\"Mengurangi kebutuhan stopkontak di meja\"},{\"name\":\"Penataan Kabel Fleksibel\",\"value\":\"Gunakan kabel 10 meter yang disertakan\",\"additional\":\"Atau gunakan kabel Anda sendiri hingga 40 meter\"},{\"name\":\"Kompatibilitas\",\"value\":\"Dengan semua Tap Mount\",\"additional\":\"Termasuk Table, Riser, dan Wall Mount\"}]', '<h4>Fitur Unggulan</h4><p>Pengaturan kabel yang fleksibel dan kompatibilitas dengan semua Tap Mount untuk pengalaman rapat yang lebih baik.</p>', 1, 0, 0, '2026-02-20 01:04:09', '2026-02-20 01:04:09'),
(8, 1, 1, 'Logitech Compute Mount', 'logitech-compute-mount', '<h4>Deskripsi Produk</h4><p>Logitech Compute Mount adalah dudukan yang dirancang untuk menyembunyikan dan mengamankan mini PC atau Chromebox di balik layar atau di dalam meja ruang meeting. Mount ini membantu menjaga tampilan ruang rapat tetap bersih, profesional, dan bebas dari kabel yang berantakan, sekaligus memberikan akses mudah untuk servis dan pemeliharaan.</p><h4>Fitur Utama</h4><ul><li><strong>Desain Tersembunyi:</strong> Dipasang di belakang layar atau di bawah meja untuk tampilan minimalis.</li><li><strong>Keamanan Perangkat:</strong> Menjaga mini PC tetap terkunci dan aman dari gangguan.</li><li><strong>Manajemen Kabel:</strong> Membantu merapikan kabel daya dan koneksi.</li><li><strong>Kompatibilitas Luas:</strong> Mendukung berbagai mini PC dan Chromebox populer.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Tipe Mount: Universal mini PC mount</li><li>Lokasi Pemasangan: Belakang layar (VESA) atau bawah meja</li><li>Material: Baja kokoh berlapis powder coat</li><li>Kompatibilitas: PC mini form factor & Chromebox</li></ul>', 'products/logitech-compute-mount/logitech-compute-mount-2026-1771574649.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000097', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/compute-mount-datasheet.pdf', '[\"compute mount\",\"logitech\",\"video conferencing\",\"mounting bracket\",\"room solutions\",\"cable management\",\"VESA mount\"]', '{\"Dimensi\":{\"Tinggi\":\"35 mm\",\"Lebar\":\"164 mm\",\"Tebal\":\"350 mm\"},\"Kompatibilitas\":{\"Logitech RoomMate\":\"Ya\",\"Komputer SFF\":\"Ya, dengan pola VESA 100x100 atau 75x75\"},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Compute Mount dirancang untuk menyimpan perangkat komputasi dengan rapi dan aman, ideal untuk ruang video conferencing.</p>', '[{\"name\":\"Isi Kemasan\",\"value\":\"Compute Mount dengan Jepitan Penyimpanan Kabel\",\"additional\":\"Mounting Hardware, Dokumentasi\"},{\"name\":\"Dukungan\",\"value\":\"Temukan semua dokumentasi yang kami sediakan agar bisa segera menjalankan produk ini.\",\"additional\":\"\"},{\"name\":\"Penyangga Kabel Terintegrasi\",\"value\":\"Jepitan penyangga kabel mengurangi tegangan kabel dan menjaga koneksi tetap kencang dan aman.\",\"additional\":\"Kompatibel dengan pola VESA 100x100 atau 75x75.\"},{\"name\":\"Rancangan Tersembunyi\",\"value\":\"Compute Mount mencakup hardware untuk menyangga RoomMate atau perangkat komputasi lainnya yang kompatibel agar tidak terlihat dan tetap aman.\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Mounting bracket ini dilengkapi dengan penyimpanan kabel dan kompatibel dengan Logitech RoomMate serta perangkat SFF lainnya.</p>', 1, 0, 0, '2026-02-20 01:04:09', '2026-02-20 01:04:09'),
(9, 1, 1, 'Logitech Rally Camera Conference Cameras', 'logitech-rally-camera-conference-cameras', '<h4>Deskripsi Produk</h4><p>Logitech Conference Cameras adalah lini kamera konferensi video profesional yang dirancang untuk berbagai ukuran ruang rapat, mulai dari huddle room kecil hingga ruang konferensi besar. Kamera ini menghadirkan kualitas video tinggi, teknologi auto-framing pintar, dan integrasi mudah dengan platform seperti Microsoft Teams, Zoom, dan Google Meet.</p><h4>Fitur Utama</h4><ul><li><strong>Kualitas Video HD hingga 4K:</strong> Gambar tajam dan jernih untuk pengalaman meeting yang profesional.</li><li><strong>Auto-Framing & AI:</strong> Teknologi RightSight™ yang secara otomatis memusatkan peserta.</li><li><strong>Plug-and-Play USB:</strong> Instalasi cepat tanpa konfigurasi rumit.</li><li><strong>Kompatibilitas Platform:</strong> Tersertifikasi untuk Teams, Zoom, dan Google Meet.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Resolusi: Hingga 4K (tergantung model)</li><li>Koneksi: USB atau Appliance Mode</li><li>Field of View: Wide-angle hingga PTZ (tergantung model)</li><li>Kompatibilitas: Windows, macOS, dan platform meeting utama</li></ul>', 'products/logitech-rally-camera-conference-cameras/logitech-rally-camera-conference-cameras-2026-1771574649.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', NULL, NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/rally-camera.pdf', '[\"kamera konferensi\",\"video conferencing\",\"ruang meeting\",\"speakerphone\",\"sistem video\",\"kontroler sentuh\",\"solusi ruang\"]', '{\"Dimensi\":{\"Tinggi\":\"\",\"Lebar\":\"\",\"Panjang\":\"\"},\"Berat\":\"\",\"Persyaratan Sistem\":\"\",\"Kompatibilitas\":{\"Windows\":\"\",\"Mac\":\"\",\"Linux\":\"\"},\"Sertifikasi\":\"\",\"Daya\":\"\",\"Lingkungan\":\"\"}', '<h4>Spesifikasi Utama</h4><p>Kamera ruang konferensi dengan sistem audio dan video yang terintegrasi, ideal untuk berbagai jenis ruang meeting.</p>', '[{\"name\":\"All-in-one video bar\",\"value\":\"Sistem video conferencing yang mudah disiapkan\",\"additional\":\"\"},{\"name\":\"Speakerphone\",\"value\":\"Menyediakan audio yang jelas\",\"additional\":\"\"},{\"name\":\"Kontroler sentuh\",\"value\":\"Memudahkan pengaturan rapat\",\"additional\":\"\"},{\"name\":\"Kamera PTZ\",\"value\":\"Kontrol kamera otomatis\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>All-in-one video bar dengan speakerphone dan kontroler sentuh untuk pengalaman rapat yang lebih baik.</p>', 1, 0, 0, '2026-02-20 01:04:09', '2026-02-20 01:04:09'),
(10, 1, 1, 'Logitech ConferenceCam Connect', 'logitech-conferencecam-connect', '<h4>Deskripsi Produk</h4><p>Logitech ConferenceCam Connect adalah solusi konferensi video portabel berbentuk silinder yang elegan dan fleksibel. Perangkat ini dirancang untuk mobilitas tinggi dengan baterai isi ulang internal, menjadikannya ideal untuk ruangan kecil atau rapat dadakan di mana saja. Connect juga dapat berfungsi sebagai speakerphone Bluetooth mandiri dan memiliki kemampuan mirroring layar nirkabel pada perangkat yang kompatibel.</p><h4>Fitur Utama</h4><ul><li><strong>Portabilitas Tinggi:</strong> Baterai isi ulang tahan hingga 3 jam (video) atau 15 jam (audio).</li><li><strong>Bluetooth & NFC:</strong> Mudah dipasangkan ke ponsel untuk panggilan audio berkualitas tinggi.</li><li><strong>Lensa Premium:</strong> Lensa Carl Zeiss dengan autofocus dan 4x digital zoom.</li><li><strong>Remote Control:</strong> Remote yang juga berfungsi sebagai penutup lensa magnetik saat tidak digunakan.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Resolusi: 1080p Full HD</li><li>Field of View: 90 derajat</li><li>Audio: Suara 360 derajat dengan jangkauan 3.6 meter</li><li>Konektivitas: USB, Bluetooth, NFC</li></ul>', 'products/logitech-conferencecam-connect/logitech-conferencecam-connect-2026-1771574649.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001035', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/connect-datasheet.pdf', '[\"webcam\",\"logitech conferencecam\",\"video conferencing\",\"portable camera\",\"bluetooth speakerphone\",\"huddle room\",\"home office\"]', '{\"Dimensi\":{\"Unit utama\":{\"Tinggi\":\"304,2 mm\",\"Lebar\":\"75 mm\",\"Tebal\":\"75 mm\",\"Berat\":\"766 g\"},\"Remote Control\":{\"Tinggi\":\"128 mm\",\"Lebar\":\"41 mm\",\"Tebal\":\"9 mm\",\"Berat\":\"32 g\"}},\"Spesifikasi Teknis\":{\"Kamera\":{\"Panggilan video\":\"Full HD 1080p (hingga 1920 x 1080 piksel); panggilan video 720p HD (hingga 1280 x 720 piksel) dengan klien yang didukung\",\"H.264 UVC\":\"1.5 dengan Scalable Video Coding (SVC)\",\"Dukungan\":\"H.264 SVC 1080p, bersama dengan optimisasi untuk kinerja panggilan terbaik dalam video HD dengan satu atau beberapa pihak\"},\"Bidang Pandang\":{\"Diagonal\":\"90\\u00b0\",\"Horizontal\":\"82,1\\u00b0\",\"Vertikal\":\"52,2\\u00b0\",\"Zoom\":\"4X digital zoom\",\"Teknologi\":\"RightLight\\u2122 2 untuk kejernihan dalam berbagai lingkungan pencahayaan, bahkan dalam cahaya redup\",\"Fungsi\":\"pan (geser), tilt (miring), dan zoom digital dari remote control atau aplikasi opsional yang dapat didownload\",\"Mechanical tilt wheel\":\"Ya\",\"LED Kamera\":\"untuk indikasi streaming sedang aktif\"},\"Speakerphone\":{\"Tipe\":\"Speakerphone full duplex terintegrasi dengan echo dan noise cancellation\",\"Audio\":\"Wideband audio 360\\u00b0\",\"Konektivitas\":\"Berkemampuan Bluetooth dan NFC\",\"LED\":\"untuk streaming speakerphone, mematikan suara, menunda panggilan, dan pairing Bluetooth\",\"Kontrol\":\"untuk menjawab\\/mengakhiri panggilan, volume, dan mute\"},\"Mikrofon\":{\"Tipe\":\"Dua mikrofon omni-directional mencakup jangkauan seluas diameter 3,6 meter\",\"Respons Frekuensi\":\"100Hz \\u2013 16KHz\",\"Sensitivitas\":\"34 dB +\\/- 3 dB\",\"Distorsi\":\"<1% @ 1kHz pada 65 dB\"},\"Speaker\":{\"Respons Frekuensi\":\"140Hz \\u2013 16KHz\",\"Sensitivitas\":\"89 dBSPL +\\/-3 dB pada 1 W\\/0,5 M\",\"Output maks.\":\"91,5 dBSPL pada 0,5 m\",\"Distorsi\":\"<5% dari 200Hz\"},\"Remote Control\":{\"Fungsi\":\"Dapat dipasangkan ke perangkat dan berfungsi sebagai cover lensa\",\"Jangkauan IR\":\"3 m\",\"Baterai\":\"CR2032 (disertakan)\"},\"Kabel\\/Daya\":{\"Adaptor\":\"Adaptor Daya AC dengan plug regional\",\"Kabel\":\"USB 1,8 m\",\"Baterai\":\"isi ulang yang terintegrasi\"},\"MOUNT\":{\"Tipe\":\"Didesain untuk digunakan di atas meja\",\"Kensington security slot\":\"Ya\"},\"KOMPATIBILITAS DAN SERTIFIKASI\":{\"Konektivitas\":\"USB plug-and-play\",\"Sertifikasi\":[\"Skype for Business\",\"Microsoft\\u00ae Teams\",\"Zoom\",\"Fuze\\u00ae\"],\"Kompatibilitas\":[\"Google Meet\\u00ae\",\"Cisco Jabber\",\"WebEX\",\"BlueJeans\",\"BroadSoft\",\"GoToMeeting\",\"Vidyo\",\"aplikasi video conferencing, recording, and broadcasting lainnya yang mendukung kamera USB\"]}}}', '<h4>Spesifikasi Utama</h4><p>Logitech ConferenceCam Connect adalah solusi video conferencing yang ideal untuk ruang berkumpul, kantor di rumah, dan perjalanan. Dengan desain portabel dan fitur canggih, Anda dapat melakukan panggilan video berkualitas tinggi di mana saja.</p>', '[{\"name\":\"Panggilan Video\",\"value\":\"Full HD 1080p\",\"additional\":\"Hingga 1920 x 1080 piksel\"},{\"name\":\"Bluetooth dan NFC\",\"value\":\"Ya\",\"additional\":\"Konektivitas tanpa kabel\"},{\"name\":\"Wideband Audio\",\"value\":\"360\\u00b0\",\"additional\":\"Audio jernih di seluruh ruangan\"},{\"name\":\"Remote Control\",\"value\":\"Ya\",\"additional\":\"Dapat berfungsi sebagai cover lensa\"},{\"name\":\"Baterai Isi Ulang\",\"value\":\"3 jam untuk video, 15 jam untuk audio\",\"additional\":\"Daya portabel\"},{\"name\":\"Plug-and-Play\",\"value\":\"Ya\",\"additional\":\"Tanpa memerlukan software tambahan\"},{\"name\":\"Kensington Security Slot\",\"value\":\"Ya\",\"additional\":\"Perlindungan dari pencurian\"}]', '<h4>Fitur Unggulan</h4><p>ConferenceCam Connect dilengkapi dengan speakerphone Bluetooth, dua mikrofon omni-directional, dan kemampuan video Full HD, menjadikannya pilihan sempurna untuk kolaborasi jarak jauh.</p>', 1, 0, 0, '2026-02-20 01:04:09', '2026-02-20 01:04:09'),
(11, 1, 1, 'Logitech Desk Booking', 'logitech-desk-booking', '<h4>Deskripsi Produk</h4><p>Logitech Desk Booking (Logi Dock Flex) adalah docking station pintar yang dikelola untuk manajemen ruang kerja modern dan hot desking. Perangkat ini menampilkan layar sentuh 8 inci yang menunjukkan status reservasi meja, nama pengguna, dan jadwal. Saat laptop dihubungkan, perangkat ini otomatis melakukan check-in dan menghubungkan pengguna ke monitor ganda, jaringan, dan periferal meja sekaligus mengisi daya laptop.</p><h4>Fitur Utama</h4><ul><li><strong>Layar Sentuh 8 Inci:</strong> Menampilkan status booking meja, foto, dan info pengguna secara jelas.</li><li><strong>Satu Kabel untuk Semua:</strong> Menghubungkan laptop ke layar, internet, dan aksesori sekaligus mengisi daya.</li><li><strong>Manajemen IT:</strong> Dapat dipantau dan dikelola jarak jauh via Logitech Sync.</li><li><strong>Integrasi Software:</strong> Bekerja dengan Microsoft Teams, Zoom Workspace, dan Appspace.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Layar: 8 inch IPS LCD (1280 x 800)</li><li>Ports: 2x HDMI/DisplayPort (Dual 4K), 6x USB ports, Gigabit Ethernet</li><li>Daya Laptop: Hingga 100W via USB-C</li></ul>', 'products/logitech-desk-booking/logitech-desk-booking-2026-1771574650.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', NULL, NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/deskbooking-datasheet.pdf', '[\"logitech desk booking\",\"reservasi meja\",\"solusi kantor\",\"manajemen ruang\",\"fleksibilitas kerja\",\"integrasi kalender\",\"analisis penggunaan\"]', '{\"Dimensi\":{\"Tinggi\":\"N\\/A\",\"Lebar\":\"N\\/A\",\"Panjang\":\"N\\/A\"},\"Berat\":\"N\\/A\",\"Persyaratan Sistem\":\"N\\/A\",\"Kompatibilitas\":{\"Windows\":\"Ya\",\"Mac\":\"Ya\",\"Linux\":\"N\\/A\"},\"Sertifikasi\":\"N\\/A\",\"Daya\":\"N\\/A\",\"Lingkungan\":{\"Suhu Operasional\":\"N\\/A\",\"Kelembapan\":\"N\\/A\"}}', '<h4>Spesifikasi Utama</h4><p>Logitech Desk Booking menawarkan solusi reservasi meja yang efisien dan terintegrasi dengan alat yang sudah ada.</p>', '[{\"name\":\"Reservasi Meja\",\"value\":\"Ya\",\"additional\":\"Melalui Logi Tune\"},{\"name\":\"Integrasi Kalender\",\"value\":\"Ya\",\"additional\":\"Dengan Office365 & Google Workspace\"},{\"name\":\"Kebijakan Reservasi\",\"value\":\"Ya\",\"additional\":\"Dapat disesuaikan\"},{\"name\":\"Manajemen Pengguna SCIM\",\"value\":\"Ya\",\"additional\":\"Integrasi dengan direktori pengguna\"},{\"name\":\"Logitech View\",\"value\":\"Ya\",\"additional\":\"Memerlukan RoomMate\"},{\"name\":\"Penggunaan Meja dan Wawasan\",\"value\":\"Ya\",\"additional\":\"Analisis penggunaan meja\"},{\"name\":\"Keamanan Standar Perusahaan\",\"value\":\"Ya\",\"additional\":\"Enkripsi end-to-end\"},{\"name\":\"Multitenancy\",\"value\":\"Ya\",\"additional\":\"Mengelola beberapa organisasi\"},{\"name\":\"Sign-on Tunggal\",\"value\":\"Ya\",\"additional\":\"Kemudahan akses\"},{\"name\":\"Manajemen Sumber Daya\",\"value\":\"Ya\",\"additional\":\"Notifikasi koneksi terputus\"}]', '<h4>Fitur Unggulan</h4><p>Memudahkan karyawan untuk memesan meja dan mengelola ruang kerja dengan efisien.</p>', 1, 0, 0, '2026-02-20 01:04:09', '2026-02-20 01:04:10'),
(12, 1, 1, 'Logitech Easy Clean Cover', 'logitech-easy-clean-cover', '<h4>Deskripsi Produk</h4><p>Logitech Easy Clean Cover adalah aksesori pelindung berbahan kain khusus yang dirancang untuk Rally Bar Huddle. Cover ini membantu melindungi permukaan depan perangkat dari debu, noda, dan percikan cairan, sekaligus memudahkan proses pembersihan rutin di ruang meeting dengan standar kebersihan tinggi seperti ruang kesehatan atau ruang publik.</p><h4>Fitur Utama</h4><ul><li><strong>Mudah Dibersihkan:</strong> Material kain yang dirancang untuk dibersihkan dengan cepat dan efisien.</li><li><strong>Perlindungan Tambahan:</strong> Membantu menjaga perangkat tetap higienis dan tahan lama.</li><li><strong>Desain Presisi:</strong> Dibuat khusus agar pas dengan Rally Bar Huddle.</li><li><strong>Estetika Profesional:</strong> Menyatu dengan desain modern ruang meeting.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Logitech Rally Bar Huddle</li><li>Material: Kain khusus mudah dibersihkan</li><li>Warna: Graphite / Off-White (tergantung varian)</li></ul>', 'products/logitech-easy-clean-cover/logitech-easy-clean-cover-2026-1771574650.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000146', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/rallybar-huddle-accessories-datasheet.pdf', '[\"cover mudah dibersihkan\",\"rally bar huddle\",\"aksesori video conference\",\"sanitasi\",\"perlindungan perangkat\",\"Logitech\",\"video conferencing\"]', '{\"Dimensi\":{\"Panjang\":\"549,4 mm\",\"Lebar\":\"79 mm\",\"Tinggi\":\"15,2 mm\"},\"Berat\":\"158 g\",\"Kompatibilitas\":\"Kompatibel hanya dengan Rally Bar Huddle\",\"Sertifikasi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Cover ini dirancang untuk memudahkan pembersihan dan menjaga kebersihan perangkat video conference Anda.</p>', '[{\"name\":\"Cover yang Mudah Dibersihkan\",\"value\":\"Dapat digunakan untuk sanitasi\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Cover ini tidak hanya melindungi perangkat Anda tetapi juga mudah dibersihkan untuk menjaga kebersihan di ruang pertemuan.</p>', 1, 0, 0, '2026-02-20 01:04:10', '2026-02-20 01:04:10'),
(13, 1, 1, 'Logitech Extend', 'logitech-extend', '<h4>Deskripsi Produk</h4><p>Logitech Extend adalah solusi infrastruktur cerdas untuk ruang rapat berbasis Android atau BYOD. Sistem ini memecahkan masalah kabel yang berantakan dengan menggunakan kabel kategori (Cat5e/Cat6) standar untuk menghubungkan perangkat di meja ke perangkat di layar hingga jarak 100 meter. Ini memungkinkan pengguna berjalan masuk, mencolokkan satu kabel USB-C ke laptop mereka, dan langsung mengambil alih kamera serta layar ruangan.</p><h4>Fitur Utama</h4><ul><li><strong>Single Cable BYOD:</strong> Satu kabel USB-C membawa sinyal video, data, dan kontrol sekaligus.</li><li><strong>Long Distance:</strong> Menggunakan kabel ethernet standar untuk jangkauan hingga 100m antara hub meja dan layar.</li><li><strong>Instalasi Bersih:</strong> Menghilangkan kebutuhan akan kabel HDMI dan USB panjang yang menjuntai.</li><li><strong>Passthrough:</strong> Memungkinkan laptop mengontrol Rally Bar atau sistem kamera ruangan secara langsung.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Komponen: Kotak TX (Table) dan Kotak RX (Display)</li><li>Koneksi Antar Box: RJ45 (Kabel LAN standar)</li><li>Koneksi User: USB-C (dengan dukungan DisplayPort Alt Mode)</li></ul>', 'products/logitech-extend/logitech-extend-2026-1771574652.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000200', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/logitech-extend-datasheet.pdf', '[\"video conferencing\",\"USB-C connector\",\"Logitech Extend\",\"BYOD solution\",\"meeting room technology\",\"video conferencing accessories\",\"Logitech Sync\"]', '{\"Dimensi\":{\"Tinggi\":\"143 mm\",\"Lebar\":\"143 mm\",\"Tebal\":\"34,5 mm\"},\"Kompatibilitas\":{\"Memerlukan\":{\"Perlengkapan Ruang Rapat\":{\"Layar\":\"HDMI 1.4 atau versi terbaru\",\"Perangkat AV\":\"USB Type-A 2.0 atau versi terbaru\"},\"Komputer Laptop\":{\"Port\":\"USB Type-C dengan DisplayPort Alt Mode\"}},\"Kompatibel dengan\":{\"Kamera Conferencing\":\"Rally Bar, Rally Bar Mini, Rally Bar Huddle, MeetUp, MeetUp 2, dan masih banyak lagi\",\"Sistem Operasi Laptop\":\"Windows 10, Windows 11, macOS (2 versi terbaru)\"}},\"Sertifikasi\":{\"Keamanan\":{\"Enkripsi Berbasis File\":\"NIST SHA-256 bit\",\"Enkripsi Data\":\"Hash Kunci Publik\",\"Pembaruan Firmware\":\"Tanda Tangan Digital\"}},\"Daya\":{\"Catu daya\":\"Auto-sensing\",\"Voltase Operasi\\/Daya\":\"100-240V, 48V, 0,5A\",\"Dimensi Catu Daya\":\"73,5 mm x 53 mm x 35 mm\",\"Kabel DC\":\"1,5 m\",\"Kabel USB-C ke USB-C 3.2 Gen 1\":\"1,5 m\",\"Kabel USB A ke Micro USB\":\"1 m\"},\"Lingkungan\":{\"Suhu Pengoperasian\":\"0\\u00b0 hingga 40\\u00b0 C\",\"Suhu Penyimpanan\":\"-25\\u00b0 hingga 70\\u00b0 C\",\"Kelembapan\":\"10% hingga 90%\"},\"Keberlanjutan\":{\"Dibuat dengan plastik daur ulang\":\"Logitech Extend konten plastik: Minimum 40% bahan Post-Consumer Recycled (PCR)\",\"Kemasan yang Ramah Lingkungan\":\"Kemasan kertas bersertifikasi FSC\\u2122\"}}', '<h4>Spesifikasi Utama</h4><p>Logitech Extend memungkinkan koneksi mudah ke ruang video conferencing dengan satu kabel USB-C, mendukung berbagai perangkat dan sistem operasi.</p>', '[{\"name\":\"Konektor BYOD\",\"value\":\"Dioptimalkan untuk ruangan berbasis Android dan BYOD\",\"additional\":\"\"},{\"name\":\"Pengiriman Daya\",\"value\":\"Hingga 100W (disediakan pengguna)\",\"additional\":\"\"},{\"name\":\"Manajemen Perangkat\",\"value\":\"Manajemen perangkat Logitech Sync\",\"additional\":\"\"},{\"name\":\"Pemasangan\",\"value\":\"VESA: 100 x 100 mm\",\"additional\":\"Dua lubang tembus untuk pemasangan langsung ke dinding atau meja\"},{\"name\":\"Kabel Tunggal\",\"value\":\"Kesederhanaan kabel tunggal \\u2014 tidak memerlukan beberapa kabel, adaptor, atau dongle.\",\"additional\":\"\"},{\"name\":\"Dock Magnetik\",\"value\":\"Letakkan kabel USB-C di dock magnetik yang disertakan untuk meja yang bersih.\",\"additional\":\"\"},{\"name\":\"Adaptor Grommet\",\"value\":\"Jalankan kabel USB-C dengan mudah melalui meja dengan adaptor yang disertakan.\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Dengan Logitech Extend, Anda dapat menghubungkan perangkat Anda dengan cepat dan mudah, tanpa perlu driver tambahan.</p>', 1, 0, 0, '2026-02-20 01:04:10', '2026-02-20 01:04:12'),
(14, 1, 1, 'Logitech Group 10m Extended Cable', 'logitech-group-10m-extended-cable', '<h4>Deskripsi Produk</h4><p>Logitech Group 10m Extended Cable adalah kabel perpanjangan resmi yang dirancang untuk sistem video conference Logitech Group. Kabel ini memungkinkan fleksibilitas instalasi dengan memperpanjang jarak antara hub dan kamera atau speakerphone, ideal untuk ruang meeting dengan tata letak besar atau konfigurasi kompleks.</p><h4>Fitur Utama</h4><ul><li><strong>Perpanjangan 10 Meter:</strong> Memberikan fleksibilitas tambahan dalam penempatan perangkat.</li><li><strong>Kualitas Sinyal Stabil:</strong> Dirancang untuk menjaga performa audio dan video tetap optimal.</li><li><strong>Instalasi Profesional:</strong> Cocok untuk routing kabel melalui meja atau dinding.</li><li><strong>Kompatibilitas Khusus:</strong> Untuk sistem Logitech Group.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Panjang: 10 meter</li><li>Kompatibilitas: Logitech Group System</li><li>Tipe Kabel: Proprietary extension cable</li></ul>', 'products/logitech-group-10m-extended-cable/logitech-group-10m-extended-cable-2026-1771574653.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '939-001487', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/group-10m-extended-cable.pdf', '[\"kabel perpanjangan\",\"logitech group\",\"ruang konferensi\",\"aksesori video konferensi\",\"kabel din\",\"konferensi jarak jauh\",\"solusi konferensi\"]', '{\"Dimensi\":{\"Tebal\":\"10 meter\",\"Ketebalan Kabel\":\"4 mm\",\"Panjang Repeater\":\"50 mm\",\"Ketebalan Repeater\":\"12 mm\"},\"Berat\":\"278 g\",\"Kompatibilitas\":{\"Logitech GROUP\":\"Ya\"},\"Kepatuhan\":{\"Emisi\":\"FCC Class (A), CE\",\"Peraturan\":\"RoHS\",\"Mudah Terbakar\":\"UL\\/CSA Type CM, VW-1\"},\"Garansi\":\"Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Kabel 10 meter ini ideal untuk ruang konferensi besar dan menggantikan kabel DIN 5 meter yang disertakan dengan Logitech GROUP.</p>', '[{\"name\":\"Jenis Koneksi\",\"value\":\"Mini-DIN-6\",\"additional\":\"\"},{\"name\":\"Isi Kemasan\",\"value\":\"Satu Kabel DIN 10m, Tali Pengelolaan Kabel Velcro\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Kabel ini memungkinkan pengaturan ruangan konferensi yang lebih fleksibel dengan panjang 10 meter.</p>', 1, 0, 0, '2026-02-20 01:04:12', '2026-02-20 01:04:13');
INSERT INTO `products` (`id`, `service_id`, `brand_id`, `name`, `slug`, `description`, `image_path`, `thumbnail_path`, `price`, `link_accommerce`, `whatsapp_note`, `sku`, `solution_type`, `datasheet_url`, `tags`, `specs`, `specification_text`, `features`, `features_text`, `is_active`, `is_featured`, `is_new`, `created_at`, `updated_at`) VALUES
(15, 1, 1, 'Logitech Group 15m Extended Cable', 'logitech-group-15m-extended-cable', '<h4>Deskripsi Produk</h4><p>Logitech Group 15m Extended Cable adalah kabel perpanjangan tambahan untuk sistem Logitech Group yang dirancang untuk ruang konferensi besar. Dengan panjang 15 meter, kabel ini memungkinkan penempatan kamera dan hub secara fleksibel tanpa mengurangi kualitas koneksi.</p><h4>Fitur Utama</h4><ul><li><strong>Perpanjangan 15 Meter:</strong> Ideal untuk ruang meeting besar atau boardroom.</li><li><strong>Stabil dan Andal:</strong> Menjaga integritas sinyal audio dan video.</li><li><strong>Instalasi Rapi:</strong> Mendukung manajemen kabel profesional.</li><li><strong>Kompatibilitas Resmi:</strong> Dirancang khusus untuk Logitech Group.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Panjang: 15 meter</li><li>Kompatibilitas: Logitech Group System</li><li>Tipe Kabel: Proprietary extension cable</li></ul>', 'products/logitech-group-15m-extended-cable/logitech-group-15m-extended-cable-2026-1771574653.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '939-001490', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/group-15m-extended-cable.pdf', '[\"kabel perpanjangan\",\"logitech group\",\"konferensi video\",\"aksesori konferensi\",\"kabel din\",\"instalasi ruang konferensi\",\"perangkat video konferensi\"]', '{\"Dimensi\":{\"Tebal\":\"15 m\",\"Ketebalan Kabel\":\"5 mm\",\"Panjang Repeater\":\"50 mm\",\"Ketebalan Repeater\":\"12 mm\"},\"Berat\":\"510 g\",\"Spesifikasi Teknis\":{\"Jenis Koneksi\":\"Mini-DIN-6\",\"Kepatuhan\":{\"Emisi\":\"FCC Class (A), CE\",\"Peraturan\":\"RoHS\",\"Mudah Terbakar\":\"UL\\/CSA Tipe CMP\"}},\"Kompatibilitas\":{\"Logitech GROUP\":\"Ya\"},\"Isi Kemasan\":[\"Satu Kabel DIN 15m\",\"Tali Pengelolaan Kabel Velcro\"],\"Garansi\":\"Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Kabel Perpanjangan Logitech GROUP 15m dirancang untuk meningkatkan jarak koneksi dalam ruang konferensi besar, dengan ketebalan kabel yang optimal dan koneksi yang stabil.</p>', '[{\"name\":\"Panjang Kabel\",\"value\":\"15 m\",\"additional\":\"Mendukung konferensi video di ruangan yang lebih besar\"},{\"name\":\"Ketebalan Kabel\",\"value\":\"5 mm\",\"additional\":\"Kabel yang kuat dan tahan lama\"},{\"name\":\"Jenis Koneksi\",\"value\":\"Mini-DIN-6\",\"additional\":\"Koneksi yang stabil untuk perangkat Logitech\"},{\"name\":\"Kepatuhan\",\"value\":\"FCC Class (A), CE\",\"additional\":\"Mematuhi standar emisi\"},{\"name\":\"Mudah Terbakar\",\"value\":\"UL\\/CSA Tipe CMP\",\"additional\":\"Aman untuk instalasi di ruang konferensi\"},{\"name\":\"Garansi\",\"value\":\"2 Tahun\",\"additional\":\"Garansi hardware terbatas\"}]', '<h4>Fitur Unggulan</h4><p>Kabel ini menawarkan panjang 15 m, ketebalan 5 mm, dan koneksi Mini-DIN-6, serta memenuhi standar kepatuhan yang ketat.</p>', 1, 0, 0, '2026-02-20 01:04:13', '2026-02-20 01:04:13'),
(16, 1, 1, 'Logitech Group', 'logitech-group', '<h4>Deskripsi Produk</h4><p>Logitech GROUP adalah solusi konferensi video terjangkau untuk ruang rapat ukuran sedang hingga besar (14-20 orang). Sistem ini menggabungkan kamera PTZ (Pan-Tilt-Zoom) berkualitas tinggi dengan speakerphone sejernih kristal. Didesain dengan kemudahan plug-and-play USB, GROUP mengubah ruang rapat biasa menjadi ruang kolaborasi video tingkat perusahaan tanpa biaya selangit.</p><h4>Fitur Utama</h4><ul><li><strong>Video Razor-Sharp:</strong> Lensa premium dengan 10x lossless zoom dan resolusi HD 1080p.</li><li><strong>Audio Full Duplex:</strong> Speakerphone dengan echo cancellation dan noise reduction untuk suara jernih.</li><li><strong>Konektivitas USB:</strong> Kompatibel dengan hampir semua aplikasi video conference (Zoom, Teams, Meet).</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kamera: Pan 260°, Tilt 130°, 10x HD Zoom</li><li>Jangkauan Audio: Standar 6m (dapat diperluas)</li><li>Preset: 5 preset kamera</li></ul>', 'products/logitech-group/logitech-group-2026-1771574654.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', NULL, NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/group-datasheet.pdf', '[\"video conferencing\",\"logitech group\",\"HD video\",\"audio clarity\",\"plug and play\",\"business conferencing\",\"remote control\"]', '{\"Dimensi\":{\"Tinggi\":\"N\\/A\",\"Lebar\":\"N\\/A\",\"Panjang\":\"N\\/A\"},\"Berat\":\"N\\/A\",\"Persyaratan Sistem\":\"N\\/A\",\"Kompatibilitas\":{\"Windows\":\"N\\/A\",\"Mac\":\"N\\/A\",\"Linux\":\"N\\/A\"},\"Sertifikasi\":\"Skype for Business, Microsoft Teams\",\"Daya\":\"N\\/A\",\"Lingkungan\":\"N\\/A\"}', '<h4>Spesifikasi Utama</h4><p>GROUP menawarkan video HD berkualitas tinggi dan audio jernih untuk ruangan meeting berukuran sedang hingga besar.</p>', '[{\"name\":\"Video High-Definition\",\"value\":\"HD 1080p\\/30\",\"additional\":\"10x lossless zoom\"},{\"name\":\"Audio yang Terdengar Alami\",\"value\":\"Full duplex speakerphone\",\"additional\":\"Acoustic echo cancellation\"},{\"name\":\"Konektivitas USB\",\"value\":\"Plug-and-play\",\"additional\":\"Kompatibel dengan software konferensi video\"},{\"name\":\"Speakerphone dengan Bluetooth\",\"value\":\"Cakupan 360\\u00b0\",\"additional\":\"Empat mikrofon omnidirectional\"},{\"name\":\"Kontrol yang Nyaman\",\"value\":\"Remote control genggam\",\"additional\":\"Layar status LCD\"},{\"name\":\"Opsi Memberikan Kedayagunaan\",\"value\":\"Perpanjangan mikrofon opsional\",\"additional\":\"Jangkauan audio hingga 8,5 meter\"},{\"name\":\"MUTE dengan Percaya Diri\",\"value\":\"Tombol mute sensitif\",\"additional\":\"Cincin status LED\"}]', '<h4>Fitur Unggulan</h4><p>Dengan teknologi canggih, GROUP memudahkan kolaborasi dalam setiap pertemuan.</p>', 1, 0, 0, '2026-02-20 01:04:13', '2026-02-20 01:04:14'),
(17, 1, 1, 'Logitech Group Expansion Mics', 'logitech-group-expansion-mics', '<h4>Deskripsi Produk</h4><p>Logitech GROUP Expansion Microphones dirancang untuk memperluas jangkauan audio sistem Logitech GROUP. Dengan menambahkan dua mikrofon ini, Anda dapat mengakomodasi kelompok yang lebih besar (hingga 20 orang) dalam satu ruangan. Kabel yang panjang memungkinkan penempatan mikrofon yang fleksibel di ujung meja konferensi yang panjang.</p><h4>Fitur Utama</h4><ul><li><strong>Jangkauan Luas:</strong> Memperluas jangkauan penangkapan suara dari 6 meter menjadi 8.5 meter.</li><li><strong>Mudah Digunakan:</strong> Cukup colokkan ke speakerphone GROUP dan langsung aktif (plug-and-play).</li><li><strong>Kontrol Mute:</strong> Tombol bisu mikrofon yang mudah diakses di setiap unit.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Tipe Koneksi: Plug-and-play proprietari</li><li>Panjang Kabel: 2.4 meter per mikrofon</li><li>Pickup Voice: 360 derajat</li></ul>', 'products/logitech-group-expansion-mics/logitech-group-expansion-mics-2026-1771574654.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '989-000171', NULL, 'https://www.wordtext.com.ph/wp-content/uploads/2019/01/Logitech_Group_Expansion_Mic.pdf', '[\"microphone\",\"logitech group\",\"video conferencing\",\"expansion mic\",\"conference room\",\"audio equipment\",\"business communication\"]', '{\"Dimensi\":{\"Tinggi\":\"83 mm\",\"Lebar\":\"83 mm\",\"Tebal\":\"21 mm\"},\"Berat\":\"230 g\",\"Kompatibilitas\":{\"Logitech GROUP\":\"\"},\"Spesifikasi Teknis\":{\"Jenis Koneksi\":\"Plug-and-play\",\"Lampu Indikator (LED)\":\"LED untuk menunjukkan streaming video, mute pada mikrofon, on-hold, dan pairing Bluetooth.\",\"Jenis Mikrofon\":\"Mono, wideband, noise canceling\",\"Tombol \\/ Switch\":\"Mikrofon mute\"},\"Garansi\":\"Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>GROUP Expansion Mics dirancang untuk meningkatkan pengalaman konferensi video dengan jangkauan suara yang lebih baik di ruangan besar.</p>', '[{\"name\":\"Isi Kemasan\",\"value\":\"Dua perpanjangan mikrofon\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Mikrofon ini mudah dipasang dan memiliki indikator LED untuk status koneksi dan mute.</p>', 1, 0, 0, '2026-02-20 01:04:14', '2026-02-20 01:04:14'),
(18, 1, 1, 'Logitech Rally Mic Pod Hub', 'logitech-rally-mic-pod-hub', '<h4>Deskripsi Produk</h4><p>Logitech Rally Mic Pod Hub memberikan fleksibilitas instalasi untuk mikrofon dalam sistem Rally atau Rally Plus. Alih-alih menghubungkan mikrofon secara seri (daisy-chain), Hub ini memungkinkan Anda menghubungkan mikrofon dalam konfigurasi bintang. Ini sangat berguna untuk meja berbentuk U atau konfigurasi meja yang unik, menyembunyikan kabel di bawah meja untuk tampilan yang bersih.</p><h4>Fitur Utama</h4><ul><li><strong>Kabel Rapi:</strong> Mengurangi kekacauan kabel di atas meja konferensi.</li><li><strong>Koneksi Fleksibel:</strong> Mendukung hingga 3 Mic Pod atau Hub tambahan per unit.</li><li><strong>Desain Tersembunyi:</strong> Dapat dipasang di bawah meja (mounting hardware disertakan).</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Dimensi: 16 x 102 x 102 mm</li><li>Kompatibilitas: Logitech Rally, Rally Bar, Rally Bar Mini</li><li>Konektor: 1x 12-pin input, 3x 12-pin output</li></ul>', 'products/logitech-rally-mic-pod-hub/logitech-rally-mic-pod-hub-2026-1771574654.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '939-001647', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/rally-accessories-datasheet.pdf', '[\"rally mic pod\",\"logitech video conferencing\",\"conference room solutions\",\"microphone hub\",\"audio conferencing\",\"meeting room technology\",\"logitech accessories\"]', '{\"Dimensi\":{\"Tinggi\":\"16 mm\",\"Lebar\":\"102 mm\",\"Tebal\":\"102 mm\"},\"Spesifikasi Teknis\":{\"Koneksi\":\"Tiga koneksi 12-pin untuk setiap kombinasi Hub Rally Mic Pod atau Rally Mic Pod tambahan.\",\"Kabel\":\"Kabel 12-pin sepanjang 2,95 m\",\"Mounting\":\"Mounting hardware di bawah meja.\"},\"Kompatibilitas\":{\"Sistem\":\"Rally, Rally Plus, Rally Bar, atau Rally Bar Mini\",\"Catatan\":\"Hub Rally Mic Pod kompatibel dengan sistem Logitech Rally dan tidak kompatibel dengan USB Rally Camera secara terpisah.\"},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Rally Mic Pod Hub menyediakan fleksibilitas kepada installer untuk mengkustomisasi penataan mikrofon pada hampir semua meja konferensi.</p>', '[{\"name\":\"Kustomisasi Penataan\",\"value\":\"Fleksibilitas untuk mengkustomisasi penataan mikrofon pada hampir semua meja konferensi.\",\"additional\":\"\"},{\"name\":\"Koneksi Tiga\",\"value\":\"Mendukung setiap kombinasi mic pod atau hub tambahan.\",\"additional\":\"\"},{\"name\":\"Kabel Tersembunyi\",\"value\":\"Menghubungkan mic pod melalui grommet pada hub di bawah meja.\",\"additional\":\"\"},{\"name\":\"Mobilitas Mic Pod\",\"value\":\"Memungkinkan pemindahan mic pod tanpa menarik mic pod tetangga.\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Kustomisasi penataan mikrofon dengan koneksi yang mendukung berbagai kombinasi mic pod.</p>', 1, 0, 0, '2026-02-20 01:04:14', '2026-02-20 01:04:14'),
(19, 1, 1, 'Logitech TV Mount for Huddle Rooms', 'logitech-tv-mount-for-huddle-rooms', '<h4>Deskripsi Produk</h4><p>Logitech TV Mount for Huddle Rooms adalah solusi pemasangan yang dirancang untuk menempatkan perangkat konferensi seperti MeetUp di atas atau di bawah layar TV di ruang meeting kecil. Mount ini memanfaatkan pola lubang VESA standar pada TV sehingga tidak memerlukan pengeboran tambahan pada dinding.</p><h4>Fitur Utama</h4><ul><li><strong>Pemasangan VESA:</strong> Kompatibel dengan sebagian besar TV layar datar.</li><li><strong>Instalasi Fleksibel:</strong> Dapat dipasang di atas atau di bawah layar.</li><li><strong>Desain Kokoh:</strong> Menjaga kamera tetap stabil untuk kualitas video optimal.</li><li><strong>Tampilan Rapi:</strong> Integrasi yang menyatu dengan layar TV.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Logitech MeetUp</li><li>Mounting: VESA standard</li><li>Material: Baja kokoh</li></ul>', 'products/logitech-tv-mount-for-huddle-rooms/logitech-tv-mount-for-huddle-rooms-2026-1771574655.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000248', NULL, 'https://www.logitech.com/content/dam/logitech/nl/video-collaboration/pdf/huddle-tv-mount-datasheet.pdf', '[\"logitech\",\"tv mount\",\"rally bar huddle\",\"video conferencing\",\"mounting kit\",\"huddle room solutions\",\"wall mount\"]', '{\"Dimensi\":{\"Tinggi\":\"548 mm\",\"Lebar\":\"36 mm\",\"Tebal\":\"3 mm\"},\"Persyaratan Sistem\":{\"Dukungan\":[\"Rally Bar Huddle Dudukkan Multi\",\"Rally Bar Huddle\"]},\"Kompatibilitas\":{\"Layar\":\"Layar yang dipasang di dinding atau di troli berukuran maksimum 65 inci (diagonal) dengan titik pemasangan VESA\"},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun. Perpanjangan Garansi 1 Tahun dan 3 Tahun tersedia untuk pembelian.\"}', '<h4>Spesifikasi Utama</h4><p>Kit Adaptor TV Mount untuk Rally Bar Huddle memungkinkan pemasangan yang fleksibel dan ramping di atas atau di bawah layar TV Anda.</p>', '[{\"name\":\"Desain\",\"value\":\"Desain ayunan lengan\",\"additional\":\"\"},{\"name\":\"Pemasangan\",\"value\":\"Pasang Rally Bar Huddle di atas atau di bawah layar\",\"additional\":\"\"},{\"name\":\"Isi Kemasan\",\"value\":\"2 Lengan ayun, 2 Washer stainless steel, 2 mur pengunci M4\\/7mm, 2 baut Phillips, Kunci pas 7 mm\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Desain ayunan lengan dan kemudahan pemasangan membuat kit ini ideal untuk ruang huddle dan pertemuan.</p>', 1, 0, 0, '2026-02-20 01:04:14', '2026-02-20 01:04:15'),
(20, 1, 1, 'Logitech Logi Bolt USB Receiver', 'logitech-logi-bolt-usb-receiver', '<h4>Deskripsi Produk</h4><p>Logitech Logi Bolt USB Receiver adalah dongle nirkabel generasi terbaru yang menghadirkan konektivitas aman dan stabil untuk perangkat Logitech yang kompatibel dengan teknologi Logi Bolt. Dirancang untuk lingkungan perusahaan dengan tingkat keamanan tinggi, receiver ini menggunakan enkripsi canggih dan koneksi nirkabel yang andal.</p><h4>Fitur Utama</h4><ul><li><strong>Koneksi Aman:</strong> Enkripsi tingkat perusahaan untuk perlindungan data.</li><li><strong>Kinerja Stabil:</strong> Koneksi nirkabel yang lebih andal dibanding Bluetooth standar.</li><li><strong>Multi-Device:</strong> Dapat menghubungkan beberapa perangkat kompatibel Logi Bolt.</li><li><strong>Plug-and-Play:</strong> Instalasi mudah tanpa konfigurasi rumit.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Koneksi: Logi Bolt Wireless Technology</li><li>Interface: USB-A</li><li>Kompatibilitas: Perangkat Logitech yang mendukung Logi Bolt</li></ul>', 'products/logitech-logi-bolt-usb-receiver/logitech-logi-bolt-usb-receiver-2026-1771574656.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '956-000009, 956-000158', NULL, 'https://www.logitech.com/content/dam/logitech/en/business/pdf/logi-bolt-ebook.pdf', '[\"logi bolt\",\"usb receiver\",\"wireless mouse\",\"wireless keyboard\",\"logitech\",\"connectivity\",\"multi-computer\"]', '{\"Dimensi\":{\"USB Receiver Type A\":{\"Tinggi\":\"6.11 mm\",\"Lebar\":\"14.4 mm\",\"Tebal\":\"18.65 mm\",\"Berat\":\"1.68 g\"},\"USB Receiver Type C\":{\"Tinggi\":\"7 mm\",\"Lebar\":\"12.85 mm\",\"Tebal\":\"14.1 mm\",\"Berat\":\"0.97 g\"}},\"Persyaratan Sistem\":{\"Persyaratan\":\"Tersedia Port USB Tipe-A atau Tipe C\",\"Kompatibilitas\":\"Windows\\u00ae 10, 11 atau versi lebih baru, macOS 10.14 atau versi lebih baru, Linux, ChromeOS\",\"Aplikasi kustomisasi\":\"Memerlukan akses Internet untuk men-download aplikasi kustomisasi opsional Logi Options+. Tersedia pada Windows dan macOS di logi.com\\/optionsplus\",\"Penting\":\"Fungsi dasar perangkat wireless Logi Bolt akan didukung tanpa driver tambahan pada ChromeOS dan distribusi Linux yang paling populer.\"},\"Informasi Garansi\":\"Garansi Hardware Terbatas 1 Tahun\",\"Nomor Komponen\":{\"Graphite Tipe USB A\":\"956-000009\",\"Graphite Tipe USB C\":\"956-000158\"}}', '<h4>Spesifikasi Utama</h4><p>Receiver USB untuk digunakan dengan mouse dan keyboard wireless Logi Bolt, tersedia dalam konektivitas USB-A dan USB-C.</p>', '[{\"name\":\"Konektivitas\",\"value\":\"USB-A dan USB-C\",\"additional\":\"Mendukung koneksi wireless berkinerja tinggi\"},{\"name\":\"Kompatibilitas\",\"value\":\"Windows, macOS, Linux, ChromeOS\",\"additional\":\"Fungsi dasar tanpa driver tambahan\"},{\"name\":\"Aplikasi Kustomisasi\",\"value\":\"Logi Options+\",\"additional\":\"Memerlukan akses Internet untuk download\"},{\"name\":\"Jejak Karbon\",\"value\":\"0.63 kg CO2e\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Konektivitas yang aman dan berkinerja tinggi untuk perangkat wireless Logi Bolt.</p>', 1, 0, 0, '2026-02-20 01:04:15', '2026-02-20 01:04:17'),
(21, 1, 1, 'Logitech Logi Dock Flex', 'logitech-logi-dock-flex', '<h4>Deskripsi Produk</h4><p>Logi Dock Flex adalah docking station terkelola yang dirancang khusus untuk lingkungan kerja hot-desking (meja bersama). Perangkat ini memungkinkan karyawan memesan meja, melakukan check-in, dan langsung terhubung ke semua periferal meja. Dilengkapi layar sentuh 8 inci, dock ini menampilkan status ketersediaan meja dan jadwal, serta memudahkan tim IT dalam memantau penggunaan perangkat dari jarak jauh.</p><h4>Fitur Utama</h4><ul><li><strong>Desk Booking Display:</strong> Layar 8 inci yang menampilkan nama pengguna dan status reservasi.</li><li><strong>Single Cable Connect:</strong> Menghubungkan laptop ke monitor ganda, jaringan, dan periferal sekaligus mengisi daya.</li><li><strong>Manajemen Kabel:</strong> Desain rapi yang menyembunyikan kabel-kabel kusut di belakang meja.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Layar: 8\" multi-touch (1280 x 800)</li><li>Daya Laptop: Hingga 100W via USB-C</li><li>Ports: 2x USB-C, 2x USB-A, HDMI, DisplayPort, Gigabit Ethernet</li></ul>', 'products/logitech-logi-dock-flex/logitech-logi-dock-flex-2026-1771574658.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '939-002180', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/logi-dock-flex-datasheet.pdf', '[\"logitech dock\",\"video conferencing\",\"desk reservation\",\"logi dock flex\",\"collaboration tools\",\"office technology\",\"workspace management\"]', '{\"Dimensi\":{\"Tinggi\":\"141.2 mm\",\"Lebar\":\"201 mm\",\"Depth\":\"176.9 mm\"},\"Berat\":\"1.0 kg\",\"Persyaratan Sistem\":{\"Windows\":\"Windows 11, Windows 10\",\"Mac\":\"macOS two most recent versions\",\"USB-C\":\"Available USB-C port\"},\"Kompatibilitas\":{\"Platform\":\"Logitech CollabOS\",\"Platform Manajemen\":\"Logitech Sync\"},\"Ports\":{\"Depan\":{\"USB-C\":\"2x (2x7,5w)\",\"USB-A\":\"1x (7,5w)\"},\"Belakang\":{\"USB-C\":\"1x (7,5w)\",\"USB-A\":\"2x (2x7,5w)\",\"HDMI\":\"1x (Dukungan maksimum 4K, yaitu 3840 x 2160 @60Hz HDR)\",\"DisplayPort\":\"1x (Dukungan maksimum 4K, yaitu 3840 x 2160 @60Hz HDR)\",\"RJ45\":\"1x (10\\/100\\/1000)\",\"Koneksi Daya\":\"DC\",\"Koneksi Laptop\":\"1x USB-C, pengisian daya hingga 100 watt\"}},\"Lingkungan\":{\"Suhu Pengoperasian\":\"0 hingga 40\\u00b0C\",\"Kelembaban Pengoperasian\":\"10 to 90%\",\"Suhu Penyimpanan\":\"-40 hingga 70\\u00b0C\",\"Kelembaban Tersimpan\":\"0 to 95%\"},\"Keamanan\":{\"Full Disk Encryption\":\"Port USB yang kosong\",\"Enkripsi Data\":\"Tombol Simetris, PKI\",\"Identitas Perangkat\":\"Dilindungi oleh atestasi perangkat\",\"Perlindungan Tombol\":\"Arm TrustZone, RPMP\",\"Keamanan Perangkat\":\"Kensington Lock\"},\"Keberlanjutan\":{\"Plastik\":\"Plastik daur ulang post-consumer bersertifikat 36%\",\"Aluminimum\":\"Karbon Rendah\",\"Kemasan Kertas\":\"Bersertifikat FSC\\u2122\",\"Netral Karbon\":\"Bersertifikat\"}}', '<h4>Spesifikasi Utama</h4><p>Logi Dock Flex adalah stasiun docking terkelola yang memungkinkan reservasi meja yang mudah dan dipersonalisasi untuk karyawan.</p>', '[{\"name\":\"Ketersediaan meja dengan cepat\",\"value\":\"Layar 8\\u201d dengan jelas menunjukkan status meja dengan cepat.\"},{\"name\":\"Reservasi meja bersama dengan mudah\",\"value\":\"Ketuk untuk membuat reservasi dan klaim meja langsung di meja Anda.\"},{\"name\":\"Kelola ruang dan perangkat dengan mudah\",\"value\":\"Pastikan meja sudah beroperasi penuh kapan pun juga dari lokasi mana pun.\"}]', '<h4>Fitur Unggulan</h4><p>Dengan layar 8” yang jelas, karyawan dapat dengan cepat melihat status meja dan melakukan reservasi dengan mudah.</p>', 1, 0, 0, '2026-02-20 01:04:17', '2026-02-20 01:04:18'),
(22, 1, 1, 'Logitech Logi Dock', 'logitech-logi-dock', '<h4>Deskripsi Produk</h4><p>Logi Dock adalah docking station all-in-one yang dilengkapi dengan kontrol rapat dan speakerphone built-in. Didesain untuk bekerja dari rumah (WFH) atau ruang kerja pribadi, alat ini menyederhanakan meja kerja Anda dengan mengurangi jumlah kabel dan meniadakan kebutuhan akan speaker atau headset tambahan. Tombol kontrol rapat satu sentuhan memudahkan Anda bergabung atau mematikan suara saat meeting online.</p><h4>Fitur Utama</h4><ul><li><strong>Kontrol Rapat:</strong> Tombol fisik untuk join meeting, mute, video on/off, dan volume.</li><li><strong>Speakerphone Kristal:</strong> 6 mikrofon beamforming dan speaker bass-heavy untuk suara jernih.</li><li><strong>Integrasi Kalender:</strong> Lampu indikator memberi tahu saat meeting akan dimulai (via Logi Tune).</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Output Daya: Up to 100W charging</li><li>Kompatibilitas: Teams, Zoom, Google Meet</li><li>Speaker: 2x 55mm neodymium drivers</li></ul>', 'products/logitech-logi-dock/logitech-logi-dock-2026-1771574658.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', NULL, NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/logi-dock-datasheet.pdf', '[\"logitech dock\",\"usb-c docking station\",\"video conferencing\",\"speakerphone\",\"meeting control\",\"audio switching\",\"workspace organization\"]', '{\"Dimensi\":{\"Tinggi\":\"N\\/A\",\"Lebar\":\"N\\/A\",\"Panjang\":\"N\\/A\"},\"Berat\":\"N\\/A\",\"Persyaratan Sistem\":\"N\\/A\",\"Kompatibilitas\":{\"Windows\":\"N\\/A\",\"Mac\":\"N\\/A\",\"Chromebook\":\"Tidak tersedia\"},\"Sertifikasi\":[\"Microsoft Teams\",\"Zoom\",\"Google Meet\",\"Google Voice\"],\"Daya\":{\"Output\":\"100W\"},\"Lingkungan\":{\"Sertifikasi Karbon\":\"Netral karbon\",\"Kemasan\":\"Berasal dari hutan bersertifikasi FSC\\u2122\"}}', '<h4>Spesifikasi Utama</h4><p>Logi Dock adalah stasiun docking USB-C all-in-one yang menyederhanakan video meeting dengan kontrol meeting satu sentuhan dan speakerphone berkualitas tinggi.</p>', '[{\"name\":\"Kontrol Meeting\",\"value\":\"Satu sentuhan untuk bergabung ke meeting\",\"additional\":\"Dukungan untuk integrasi kalender dengan Logi Tune\"},{\"name\":\"Speakerphone\",\"value\":\"Speakerphone berkualitas profesional\",\"additional\":\"Dilengkapi enam mikrofon beamforming\"},{\"name\":\"Audio Switching\",\"value\":\"Mudah berganti audio antara speakerphone dan headset\",\"additional\":\"Dukungan untuk headset Zone\"},{\"name\":\"Pengisian Daya\",\"value\":\"Mengisi daya maksimum lima periferal USB dan dua monitor\",\"additional\":\"Menghilangkan pengisi daya dan kabel yang tidak diperlukan\"}]', '<h4>Fitur Unggulan</h4><p>Logi Dock menawarkan kontrol meeting yang mudah, speakerphone berkualitas profesional, dan kemampuan audio switching yang cerdas.</p>', 1, 0, 0, '2026-02-20 01:04:18', '2026-02-20 01:04:19'),
(23, 1, 1, 'Logitech Logi Tune', 'logitech-logi-tune', '<h4>Deskripsi Produk</h4><p>Logi Tune adalah perangkat lunak manajemen personal yang memungkinkan pengguna mengontrol dan menyesuaikan webcam, headset, dan Logi Dock mereka. Aplikasi ini menempatkan pengaturan penting seperti zoom kamera, filter warna, dan equalizer audio tepat di layar komputer Anda tanpa mengganggu alur kerja. Logi Tune juga menyediakan integrasi kalender untuk notifikasi rapat yang cepat.</p><h4>Fitur Utama</h4><ul><li><strong>Kustomisasi Webcam:</strong> Atur Field of View, warna, kecerahan, dan fokus manual.</li><li><strong>Audio Settings:</strong> Atur sidetone, equalizer mikrofon, dan level noise cancellation.</li><li><strong>Agenda Rapat:</strong> Lihat jadwal harian dan bergabung ke meeting dengan satu klik.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Platform: Windows dan macOS</li><li>Lisensi: Gratis</li><li>Dukungan: Sebagian besar Webcam dan Headset bisnis Logitech terbaru</li></ul>', 'products/logitech-logi-tune/logitech-logi-tune-2026-1771574659.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', NULL, NULL, 'https://www.logitech.com/content/dam/logitech/en/business/pdf/personal-workspace-solutions-guide.pdf', '[\"logitech\",\"logi tune\",\"video conference\",\"software\",\"headset\",\"webcam\",\"mouse\",\"keyboard\"]', '{\"Dimensi\":[],\"Berat\":[],\"Persyaratan_Sistem\":{\"Logi Tune Desktop\":\"Windows 10, 11 \\/ MacOS 12.0\",\"Logi Tune Mobile\":\"iOS 15+, Android 11+\"},\"Kompatibilitas\":[],\"Sertifikasi\":[],\"Daya\":[],\"Lingkungan\":[]}', '<h4>Spesifikasi Utama</h4><p>Logi Tune memberikan kebebasan untuk mempersonalisasi perangkat Anda dan mengelola ruang kerja dengan mudah.</p>', '[{\"name\":\"Pengaturan Headset\",\"value\":\"Kendalikan sepenuhnya pengalaman dengan pengaturan cerdas untuk ANC, sidetone, mic EQ, dan level mic.\",\"additional\":\"\"},{\"name\":\"Pengaturan Webcam\",\"value\":\"Selalu tampil terbaik dengan penyesuaian bingkai, fokus, dan gambar yang dioptimalkan oleh AI.\",\"additional\":\"\"},{\"name\":\"Pengaturan Mouse\",\"value\":\"Sesuaikan setiap tombol untuk alur kerja Anda.\",\"additional\":\"\"},{\"name\":\"Pengaturan Keyboard\",\"value\":\"Dapatkan kontrol penuh atas tata letak keyboard dan sesuaikan pintasan serta tombol.\",\"additional\":\"\"},{\"name\":\"Integrasi Logi Dock\",\"value\":\"Logi Tune terintegrasi dengan mulus dengan Logi Dock dan Logi Dock Flex.\",\"additional\":\"\"},{\"name\":\"Notifikasi Rapat\",\"value\":\"Dapatkan pemberitahuan saat rapat Anda dimulai.\",\"additional\":\"\"},{\"name\":\"Pemesanan Meja\",\"value\":\"Pesan meja, terhubung dengan rekan kerja, dan navigasi kantor.\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Sesuaikan pengaturan perangkat Anda untuk pengalaman kerja yang lebih baik.</p>', 1, 0, 0, '2026-02-20 01:04:19', '2026-02-20 01:04:19'),
(24, 1, 1, 'Logitech LoRaWAN Gateway for Spot Sensor', 'logitech-lorawan-gateway-for-spot-sensor', '<h4>Deskripsi Produk</h4><p>Logitech Spot (sering merujuk pada ekosistem Logitech View atau sensor okupansi) adalah sistem sensor cerdas untuk manajemen ruang kerja modern. Sistem ini memantau penggunaan meja dan ruang rapat secara real-time, memberikan data akurat kepada manajer fasilitas tentang bagaimana kantor digunakan. Data ini membantu optimalisasi ruang dan memudahkan karyawan menemukan tempat duduk yang tersedia melalui peta navigasi.</p><h4>Fitur Utama</h4><ul><li><strong>Real-time Occupancy:</strong> Mendeteksi keberadaan orang di meja atau ruang rapat secara presisi.</li><li><strong>Tanpa Kamera:</strong> Menggunakan sensor (seperti PIR/ToF) untuk menjaga privasi karyawan (bukan kamera pengawas).</li><li><strong>Integrasi Cloud:</strong> Data dikirim ke Logitech Sync atau platform booking untuk analisis.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Konektivitas: LoRaWAN atau Bluetooth (tergantung model gateway)</li><li>Daya: Baterai tahan lama atau USB power</li><li>Pemasangan: Di bawah meja atau langit-langit</li></ul>', 'products/logitech-lorawan-gateway-for-spot-sensor/logitech-lorawan-gateway-for-spot-sensor-2026-1771574659.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '950-000123', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/lorawan-gateway-for-logitech-spot-datasheet.pdf', '[\"LoRaWAN\",\"Logitech Spot\",\"sensor\",\"gateway\",\"Kerlink\",\"video conferencing\",\"IoT\",\"wireless connectivity\",\"smart office\"]', '{\"Dimensi\":{\"Tinggi\":\"160 mm\",\"Lebar\":\"90 mm\",\"Tebal\":\"35 mm\"},\"Berat\":\"162 g\",\"Persyaratan Sistem\":{\"Kompatibilitas\":\"Hanya dengan sensor Logitech Spot\",\"Perangkat lunak tambahan\":\"Perangkat tegar yang memerlukan konfigurasi dan manajemen, lihat hub.sync.logitech.com\\/logitech-spot untuk keterangan lebih lanjut.\"},\"Listrik & Lingkungan\":{\"Catu daya\":\"230VAC\\/12VDC dengan konektor jack yang disediakan 2.5mm\\/5.5mm\",\"Suhu pengoperasian\":\"-20\\u00b0C +55\\u00b0C (hanya untuk gerbang, tanpa catu daya)\",\"Kelembaban\":\"5% hingga 95%\"},\"Port & Antarmuka\":{\"Konektivitas\":\"RJ45\",\"Tombol\":\"Tombol tekan WPS, Tombol Atur Ulang\",\"LED yang dapat diprogram\":\"1 x LED (hijau\\/merah) untuk status Daya, 1 LED (hijau\\/merah) untuk status Backhaul, 1 LED (hijau\\/merah) untuk aktivitas rf LoRa Rx\\/Tx\",\"USB (Type A)\":\"untuk konfigurasi\",\"SMA atau RP-SMA\":\"untuk antena LoRa\"},\"Konektivitas\":{\"Ethernet\":\"10\\/100 Mbps\",\"Konektivitas backhaul\":\"Wi-Fi 2.4GHz dan Ethernet (RJ45)\",\"Sensitivitas Rx\":\"-141 dBm (SF12)\",\"Daya yang Dihasilkan TX\":\"dapat dikonfigurasi dari 5dBm hingga 27dBm\",\"Keuntungan antena\":\"LoRa swivel antenna 3 dBi peak gain\"},\"Keamanan\":{\"Opsi Keamanan\":\"SecureBoot, SecureStorage, mTLS Protection, SafeReboot\"}}', '<h4>Spesifikasi Utama</h4><p>LoRaWAN Gateway untuk Logitech Spot adalah hub gerbang yang dirancang untuk menghubungkan ratusan sensor Logitech Spot dengan jaringan LoRaWAN yang aman dan efisien.</p>', '[{\"name\":\"Sniffer BLE\",\"value\":\"Sniffer untuk LBT (Dengarkan Sebelum Bicara)\",\"additional\":\"\"},{\"name\":\"Analisis spektrum\",\"value\":\"mematuhi\",\"additional\":\"\"},{\"name\":\"Casing\",\"value\":\"IP30\",\"additional\":\"\"},{\"name\":\"CPU\",\"value\":\"ARM Cortex A9\",\"additional\":\"\"},{\"name\":\"Memori utama\",\"value\":\"DDRAM 256MB\",\"additional\":\"\"},{\"name\":\"Memori flash\",\"value\":\"8GB eMMC (6GB tersedia untuk pengguna)\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Gateway ini menawarkan konektivitas yang handal dan mudah dikelola, memungkinkan pengguna untuk memantau dan mengelola sensor dengan mudah melalui platform Logitech Sync.</p>', 1, 0, 0, '2026-02-20 01:04:19', '2026-02-20 01:04:19'),
(25, 1, 1, 'Logitech MeetUp', 'logitech-meetup', '<h4>Deskripsi Produk</h4><p>Logitech MeetUp adalah ConferenceCam utama untuk ruang konferensi kecil (huddle rooms). Dengan lensa super-wide 120 derajat, MeetUp memastikan setiap orang di meja, bahkan yang duduk dekat kamera, tetap terlihat. Audio terintegrasi dioptimalkan untuk akustik ruang kecil, memastikan setiap orang terdengar sama baiknya dengan penampilan mereka.</p><h4>Fitur Utama</h4><ul><li><strong>Super-Wide FOV:</strong> Sudut pandang 120° menangkap seluruh ruangan kecil tanpa distorsi fisheye berlebih.</li><li><strong>Audio Terintegrasi:</strong> 3 mikrofon beamforming dan speaker custom-tuned.</li><li><strong>Desain Kompak:</strong> All-in-one form factor yang mudah dipasang di dinding atau di atas TV.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Resolusi: 4K Ultra HD</li><li>Optik: Lensa bermotor pan/tilt</li><li>Mikrofon: Jangkauan 4 meter (bisa diperluas)</li></ul>', 'products/logitech-meetup/logitech-meetup-2026-1771574659.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001101', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/meetup-datasheet.pdf', '[\"webcam 4k\",\"logitech brio\",\"video conference\",\"windows hello\",\"hdr webcam\",\"streaming camera\",\"business webcam\"]', '{\"Dimensi\":{\"Unit utama\":{\"Tinggi\":\"104 mm\",\"Lebar\":\"400 mm\",\"Tebal\":\"85 mm\",\"Berat\":\"1,04 kg\"},\"Remote Control\":{\"Tinggi\":\"83 mm\",\"Lebar\":\"83 mm\",\"Tebal\":\"10 mm\"}},\"Spesifikasi Teknis\":{\"Kamera\":{\"Lensa\":\"Lensa Logitech khusus dengan 5x HD zoom dan fungsi pan (geser) (+\\/- 25\\u00b0) dan tilt (miring) (+\\/- 15\\u00b0) bermotor\",\"Bidang Pandang\":{\"Diagonal\":\"120\\u00b0\",\"Horizontal\":\"113\\u00b0\",\"Vertikal\":\"80,7\\u00b0\"},\"Total Cakupan Ruangan\":\"Lebar 163\\u00b0 x tinggi 110\\u00b0\",\"Preset Posisi Kamera\":\"3 preset posisi kamera\",\"RightSight auto-framing\":\"Memerlukan Windows 10 64-bit atau macOS 10.14, atau versi terbaru\"},\"Kinerja Video\":{\"4K Ultra HD\":\"Maksimal 3840 x 2160 pixel @ 30 fps dengan kabel USB 3.0 yang dipasok pelanggan\",\"Full HD\":\"Hingga 1920 x 1080 piksel @ 30 fps\",\"HD\":\"Hingga 1280 x 720 piksel @ 30 fps\"},\"Mikrofon\":{\"Mikrofon Terintegrasi\":\"Mikrofon terintegrasi dengan 3 unsur beamforming\",\"Jangkauan Pickup\":{\"MeetUp\":\"4 m\",\"Dengan Perpanjangan Mikrofon opsional\":\"5 m\"},\"Sensitivitas\":\"-27 dB\",\"Respons Frekuensi\":\"90Hz-16kHz untuk reproduksi suara lengkap dan kejelasan tinggi tanpa noise\",\"Kinerja Beamforming\":\"Algoritme beamforming broadside dengan distorsi sangat rendah\"}}}', '<h4>Spesifikasi Utama</h4><p>MeetUp adalah kamera konferensi all-in-one yang dirancang untuk ruang berkumpul dan kecil, dengan fitur-fitur canggih seperti 5x zoom dan pengaturan yang mudah.</p>', '[{\"name\":\"Desain All-In-One\",\"value\":\"Dirancang untuk ruang berkumpul dan ruang kecil lainnya, MeetUp mengemas fitur besar ke dalam form factor yang ringkas.\",\"additional\":\"\"},{\"name\":\"Penyetelan yang Sederhana\",\"value\":\"MeetUp terhubung ke sebuah komputer atau laptop via USB untuk pemasangan yang mudah dan plug-and-play video conferencing.\",\"additional\":\"\"},{\"name\":\"Mount yang Nyaman\",\"value\":\"Dimensi yang ringkas dan opsi mounting yang fleksibel menghemat ruang dan meminimalkan penataan kabel.\",\"additional\":\"\"},{\"name\":\"5X Zoom\",\"value\":\"Menyorot presenter secara sempurna untuk meminimalkan gangguan di latar belakang.\",\"additional\":\"\"},{\"name\":\"Optik Kamera Premium\",\"value\":\"MeetUp dilengkapi optik kamera premium yang dibuat dengan sangat cermat.\",\"additional\":\"\"},{\"name\":\"Bluetooth\\u00ae Speakerphone\",\"value\":\"Pairing MeetUp dengan smartphone atau tablet Anda untuk menikmati kejelasan audio yang luar biasa.\",\"additional\":\"\"},{\"name\":\"Remote Control\",\"value\":\"Menggunakan sinyal radio frequency (RF) untuk kontrol yang andal.\",\"additional\":\"\"},{\"name\":\"RightSense Technologies\",\"value\":\"Teknologi proaktif dari Logitech RightSense\\u2122 memudahkan dan mengotomatisasi video meeting.\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Dirancang untuk kemudahan penggunaan, MeetUp menawarkan penyetelan yang sederhana dan desain yang nyaman untuk berbagai konfigurasi ruang.</p>', 1, 0, 0, '2026-02-20 01:04:19', '2026-02-20 01:04:19'),
(26, 1, 1, 'Logitech MeetUp Expansion Mics', 'logitech-meetup-expansion-mics', '<h4>Deskripsi Produk</h4><p>Logitech MeetUp Expansion Mics adalah mikrofon tambahan yang dirancang untuk memperluas jangkauan audio pada sistem konferensi Logitech MeetUp. Aksesori ini ideal untuk ruang meeting berukuran lebih besar, memastikan setiap peserta terdengar jelas tanpa harus duduk dekat dengan perangkat utama.</p><h4>Fitur Utama</h4><ul><li><strong>Jangkauan Lebih Luas:</strong> Memperluas pickup audio hingga 4,2 meter.</li><li><strong>Kualitas Audio Jernih:</strong> Teknologi beamforming untuk fokus pada suara pembicara.</li><li><strong>Instalasi Mudah:</strong> Plug-and-play langsung ke unit MeetUp.</li><li><strong>Tombol Mute Terintegrasi:</strong> Dengan indikator LED status.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Pickup Range: Hingga 4,2 meter</li><li>Koneksi: Kabel langsung ke MeetUp</li><li>Kompatibilitas: Logitech MeetUp</li></ul>', 'products/logitech-meetup-expansion-mics/logitech-meetup-expansion-mics-2026-1771574660.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '989-000405', NULL, 'https://activ.co.id/datasheet/logitech/ds-logitech-meet-up-expansion-mics.pdf', '[\"logitech\",\"expansion mic\",\"video conferencing\",\"audio pickup\",\"conference mic\",\"meeting room\",\"microphone\"]', '{\"Dimensi\":{\"Tinggi\":\"13,4 mm\",\"Lebar\":\"83 mm\",\"Tebal\":\"83 mm\"},\"Berat\":\"302 g\",\"Persyaratan Sistem\":{\"Jenis Koneksi\":\"Plug-and-play\",\"Panjang kabel\":\"6 m\"},\"Kompatibilitas\":{\"Logitech MeetUp\":\"Ya\"},\"Sertifikasi\":{\"Garansi\":\"Hardware Terbatas 2 Tahun\"},\"Lingkungan\":{\"Lampu Indikator (LED)\":\"Indikator LED untuk menunjukkan streaming video, mute pada mikrofon, on-hold, dan pairing Bluetooth\"},\"Jenis Mikrofon\":\"Mono, wideband, noise canceling\",\"Tombol \\/ Switch\":\"Mikrofon mute\"}', '<h4>Spesifikasi Utama</h4><p>Expansion Mic untuk MeetUp memberikan jangkauan audio yang lebih luas dengan kontrol mute yang mudah digunakan.</p>', '[{\"name\":\"Suara Superior\",\"value\":\"Dengar dengan jelas hingga 5 meter\",\"additional\":\"Mikrofon beamforming internal dioptimalkan hingga 4 meter\"},{\"name\":\"Kontrol Mute\",\"value\":\"Tombol mute pada mikrofon\",\"additional\":\"Lampu indikator menunjukkan status mute dan aktif\"},{\"name\":\"Fleksibilitas Ruang\",\"value\":\"Dapat digunakan di berbagai konfigurasi ruang\",\"additional\":\"Memperluas jangkauan pickup mikrofon\"}]', '<h4>Fitur Unggulan</h4><p>Mikrofon ini menawarkan suara superior dan fleksibilitas untuk berbagai konfigurasi ruang.</p>', 1, 0, 0, '2026-02-20 01:04:19', '2026-02-20 01:04:20'),
(27, 1, 1, 'Logitech MeetUp Mic Extension Cable', 'logitech-meetup-mic-extension-cable', '<h4>Deskripsi Produk</h4><p>Logitech MeetUp Mic Extension Cable adalah kabel perpanjangan resmi untuk mikrofon ekspansi MeetUp. Kabel ini memberikan fleksibilitas tambahan dalam penempatan mikrofon di ruang meeting, memungkinkan tata letak meja yang lebih luas tanpa mengurangi kualitas audio.</p><h4>Fitur Utama</h4><ul><li><strong>Panjang Tambahan:</strong> Memungkinkan penempatan mikrofon lebih fleksibel.</li><li><strong>Kualitas Sinyal Stabil:</strong> Dirancang khusus untuk menjaga performa audio.</li><li><strong>Instalasi Profesional:</strong> Cocok untuk routing kabel tersembunyi.</li><li><strong>Kompatibilitas Resmi:</strong> Untuk MeetUp Expansion Mic.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Panjang: 10 meter</li><li>Kompatibilitas: Logitech MeetUp Expansion Mic</li><li>Tipe: Kabel perpanjangan proprietary</li></ul>', 'products/logitech-meetup-mic-extension-cable/logitech-meetup-mic-extension-cable-2026-1771574660.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '950-000005', NULL, 'https://activ.co.id/datasheet/logitech/logitech-meetup-mic-extension-cable-adatlap-1.pdf', '[\"kabel mikrofon\",\"perpanjangan mikrofon\",\"aksesori video konferensi\",\"logitech meetup\",\"kabel audio\",\"peralatan konferensi\",\"solusi audio\"]', '{\"Dimensi\":{\"Panjang kabel\":\"10 meter\",\"Ketebalan Kabel\":\"4,2 mm\",\"Dimensi Konektor\":{\"Tinggi\":\"42,4 mm\",\"Lebar\":\"10 mm\",\"Tebal\":\"11,4 mm\"}},\"Kompatibilitas\":{\"Perpanjangan Mikrofon\":\"MeetUp\"},\"Garansi\":\"Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Kabel Perpanjangan Mikrofon MeetUp menambahkan jarak 10 meter pada kabel standar mikrofon 6 meter, memberikan total 16 meter untuk penataan yang rapi.</p>', '[{\"name\":\"Isi Kemasan\",\"value\":\"Kabel Perpanjangan 10 m, Klip Kabel, Dokumentasi\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Kabel ini dilengkapi dengan klip kabel untuk menjaga koneksi tetap aman dan teratur.</p>', 1, 0, 0, '2026-02-20 01:04:20', '2026-02-20 01:04:20'),
(28, 1, 1, 'Logitech MeetUp 2', 'logitech-meetup-2', '<h4>Deskripsi Produk</h4><p>Logitech MeetUp 2 (Generasi Baru/Rally Bar Huddle) adalah evolusi dari kamera huddle room terlaris. Perangkat ini membawa kecerdasan buatan (AI) video canggih ke ruang kecil. Dengan sistem operasi berbasis collabOS, ia dapat berjalan dalam mode USB (BYOD) atau sebagai appliance. Dilengkapi penutup privasi otomatis dan dibuat dengan plastik daur ulang untuk keberlanjutan.</p><h4>Fitur Utama</h4><ul><li><strong>AI Video Intelligence:</strong> RightSight 2 secara otomatis membingkai peserta rapat.</li><li><strong>Audio Jernih:</strong> AI Sound suppression menghilangkan kebisingan latar belakang yang tidak diinginkan.</li><li><strong>Privacy Shutter:</strong> Penutup lensa otomatis yang menutup saat rapat berakhir.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Platform: Works with Zoom, Teams, Google Meet</li><li>Resolusi: 4K</li><li>Konektivitas: USB, HDMI, Ethernet, WiFi</li></ul>', 'products/logitech-meetup-2/logitech-meetup-2-2026-1771574660.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001681', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/meetup2-datasheet.pdf', '[\"webcam\",\"logitech meetup\",\"video conference\",\"small room camera\",\"AI camera\",\"USB camera\",\"business webcam\"]', '{\"Dimensi\":{\"Tinggi\":\"73,3 mm\",\"Lebar\":\"469,2 mm\",\"Tebal\":\"73 mm\"},\"Berat\":\"1,8 kg\",\"Persyaratan Sistem\":{\"Windows\":\"Windows 10 dan versi terbaru\",\"Mac\":\"macOS: dua versi terbaru\",\"Koneksi Jaringan\":\"berkabel atau nirkabel\"},\"Kompatibilitas\":{\"RoomMate\":\"Tidak kompatibel dengan Logitech RoomMate, MeetUp 2 hanya dapat digunakan dalam mode PC dan BYOD.\"},\"Sertifikasi\":\"Bersertifikasi untuk Microsoft Teams, Zoom, dan Google Meet\",\"Daya\":{\"Catu daya\":\"Auto-sensing\",\"Voltase Operasi\\/Daya\":\"100-240V, 19V, 2,1A\"},\"Lingkungan\":{\"Suhu pengoperasian\":\"0 hingga 40\\u00b0C\",\"Suhu Penyimpanan\":\"-25-70\\u00b0C\",\"Kelembapan\":\"10 to 90%\"}}', '<h4>Spesifikasi Utama</h4><p>MeetUp 2 adalah kamera konferensi USB untuk ruangan kecil yang didukung oleh fitur AI yang menyederhanakan pengalaman meeting.</p>', '[{\"name\":\"Kamera PTZ digital\",\"value\":\"4K\",\"additional\":\"Zoom digital 4X HD\"},{\"name\":\"Mikrofon\",\"value\":\"6 rangkaian mikrofon DMIC\",\"additional\":\"Jangkauan Pickup maksimum 7 m\"},{\"name\":\"Speaker\",\"value\":\"1 speaker ported dengan suara lengkap\",\"additional\":\"Driver 55 mm dengan casing refleks bass\"},{\"name\":\"Manajemen kabel\",\"value\":\"Sistem retensi\",\"additional\":\"Multi-dudukan\"},{\"name\":\"Platform\",\"value\":\"Logitech CollabOS\",\"additional\":\"Logitech RightSight 2 dan RightSound 2\"}]', '<h4>Fitur Unggulan</h4><p>Pengalaman audio dan video yang cerdas untuk penggunaan berbasis USB di ruangan kecil.</p>', 1, 0, 0, '2026-02-20 01:04:20', '2026-02-20 01:04:20'),
(29, 1, 1, 'Logitech Rally Mic Pod', 'logitech-rally-mic-pod', '<h4>Deskripsi Produk</h4><p>Logitech Rally Mic Pod adalah mikrofon modular tambahan yang elegan untuk sistem Rally, Rally Bar, dan Rally Bar Mini. Dilengkapi teknologi RightSound, mic pod ini secara otomatis menyetarakan suara (auto-leveling) dan menekan kebisingan latar belakang. Desainnya yang rendah dan bahan premium membuatnya tampak estetik di ruang rapat modern.</p><h4>Fitur Utama</h4><ul><li><strong>RightSound Technology:</strong> Fokus pada pembicara aktif dan meredam gangguan audio.</li><li><strong>Tombol Mute:</strong> Indikator LED dan tombol bisu yang mudah dijangkau di tengah pod.</li><li><strong>Daisy Chain:</strong> Dapat dihubungkan satu sama lain untuk cakupan ruang yang luas.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Jangkauan Pickup: Diameter 4.5 meter</li><li>Mikrofon: 4 mikrofon omni-directional membentuk 8 acoustic beams</li><li>Warna: Tersedia dalam Graphite dan White</li></ul>', 'products/logitech-rally-mic-pod/logitech-rally-mic-pod-2026-1771574661.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '989-000430', NULL, 'https://www.logitech.com/assets/66125/rally-mic-pod-placement-guide.pdf', '[\"logitech rally mic pod\",\"video conference microphone\",\"modular microphone\",\"rightsound technology\",\"audio clarity\",\"beamforming microphone\",\"conference room audio\"]', '{\"Dimensi\":{\"Tinggi\":\"21 mm\",\"Lebar\":\"102 mm\",\"Tebal\":\"102 mm\"},\"Kompatibilitas\":{\"Graphite\":\"N\\/A\",\"Putih\":\"Plenum Rated, Eca\\/IEC 60332-1-2 Compliant\"},\"Mikrofon\":{\"Respons Frekuensi\":\"90Hz \\u2013 16kHz\",\"Sensitivitas\":\">-27 dB +\\/-1dB @ 1Pa\",\"Microphone data rate output\":\"48 kHz\",\"Jangkauan Pickup\":\"4,5 m\",\"Unsur Beamforming\":\"Empat mikrofon omnidirectional membentuk delapan acoustic beam\",\"Pemrosesan audio\":\"AEC (Acoustic Echo Cancellation), VAD (Voice Activity Detector)\",\"Peredaman noise\":\"Filter AI\"},\"Antarmuka\":{\"Keluaran\":\"Kabel 12-pin sepanjang 2,95 m\",\"Input\":\"Antarmuka 12-pin ke daisy-chain Mic Pods atau terhubung ke Rally Mic Pod Hub\"},\"Manajemen Perangkat\":{\"Platform\":\"Logitech Sync\"},\"Aksesori\":{\"Hub\":\"Rally Mic Pod Hub\",\"Mount\":\"Rally Mic Pod Mount (tersedia dalam warna graphite dan putih)\",\"Kabel\":\"Kabel Perpanjangan Rally Mic Pod\"},\"Garansi\":\"Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Rally Mic Pod adalah mikrofon modular yang dirancang untuk memberikan audio percakapan yang jelas dan alami dengan teknologi RightSound™.</p>', '[{\"name\":\"RightSound\\u2122\",\"value\":\"Mengatur auto-level suara, meredam noise, dan meredam echo.\"},{\"name\":\"Desain Modular\",\"value\":\"Dapat ditata secara daisy-chain untuk menjangkau seisi ruangan.\"},{\"name\":\"Material Premium\",\"value\":\"Resistan terhadap sidik jari dan noda.\"},{\"name\":\"Indikator LED\",\"value\":\"Memberikan konfirmasi visual yang jelas ketika dalam posisi mute.\"}]', '<h4>Fitur Unggulan</h4><p>Dilengkapi dengan desain modular dan material premium, mic pod ini menawarkan jangkauan suara yang luar biasa dan pengaturan yang mudah.</p>', 1, 0, 0, '2026-02-20 01:04:20', '2026-02-20 01:04:21'),
(30, 1, 1, 'Logitech Mic Pod Mount', 'logitech-mic-pod-mount', '<h4>Deskripsi Produk</h4><p>Logitech Mic Pod Mount adalah aksesori pemasangan khusus yang memberikan tampilan profesional untuk Rally Mic Pods. Mount ini mengamankan mikrofon di tempatnya di atas meja (anchor) dan menyembunyikan kabel melalui lubang grommet (diameter 25-65mm). Selain merapikan kabel, mount ini juga mencegah mikrofon bergeser atau ditarik secara tidak sengaja oleh pengguna.</p><h4>Fitur Unggulan</h4><ul><li><strong>Manajemen Kabel:</strong> Menggulung sisa kabel yang tidak terpakai di dalam mount untuk tampilan bersih.</li><li><strong>Posisi Tetap:</strong> Menjaga mikrofon tetap di tengah meja dan teratur.</li><li><strong>Fleksibilitas:</strong> Bisa juga digunakan untuk pemasangan di langit-langit (ceiling).</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Rally Mic Pod</li><li>Warna: Graphite, White</li><li>Tipe Lubang Meja: Grommet 25mm - 65mm</li></ul>', 'products/logitech-mic-pod-mount/logitech-mic-pod-mount-2026-1771574661.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000002', NULL, 'https://www.logitech.com/assets/66125/rally-mic-pod-placement-guide.pdf', '[\"mic pod mount\",\"logitech accessories\",\"video conferencing\",\"rally mic pod\",\"meeting room solutions\",\"cable management\",\"audio accessories\"]', '{\"Dimensi\":{\"Dengan Threaded Rod Terpasang\":{\"Tinggi\":\"90 mm\",\"Lebar\":\"146 mm\",\"Tebal\":\"146 mm\"},\"Tanpa Threaded Rod\":{\"Tinggi\":\"22 mm\",\"Lebar\":\"146 mm\",\"Tebal\":\"146 mm\"}},\"Kompatibilitas\":{\"Perangkat\":\"Rally Mic Pod\",\"Ketebalan Meja\":\"20-50 mm\",\"Diameter Lubang Grommet\":\"25 - 65 mm\"},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Mic Pod Mount dirancang untuk pemasangan yang rapi dan fleksibel, cocok untuk berbagai jenis meja dan ruang rapat.</p>', '[{\"name\":\"Desain Ringkas\",\"value\":\"Mempercantik tampilan ruang rapat.\",\"additional\":\"Menopang mic pod dengan kencang.\"},{\"name\":\"Manajemen Kabel\",\"value\":\"Jalur penataan kabel yang tersembunyi.\",\"additional\":\"Melilitkan kabel berlebih di bawah meja.\"},{\"name\":\"Fleksibilitas Pemasangan\",\"value\":\"Dapat dipasang di meja atau langit-langit.\",\"additional\":\"Cocok untuk ruang serbaguna.\"}]', '<h4>Fitur Unggulan</h4><p>Desain ringkas dan manajemen kabel yang efisien untuk tampilan ruang rapat yang lebih baik.</p>', 1, 0, 0, '2026-02-20 01:04:21', '2026-02-20 01:04:21');
INSERT INTO `products` (`id`, `service_id`, `brand_id`, `name`, `slug`, `description`, `image_path`, `thumbnail_path`, `price`, `link_accommerce`, `whatsapp_note`, `sku`, `solution_type`, `datasheet_url`, `tags`, `specs`, `specification_text`, `features`, `features_text`, `is_active`, `is_featured`, `is_new`, `created_at`, `updated_at`) VALUES
(31, 1, 1, 'Logitech Mic Pod Pendant Mount', 'logitech-mic-pod-pendant-mount', '<h4>Deskripsi Produk</h4><p>Logitech Mic Pod Pendant Mount adalah solusi elegan untuk menggantung Rally Mic Pod dari langit-langit. Ini ideal untuk ruangan dengan meja fleksibel yang sering dipindahkan, atau ruangan dengan langit-langit tinggi di mana mikrofon meja tidak praktis. Dengan menggantung mikrofon, Anda membebaskan permukaan meja sepenuhnya sambil tetap memastikan penangkapan suara yang optimal dari atas.</p><h4>Fitur Unggulan</h4><ul><li><strong>Audio dari Atas:</strong> Memastikan jangkauan suara merata tanpa terhalang laptop atau barang di meja.</li><li><strong>Estetika Ruangan:</strong> Tampilan modern dan bersih, kabel tersembunyi di dalam kabel gantung.</li><li><strong>Fleksibilitas Ruang:</strong> Memungkinkan meja di bawahnya dipindahkan tanpa perlu mencabut kabel mikrofon.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Rally Mic Pod</li><li>Warna: White</li></ul>', 'products/logitech-mic-pod-pendant-mount/logitech-mic-pod-pendant-mount-2026-1771574662.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000123', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/mic-pod-pendant-mount-configuration-guide.pdf', '[\"mic pod\",\"pendant mount\",\"rally mic pod\",\"video conferencing\",\"logitech accessories\",\"ceiling mount\",\"audio solutions\"]', '{\"Dimensi\":{\"Ceiling Mount\":{\"Tinggi\":\"80 mm\",\"Lebar\":\"82 mm\"},\"Wadah Mikrofon\":{\"Tinggi\":\"56 mm\",\"Lebar\":\"145 mm\"}},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Mic Pod Pendant Mount dirancang untuk menggantung mikrofon Rally Mic Pod di langit-langit, memastikan suara yang jelas di seluruh ruangan.</p>', '[{\"name\":\"Isi Kemasan\",\"value\":\"Ceiling Mount, Wadah Mikrofon, Hardware Pemasangan, Panduan Mulai Cepat\"}]', '<h4>Fitur Unggulan</h4><p>Memungkinkan pemasangan yang fleksibel dan aman untuk mikrofon di berbagai jenis langit-langit.</p>', 1, 0, 0, '2026-02-20 01:04:21', '2026-02-20 01:04:22'),
(32, 1, 1, 'Logitech Mounting Kit for Rally', 'logitech-mounting-kit-for-rally', '<h4>Deskripsi Produk</h4><p>Logitech Mounting Kit for Rally adalah paket aksesori pemasangan yang dirancang untuk sistem konferensi Logitech Rally. Kit ini memungkinkan pemasangan kamera, speaker, dan hub secara aman dan profesional di dinding atau meja.</p><h4>Fitur Utama</h4><ul><li><strong>Pemasangan Profesional:</strong> Dirancang khusus untuk sistem Rally.</li><li><strong>Manajemen Kabel:</strong> Membantu instalasi lebih rapi dan aman.</li><li><strong>Desain Presisi:</strong> Cocok dengan komponen Rally.</li><li><strong>Konstruksi Kokoh:</strong> Material berkualitas tinggi untuk penggunaan jangka panjang.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Logitech Rally System</li><li>Tipe: Mounting kit lengkap</li><li>Material: Baja tahan lama</li></ul>', 'products/logitech-mounting-kit-for-rally/logitech-mounting-kit-for-rally-2026-1771574662.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '939-001644', NULL, 'https://www.logitech.com/assets/65596/mounting-kit-for-rally.pdf', '[\"mounting kit\",\"logitech rally\",\"video conferencing\",\"installation kit\",\"cable management\",\"speaker bracket\",\"camera mount\"]', '{\"Dimensi\":{\"Bracket Speaker\":{\"Tinggi\":\"36 mm\",\"Lebar\":\"266 mm\",\"Tebal\":\"8 mm\"},\"Bracket Kamera\":{\"Tinggi\":\"63 mm\",\"Lebar\":\"109 mm\",\"Tebal\":\"166 mm\"},\"Bracket Table Hub\":{\"Tinggi\":\"12 mm\",\"Lebar\":\"164 mm\",\"Tebal\":\"115 mm\"},\"Bracket Display Hub\":{\"Tinggi\":\"12 mm\",\"Lebar\":\"164 mm\",\"Tebal\":\"115 mm\"},\"Penyangga Kabel\":{\"Tinggi\":\"23 mm\",\"Lebar\":\"164 mm\",\"Tebal\":\"38 mm\"}},\"Kompatibilitas\":{\"Sistem\":\"Logitech Rally atau Logitech Rally Plus\",\"Catatan\":\"Rally Mounting Kit didesain hanya untuk sistem Logitech Rally.\"},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Mounting Kit ini dirancang untuk memberikan pemasangan yang mulus dan tata letak kabel yang aman untuk sistem Logitech Rally.</p>', '[{\"name\":\"Bracket Kamera Bolak-Balik\",\"value\":\"Fleksibilitas untuk pemasangan kamera di dinding tepat di atas atau di bawah layar.\",\"additional\":\"Menyediakan sudut pandang yang lebih luas untuk ruang meeting besar.\"},{\"name\":\"Bracket Speaker yang Sederhana\",\"value\":\"Dua bracket yang menopang speaker di kedua sisi layar.\",\"additional\":\"Menciptakan tampilan \'mengambang\' yang cantik.\"},{\"name\":\"Bracket Berventilasi untuk Display Hub dan Table Hub\",\"value\":\"Dua bracket hub berventilasi untuk meletakkan Display Hub dan Table Hub.\",\"additional\":\"Memastikan sirkulasi udara yang memadai untuk pendinginan.\"},{\"name\":\"Bracket Penyangga Kabel\",\"value\":\"Mencegah terjadinya pemutusan koneksi yang tidak disengaja.\",\"additional\":\"Menjaga kabel tetap rapi.\"}]', '<h4>Fitur Unggulan</h4><p>Bracket kamera bolak-balik, bracket speaker yang sederhana, dan bracket berventilasi untuk hub memberikan fleksibilitas dan kemudahan dalam pemasangan.</p>', 1, 0, 0, '2026-02-20 01:04:22', '2026-02-20 01:04:22'),
(33, 1, 1, 'Logitech Off-White Fabric Cover', 'logitech-off-white-fabric-cover', '<h4>Deskripsi Produk</h4><p>Logitech Off-White Fabric Cover adalah penutup berbahan kain premium yang dirancang untuk Rally Bar Huddle. Cover ini memberikan tampilan estetis yang lebih terang sekaligus membantu menjaga kebersihan perangkat di ruang meeting modern.</p><h4>Fitur Utama</h4><ul><li><strong>Desain Elegan:</strong> Warna off-white untuk tampilan modern.</li><li><strong>Mudah Dibersihkan:</strong> Material kain yang tahan noda.</li><li><strong>Pas Presisi:</strong> Dirancang khusus untuk Rally Bar Huddle.</li><li><strong>Perlindungan Tambahan:</strong> Menjaga permukaan perangkat tetap bersih.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Logitech Rally Bar Huddle</li><li>Warna: Off-White</li><li>Material: Fabric premium</li></ul>', 'products/logitech-off-white-fabric-cover/logitech-off-white-fabric-cover-2026-1771574662.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000147', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/rallybar-huddle-accessories-datasheet.pdf', '[\"cover kain\",\"off-white\",\"rally bar\",\"video conferencing\",\"aksesori\",\"huddle room\",\"logitech\"]', '{\"Dimensi\":{\"Panjang\":\"549,4 mm\",\"Lebar\":\"79 mm\",\"Tinggi\":\"15,2 mm\"},\"Berat\":\"158 g\",\"Kompatibilitas\":\"Kompatibel hanya dengan Rally Bar Huddle\",\"Sertifikasi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Cover kain warna off-white ini dirancang khusus untuk Rally Bar Huddle, memberikan tampilan yang elegan dan profesional.</p>', '[{\"name\":\"Material Kain Off-White Premium\",\"value\":\"Penutup berbahan kain berkualitas tinggi dengan warna off-white yang elegan.\",\"additional\":\"Memberikan tampilan profesional dan bersih yang menyatu dengan desain interior modern.\"},{\"name\":\"Desain Akustik Transparan\",\"value\":\"Material fabric yang dirancang khusus agar tidak menghalangi transmisi suara.\",\"additional\":\"Memastikan kualitas audio speaker dan sensitivitas mikrofon tetap optimal meski tertutup cover.\"},{\"name\":\"Pemasangan Magnetik yang Mudah\",\"value\":\"Sistem penggantian cover yang cepat tanpa memerlukan alat bantu tambahan.\",\"additional\":\"Memudahkan pembersihan atau penggantian unit jika terjadi kerusakan fisik pada kain.\"},{\"name\":\"Estetika Ruang Meeting\",\"value\":\"Alternatif desain untuk menggantikan cover standar berwarna Graphite.\",\"additional\":\"Menciptakan kesan ruangan yang lebih terang dan minimalis.\"}]', '<h4>Fitur Unggulan</h4><p>Desain yang stylish dan kompatibilitas yang sempurna dengan perangkat Logitech.</p>', 1, 0, 0, '2026-02-20 01:04:22', '2026-02-20 01:04:22'),
(34, 1, 1, 'Logitech PC Mount', 'logitech-pc-mount', '<h4>Deskripsi Produk</h4><p>Logitech PC Mount adalah dudukan khusus untuk mengamankan mini PC atau perangkat komputasi di ruang meeting. Mount ini membantu menyembunyikan perangkat di belakang layar atau di bawah meja untuk tampilan yang lebih bersih dan profesional.</p><h4>Fitur Utama</h4><ul><li><strong>Instalasi Fleksibel:</strong> Dipasang di belakang monitor atau di bawah meja.</li><li><strong>Keamanan Perangkat:</strong> Menjaga mini PC tetap stabil dan aman.</li><li><strong>Manajemen Kabel:</strong> Membantu merapikan kabel daya dan data.</li><li><strong>Konstruksi Kokoh:</strong> Material tahan lama untuk penggunaan jangka panjang.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Tipe Mount: Mini PC Mount</li><li>Kompatibilitas: Mini PC/Chromebox</li><li>Material: Baja berkualitas tinggi</li></ul>', 'products/logitech-pc-mount/logitech-pc-mount-2026-1771574662.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '939-001825', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/compute-mount-datasheet.pdf', '[\"logitech pc mount\",\"mini pc mount\",\"chromebox mount\",\"cable management\",\"vesa mount\",\"video conferencing accessories\",\"small form factor pc\"]', '{\"Dimensi\":{\"Tinggi\":\"26 mm\",\"Lebar\":\"164 mm\",\"Tebal\":\"250 mm\"},\"Kompatibilitas\":{\"Komputer\":\"small form factor (SFF) dengan pola VESA 100 x 100 mm\"},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>PC Mount dirancang untuk menyimpan mini PC dan Chromebox dengan aman dan tersembunyi, ideal untuk ruang meeting dan lokasi retail.</p>', '[{\"name\":\"Cocok untuk Sebagian Besar SFF PC\",\"value\":\"Steel mount yang kuat cocok untuk komputer dengan small form factor (SFF) dan Chromebox serta mounting plate dengan pola VESA 100 mm.\",\"additional\":\"\"},{\"name\":\"Penyangga Kabel Terintegrasi\",\"value\":\"Dua potong jepitan penyangga kabel akan menghilangkan tegangan dan menjaga USB, HDMI, daya, dan kabel jaringan tetap kencang dan aman.\",\"additional\":\"\"},{\"name\":\"Rancangan Tersembunyi\",\"value\":\"Termasuk hardware untuk memasang PC di belakang layar di dinding atau di bawah meja.\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Mounting bracket dengan penyangga kabel untuk mini PC dan Chromebox, cocok untuk berbagai aplikasi.</p>', 1, 0, 0, '2026-02-20 01:04:22', '2026-02-20 01:04:22'),
(35, 1, 1, 'Logitech PTZ Pro 2', 'logitech-ptz-pro-2', '<h4>Deskripsi Produk</h4><p>Logitech PTZ Pro 2 adalah kamera video conference USB premium yang memberikan optik dan audio serealistis mungkin untuk menciptakan pengalaman duduk di ruangan yang sama. Kamera ini ideal untuk ruang konferensi, auditorium, dan ruang kelas yang besar di mana kemampuan zoom optik sangat dibutuhkan untuk menyorot pembicara atau papan tulis dari jarak jauh.</p><h4>Fitur Utama</h4><ul><li><strong>Optik Canggih:</strong> Lensa kamera premium dengan warna alami dan ketajaman luar biasa.</li><li><strong>10x HD Zoom:</strong> Zoom optik dan digital tanpa pecah untuk close-up detail.</li><li><strong>Preset Kamera:</strong> Simpan hingga 3 lokasi kamera untuk transisi cepat via remote.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Resolusi: 1080p/30fps</li><li>Field of View: 90 derajat</li><li>Gerakan: Pan 260° / Tilt 130° motorik halus</li><li>Koneksi: USB Plug-and-Play</li></ul>', 'products/logitech-ptz-pro-2/logitech-ptz-pro-2-2026-1771574662.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001184', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/ptz-pro-2-datasheet.pdf', '[\"video conference camera\",\"logitech ptz pro 2\",\"hd camera\",\"remote control camera\",\"business video conferencing\",\"usb camera\",\"1080p camera\"]', '{\"Dimensi\":{\"Kamera\":{\"Tinggi\":\"146 mm\",\"Lebar\":\"131 mm\",\"Tebal\":\"130 mm\",\"Berat\":\"580 g\"},\"Remote\":{\"Tinggi\":\"10 mm\",\"Lebar\":\"50 mm\",\"Tebal\":\"120 mm\",\"Berat\":\"48 g\"}},\"Spesifikasi Teknis\":{\"Kamera\":{\"Fungsi\":\"pan (geser), tilt (miring), dan zoom bermotor yang mulus\",\"Pan\":\"\\u00b1 90\\u00b0\",\"Tilt\":\"\\u00b1 35\\u00b0 \\/ 45\\u00b0\",\"Zoom\":\"10x HD\",\"Bidang Pandang\":{\"Diagonal\":\"90\\u00b0\",\"Horizontal\":\"82,1\\u00b0\",\"Vertikal\":\"52,2\\u00b0\"},\"Resolusi\":\"Full HD 1080p 30fps\",\"Kompresi\":\"H.264 UVC 1.5 dengan Scalable Video Coding (SVC)\",\"Autofocus\":true,\"Preset\":\"3 preset kamera plus tombol posisi home\",\"Indikator\":\"LED mute\\/unmute video\",\"Tripod\":\"Ulir tripod standar\"},\"Remote Control\":{\"Jangkauan\":\"IR 8,5 m\",\"Baterai\":\"CR2032 (disertakan)\"},\"Kabel\\/Daya\":{\"Adaptor\":\"Adaptor Daya AC dengan plug regional\",\"Kabel daya\":\"3 m\"},\"Mount\":\"Dual-purpose bracket dapat digunakan untuk pemasangan di dinding maupun meninggikan posisi perangkat di atas meja\"},\"Kompatibilitas dan Sertifikasi\":{\"Konektivitas\":\"USB plug-and-play\",\"Sertifikasi\":[\"Skype for Business\",\"Microsoft Teams\",\"Fuze\\u00ae\",\"Google Meet\\u00ae\",\"Cisco Jabber\",\"WebEX\",\"BlueJeans\\u00ae\",\"BroadSoft\\u00ae\",\"GoToMeeting\\u00ae\",\"Vidyo\\u00ae\"]},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Logitech PTZ Pro 2 menghadirkan optik premium dan video bagaikan nyata untuk menciptakan pengalaman duduk bersama di ruangan yang sama, bahkan jika Anda berjarak lebih dari 5.000 km jauhnya.</p>', '[{\"name\":\"Fungsi Pan dan Tilt\",\"value\":\"\\u00b1 90\\u00b0 Pan, \\u00b1 35\\u00b0 \\/ 45\\u00b0 Tilt\",\"additional\":\"Kontrol yang fleksibel untuk pengaturan sudut\"},{\"name\":\"Zoom\",\"value\":\"10x HD\",\"additional\":\"Zoom yang jelas dan detail\"},{\"name\":\"Bidang Pandang\",\"value\":\"90\\u00b0 Diagonal\",\"additional\":\"Mampu menangkap gambar luas\"},{\"name\":\"Resolusi Video\",\"value\":\"Full HD 1080p 30fps\",\"additional\":\"Kualitas video yang tajam\"},{\"name\":\"Autofocus\",\"value\":\"Ya\",\"additional\":\"Menjaga fokus pada objek\"},{\"name\":\"Preset Kamera\",\"value\":\"3 preset\",\"additional\":\"Menyimpan pengaturan untuk kemudahan\"},{\"name\":\"Indikator LED\",\"value\":\"Mute\\/Unmute Video\",\"additional\":\"Memberikan informasi status\"},{\"name\":\"Konektivitas\",\"value\":\"USB plug-and-play\",\"additional\":\"Mudah dipasang dan digunakan\"}]', '<h4>Fitur Unggulan</h4><p>Dengan fungsi pan, tilt, dan zoom yang lebih baik, PTZ Pro 2 sangat ideal untuk ruang kelas, auditorium, dan ruang meeting besar.</p>', 1, 0, 0, '2026-02-20 01:04:22', '2026-02-20 01:04:22'),
(36, 1, 1, 'Logitech Rally Board 65', 'logitech-rally-board-65', '<h4>Deskripsi Produk</h4><p>Logitech Google Meet Series One Board 65 (by Avocor) adalah solusi kolaborasi layar sentuh all-in-one yang dirancang untuk Google Meet. Perangkat ini menggabungkan layar sentuh 65 inci interaktif, kamera digital pan-tilt-zoom, speaker, dan mikrofon berkualitas tinggi dalam satu perangkat yang elegan. Sangat ideal untuk ruang kolaborasi kreatif di mana whiteboarding digital dan video conference terjadi bersamaan.</p><h4>Fitur Utama</h4><ul><li><strong>Digital Whiteboarding:</strong> Layar sentuh responsif yang terintegrasi dengan Jamboard app.</li><li><strong>Google AI Audio:</strong> TrueVoice technology menghilangkan kebisingan latar belakang secara real-time.</li><li><strong>All-in-One:</strong> Tidak memerlukan PC eksternal, cukup colok daya dan jaringan.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Layar: 65&quot; 4K Touch Display</li><li>Kamera: 12MP dengan 100° FOV</li><li>Prosesor: Intel Core i7 + Google TPU untuk AI</li></ul>', 'products/logitech-rally-board-65/logitech-rally-board-65-2026-1771574662.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001698', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/rally-board-65-datasheet.pdf', '[\"video conferencing\",\"logitech rally\",\"collaboration device\",\"touch screen\",\"4k video\",\"audio system\",\"smart features\"]', '{\"Dimensi\":{\"Lebar\":\"1500 mm\",\"Tinggi\":\"989 mm\",\"Tebal\":\"76 mm\",\"Berat\":\"46 kg\",\"VESA\":\"400 x 400 mm dan 400 x 200 mm\"},\"Spesifikasi Teknis\":{\"Komponen Internal\":\"Rangkaian pelantam depan, kamera PTZ digital, dual pelantang bersuara lebar, dual tweeter, emitor ultrasonik, manajemen kabel dan sistem retensi, shutter privasi bermotor terintegrasi, kamera depth mapping, radar motion sensing, dan sensor lingkungan\",\"Dukungan Tampilan Kedua\":\"Hingga UHD 4K60 (3840 x 2160)\",\"Shutter Privasi\":\"Bermotor otomatis\",\"HDMI Ingest\":\"Resolusi hingga 4K60 (3840 x 2160)\",\"Dukungan Protokol Jaringan\":\"IPv4, IPv6\",\"Dukungan Proksi\":\"Proksi berbasis IP, proksi berbasis FQDN, proksi menggunakan berkas PAC\"},\"Persyaratan Sistem\":{\"Catu Daya\":\"100 - 240v\",\"Koneksi Internet\":\"Dengan kabel atau nirkabel\",\"Lisensi\":\"Perangkat solusi ruangan (tidak termasuk)\"},\"Tampilan\":{\"Layar\":\"LCD 65 inci\",\"Sentuhan\":\"Berbasis IR dengan 20 titik sentuh\",\"Resolusi\":\"UHD 4K (3840 x 2160)\",\"Rasio Aspek\":\"16:9\",\"Lapisan\":\"Anti-silau dan anti-sidik jari\",\"Rasio Kontras\":\"5000:1 Khas\",\"Kecerahan\":\"400 nits Khas\"},\"Kamera\":{\"Kamera Utama - Sensor Pencitraan\":\"1 inci, 20,3MP\",\"Kamera Utama - Resolusi\":\"4K, 1440p, 1080p, 900p, 720p, dan SD pada 30fps\",\"Kamera Utama - Kemiringan\":\"Bermotor otomatis berdasarkan orientasi perangkat\",\"Kamera Utama - Zoom\":\"Zoom digital 4X HD\",\"Kamera Utama - Bidang Pandang - Diagonal\":\"115.7\\u00b0\",\"Kamera Utama - Bidang Pandang - Horizontal\":\"103.3\\u00b0\",\"Kamera Utama - Bidang Pandang - Vertikal\":\"60.7\\u00b0\",\"Kamera Pemetaan Kedalaman - Bidang Pandang Diagonal\":\"145\\u00b0\",\"Kamera Pemetaan Kedalaman - Bidang Pandang Horizontal\":\"121\\u00b0\"},\"Speaker\":{\"Dual Pelantang - Driver\":\"2 x 70 mm\",\"Dual Pelantang - Sensitivitas\":\"89 dB SPL pada 1W\\/0,5 m\",\"Dual Pelantang - Rated Power\":\"8W\",\"Dual Pelantang - THD\":\"Pada 1W, 1 kHz <2%\",\"Tweeter Dual Frekuensi Tinggi - Driver\":\"2 x 31 mm\",\"Tweeter Dual Frekuensi Tinggi - Sensitivitas\":\"93 dB SPL pada 1W\\/0,5 m\",\"Tweeter Dual Frekuensi Tinggi - Rated Power\":\"8W\",\"Tweeter Dual Frekuensi Tinggi - THD\":\"Pada 1W, 4 kHz < 2%\"},\"Mikrofon\":{\"Susunan Mikrofon Depan - Respons Frekuensi\":\"90Hz-16KHz\",\"Susunan Mikrofon Depan - Sensitivitas\":\"-36 dB FS +\\/-1 dB @ 1 Pa\",\"Susunan Mikrofon Depan - Microphone Data Rate Output\":\"48KHz\",\"Susunan Mikrofon Depan - Jangkauan Pickup\":\"Maksimum 7 m\",\"Susunan Mikrofon Depan - RightSound 2 - AI Speech Enhance\":\"Menghilangkan kebisingan sementara dan stasioner\",\"Susunan Mikrofon Depan - RightSound 2 - Beamforming\":\"Dengan AI Beam Selection\",\"Susunan Mikrofon Depan - RightSound 2 - Pendeteksi Ucapan AI\":\"Ya\",\"Susunan Mikrofon Depan - RightSound 2 - Arah Bicara AI\":\"Ya\",\"Susunan Mikrofon Depan - RightSound 2 - Peredam Gema Akustik\":\"Ya\"},\"Sensor\":{\"Suhu\":\"Ya\",\"Kelembapan\":\"Ya\",\"SOKM\":\"Ya\",\"Karbon Dioksida\":\"Ya\",\"PM2.5\":\"Ya\",\"PM10\":\"Ya\",\"Radar\":\"Ya\",\"Cahaya Sekitar\":\"Ya\"},\"Antarmuka\":{\"HDMI Keluar\":\"1 x HDMI hingga 4k60\",\"HDMI Masuk\":\"1 x HDMI hingga 4k60\",\"USB-A\":\"3 x USB 3.1\",\"USB-C\":\"1 x USB 3.1 Tipe C dengan DP Alt Mode\",\"Line-Keluar\":\"3,5 mm line tingkat keluaran audio\",\"Jaringan\":\"10\\/100\\/1G Ethernet\",\"Wi-Fi\":\"802.11a\\/b\\/g\\/n\\/ac\\/ax\",\"Bluetooth\":\"Bluetooth Low Energy\",\"EXT\":\"RJ45 dicadangkan untuk penggunaan di masa mendatang\"},\"Daya dan Kabel\":{\"Catu Daya\":\"Pengindraan otomatis tertanam 100-240V\",\"Kabel AC\":\"3 m\"},\"Lingkungan\":{\"Suhu Pengoperasian\":\"0-35 \\u00b0C\",\"Suhu Penyimpanan\":\"-40-60 \\u00b0C\",\"Kelembapan\":\"10-95%\"},\"Keamanan\":{\"Enkripsi Berbasis File\":\"AES-256\",\"Enkripsi Data\":\"Tombol Simetris, PKI\",\"Identitas Perangkat\":\"Dilindungi oleh atestasi perangkat\",\"Akses Perangkat\":\"Diautentikasi menggunakan API\",\"Perlindungan Tombol\":\"Arm TrustZone, RPMB\"},\"Aksesori\":[\"Rally Board 65 Cart\",\"Kabel USB Aktif\"]}', '<h4>Spesifikasi Utama</h4><p>Rally Board 65 adalah perangkat video konferensi yang menggabungkan audio dan video berkualitas tinggi dengan layar sentuh 65 inci, dirancang untuk meningkatkan pengalaman kolaborasi.</p>', '[{\"name\":\"Dukungan Protokol Jaringan\",\"value\":\"IPv4, IPv6\",\"additional\":null},{\"name\":\"Dukungan Tampilan Kedua\",\"value\":\"Hingga UHD 4K60 (3840 x 2160)\",\"additional\":null},{\"name\":\"Shutter Privasi\",\"value\":\"Bermotor otomatis\",\"additional\":null},{\"name\":\"Kamera Utama\",\"value\":\"1 inci, 20,3MP\",\"additional\":null},{\"name\":\"Resolusi Kamera\",\"value\":\"4K, 1440p, 1080p, 900p, 720p, dan SD pada 30fps\",\"additional\":null},{\"name\":\"Zoom\",\"value\":\"Zoom digital 4X HD\",\"additional\":null},{\"name\":\"Speaker\",\"value\":\"Dual Pelantang dengan suara lebar\",\"additional\":null},{\"name\":\"Mikrofon\",\"value\":\"Susunan mikrofon depan\",\"additional\":null},{\"name\":\"Kelembapan\",\"value\":\"10-95%\",\"additional\":null},{\"name\":\"Suhu Pengoperasian\",\"value\":\"0-35 \\u00b0C\",\"additional\":null}]', '<h4>Fitur Unggulan</h4><p>Dengan teknologi AI dan desain yang fleksibel, Rally Board 65 menawarkan pengalaman konferensi yang optimal untuk berbagai kebutuhan ruang.</p>', 1, 0, 1, '2026-02-20 01:04:22', '2026-02-22 23:15:29'),
(37, 1, 1, 'Logitech Rally Board Cart', 'logitech-rally-board-cart', '<h4>Deskripsi Produk</h4><p>Logitech Rally Board Cart adalah dudukan mobile yang dirancang khusus untuk Logitech Rally Board 65. Cart ini memungkinkan perangkat dipindahkan dengan mudah antar ruangan, memberikan fleksibilitas kolaborasi yang tinggi.</p><h4>Fitur Utama</h4><ul><li><strong>Mobilitas Tinggi:</strong> Roda dengan sistem pengunci.</li><li><strong>Desain Stabil:</strong> Mendukung perangkat dengan aman.</li><li><strong>Manajemen Kabel:</strong> Jalur kabel terintegrasi.</li><li><strong>Kompatibilitas Khusus:</strong> Untuk Rally Board 65.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Logitech Rally Board 65</li><li>Tipe: Mobile Cart</li><li>Material: Baja kokoh</li></ul>', 'products/logitech-rally-board-cart/logitech-rally-board-cart-2026-1771574662.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000251', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/rally-board-cart-datasheet.pdf', '[\"Rally Board 65\",\"Logitech\",\"video conferencing\",\"mobile cart\",\"meeting room\",\"cable management\",\"stable design\"]', '{\"Dimensi\":{\"Dirakit dengan Rally Board 65 dengan orientasi kamera-tinggi - Tinggi\":\"1963 mm\",\"Dirakit dengan Rally Board 65 dengan orientasi kamera-tinggi - Lebar\":\"1500 mm\",\"Dirakit dengan Rally Board 65 dengan orientasi kamera-tinggi - Tebal\":\"812 mm\",\"Dirakit dengan Rally Board 65 dengan orientasi kamera-tinggi - Tinggi bagian tengah lensa\":\"1876,8 mm\",\"Dirakit dengan Rally Board 65 dengan orientasi kamera-rendah - Tinggi\":\"1963 mm\",\"Dirakit dengan Rally Board 65 dengan orientasi kamera-rendah - Lebar\":\"1500 mm\",\"Dirakit dengan Rally Board 65 dengan orientasi kamera-rendah - Tebal\":\"812 mm\",\"Dirakit dengan Rally Board 65 dengan orientasi kamera-rendah - Tinggi bagian tengah lensa\":\"1000,5 mm\",\"Dirakit dengan Rally Board 65 dengan orientasi pembalikan tengah - Tinggi\":\"1963 mm\",\"Dirakit dengan Rally Board 65 dengan orientasi pembalikan tengah - Lebar\":\"1500 mm\",\"Dirakit dengan Rally Board 65 dengan orientasi pembalikan tengah - Tebal\":\"989 mm\",\"Berat keranjang\":\"49 kg\",\"Berat setelah dirakit\":\"95 kg\",\"Jenis cetakan\":\"Cetakan penguncian empat inci roda kembar\"},\"Kompatibilitas\":{\"Desain\":\"Didesain khusus untuk digunakan dengan Logitech Rally Board 65\"},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun. Perpanjangan Garansi 1 Tahun dan 3 Tahun tersedia untuk pembelian.\"}', '<h4>Spesifikasi Utama</h4><p>Rally Board 65 Cart adalah pajangan bergerak yang dibuat khusus dan tahan lama untuk memindahkan Rally Board 65 dengan mudah di sekitar ruang kerja.</p>', '[{\"name\":\"Dua Cara Orientasi\",\"value\":\"Balikkan Rally Board 65 sehingga kamera berada di atas atau di bawah layar agar sesuai dengan pengaturan ruangan yang Anda perlukan.\",\"additional\":\"Mekanisme pembalikan bergerak lancar kemudian mengunci dengan aman di orientasi apa pun.\"},{\"name\":\"Stabil\",\"value\":\"Desain yang seimbang dan dapat bermanuver memudahkan untuk memosisikan Rally Board 65 dengan aman.\",\"additional\":\"Menjaga stabilitas selama pertemuan.\"},{\"name\":\"Desain yang Cermat\",\"value\":\"Rally Board 65 Cart dilengkapi sistem manajemen kabel yang didesain dengan cermat.\",\"additional\":\"Menjaga kabel tetap rapi dan mencegah kabel kusut.\"},{\"name\":\"Aman\",\"value\":\"Dilengkapi cetakan penguncian yang kokoh.\",\"additional\":\"Menjaga Rally Board 65 tetap aman di tempatnya.\"}]', '<h4>Fitur Utama</h4><p>Dengan roda yang dapat dikunci dan manajemen kabel internal, perangkat ini dapat digunakan secara fleksibel sesuai permintaan di mana pun pertemuan diperlukan.</p>', 1, 0, 1, '2026-02-20 01:04:22', '2026-02-22 23:15:51'),
(38, 1, 1, 'Logitech Rally Mic Pod CAT Coupler', 'logitech-rally-mic-pod-cat-coupler', '<h4>Deskripsi Produk</h4><p>Logitech Rally Mic Pod CAT Coupler adalah adaptor cerdas yang memungkinkan Anda memperpanjang jarak antara Rally Mic Pods menggunakan kabel CAT6 standar (kabel LAN). Solusi ini mengatasi batasan panjang kabel bawaan mikrofon, memberikan fleksibilitas luar biasa untuk instalasi di ruangan yang sangat besar atau dengan jalur kabel yang kompleks melalui langit-langit.</p><h4>Fitur Unggulan</h4><ul><li><strong>Kustomisasi Panjang:</strong> Gunakan kabel CAT6 pengguna sendiri untuk mencapai jarak yang diinginkan antar mikrofon.</li><li><strong>Instalasi Mudah:</strong> Konektor plug-and-play sederhana.</li><li><strong>Kualitas Sinyal:</strong> Mempertahankan kualitas audio digital tanpa degradasi jarak jauh.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Rally Mic Pod, Rally Bar, Rally Bar Mini</li><li>Konektor: Mic Pod Connector ke RJ45</li></ul>', 'products/logitech-rally-mic-pod-cat-coupler/logitech-rally-mic-pod-cat-coupler-2026-1771574663.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000181', NULL, 'https://activ.co.id/datasheet/logitech/vc-product-wiring-diagrams.pdf', '[\"Rally Mic Pod\",\"CAT Coupler\",\"Logitech\",\"video conferencing\",\"audio accessories\",\"Rally Bar\",\"Rally Plus\",\"CAT6 cable\"]', '{\"Dimensi\":{\"Tinggi\":\"15 mm\",\"Lebar\":\"22 mm\",\"Tebal\":\"58 mm\",\"Panjang kabel\":\"215 mm\"},\"Spesifikasi Teknis\":{\"Maksimum panjang kabel\":\"20 meter\",\"Jenis kabel yang didukung\":\"CAT6 SFTP\\/SSTP\"},\"Kompatibilitas\":{\"Perangkat yang kompatibel\":[\"Rally Bar\",\"Rally Bar Mini\",\"Rally\",\"Rally Plus\",\"Rally Mic Pod\",\"Rally Mic Pod Hub\"]},\"Garansi\":\"Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Rally Mic Pod CAT Coupler memungkinkan Anda untuk memperpanjang kabel Rally Mic Pod dengan mudah menggunakan kabel CAT standar.</p>', '[{\"name\":\"Dukungan panjang kabel\",\"value\":\"Mendukung panjang kabel CAT hingga maksimum 20 meter\",\"additional\":\"\"},{\"name\":\"Jenis kabel yang didukung\",\"value\":\"CAT6 SFTP\\/SSTP\",\"additional\":\"\"},{\"name\":\"Isi Kemasan\",\"value\":\"Coupler x 2, Kabel patch, Dokumentasi pengguna\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Dengan dukungan untuk panjang kabel hingga 20 meter, Coupler ini sangat ideal untuk berbagai pengaturan ruang konferensi.</p>', 1, 0, 0, '2026-02-20 01:04:22', '2026-02-20 01:04:23'),
(39, 1, 1, 'Logitech Rally Mic Pod Extension Cable', 'logitech-rally-mic-pod-extension-cable', '<h4>Deskripsi Produk</h4><p>Logitech Rally Mic Pod Extension Cable adalah kabel perpanjangan 10 meter yang dirancang khusus untuk menambah jangkauan Rally Mic Pods. Kabel ini bersertifikat plenum (aman untuk instalasi dinding/pleno) dan Eca, memungkinkan pemasangan yang aman melalui saluran udara atau konduit. Kabel ini memberikan kebebasan lebih dalam menempatkan mikrofon jauh dari hub atau video bar utama.</p><h4>Fitur Unggulan</h4><ul><li><strong>Panjang Ekstra:</strong> Menambah jangkauan 10 meter, memungkinkan fleksibilitas penempatan mic.</li><li><strong>Sertifikasi Plenum:</strong> Aman untuk instalasi komersial di langit-langit atau dinding.</li><li><strong>Klip Pengaman:</strong> Termasuk klip kabel untuk mencegah sambungan terlepas.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Panjang: 10 meter</li><li>Warna: Putih</li><li>Kompatibilitas: Rally Mic Pod</li></ul>', 'products/logitech-rally-mic-pod-extension-cable/logitech-rally-mic-pod-extension-cable-2026-1771574663.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000047', NULL, 'https://www.logitech.com/assets/65641/2/rally-acessories-datasheet.ENG.pdf', '[\"kabel perpanjangan\",\"rally mic pod\",\"video conferencing\",\"logitech\",\"audio extension\",\"commercial installation\",\"conference room\"]', '{\"Dimensi\":{\"Panjang kabel\":\"10 m\"},\"Kompatibilitas\":{\"Rally Bar\":\"mendukung hingga 2 kabel\",\"Rally Bar Mini\":\"mendukung hingga 2 kabel\",\"Rally\":\"mendukung 1 kabel\",\"Rally Plus\":\"mendukung 1 kabel\"},\"Sertifikasi\":{\"Plenum-rated\":true,\"ECA\":true},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Kabel perpanjangan 10 meter yang mendukung berbagai perangkat Logitech.</p>', '[{\"name\":\"Jangkauan Ekstra Panjang\",\"value\":\"Menambahkan jangkauan tambahan sepanjang 10 meter.\",\"additional\":\"Dapat digunakan dengan Rally Mic Pod atau Rally Mic Pod Hub.\"},{\"name\":\"Koneksi Jarak Jauh\",\"value\":\"Dua kabel dapat dihubungkan untuk menambahkan jangkauan sepanjang 20 meter.\",\"additional\":\"Bisa digunakan dengan Rally Bar dan Rally Bar Mini.\"},{\"name\":\"Dari Table Hub hingga Ujung Meja\",\"value\":\"Mengakomodasi meja berukuran besar.\",\"additional\":\"Hubungkan langsung ke table hub.\"},{\"name\":\"Penyimpanan Kabel Terintegrasi\",\"value\":\"Dilengkapi dengan klip kabel.\",\"additional\":\"Menjaga koneksi tetap kencang dan aman.\"}]', '<h4>Fitur Unggulan</h4><p>Menawarkan jangkauan ekstra dan penyimpanan kabel terintegrasi untuk pengalaman yang lebih baik.</p>', 1, 0, 0, '2026-02-20 01:04:23', '2026-02-20 01:04:23'),
(40, 1, 1, 'Logitech Rally Speaker', 'logitech-rally-speaker', '<h4>Deskripsi Produk</h4><p>Logitech Rally Speaker adalah unit speaker tambahan berkinerja tinggi yang dirancang khusus untuk sistem Logitech Rally. Speaker ini menghadirkan suara yang kaya, jernih, dan bebas distorsi bahkan pada volume tinggi. Fitur utamanya adalah sistem suspensi paten yang memisahkan modul speaker dari dinding atau meja, mencegah getaran yang dapat mengganggu mikrofon atau membuat kamera bergoyang (anti-vibration enclosure). Ini memastikan audio terdengar alami dan percakapan video tetap stabil.</p><h4>Fitur Unggulan</h4><ul><li><strong>Front-of-Room Audio:</strong> Suara diproyeksikan dari depan ruangan (dekat layar), menyelaraskan suara dengan video untuk pengalaman yang natural.</li><li><strong>Anti-Vibration Enclosure:</strong> Meredam getaran mekanis, memungkinkan volume tinggi tanpa echo atau gangguan video.</li><li><strong>Konektivitas Aman:</strong> Menggunakan kabel Mini XLR custom untuk sinyal yang kuat dan koneksi yang tidak mudah lepas.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Driver: 76mm high-performance driver</li><li>Volume: 95dB SPL @ 1W, 1m; 100dB SPL @ 7.5W, 1m</li><li>Dimensi: 103 x 449 x 80 mm</li><li>Aksesori: Termasuk kabel Mini XLR 2.95m</li></ul>', 'products/logitech-rally-speaker/logitech-rally-speaker-2026-1771574663.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001230', NULL, 'https://www.logitech.com/assets/65592/11/rally-datasheet.IND.pdf', '[\"logitech rally speaker\",\"video conferencing\",\"audio clarity\",\"speaker system\",\"conference room audio\",\"professional audio equipment\",\"high-performance speaker\"]', '{\"Dimensi\":{\"Tinggi\":\"103 mm\",\"Lebar\":\"449 mm\",\"Tebal\":\"80 mm\"},\"Kompatibilitas\":{\"Sistem\":\"Logitech Rally dengan sebuah speaker\",\"Maksimum speaker per sistem\":\"2\"},\"Spesifikasi Teknis\":{\"Driver\":\"76 mm berkinerja tinggi dengan magnet bumi yang langka\",\"Sistem suspensi\":\"Menghilangkan gerakan kamera yang diakibatkan getaran dan gangguan audio\",\"Kabel\":\"Mini XLR terhubung ke Rally Display Hub untuk sinyal maupun daya\",\"Volume speaker\":\"95 dB SPL @1 W, 100 dB SPL @7,5 W, keduanya +\\/-2 dB pada \\u00bd meter\",\"Distorsi\":\"200 Hz\\u2013300 Hz <2,5%, 300 Hz\\u201310 kHz < 1%@7,5 W\",\"Speaker Sampling Rate\":\"48 KHz\"},\"Aksesori\":{\"Rally Mounting Kit\":\"Mencakup dua wall-mount bracket untuk Rally Speaker, plus penyangga kabel (x2), dan mounting bracket untuk kamera dan hub (x2)\"},\"Garansi\":\"Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Rally Speaker menghadirkan suara yang jernih dan kaya, ideal untuk ruang besar dengan teknologi yang menghilangkan distorsi.</p>', '[{\"name\":\"Audio di Bagian Depan Ruangan\",\"value\":\"Dengan Rally Speaker di bagian depan ruangan, suara dan video selalu datang dari arah yang sama.\",\"additional\":\"\"},{\"name\":\"Wadah Anti-Getaran\",\"value\":\"Sistem suspensi yang canggih ini akan memisahkan modul speaker di dalam wadah eksternal.\",\"additional\":\"\"},{\"name\":\"Volume Nyaman di Ruangan Besar\",\"value\":\"Meningkatkan kejelasan sementara menjaga volume pada level yang nyaman untuk semua orang di dalam ruangan.\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Dengan desain yang inovatif, Rally Speaker memberikan pengalaman audio yang luar biasa dalam setiap pertemuan video.</p>', 1, 0, 0, '2026-02-20 01:04:23', '2026-02-20 01:04:23'),
(41, 1, 1, 'Logitech Rally Plus', 'logitech-rally-plus', '<h4>Deskripsi Produk</h4><p>Logitech Rally Plus adalah sistem konferensi video modular ultimate untuk ruangan besar dan ekstra besar. Sistem ini mencakup satu Rally Camera (4K PTZ), dua Rally Speakers, dan dua Rally Mic Pods, serta Display Hub dan Table Hub. Arsitektur modular ini memungkinkan Anda menempatkan speaker di depan ruangan (di layar) dan mikrofon di meja, dengan hanya satu kabel CAT6 yang menghubungkan hub meja dan hub layar, menjaga instalasi tetap rapi dan profesional.</p><h4>Fitur Unggulan</h4><ul><li><strong>Cakupan Ruang Besar:</strong> Paket standar mencakup hingga 16 orang, dan dapat diperluas hingga 46 orang dengan total 7 Mic Pods.</li><li><strong>RightSense Automation:</strong> Mengotomatiskan pencahayaan (RightLight), pembingkaian kamera (RightSight), dan kejernihan audio (RightSound).</li><li><strong>Audio Modular:</strong> Speaker dan mikrofon terpisah memungkinkan penempatan akustik yang optimal.</li><li><strong>Hub Architecture:</strong> Meminimalkan kabel panjang HDMI/USB yang melintasi lantai ruangan.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kamera: 4K PTZ, 15x HD Zoom</li><li>Paket Termasuk: 1x Camera, 2x Speakers, 2x Mic Pods, 1x Table Hub, 1x Display Hub, 2x Power Supplies</li><li>Konektivitas: USB to PC/Mac (Plug-and-Play)</li></ul>', 'products/logitech-rally-plus/logitech-rally-plus-2026-1771574663.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001224', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/rally-plus.pdf', '[\"webcam 4k\",\"logitech rally\",\"video conference\",\"audio video system\",\"business webcam\",\"streaming camera\",\"modular conference system\"]', '{\"Dimensi\":{\"Rally Camera\":{\"Tinggi\":\"182,5 mm\",\"Lebar\":\"152 mm\",\"Tebal\":\"152 mm\"},\"Rally Speaker\":{\"Tinggi\":\"103 mm\",\"Lebar\":\"449 mm\",\"Tebal\":\"80 mm\"},\"Rally Mic Pod\":{\"Tinggi\":\"21 mm\",\"Lebar\":\"102 mm\",\"Tebal\":\"102 mm\"},\"Rally Display Hub\":{\"Tinggi\":\"40 mm\",\"Lebar\":\"206 mm\",\"Tebal\":\"179 mm\"},\"Rally Table Hub\":{\"Tinggi\":\"40 mm\",\"Lebar\":\"176 mm\",\"Tebal\":\"138 mm\"}},\"Kompatibilitas\":{\"Windows\":\"Windows 7, 8.1 or Windows 10\",\"macOS\":\"10.10 atau versi terbaru\",\"Chrome OS\":\"Chrome OS\\u2122\"},\"Sertifikasi\":\"Untuk informasi terbaru tentang sertifikasi dan kompatibilitas, kunjungi www.logitech.com\\/support\\/vc-certifications\",\"Daya\":\"Input daya\",\"Lingkungan\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Rally Plus adalah sistem video conferencing modular premium untuk ruangan besar dan ekstra besar.</p>', '[{\"name\":\"Zoom\",\"value\":\"15x HD zoom (5x optik, 3x digital)\",\"additional\":\"\"},{\"name\":\"Pan (Geser)\",\"value\":\"180\\u00b0 (\\u00b190\\u00b0)\",\"additional\":\"\"},{\"name\":\"Tilt (Miring)\",\"value\":\"140\\u00b0 (+50\\u00b0 \\/ -90\\u00b0)\",\"additional\":\"\"},{\"name\":\"Bidang Pandang\",\"value\":\"Diagonal: 90\\u00b0, Horizontal: 82\\u00b0, Vertikal: 52\\u00b0\",\"additional\":\"\"},{\"name\":\"Resolusi @ 30fps\",\"value\":\"4K Ultra HD, 1440p, 1080p, 900p, 720p, dan SD\",\"additional\":\"\"},{\"name\":\"Resolusi @ 60fps\",\"value\":\"1080p, 720p\",\"additional\":\"\"},{\"name\":\"Teknologi RightLight\",\"value\":\"Wide Dynamic Range (WDR), kompensasi cahaya redup, mengurangi video noise, optimisasi kejenuhan cahaya redup\",\"additional\":\"\"},{\"name\":\"Privasi\",\"value\":\"Lensa berada pada sudut -90\\u00b0 dalam mode sleep untuk memastikan privasi\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Rally Plus menawarkan teknologi RightLight, RightSound, dan RightSight untuk pengalaman konferensi yang lebih baik.</p>', 1, 0, 0, '2026-02-20 01:04:23', '2026-02-20 01:04:23'),
(42, 1, 1, 'Logitech Rally Ultra HD PTZ Camera', 'logitech-rally-ultra-hd-ptz-camera', '<h4>Deskripsi Produk</h4><p>Logitech Rally Ultra HD PTZ Camera adalah kamera konferensi premium dengan kualitas video 4K dan kemampuan pan, tilt, zoom presisi tinggi. Dirancang untuk ruang meeting besar, kamera ini menghadirkan performa optik terbaik dan teknologi RightSense™ untuk pengalaman rapat yang lebih cerdas.</p><h4>Fitur Utama</h4><ul><li><strong>4K Ultra HD:</strong> Video berkualitas tinggi dengan detail tajam.</li><li><strong>PTZ Motorized:</strong> Gerakan kamera halus dan presisi.</li><li><strong>RightSense™:</strong> Otomatisasi framing dan pencahayaan.</li><li><strong>Desain Elegan:</strong> Tampilan premium untuk ruang profesional.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Resolusi: 4K</li><li>Zoom: 15x HD</li><li>Koneksi: USB</li><li>Field of View: Adjustable PTZ</li></ul>', 'products/logitech-rally-ultra-hd-ptz-camera/logitech-rally-ultra-hd-ptz-camera-2026-1771574663.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001226', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/rally-camera.pdf', '[\"webcam 4k\",\"logitech rally\",\"video conference\",\"streaming camera\",\"business webcam\",\"PTZ camera\",\"ultra HD camera\"]', '{\"Dimensi\":{\"Tinggi\":\"182,5 mm\",\"Lebar\":\"152 mm\",\"Tebal\":\"152 mm\"},\"Kompatibilitas\":{\"Windows\":\"Windows 7, 8.1 atau Windows 10\",\"Mac\":\"macOS 10.10 atau lebih baru\"},\"Sertifikasi\":[\"Skype\\u00ae for Business\",\"Microsoft\\u00ae Teams\",\"Zoom\\u00ae\",\"Fuze\\u00ae\"],\"Persyaratan Sistem\":{\"Resolusi lebih tinggi dari 1080p\":[\"Windows 8.1 atau lebih baru\",\"macOS 10.10 atau lebih baru\",\"Port USB 3.0 dan kabel Type C\",\"Software yang kompatibel\"]},\"Daya\":{\"Adaptor Daya\":\"AC dengan plug regional\",\"Kabel Daya\":\"3 m\"},\"Lingkungan\":{\"Suhu Operasional\":\"0\\u00b0C hingga 40\\u00b0C\",\"Kelembapan\":\"10% hingga 90% tanpa kondensasi\"}}', '<h4>Spesifikasi Utama</h4><p>Rally Camera menawarkan sistem pencitraan Ultra-HD dan kontrol kamera otomatis untuk pengalaman video conferencing yang luar biasa.</p>', '[{\"name\":\"Video Berkualitas Studio\",\"value\":\"Sistem pencitraan Ultra-HD dengan resolusi hingga 4K.\",\"additional\":\"Teknologi Logitech RightLight\\u2122 mengoptimalkan keseimbangan cahaya.\"},{\"name\":\"Kontrol Kamera Otomatis\",\"value\":\"Teknologi RightSight\\u2122 secara otomatis menyesuaikan lensa.\",\"additional\":\"Menangkap semua peserta dalam beragam bentuk dan ukuran ruangan.\"},{\"name\":\"Desain Industrial yang Ramping\",\"value\":\"Tampak elegan dengan bahan matte black dan slate gray metal trim.\",\"additional\":\"Dapat dipasang di dinding atau tripod.\"},{\"name\":\"Perekaman dan Streaming 4K\",\"value\":\"Menangkap video hingga 4K pada maksimal 30 fps.\",\"additional\":\"Ideal untuk perekaman dan streaming Ultra HD.\"},{\"name\":\"Plug-and-Play Easy\",\"value\":\"Hubungkan ke daya dan perangkat PC, Mac, dan Chrome\\u2122 via USB.\",\"additional\":\"Kompatibel dengan hampir setiap aplikasi video conferencing.\"}]', '<h4>Fitur Unggulan</h4><p>Dengan teknologi RightSight dan RightLight, Rally Camera memberikan kualitas video yang optimal dalam berbagai kondisi pencahayaan.</p>', 1, 0, 0, '2026-02-20 01:04:23', '2026-02-20 01:04:23'),
(43, 1, 1, 'Logitech Rally Bar + Tap IP', 'logitech-rally-bar-+-tap-ip', '<h4>Deskripsi Produk</h4><p>Paket bundling ini menggabungkan Logitech Rally Bar, video bar all-in-one yang kuat, dengan Logitech Tap IP, pengontrol sentuh berbasis jaringan. Solusi ini dirancang untuk menyederhanakan penerapan Microsoft Teams Rooms atau Zoom Rooms. Dengan Tap IP yang terhubung melalui jaringan (PoE), Anda tidak perlu menarik kabel panjang dari meja ke unit Rally Bar di depan ruangan, memberikan fleksibilitas instalasi yang luar biasa dan meja yang bebas kabel.</p><h4>Fitur Unggulan</h4><ul><li><strong>Konektivitas Berbasis IP:</strong> Tap IP terhubung ke jaringan via kabel Ethernet, bukan langsung ke Rally Bar, memudahkan penataan ruang.</li><li><strong>Pengalaman All-in-One:</strong> Rally Bar bertindak sebagai appliance (komputer) dan kamera/audio sekaligus.</li><li><strong>One-Touch Join:</strong> Memulai rapat semudah mengetuk layar Tap IP.</li><li><strong>Kualitas Audio/Video Premium:</strong> Membawa semua keunggulan optik 4K dan audio stereo Rally Bar.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Isi Paket: Logitech Rally Bar, Logitech Tap IP</li><li>Koneksi Controller: Power over Ethernet (PoE)</li><li>Kompatibilitas: Zoom Rooms, Microsoft Teams Rooms on Android</li></ul>', 'products/logitech-rally-bar-+-tap-ip/logitech-rally-bar-+-tap-ip-2026-1771574663.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '991-000422', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/rallybar.pdf', '[\"video conferencing\",\"logitech rally\",\"tap ip\",\"all-in-one video bar\",\"touch controller\",\"PoE connectivity\",\"business solutions\"]', '{\"Dimensi\":{\"Ketuk IP\":{\"Tinggi\":\"56,1 mm\",\"Lebar\":\"246,2 mm\",\"Tebal\":\"171,3 mm\",\"Berat\":\"1,0 kg\"},\"Rally Bar\":{\"Tinggi\":\"164 mm\",\"Lebar\":\"910 mm\",\"Tebal\":\"130.5 mm\",\"Kedalaman Lensa\":\"28,8 mm\",\"Berat\":\"7,08 kg\"}},\"Spesifikasi Teknis\":{\"Tap IP\":{\"Layar Sentuh\":\"Layar diagonal 257 mm dengan sudut layar 14\\u00b0\",\"Resolusi\":\"1280 x 800\",\"Pengkabelan\":\"Kabel Power over Ethernet (PoE) (tidak disertakan), Perangkat IEEE 802.3af Type 1, Class 3.\",\"Manajemen Kabel\":\"Retensi kabel internal dan sistem strain relief\",\"Ethernet\":\"10\\/100 Mbps\",\"Wi-Fi\":\"802.11a\\/b\\/g\\/n\\/ac\",\"Manajemen Perangkat\":\"Logitech Sync\",\"Warna\":\"Grafit\",\"Pemasangan\":\"100 mm x 100 mm VESA FDMI\"},\"Rally Bar\":{\"Komponen Internal\":\"6 mikrofon beamforming, kamera PTZ, 2 speaker, AI Viewfinder, sistem penyimpanan dan manajemen kabel, dudukan meja, platform Logitech CollabOS\",\"Enklosur\":\"Enclosure all-in-one dengan sistem suspensi berpaten untuk menghilangkan guncangan kamera akibat getaran dan gangguan audio\",\"Manajemen Perangkat\":\"Logitech Sync\",\"Layar yang Didukung\":\"2\",\"Resolusi Layar\":\"Mendukung 1080p\",\"Warna\":\"Graphite, Putih\"}},\"Sertifikasi & Kompatibilitas\":{\"Informasi\":\"Untuk informasi terbaru tentang sertifikasi dan kompatibilitas, kunjungi www.logitech.com\\/support\\/vc-certifications.\",\"Sertifikasi\":[\"Zoom Rooms\",\"Microsoft Teams di Android\",\"Google Meet di Android\"],\"Mode Peralatan\":[\"Zoom Rooms\",\"Microsoft Teams di Android\",\"Google Meet di Android\"]}}', '<h4>Spesifikasi Utama</h4><p>Rally Bar + Tap IP adalah solusi video konferensi all-in-one yang ideal untuk ruangan medium dan besar, dilengkapi dengan teknologi terkini untuk pengalaman kolaborasi yang lebih baik.</p>', '[{\"name\":\"Ideal untuk\",\"value\":\"ruangan medium dan besar untuk maksimum 20 orang\",\"additional\":\"Gunakan Rally Mic Pods tambahan untuk memperluas jangkauan matriks mikrofon beamforming ke seluruh ruangan.\"},{\"name\":\"Garansi\",\"value\":\"hardware terbatas 2 tahun\",\"additional\":\"Perpanjangan garansi satu tahun dan tiga tahun tersedia pada saat pembelian hardware.\"}]', '<h4>Fitur Unggulan</h4><p>Dengan desain yang elegan dan fungsional, Rally Bar + Tap IP menawarkan kualitas video dan audio yang superior, serta kemudahan penggunaan melalui layar sentuh.</p>', 1, 0, 0, '2026-02-20 01:04:23', '2026-02-20 01:04:23');
INSERT INTO `products` (`id`, `service_id`, `brand_id`, `name`, `slug`, `description`, `image_path`, `thumbnail_path`, `price`, `link_accommerce`, `whatsapp_note`, `sku`, `solution_type`, `datasheet_url`, `tags`, `specs`, `specification_text`, `features`, `features_text`, `is_active`, `is_featured`, `is_new`, `created_at`, `updated_at`) VALUES
(44, 1, 1, 'Logitech Rally Bar', 'logitech-rally-bar', '<h4>Deskripsi Produk</h4><p>Logitech Rally Bar adalah video bar \"All-in-One\" premier yang dirancang untuk ruang rapat ukuran sedang hingga besar. Perangkat ini merevolusi pengalaman rapat hibrida dengan sistem kamera ganda (Dual Camera System) dan kecerdasan buatan (AI) yang terintegrasi. Rally Bar dapat beroperasi dalam dua mode: sebagai perangkat USB (terhubung ke PC/Mac) atau dalam Mode Appliance (menjalankan aplikasi seperti Zoom Rooms atau Microsoft Teams Rooms secara native tanpa komputer eksternal).</p><h4>Fitur Unggulan</h4><ul><li><strong>Sistem Kamera Ganda:</strong> Menggabungkan lensa utama optik PTZ untuk kualitas gambar lossless dengan AI Viewfinder sekunder yang mendedikasikan diri untuk memindai ruangan dan melacak peserta aktif.</li><li><strong>Audio Sinematik:</strong> Speaker stereo berkinerja tinggi dengan driver besar yang menghadirkan suara bass yang kaya dan volume yang mengisi ruangan, serta mikrofon beamforming adaptif.</li><li><strong>Manajemen Kabel Rapi:</strong> Penutup belakang yang cerdas menyembunyikan kabel dan menjaga koneksi tetap aman, memberikan tampilan yang sangat bersih di ruang rapat.</li><li><strong>AI Sound Optimization:</strong> RightSound™ menyeimbangkan suara keras dan lembut serta menekan kebisingan latar belakang yang tidak diinginkan.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kamera: Resolusi 4K dengan 5x Optical Zoom (Total 15x Zoom)</li><li>Audio: 6 Beamforming Mics (Jangkauan 4.5m), 2x 70mm Speakers</li><li>Platform: Zoom, Microsoft Teams, Google Meet, GoTo, Pexip, RingCentral</li><li>Konektivitas: HDMI Out (2), HDMI In (1), USB A (3), USB C (1), Ethernet</li></ul>', 'products/logitech-rally-bar/logitech-rally-bar-2026-1771574663.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001311', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/rallybar.pdf', '[\"video conferencing\",\"logitech rally bar\",\"all-in-one video bar\",\"medium room solutions\",\"AI video technology\",\"audio solutions\",\"conference camera\"]', '{\"Dimensi\":{\"Tinggi\":\"164 mm\",\"Lebar\":\"910 mm\",\"Tebal\":\"130.5 mm\",\"Kedalaman Lensa\":\"28,8 mm\"},\"Berat\":\"7,08 kg\",\"Persyaratan Sistem\":{\"Koneksi Internet\":\"kabel atau wireless\",\"Mode USB\":\"Windows 11, Windows 10, dua versi macOS terbaru\",\"Mode Penggunaan\":\"Lisensi perangkat solusi ruangan (tidak termasuk)\"},\"Kompatibilitas\":{\"Microsoft Teams Rooms di Android\":\"Untuk ruangan berukuran medium\",\"Microsoft Teams Rooms di Windows\":\"Untuk ruangan berukuran medium\"},\"Sertifikasi\":\"Untuk informasi terbaru tentang sertifikasi dan kompatibilitas, kunjungi www.logitech.com\\/support\\/vc-certifications\",\"Daya\":{\"Catu daya\":\"Auto-sensing\",\"Voltase Operasi\\/Daya\":\"100-240V, 19V, 4.74A\",\"Dimensi Catu Daya\":\"127 mm x 51 mm x 30 mm\",\"Kabel DC\":\"1,5 m\",\"Kabel AC\":\"1 m\",\"Kabel HDMI 1.4\":\"2 m\",\"Kabel USB-A ke USB-C 3.0\":\"2,2 m\"},\"Lingkungan\":{\"Suhu Pengoperasian\":\"0 hingga 40\\u00b0C\",\"Suhu Penyimpanan\":\"-40 hingga 70 \\u00b0C\",\"Kelembapan\":\"10 hingga 95%\",\"BTU\\/jam\":\"57 idle, 64 dalam pertemuan\"}}', '<h4>Spesifikasi Utama</h4><p>Rally Bar adalah video bar all-in-one yang dirancang untuk ruangan berukuran medium hingga besar, dengan teknologi AI dan audio berkualitas tinggi.</p>', '[{\"name\":\"Resolusi\",\"value\":\"4K, 1440p, 1080p, 900p, 720p, dan SD pada 30 fps\",\"additional\":\"\"},{\"name\":\"Pan (Geser)\",\"value\":\"Bermotor \\u00b125\\u00b0\",\"additional\":\"\"},{\"name\":\"Tilt (Miring)\",\"value\":\"Bermotor \\u00b115\\u00b0\",\"additional\":\"\"},{\"name\":\"Zoom\",\"value\":\"15X HD zoom (5X optik dan 3X digital)\",\"additional\":\"\"},{\"name\":\"Bidang Pandang Diagonal\",\"value\":\"90\\u00b0\",\"additional\":\"\"},{\"name\":\"Bidang Pandang Horizontal\",\"value\":\"82,1\\u00b0\",\"additional\":\"\"},{\"name\":\"Bidang Pandang Vertikal\",\"value\":\"52,2\\u00b0\",\"additional\":\"\"},{\"name\":\"Total Cakupan Ruangan\",\"value\":\"132,1\\u00b0 horizontal x 82,2\\u00b0 vertikal\",\"additional\":\"\"},{\"name\":\"Driver Speaker\",\"value\":\"2x 70 mm\",\"additional\":\"\"},{\"name\":\"Sensitivitas Speaker\",\"value\":\"92dB SPL @1W, 99dB SPL @8.0W\",\"additional\":\"\"},{\"name\":\"Rated Power\",\"value\":\"8W\",\"additional\":\"\"},{\"name\":\"THD\",\"value\":\"1kHz < 2% pada 1W\",\"additional\":\"\"},{\"name\":\"Speaker Sampling Rate\",\"value\":\"48 kHz\",\"additional\":\"\"},{\"name\":\"Impedansi\",\"value\":\"4 Ohm\",\"additional\":\"\"},{\"name\":\"Respons Frekuensi Mikrofon\",\"value\":\"90Hz \\u2013 16kHz\",\"additional\":\"\"},{\"name\":\"Sensitivitas Mikrofon\",\"value\":\">-36 dBFS +\\/-1 dB @ 1 Pa\",\"additional\":\"\"},{\"name\":\"Jangkauan Pickup\",\"value\":\"Maksimum 7 m\",\"additional\":\"\"},{\"name\":\"Unsur Beamforming\",\"value\":\"6 mikrofon MEMS digital omnidirectional membentuk 5 broadside beam akustik adaptif\",\"additional\":\"\"},{\"name\":\"Pemrosesan audio\",\"value\":\"AEC (Acoustic Echo Cancellation), VAD (Voice Activity Detector)\",\"additional\":\"\"},{\"name\":\"Peredaman noise\",\"value\":\"De-noising algoritma berbasis AI\",\"additional\":\"\"},{\"name\":\"Add-on Mic\",\"value\":\"Mendukung maksimum 4 Rally Mic Pod dan 2 Rally Mic Pod Hub tambahan untuk ruang konferensi berukuran besar\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Dengan kemampuan video 4K dan audio yang canggih, Rally Bar memberikan pengalaman konferensi yang luar biasa.</p>', 1, 0, 0, '2026-02-20 01:04:23', '2026-02-20 01:04:23'),
(45, 1, 1, 'Logitech Rally Bar Huddle', 'logitech-rally-bar-huddle', '<h4>Deskripsi Produk</h4><p>Logitech Rally Bar Huddle adalah video bar terbaru yang dirancang khusus untuk ruang huddle dan ruang rapat kecil yang dinamis. Perangkat ini menonjol dengan desain yang modern, penutup kain yang dapat diganti, dan kemudahan penggunaan. Rally Bar Huddle dibangun untuk skala besar, memungkinkan tim IT menyebarkan ribuan unit dengan mudah berkat manajemen jarak jauh via Logitech Sync. Perangkat ini juga merupakan produk video conference pertama Logitech yang dibuat dengan plastik daur ulang dalam jumlah besar.</p><h4>Fitur Unggulan</h4><ul><li><strong>Penutup Privasi Otomatis:</strong> Shutter fisik yang menutup lensa secara otomatis saat rapat berakhir untuk keamanan visual yang jelas.</li><li><strong>Integrasi CollabOS:</strong> Sistem operasi yang aman dan terus diperbarui, mendukung platform video utama secara native.</li><li><strong>Opsi Mounting Fleksibel:</strong> Dapat dipasang di dinding, di atas meja, atau digantung di layar (Multi-Mount dijual terpisah).</li><li><strong>Kualitas Suara AI:</strong> Menghilangkan kebisingan latar belakang menggunakan algoritma berbasis AI untuk kejernihan vokal maksimal.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kamera: 4K ePTZ (Digital Pan/Tilt/Zoom), 4x Zoom</li><li>Field of View: 120° Diagonal</li><li>Mikrofon: 6 mikrofon MEMS digital omni-directional</li><li>Konektivitas: HDMI, USB, WiFi, Ethernet (PoE)</li></ul>', 'products/logitech-rally-bar-huddle/logitech-rally-bar-huddle-2026-1771574664.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001501', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/rallybar-huddle-datasheet.pdf', '[\"video bar\",\"logitech rally\",\"video conferencing\",\"huddle room\",\"small room solutions\",\"collaboration tools\",\"hybrid work\"]', '{\"Dimensi\":{\"Lebar\":\"549,6 mm\",\"Tinggi\":\"78,9 mm\",\"Tebal\":\"76,0 mm\",\"Berat\":\"1,8 kg\"},\"Kompatibilitas\":{\"Koneksi Internet\":\"kabel atau wireless\",\"Mode USB\":\"Windows 11, Windows 10, dua versi macOS terbaru\",\"Mode Penggunaan\":\"Lisensi perangkat solusi ruangan (tidak termasuk)\"},\"Sertifikasi\":\"Untuk informasi terbaru tentang sertifikasi dan kompatibilitas, lihat www.logitech.com\\/support\\/vc-certifications.\",\"Daya\":{\"Catu daya\":\"Auto-sensing\",\"Voltase Operasi\\/Daya\":\"100-240V, 19V, 2,1A\"},\"Lingkungan\":{\"Suhu Pemakaian\":\"0 hingga 40\\u00b0C\",\"Suhu Penyimpanan\":\"-25 hingga 70\\u00b0C\",\"Kelembapan\":\"10 hingga 90%\"},\"Audio\":{\"Driver\":\"55 mm dengan enclosure bass reflex dan desain suspensi yang dipatenkan\",\"Sensitivitas\":\"83 dB SPL @1W +\\/-2dB @ 1 meter\",\"Rated Power\":\"8W\"},\"Kamera\":{\"Resolusi\":\"4K\",\"Bidang Pandang Diagonal\":\"120\\u00b0\",\"Zoom\":\"4X HD digital zoom\"},\"Mikrofon\":{\"Respons Frekuensi\":\"90Hz \\u2013 16kHz\",\"Jangkauan Pickup\":\"Maksimum 7 m\"}}', '<h4>Spesifikasi Utama</h4><p>Rally Bar Huddle adalah solusi video bar all-in-one yang dirancang untuk ruang berkumpul dan ruangan kecil, dengan kualitas audio dan video yang superior.</p>', '[{\"name\":\"Kamera PTZ Digital\",\"value\":\"Ya\",\"additional\":\"Mendukung zoom dan tilt\"},{\"name\":\"Manajemen Kabel\",\"value\":\"Ya\",\"additional\":\"Sistem retensi kabel\"},{\"name\":\"Multi Mount\",\"value\":\"Ya\",\"additional\":\"Dapat dipasang di dinding atau meja\"},{\"name\":\"Shutter Privasi\",\"value\":\"Ya\",\"additional\":\"Privasi terjamin dengan shutter bermotor\"},{\"name\":\"Logitech Sync\",\"value\":\"Ya\",\"additional\":\"Manajemen perangkat yang mudah\"}]', '<h4>Fitur Unggulan</h4><p>Dengan teknologi canggih dan desain yang ramping, Rally Bar Huddle memudahkan kolaborasi dalam pertemuan hibrida.</p>', 1, 0, 0, '2026-02-20 01:04:23', '2026-02-20 01:04:24'),
(46, 1, 1, 'Logitech Rally Bar Mini + Tap IP', 'logitech-rally-bar-mini-+-tap-ip', '<h4>Deskripsi Produk</h4><p>Logitech Rally Bar Mini + Tap IP adalah solusi konferensi video all-in-one untuk ruang kecil hingga menengah. Kombinasi Rally Bar Mini dengan Tap IP menghadirkan pengalaman rapat berbasis jaringan (PoE) yang rapi, fleksibel, dan profesional.</p><h4>Fitur Utama</h4><ul><li><strong>All-in-One Video Bar:</strong> Kamera 4K, speaker, dan mikrofon terintegrasi.</li><li><strong>Tap IP Controller:</strong> Kontrol rapat berbasis jaringan dengan PoE.</li><li><strong>AI Auto-Framing:</strong> Teknologi RightSight™ untuk framing otomatis.</li><li><strong>Instalasi Rapi:</strong> Manajemen kabel minimal.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kamera: 4K</li><li>Koneksi Controller: PoE (Ethernet)</li><li>Platform: Teams Rooms & Zoom Rooms</li></ul>', 'products/logitech-rally-bar-mini-+-tap-ip/logitech-rally-bar-mini-+-tap-ip-2026-1771574664.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '991-000388', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/rallybarmini.pdf', '[\"video conferencing\",\"logitech rally bar\",\"tap ip\",\"video bar\",\"collaboration tools\",\"conference room solutions\",\"logitech video conferencing\"]', '{\"Dimensi\":{\"Ketuk IP\":{\"Tinggi\":\"56,1 mm\",\"Lebar\":\"246,2 mm\",\"Tebal\":\"171,3 mm\",\"Berat\":\"1,0 kg\"},\"Rally Bar Mini\":{\"Tinggi\":\"91.4 mm\",\"Lebar\":\"719 mm\",\"Tebal\":\"101 mm\",\"Kedalaman Lensa\":\"18,5 mm\",\"Berat\":\"4,03 kg\"}},\"Spesifikasi Teknis\":{\"Ketuk IP\":{\"Layar Sentuh\":\"Layar diagonal 257 mm dengan sudut layar 14\\u00b0\",\"Resolusi\":\"1280 x 800\",\"Pengkabelan\":\"Kabel Power over Ethernet (PoE) (tidak disertakan), Perangkat IEEE 802.3af Type 1, Class 3.\",\"Manajemen Kabel\":\"Retensi kabel internal dan sistem strain relief\",\"Ethernet\":\"10\\/100 Mbps\",\"Wi-Fi\":\"802.11a\\/b\\/g\\/n\\/ac\",\"Manajemen Perangkat\":\"Logitech Sync\",\"Warna\":\"Grafit\",\"Pemasangan\":\"100 mm x 100 mm VESA FDMI\"},\"Rally Bar Mini\":{\"Komponen Internal\":\"6 mikrofon beamforming, kamera dengan fungsi pan (geser) dan tilt (miring) bermotor dilengkapi 4x zoom digital, 3 speaker, AI Viewfinder, sistem penyimpanan dan manajemen kabel, dudukan meja, platform Logitech CollabOS\",\"Enklosur\":\"Enclosure all-in-one dengan dudukan meja terintegrasi dan sistem suspensi speaker berpaten\",\"Manajemen Perangkat\":\"Logitech Sync\",\"Layar yang Didukung\":\"2\",\"Resolusi Layar\":\"Mendukung hingga 1080p\"}},\"Sertifikasi & Kompatibilitas\":{\"Informasi\":\"Untuk informasi terbaru tentang sertifikasi dan kompatibilitas, kunjungi www.logitech.com\\/support\\/vc-certifications.\",\"Sertifikasi\":\"Semua komponen yang disertakan dalam bundle room solution sudah disertifikasi untuk Zoom Rooms, Microsoft Teams di Android, Google Meet di Android.\"}}', '<h4>Spesifikasi Utama</h4><p>Rally Bar Mini + Tap IP adalah solusi lengkap untuk video konferensi dengan fitur canggih dan desain yang kompak.</p>', '[{\"name\":\"Ideal untuk\",\"value\":\"ruangan kecil dan medium untuk maksimum 12 orang\",\"additional\":\"\"},{\"name\":\"Dukungan\",\"value\":\"Microsoft Teams Rooms, Zoom Rooms, Google Meet di Android\",\"additional\":\"\"},{\"name\":\"Garansi\",\"value\":\"Hardware terbatas 2 tahun\",\"additional\":\"Perpanjangan garansi satu tahun dan tiga tahun tersedia pada saat pembelian hardware.\"}]', '<h4>Fitur Unggulan</h4><p>Dengan dukungan untuk berbagai platform video conferencing, Rally Bar Mini + Tap IP menawarkan fleksibilitas dan kemudahan penggunaan.</p>', 1, 0, 0, '2026-02-20 01:04:24', '2026-02-20 01:04:24'),
(47, 1, 1, 'Logitech Rally Bar Mini', 'logitech-rally-bar-mini', '<h4>Deskripsi Produk</h4><p>Logitech Rally Bar Mini adalah versi kompak dari Rally Bar yang dirancang khusus untuk ruang rapat kecil dan huddle rooms. Meskipun ukurannya lebih kecil, perangkat ini tidak mengorbankan kecerdasan atau kualitas. Rally Bar Mini menghadirkan video berkualitas bioskop dan audio yang jernih dalam desain all-in-one yang hemat tempat. Seperti kakaknya, ia mendukung mode Appliance untuk menjalankan aplikasi konferensi video secara langsung tanpa PC.</p><h4>Fitur Unggulan</h4><ul><li><strong>Kecerdasan Buatan (AI):</strong> Menggunakan AI Viewfinder dan RightSight 2 untuk auto-framing dan speaker tracking yang presisi.</li><li><strong>Mekanisme Pan/Tilt Bermotor:</strong> Lensa di dalam unit dapat bergerak secara mekanis untuk mencakup seluruh ruangan (hingga 163° horizontal coverage) tanpa distorsi digital berlebih.</li><li><strong>Audio Duplex Penuh:</strong> Memungkinkan percakapan dua arah yang natural dengan peredaman gema dan kebisingan yang canggih.</li><li><strong>Desain Ramah Lingkungan:</strong> Dibuat menggunakan plastik daur ulang pasca-konsumen untuk mengurangi jejak karbon.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kamera: 4K Ultra HD, Pan ±25°, Tilt ±15°, 4x Digital Zoom</li><li>Field of View: 120° Diagonal (Super Wide)</li><li>Audio: Woofer 70mm, 2x Mid-range drivers, 6x Beamforming mics</li><li>Dimensi: 91.4 mm x 719 mm x 101 mm</li></ul>', 'products/logitech-rally-bar-mini/logitech-rally-bar-mini-2026-1771574664.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001339', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/rallybarmini.pdf', '[\"video conferencing\",\"logitech rally\",\"all-in-one video bar\",\"small room solutions\",\"AI video technology\",\"Logitech Sync\",\"conference camera\"]', '{\"Dimensi\":{\"Tinggi\":\"91.4 mm\",\"Lebar\":\"719 mm\",\"Tebal\":\"101 mm\",\"Ketebalan Lensa\":\"18,5 mm\"},\"Berat\":\"4,03 kg\",\"Persyaratan Sistem\":{\"Koneksi Internet\":\"kabel atau wireless\",\"Mode USB\":\"Windows 11, Windows 10, dua versi macOS terbaru\",\"Mode Penggunaan\":\"Lisensi perangkat solusi ruangan (tidak termasuk)\"},\"Kompatibilitas\":{\"Microsoft Teams Rooms di Android\":\"Untuk ruangan berukuran kecil\",\"Microsoft Teams Rooms di Windows\":\"Untuk ruangan berukuran kecil\"},\"Sertifikasi\":\"Untuk informasi terbaru tentang sertifikasi dan kompatibilitas, kunjungi www.logitech.com\\/support\\/vc-certifications\",\"Daya\":{\"Catu daya\":\"Auto-sensing\",\"Voltase Operasi\\/Daya\":\"100-240V, 19V, 4.74A\",\"Dimensi Catu Daya\":\"127 mm x 51 mm x 30 mm\",\"Kabel DC\":\"1,5 m\",\"Kabel AC\":\"1 m\",\"Kabel HDMI 1.4\":\"2 m\",\"Kabel USB-A ke USB-C 3.0\":\"2,2 m\"},\"Lingkungan\":{\"Suhu Pengoperasian\":\"0 hingga 40\\u00b0C\",\"Suhu Penyimpanan\":\"-40 hingga 70\\u00b0C\",\"Kelembapan\":\"10 hingga 95%\",\"BTU\\/jam\":\"57 idle, 64 dalam pertemuan\"}}', '<h4>Spesifikasi Utama</h4><p>Rally Bar Mini adalah solusi video conferencing yang sangat sederhana dengan teknologi AI, optik brilian, dan audio yang luar biasa.</p>', '[{\"name\":\"Resolusi\",\"value\":\"4K, 1440p, 1080p, 900p, 720p, dan SD pada 30 fps\",\"additional\":\"\"},{\"name\":\"Pan (Geser)\",\"value\":\"Bermotor \\u00b125\\u00b0\",\"additional\":\"\"},{\"name\":\"Tilt (Miring)\",\"value\":\"Bermotor \\u00b115\\u00b0\",\"additional\":\"\"},{\"name\":\"Zoom\",\"value\":\"4X HD digital zoom\",\"additional\":\"\"},{\"name\":\"Bidang Pandang Diagonal\",\"value\":\"120\\u00b0\",\"additional\":\"\"},{\"name\":\"Bidang Pandang Horizontal\",\"value\":\"113\\u00b0\",\"additional\":\"\"},{\"name\":\"Bidang Pandang Vertikal\",\"value\":\"80.7\\u00b0\",\"additional\":\"\"},{\"name\":\"Total Cakupan Ruangan\",\"value\":\"163\\u00b0 Horizontal x 110\\u00b0 Vertikal\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Dengan kemampuan video 4K dan audio yang ditingkatkan, Rally Bar Mini memberikan pengalaman konferensi yang luar biasa.</p>', 1, 0, 0, '2026-02-20 01:04:24', '2026-02-20 01:04:24'),
(48, 1, 1, 'Logitech Room Booking', 'logitech-room-booking', '<h4>Deskripsi Produk</h4><p>Logitech Room Booking adalah solusi manajemen dan penjadwalan ruang meeting yang memungkinkan organisasi memonitor dan mengelola penggunaan ruangan secara efisien. Sistem ini membantu meningkatkan produktivitas dan pemanfaatan ruang kerja.</p><h4>Fitur Utama</h4><ul><li><strong>Manajemen Ruang:</strong> Monitoring penggunaan ruang secara real-time.</li><li><strong>Integrasi Kalender:</strong> Terhubung dengan Microsoft 365 dan Google Workspace.</li><li><strong>Dashboard Terpusat:</strong> Kontrol dan analitik dalam satu platform.</li><li><strong>Skalabilitas Tinggi:</strong> Cocok untuk kantor kecil hingga enterprise.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Platform: Cloud-based</li><li>Integrasi: Microsoft & Google</li><li>Akses: Web dashboard</li></ul>', 'products/logitech-room-booking/logitech-room-booking-2026-1771574664.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', NULL, NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/essential-datasheet.pdf', '[\"logitech room booking\",\"reservasi ruangan\",\"video conference\",\"manajemen ruangan\",\"integrasi kalender\",\"keamanan perusahaan\",\"solusi ruang kerja\"]', '{\"Dimensi\":{\"Tinggi\":\"N\\/A\",\"Lebar\":\"N\\/A\",\"Panjang\":\"N\\/A\"},\"Berat\":\"N\\/A\",\"Persyaratan Sistem\":\"N\\/A\",\"Kompatibilitas\":{\"Windows\":\"N\\/A\",\"Mac\":\"N\\/A\",\"Linux\":\"N\\/A\"},\"Sertifikasi\":\"N\\/A\",\"Daya\":\"N\\/A\",\"Lingkungan\":\"N\\/A\"}', '<h4>Spesifikasi Utama</h4><p>Logitech Room Booking menawarkan solusi reservasi ruangan yang mudah digunakan dan terintegrasi dengan berbagai platform.</p>', '[{\"name\":\"Integrasi Kalender\",\"value\":\"Terintegrasi dengan Google Workspace dan Office 365\",\"additional\":\"\"},{\"name\":\"Keamanan Standar Perusahaan\",\"value\":\"Menggunakan enkripsi end-to-end\",\"additional\":\"\"},{\"name\":\"Multitenancy\",\"value\":\"Kelola di beberapa organisasi\",\"additional\":\"\"},{\"name\":\"Sign-on Tunggal\",\"value\":\"Menambahkan kenyamanan dan keamanan\",\"additional\":\"\"},{\"name\":\"Reservasi dan Rilis Otomatis\",\"value\":\"Mengubah status ruangan secara otomatis\",\"additional\":\"\"},{\"name\":\"Manajemen Sederhana\",\"value\":\"Dikelola melalui Logitech Sync\",\"additional\":\"\"},{\"name\":\"Kelola Peta\",\"value\":\"Unggah dan sesuaikan peta dengan mudah\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Dengan fitur-fitur canggih, Logitech Room Booking memudahkan kolaborasi dan manajemen ruangan.</p>', 1, 0, 0, '2026-02-20 01:04:24', '2026-02-20 01:04:25'),
(49, 1, 1, 'Logitech RoomMate', 'logitech-roommate', '<h4>Deskripsi Produk</h4><p>Logitech RoomMate adalah appliance komputasi (CollabOS Box) yang dirancang khusus untuk menjalankan layanan konferensi video seperti Zoom Rooms, Microsoft Teams Rooms, dan RingCentral Rooms tanpa memerlukan PC atau Mac. RoomMate mengubah sistem kamera USB modular seperti Logitech Rally Plus atau MeetUp menjadi sistem appliance mandiri yang cerdas. Ini menyederhanakan penyebaran ruang rapat berskala besar dengan perangkat keras yang didedikasikan untuk video, bukan komputer tujuan umum.</p><h4>Fitur Unggulan</h4><ul><li><strong>Kekuatan CollabOS:</strong> Sistem operasi yang aman, terkunci, dan mudah dikelola jarak jauh melalui Logitech Sync.</li><li><strong>Fleksibilitas Audio/Video:</strong> Mendukung hingga 2 layar HD dan sistem audio eksternal melalui USB atau port audio khusus.</li><li><strong>Manajemen Kabel:</strong> Mengunci kabel di tempatnya untuk mencegah diskoneksi yang tidak disengaja.</li><li><strong>Desain Low-Profile:</strong> Ukuran kecil dan tipis, mudah dipasang di belakang layar atau di bawah meja menggunakan Compute Mount.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Output Video: 2x HDMI (hingga 1080p dual atau 4K single)</li><li>Input Video: 1x HDMI (untuk sharing konten)</li><li>Port: 3x USB-A, 1x Ethernet (Gigabit), WiFi 802.11ac</li></ul>', 'products/logitech-roommate/logitech-roommate-2026-1771574665.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '950-000084', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/roommate.pdf', '[\"video conferencing\",\"logitech roommate\",\"collabOS\",\"microsoft teams\",\"zoom rooms\",\"audio conferencing\",\"video collaboration\"]', '{\"Dimensi\":{\"Tinggi\":\"34,5 mm\",\"Lebar\":\"161 mm\",\"Tebal\":\"211 mm\"},\"Persyaratan Sistem\":{\"Koneksi\":\"internet berkabel atau wireless\",\"Lisensi\":\"software room solution (tidak termasuk)\"},\"Umum\":{\"Sistem Operasi\":\"Logitech CollabOS 1.4 atau versi lebih baru\",\"Manajemen Perangkat\":\"Logitech Sync dan platform manajemen perangkat yang didukung\",\"Dukungan Protokol Jaringan\":\"IPv4, IPv6\",\"Dukungan Proxy\":\"Proxy berbasis IP, Proxy berbasis FQDN, Proxy menggunakan file PAC\"},\"Kompatibilitas\":{\"Sertifikasi\":[\"Microsoft Teams Rooms di Android\",\"Zoom Rooms\"],\"Mode Appliance\":[\"Microsoft Teams Rooms di Android\",\"Zoom Rooms\",\"Tencent Meeting Rooms\"],\"Hardware Audio yang Sudah Terverifikasi\":[\"Biamp TesiraFORT\\u00c9 X Series, Devio SCX Series, TesiraFORT\\u00c9 AVB VT4 dengan Tesira EX-UBT\",\"Extron DMP Plus dan MediaPort DSP\",\"Jajaran produk sistem audio conferencing Nureva HDL\",\"Prosesor Inti Q-SYS\",\"Shure IntelliMix P300\"],\"Hardware Tersertifikasi\":[\"Logitech MeetUp\",\"Rally Camera\",\"Rally System\",\"Rally Plus System\",\"Tap\",\"Tap IP\"],\"Tanda Digital\":[\"Appspace\",\"Tanda Digital Zoom Rooms (hanya konten video)\"]},\"Antarmuka\":{\"HDMI Out\":\"2 (maksimum 1080p)\",\"HDMI In\":\"1\",\"USB\":\"3x Type A 2.0\",\"Jaringan\":\"10\\/100\\/1G Ethernet\",\"WiFi\":\"802.11a\\/b\\/g\\/n\\/ac\",\"Remote Control\":\"Bluetooth\\u00ae Low Energy\"},\"Daya\":{\"Catu daya\":\"Auto-sensing\",\"Voltase Operasi\\/Daya\":\"100-240V, 19V, 4.74A\",\"Dimensi Catu Daya\":\"127 mm x 51 mm x 30 mm\",\"Kabel DC\":\"1,5 m\",\"Kabel AC\":\"1 m\"},\"Lingkungan\":{\"Suhu Pengoperasian\":\"0 hingga 40\\u00b0C\",\"Suhu Penyimpanan\":\"-40 hingga 70\\u00b0C\",\"Kelembapan\":\"10 hingga 95%\"},\"Keamanan\":{\"Full Disk Encryption\":\"Port USB yang kosong\",\"Enkripsi Data\":\"Tombol Simetris, PKI\",\"Identitas Perangkat\":\"Dilindungi oleh atestasi perangkat\",\"Akses Perangkat\":\"Diautentikasi menggunakan API\",\"Perlindungan Tombol\":\"Arm TrustZone, RPMP\",\"Keamanan Perangkat\":\"Kensington Lock\"}}', '<h4>Spesifikasi Utama</h4><p>Logitech RoomMate adalah appliance yang dirancang untuk video meeting dengan dukungan untuk berbagai platform konferensi.</p>', '[{\"name\":\"Fleksibilitas Modular\",\"value\":\"Hubungkan Rally System modular atau MeetUp ke RoomMate dan tambahkan Logitech Tap touch controller.\",\"additional\":\"Persyaratan pemasangan dapat bervariasi.\"},{\"name\":\"Kemampuan, Dengan Koneksi\",\"value\":\"RoomMate menghadirkan kemampuan untuk menyelenggarakan video conferencing berkualitas HD.\",\"additional\":\"Dapat digunakan dengan satu, dua, atau tiga layar.\"},{\"name\":\"Fleksibel, Rapi, Aman\",\"value\":\"Pasang RoomMate dengan aman dan tersembunyi.\",\"additional\":\"Compute Mount opsional mendukung pemasangan yang tidak kentara.\"},{\"name\":\"Partner Audio yang Sudah Terverifikasi\",\"value\":\"Gunakan sistem audio pilihan Anda.\",\"additional\":\"Default pada audio kamera konferensi.\"}]', '<h4>Fitur Unggulan</h4><p>RoomMate menawarkan fleksibilitas modular dan kemampuan untuk menghubungkan berbagai perangkat audio dan video.</p>', 1, 0, 0, '2026-02-20 01:04:25', '2026-02-20 01:04:25'),
(50, 1, 1, 'Logitech Scribe Glass Mount', 'logitech-scribe-glass-mount', '<h4>Deskripsi Produk</h4><p>Logitech Scribe Glass Mount adalah aksesori pemasangan khusus yang dirancang untuk memasang kamera whiteboard Logitech Scribe pada permukaan kaca, seperti dinding partisi kaca di ruang rapat modern. Mount ini menggunakan perekat kekuatan industri yang aman untuk memastikan kamera tetap kokoh di tempatnya tanpa perlu mengebor lubang pada kaca, menjaga estetika ruangan tetap bersih dan transparan.</p><h4>Fitur Unggulan</h4><ul><li><strong>Instalasi Tanpa Bor:</strong> Menggunakan perekat berkualitas tinggi yang kuat dan tahan lama.</li><li><strong>Desain Minimalis:</strong> Warna putih yang menyatu dengan unit Scribe dan estetika kantor modern.</li><li><strong>Kompatibilitas Khusus:</strong> Dirancang presisi hanya untuk Logitech Scribe.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Tipe Mounting: Perekat Kaca (Adhesive)</li><li>Warna: Putih (Polar White)</li><li>Material: Polikarbonat tahan lama</li></ul>', 'products/logitech-scribe-glass-mount/logitech-scribe-glass-mount-2026-1771574665.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000120', NULL, 'https://activ.co.id/datasheet/logitech/scribe-glass-mount-document.pdf', '[\"logitech scribe\",\"glass mount\",\"video conferencing\",\"whiteboard camera\",\"meeting accessories\",\"office solutions\",\"collaboration tools\"]', '{\"Dimensi\":{\"Tinggi\":\"114 mm\",\"Lebar\":\"114 mm\",\"Tebal\":\"14 mm\"},\"Kompatibilitas\":{\"Material\":\"Kaca\",\"Catatan\":\"Tidak kompatibel dengan kaca buram\"},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Pasang Logitech Scribe di permukaan kaca untuk pengalaman video meeting yang lebih baik.</p>', '[{\"name\":\"Mount\",\"value\":\"Dapat dipasang pada permukaan kaca\",\"additional\":\"\"},{\"name\":\"Dokumentasi\",\"value\":\"QSG, IID\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Mount yang mudah dipasang dan kompatibel dengan kaca, ideal untuk ruang rapat.</p>', 1, 0, 0, '2026-02-20 01:04:25', '2026-02-20 01:04:25'),
(51, 1, 1, 'Logitech Scribe Polarizer', 'logitech-scribe-polarizer', '<h4>Deskripsi Produk</h4><p>Logitech Scribe Polarizer adalah filter lensa opsional yang dirancang untuk kamera Logitech Scribe. Aksesori ini sangat penting di ruangan dengan pencahayaan yang sangat terang atau memiliki banyak pantulan cahaya (glare) pada papan tulis. Filter polarisasi ini bekerja dengan memotong silau yang dipantulkan dari permukaan whiteboard yang mengkilap, memastikan kamera dapat menangkap tulisan spidol dengan jelas tanpa gangguan \"hotspot\" cahaya.</p><h4>Fitur Unggulan</h4><ul><li><strong>Pengurangan Silau:</strong> Meminimalkan refleksi cahaya lampu atau jendela pada papan tulis.</li><li><strong>Peningkatan Saturasi:</strong> Membantu meningkatkan kontras warna spidol di bawah cahaya ekstrem.</li><li><strong>Pemasangan Mudah:</strong> Dapat dipasang langsung di depan lensa Scribe dengan mekanisme putar untuk penyesuaian sudut polarisasi.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Eksklusif untuk Logitech Scribe</li><li>Fungsi: Circular Polarizer (CPL)</li></ul>', 'products/logitech-scribe-polarizer/logitech-scribe-polarizer-2026-1771574666.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000116', NULL, 'https://www.logitech.com/content/dam/logitech/en_us/video-collaboration/pdf/scribe.pdf', '[\"polarizer\",\"logitech scribe\",\"video conferencing\",\"accessories\",\"glare reduction\",\"camera filter\",\"whiteboard visibility\"]', '{\"Dimensi\":{\"Tinggi\":\"93 mm\",\"Diameter Atas\":\"77,6 mm\",\"Diameter Bawah\":\"71,3 mm\"},\"Berat\":\"70 g\",\"Lingkungan\":{\"Suhu Penyimpanan\":\"-30 hingga 70\\u00b0C\"},\"Kompatibilitas\":{\"Produk\":\"Logitech Scribe\"},\"Garansi\":\"Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Polarizer ini dirancang untuk mengurangi cahaya terang dan meningkatkan visibilitas dalam ruangan dengan pencahayaan yang sangat terang.</p>', '[{\"name\":\"Pengurangan Cahaya Terang\",\"value\":\"Mengurangi cahaya terang dalam lingkungan dengan pencahayaan yang sangat terang.\",\"additional\":\"Membantu visibilitas whiteboard.\"},{\"name\":\"Mudah Dipasang\",\"value\":\"Polarizer opsional ini mudah dipasangkan ke lensa kamera Scribe.\",\"additional\":\"Memastikan semua orang dapat melihat whiteboard dengan jelas.\"}]', '<h4>Fitur Unggulan</h4><p>Polarizer ini mudah dipasang dan membantu mengelola pantulan dari whiteboard, memastikan visibilitas yang lebih baik.</p>', 1, 0, 0, '2026-02-20 01:04:25', '2026-02-20 01:04:26'),
(52, 1, 1, 'Logitech Scribe Security Cable', 'logitech-scribe-security-cable', '<h4>Deskripsi Produk</h4><p>Logitech Scribe Security Cable adalah kabel pengaman yang dirancang untuk melindungi perangkat Logitech Scribe dari risiko pencurian atau pemindahan tanpa izin. Aksesori ini ideal untuk ruang meeting publik atau area dengan tingkat lalu lintas tinggi.</p><h4>Fitur Utama</h4><ul><li><strong>Keamanan Tambahan:</strong> Mengunci perangkat dengan aman.</li><li><strong>Instalasi Mudah:</strong> Sistem penguncian sederhana.</li><li><strong>Konstruksi Kokoh:</strong> Material tahan lama.</li><li><strong>Kompatibilitas Khusus:</strong> Untuk Logitech Scribe.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Logitech Scribe</li><li>Tipe: Security Cable</li><li>Material: Baja berlapis</li></ul>', 'products/logitech-scribe-security-cable/logitech-scribe-security-cable-2026-1771574668.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000150', NULL, 'https://www.logitech.com/content/dam/logitech/en_us/video-collaboration/pdf/scribe.pdf', '[\"logitech scribe\",\"video conferencing\",\"secure latch\",\"accessories\",\"meeting room\",\"collaboration tools\",\"hardware security\"]', '{\"Dimensi\":{\"Tinggi\":\"5,72 mm\",\"Panjang\":\"26 mm\",\"Lebar\":\"13,5 mm\"},\"Kompatibilitas\":[],\"Sertifikasi\":[],\"Daya\":[],\"Lingkungan\":[],\"Persyaratan Sistem\":[]}', '<h4>Spesifikasi Utama</h4><p>Kaitan Pengaman Scribe dirancang untuk menjaga Logitech Scribe tetap kokoh di tempatnya dengan dimensi yang kompak.</p>', '[{\"name\":\"Latch Pengaman\",\"value\":\"Ya\",\"additional\":\"\"},{\"name\":\"Kunci Torx\",\"value\":\"Ya\",\"additional\":\"\"},{\"name\":\"Dokumentasi\",\"value\":\"Ya\",\"additional\":\"\"},{\"name\":\"Garansi Hardware\",\"value\":\"Terbatas 2 Tahun\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Fitur keamanan yang kuat dan mudah dipasang, dilengkapi dengan kunci Torx dan dokumentasi lengkap.</p>', 1, 0, 0, '2026-02-20 01:04:26', '2026-02-20 01:04:28'),
(53, 1, 1, 'Logitech Scribe Share Button', 'logitech-scribe-share-button', '<h4>Deskripsi Produk</h4><p>Logitech Scribe Share Button adalah tombol nirkabel tambahan yang memberikan kontrol taktil kepada presenter saat menggunakan kamera Scribe. Tombol ungu yang ikonik ini dapat ditempatkan di mana saja di dekat papan tulis (menggunakan perekat). Dengan menekan tombol ini, presenter dapat secara instan memulai atau menghentikan berbagi tampilan papan tulis ke dalam rapat video, tanpa perlu kembali ke pengontrol sentuh di meja.</p><h4>Fitur Unggulan</h4><ul><li><strong>Kontrol Instan:</strong> Mulai sharing dengan satu sentuhan jari atau siku.</li><li><strong>Konektivitas Bluetooth:</strong> Terhubung secara nirkabel ke unit Scribe (via dongle/receiver).</li><li><strong>Baterai Tahan Lama:</strong> Menggunakan baterai standar yang tahan bertahun-tahun penggunaan normal.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Warna: Ungu (khas tombol share Logitech)</li><li>Koneksi: Bluetooth Low Energy</li><li>Baterai: 2x CR2032 batteries</li></ul>', 'products/logitech-scribe-share-button/logitech-scribe-share-button-2026-1771574669.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000102', NULL, 'https://www.logitech.com/content/dam/logitech/en_in/video-collaboration/pdf/scribe.pdf', '[\"logitech scribe\",\"tombol berbagi\",\"video conferencing\",\"whiteboard sharing\",\"wireless button\",\"collaboration tools\",\"meeting accessories\"]', '{\"Dimensi\":{\"Tinggi\":\"12,7 mm\",\"Diameter\":\"71,8 mm\"},\"Berat\":\"108 g\",\"Daya\":\"2 x baterai CR2032\",\"Mounting\":\"Mounting dengan perekat\",\"Kompatibilitas\":{\"Logitech Scribe\":\"Dukungan tombol berbagi mungkin bervariasi tergantung pada penyedia layanan video conferencing.\"},\"Antarmuka\":{\"Bluetooth\":\"Bluetooth\\u00ae Rendah Energi\"},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Tombol berbagi wireless ini dirancang untuk memudahkan presentasi dan kolaborasi dalam pertemuan video.</p>', '[{\"name\":\"Warna\",\"value\":\"Putih\",\"additional\":\"Tersedia dalam warna ungu sebagai alternatif.\"},{\"name\":\"Fungsi\",\"value\":\"Berbagi whiteboard\",\"additional\":\"Memudahkan berbagi konten dalam video meeting.\"}]', '<h4>Fitur Unggulan</h4><p>Tombol berbagi ini memungkinkan pengguna untuk dengan mudah berbagi konten whiteboard hanya dengan menekan tombol.</p>', 1, 0, 0, '2026-02-20 01:04:28', '2026-02-20 01:04:29'),
(54, 1, 1, 'Logitech Select', 'logitech-select', '<h4>Deskripsi Produk</h4><p>Logitech Select adalah paket layanan komprehensif yang dirancang untuk memastikan kelangsungan bisnis dan ketenangan pikiran bagi perusahaan yang menggunakan solusi video kolaborasi Logitech. Layanan ini melampaui garansi standar dengan menawarkan dukungan teknis ahli 24/7, penggantian produk lanjutan (RMA) yang dipercepat, dan akses ke fitur wawasan premium di Logitech Sync. Ini adalah asuransi operasional untuk ruang rapat kritis Anda.</p><h4>Fitur Unggulan</h4><ul><li><strong>Dukungan 24/7/365:</strong> Akses langsung ke ahli teknis Logitech kapan saja.</li><li><strong>Penggantian Produk Kilat:</strong> Pengiriman unit pengganti pada hari kerja berikutnya untuk meminimalkan downtime.</li><li><strong>Sync Insights:</strong> Analisis mendalam tentang penggunaan ruang dan perangkat.</li><li><strong>Manajer Layanan Khusus:</strong> Untuk pelanggan dengan 50+ ruang, tersedia manajer akun khusus.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Durasi: Tersedia dalam paket 1, 2, atau 3 tahun</li><li>Cakupan: Per ruang (mencakup semua perangkat Logitech di satu ruang)</li></ul>', 'products/logitech-select/logitech-select-2026-1771574669.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', NULL, NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/select-datasheet.pdf', '[\"logitech select\",\"video conferencing\",\"business continuity\",\"remote support\",\"room management\",\"collaboration tools\",\"premium service\"]', '{\"Dimensi\":[],\"Berat\":[],\"Persyaratan Sistem\":[],\"Kompatibilitas\":[],\"Sertifikasi\":[],\"Daya\":[],\"Lingkungan\":[]}', '<h4>Spesifikasi Utama</h4><p>Paket Layanan Logitech Select menawarkan dukungan 24/7 dan manajer layanan untuk memastikan kelangsungan bisnis Anda.</p>', '[{\"name\":\"Bantuan 24\\/7\",\"value\":\"Dukungan 24\\/7 dengan waktu respons satu jam\",\"additional\":\"\"},{\"name\":\"Manajer Layanan\",\"value\":\"Manajer layanan yang ditunjuk untuk dukungan teknis\",\"additional\":\"\"},{\"name\":\"RMA Terbaik\",\"value\":\"Penggantian perangkat keras tingkat lanjut\",\"additional\":\"\"},{\"name\":\"Cakupan Produk\",\"value\":\"Cakupan untuk semua perangkat di ruang yang ditentukan\",\"additional\":\"\"},{\"name\":\"Software Premium\",\"value\":\"Akses ke perangkat lunak premium untuk manajemen\",\"additional\":\"\"},{\"name\":\"Minimalkan Gangguan\",\"value\":\"Penggantian perangkat keras canggih\",\"additional\":\"\"},{\"name\":\"Pembuatan Peta\",\"value\":\"Membuat peta untuk pemesanan ruangan dan meja\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Dengan Logitech Select, Anda mendapatkan bantuan 24/7, manajer layanan, dan cakupan produk lengkap untuk semua perangkat Anda.</p>', 1, 0, 0, '2026-02-20 01:04:29', '2026-02-20 01:04:29'),
(55, 1, 1, 'Logitech Sight', 'logitech-sight', '<h4>Deskripsi Produk</h4><p>Logitech Sight adalah kamera pendamping meja (tabletop camera) bertenaga AI yang bekerja bersama dengan Rally Bar atau Rally Bar Mini di bagian depan ruangan. Sight memberikan perspektif &quot;tatap muka&quot; yang lebih baik dengan menangkap peserta di sekitar meja secara close-up. Dengan kemampuan Multi-Participant Framing, Sight memastikan peserta jarak jauh merasa seolah-olah mereka duduk di meja yang sama, menangkap ekspresi non-verbal dan gestur dengan jelas.</p><h4>Fitur Unggulan</h4><ul><li><strong>Smart Switching:</strong> Sistem secara cerdas beralih antara kamera depan (Rally Bar) dan kamera meja (Sight) tergantung ke mana peserta menghadap.</li><li><strong>Jangkauan 315 Derajat:</strong> Lensa ganda 4K menangkap hampir seluruh area meja konferensi.</li><li><strong>Privacy Control:</strong> Tombol mute sensor fisik dan indikator LED yang jelas.</li><li><strong>Instalasi Bersih:</strong> Manajemen kabel terintegrasi dan opsi mounting yang mengunci ke meja.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kamera: Sensor ganda 4K dengan 7 beamforming mics</li><li>Video: Output 1080p HD</li><li>Platform: Terintegrasi dengan Zoom Smart Gallery dan Microsoft Teams IntelliFrame</li><li>Koneksi: Kabel Cat6 (PoE) ke Rally Bar/RoomMate</li></ul>', 'products/logitech-sight/products-logitech-sight-sight-front-and-center-0423-activ-teknologi-2026-3134.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', NULL, NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/sight-datasheet.pdf', '[\"webcam\",\"logitech sight\",\"video conference\",\"hybrid meeting\",\"AI camera\",\"audio clarity\",\"video clarity\"]', '{\"Dimensi\":{\"Tinggi\":\"N\\/A\",\"Lebar\":\"N\\/A\",\"Panjang\":\"N\\/A\"},\"Berat\":\"N\\/A\",\"Persyaratan Sistem\":\"N\\/A\",\"Kompatibilitas\":{\"Windows\":\"N\\/A\",\"Mac\":\"N\\/A\",\"Linux\":\"N\\/A\"},\"Sertifikasi\":\"N\\/A\",\"Daya\":\"N\\/A\",\"Lingkungan\":\"N\\/A\"}', '<h4>Spesifikasi Utama</h4><p>Logitech Sight dirancang untuk memberikan pengalaman pertemuan yang lebih baik dengan framing multi-peserta yang cerdas.</p>', '[{\"name\":\"Video Capture\",\"value\":\"Sight menggunakan video dan AI untuk mendeteksi dan membingkai peserta secara akurat, dengan bidang pandang 315\\u00b0.\",\"additional\":null},{\"name\":\"Audio Pickup\",\"value\":\"Sight menggunakan suara untuk mendeteksi pembicara aktif dan menangkap audio di meja pertemuan hingga jarak 2,3 m.\",\"additional\":null},{\"name\":\"Smart Switching\",\"value\":\"Adaptive intelligence memilih tampilan terbaik antara kamera di atas meja dengan kamera di depan ruangan, mengikuti percakapan saat kamera bergerak di antara peserta.\",\"additional\":\"Smart Switching tersedia dengan pembaruan software di masa depan.\"},{\"name\":\"Mikrofon Beamforming\",\"value\":\"Dengan 7 mikrofon beamforming, Sight menangkap percakapan dan isyarat nonverbal dengan jelas.\",\"additional\":null},{\"name\":\"Privacy Shade\",\"value\":\"Lampu indikator dan privacy shade memungkinkan pemberian sinyal dan kontrol status yang jelas.\",\"additional\":null},{\"name\":\"Indikator LED\",\"value\":\"Menunjukkan status kamera dan mikrofon.\",\"additional\":null},{\"name\":\"Kontrol Mute Mikrofon\",\"value\":\"Menyediakan kontrol yang jelas untuk mute mikrofon.\",\"additional\":null}]', '<h4>Fitur Unggulan</h4><p>Dengan teknologi AI dan mikrofon beamforming, Sight menangkap audio dan video dengan jelas untuk pertemuan yang lebih inklusif.</p>', 1, 0, 0, '2026-02-20 01:04:29', '2026-02-20 01:31:34'),
(56, 1, 1, 'Logitech Spot', 'logitech-spot', '<h4>Deskripsi Produk</h4><p>Logitech Spot adalah sensor pintar untuk pemantauan okupansi dan lingkungan ruang kerja. Perangkat ini membantu organisasi memahami penggunaan ruang serta kondisi lingkungan seperti suhu dan kualitas udara.</p><h4>Fitur Utama</h4><ul><li><strong>Occupancy Detection:</strong> Memantau penggunaan ruang secara real-time.</li><li><strong>Environmental Monitoring:</strong> Mengukur parameter lingkungan.</li><li><strong>Integrasi Sync:</strong> Terhubung dengan Logitech Sync.</li><li><strong>Desain Minimalis:</strong> Mudah dipasang di berbagai ruangan.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Koneksi: Wireless</li><li>Platform: Logitech Sync</li><li>Instalasi: Dinding atau langit-langit</li></ul>', 'products/logitech-spot/logitech-spot-2026-1771574669.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '950-000110', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/logitech-spot-datasheet.pdf', '[\"sensor kehadiran\",\"logitech spot\",\"otomatisasi tempat kerja\",\"kesehatan ruangan\",\"pemanfaatan ruangan\",\"sensor lingkungan\",\"teknologi kantor\"]', '{\"Dimensi\":{\"Tinggi\":\"50 mm\",\"Lebar\":\"134 mm\",\"Tebal\":\"98 mm\"},\"Berat\":\"300 g\",\"Persyaratan Sistem\":{\"Kompatibilitas\":\"Memerlukan koneksi Bluetooth ke perangkat host CollabOS Logitech atau koneksi LoRaWAN ke Kerlink iFemtocell Wirnet Gateway Hub\",\"Sertifikasi\":\"Untuk informasi terbaru tentang sertifikasi dan kompatibilitas, kunjungi sync.logitech.com\\/hub\\/logitech-spot\"},\"Daya\":{\"Jenis baterai\":\"1 x Lithium Thionyl Chloride Ukuran-D\",\"Daya tahan baterai\":\"Hingga 4 tahun dalam kondisi optimal\",\"Daya\":\"USB-C 5V, 0,5 A (kabel tidak disertakan)\"},\"Lingkungan\":{\"Suhu pengoperasian\":\"0 hingga 40\\u00b0C\",\"Kelembaban pengoperasian\":\"10 hingga 90%, tanpa pengembunan\",\"Suhu penyimpanan\":\"-40 hingga 70\\u00b0C\",\"Kelembaban penyimpanan\":\"10 hingga 90% RH, non-kondensasi\"},\"Konektivitas\":{\"Perangkat host Logitech\":\"Pilih perangkat CollabOS\",\"Jenis Koneksi\":\"Bluetooth, LoRaWAN\"},\"Sensors\":{\"Sensor Kehadiran\":{\"Teknologi sensor\":\"teknologi radar mmWave\",\"Posisi pemasangan\":\"dinding\",\"Jarak deteksi\":\"hingga 26,25 kaki (8 m)\",\"Sudut pandang deteksi\":\"120\\u00b0 horizontal \\/ 100\\u00b0 vertikal\"},\"Sensor Materi Partikulat\":{\"Teknologi sensor\":\"Penghitung partikel laser (Penyebaran cahaya)\",\"Rentang konsentrasi massa\":\"0 hingga 1.000 \\u03bcg\\/m\\u00b3\",\"Resolusi keluaran\":\"1 \\u03bcg\\/m\\u00b3\",\"Akurasi PM2.5\":\"\\u00b1 5 \\u00b5g\\/m\\u00b3 \\u00b1 5% pada 1 hingga 100 \\u00b5g\\/m\\u00b3; \\u00b1 10% pada 100 hingga 1000 \\u00b5g\\/m\\u00b3\",\"Akurasi PM10\":\"\\u00b1 25 \\u00b5g\\/m\\u00b3 pada 1 hingga 100 \\u00b5g\\/m\\u00b3; \\u00b1 25% pada 100 hingga 1000 \\u00b5g\\/m\\u00b3\"},\"Sensor CO\\u2082\":{\"Teknologi sensor\":\"Infrared Non-dispersive (NDIR)\",\"Rentang konsentrasi massa\":\"400 hingga 10000 ppm\",\"Resolusi keluaran\":\"1 ppm\",\"Akurasi\":\"\\u00b1 3% pada 400 hingga 5000 ppm; \\u00b1 10% pada 5000 hingga 10000 ppm\"},\"Sensor Tekanan\":{\"Teknologi sensor\":\"MEMS\",\"Rentang tekanan\":\"30 hingga 125 kPa\",\"Resolusi keluaran\":\"1,45 Pa\",\"Akurasi\":\"\\u00b1 77 Pa pada 30 hingga 110 kPa\"},\"TVOC Sensor\":{\"Teknologi sensor\":\"Kemiresistor oksida logam\",\"Rentang\":\"1 - 6000 \\u00b5g\\/m\\u00b3\",\"Resolusi\":\"1 \\u00b5g\\/m\\u00b3\",\"Akurasi\":\"\\u00b1 20 \\u00b5g\\/m\\u00b3 \\u00b1 15% pada 1 hingga 1000 \\u00b5g\\/m\\u00b3; \\u00b1 20 \\u00b5g\\/m\\u00b3 \\u00b1 20% pada 1000 hingga 2000 \\u00b5g\\/m\\u00b3\"},\"Sensor Suhu\":{\"Teknologi sensor\":\"Semikonduktor oksida logam\",\"Rentang suhu\":\"-40 hingga 125\\u00b0C\",\"Resolusi\":\"0,1\\u00b0C\",\"Akurasi\":\"\\u00b1 0,4\\u00b0C pada -10 hingga 80\\u00b0C\"},\"Sensor Kelembaban\":{\"Teknologi sensor\":\"Semikonduktor oksida logam\",\"Rentang kelembapan relatif\":\"0 hingga 100% RH\",\"Resolusi keluaran\":\"0,1 % RH\",\"Akurasi\":\"\\u00b1 3 % RH pada 10 hingga 90% RH\"}},\"Keberlanjutan\":{\"Kemasan yang Ramah Lingkungan\":\"Kemasan kertas Logitech Spot berasal dari hutan yang sudah bersertifikasi FSC\\u2122- dan sumber daya terkendali lainnya.\",\"Plastik Daur Ulang\":\"Bagian plastik di Logitech Spot mencakup 33% plastik bersertifikasi post-consumer recycled untuk memberikan masa pakai baru bagi plastik dari barang elektronik tua.\"}}', '<h4>Spesifikasi Utama</h4><p>Logitech Spot adalah sensor kehadiran dan lingkungan yang dirancang untuk meningkatkan otomatisasi tempat kerja dan memberikan wawasan tentang pemanfaatan ruangan.</p>', '[{\"name\":\"Sensor Kehadiran\",\"value\":\"Teknologi radar mmWave\",\"additional\":\"Deteksi hingga 8 m\"},{\"name\":\"Sensor CO\\u2082\",\"value\":\"Infrared Non-dispersive (NDIR)\",\"additional\":\"Akurasi \\u00b1 3% pada 400 hingga 5000 ppm\"},{\"name\":\"Sensor Suhu\",\"value\":\"Semikonduktor oksida logam\",\"additional\":\"Akurasi \\u00b1 0,4\\u00b0C pada -10 hingga 80\\u00b0C\"},{\"name\":\"Sensor Kelembaban\",\"value\":\"Semikonduktor oksida logam\",\"additional\":\"Akurasi \\u00b1 3 % RH pada 10 hingga 90% RH\"},{\"name\":\"Daya Tahan Baterai\",\"value\":\"Hingga 4 tahun\",\"additional\":\"Dalam kondisi optimal\"},{\"name\":\"Konektivitas\",\"value\":\"Bluetooth, LoRaWAN\",\"additional\":\"Mendukung perangkat CollabOS\"},{\"name\":\"Kemasan Ramah Lingkungan\",\"value\":\"Berasal dari hutan bersertifikasi FSC\\u2122\",\"additional\":\"Mengurangi jejak karbon\"}]', '<h4>Fitur Unggulan</h4><p>Sensor canggih yang mendeteksi kehadiran, kualitas udara, dan kondisi lingkungan untuk meningkatkan efisiensi ruang kerja.</p>', 1, 0, 0, '2026-02-20 01:04:29', '2026-02-20 01:04:29');
INSERT INTO `products` (`id`, `service_id`, `brand_id`, `name`, `slug`, `description`, `image_path`, `thumbnail_path`, `price`, `link_accommerce`, `whatsapp_note`, `sku`, `solution_type`, `datasheet_url`, `tags`, `specs`, `specification_text`, `features`, `features_text`, `is_active`, `is_featured`, `is_new`, `created_at`, `updated_at`) VALUES
(57, 1, 1, 'Logitech Strong USB Cable', 'logitech-strong-usb-cable', '<h4>Deskripsi Produk</h4><p>Logitech Strong USB Cable adalah kabel USB super-panjang dan super-kuat yang dirancang untuk instalasi ruang konferensi komersial. Berbeda dengan kabel USB biasa yang pendek dan rapuh, kabel ini diperkuat dengan serat aramid (bahan rompi anti peluru) untuk ketahanan tarik yang ekstrem dan bersertifikat plenum (aman untuk dipasang di dalam dinding/pleno). Kabel ini memungkinkan Anda menempatkan perangkat USB hingga 45 meter jauhnya dari komputer host.</p><h4>Fitur Unggulan</h4><ul><li><strong>Kekuatan Tarik Tinggi:</strong> Tahan tarikan hingga 200 newton, aman ditarik melalui saluran pipa (conduit).</li><li><strong>Kecepatan Penuh:</strong> Mendukung USB 3.2 Gen 2 (10Gbps) untuk data video 4K yang lancar.</li><li><strong>Sertifikasi Plenum:</strong> Eca/CMP rated untuk instalasi dinding komersial yang aman.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Panjang: Tersedia dalam 10 meter, 25 meter, dan 45 meter</li><li>Konektor: USB-A (Male) ke USB-C (Male)</li><li>Tipe: Kabel Optik Aktif (Active Optical Cable)</li></ul>', 'products/logitech-strong-usb-cable/logitech-strong-usb-cable-2026-1771574670.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '939-001799', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/strong-usb-accessory.pdf', '[\"logitech strong usb\",\"usb cable\",\"video conferencing\",\"super speed usb\",\"long reach cable\",\"commercial installation\",\"usb 3.2\"]', '{\"Dimensi\":{\"Panjang yang Tersedia\":[\"10 m\",\"25 m\",\"45 m\"]},\"Spesifikasi Teknis\":{\"Tipe Kabel\":\"Kabel optik aktif USB 3.2 Gen 2\",\"Tipe Konektor\":\"USB Type A (male) ke USB Type C (male)\",\"Throughput\":\"SuperSpeed USB 10 Gbps\",\"Kekuatan tensile\":\"200 newton\",\"Crush load\":\"1.000 kg\",\"Radius dynamic bend (minimum)\":\"25 mm\",\"Diameter Konduit (minimum)\":\"19 mm\"},\"Kompatibilitas\":{\"USB\":[\"USB 2.0\",\"3.0\",\"3.1\",\"3.2\"],\"Perangkat\":\"Perangkat USB daya-mandiri dan USB hub dengan catu daya eksternal, termasuk Logitech MeetUp, Logitech Rally Camera, dan Logitech Tap.\",\"Catatan\":\"Sebagai kabel optik aktif, Logitech Strong USB tidak mengirimkan daya ke perangkat berdaya-USB bus seperti webcam dan speakerphone.\"},\"Sertifikasi\":[\"Plenum Rated\",\"Eca\\/IEC 60332-1-2 Compliant\"],\"Garansi\":\"Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Kabel Logitech Strong USB menawarkan kecepatan hingga 10 Gbps dan jangkauan ekstra panjang hingga 45 meter.</p>', '[{\"name\":\"Jangkauan Ekstra Panjang\",\"value\":\"Tersedia dengan kabel sepanjang 10, 25, dan 45 meter.\",\"additional\":\"Memungkinkan penggunaan perangkat USB pada jarak jauh dari host PC.\"},{\"name\":\"Kekuatan yang Andal\",\"value\":\"Kekuatan tensile 200 newton dan crush load 1.000 kg.\",\"additional\":\"Cocok untuk penggunaan komersial.\"},{\"name\":\"Cepat dan Kompatibel\",\"value\":\"Dapat menyalurkan hingga 10 Gbps.\",\"additional\":\"Kepatuhan dengan spesifikasi USB 3.2 Gen 2.\"}]', '<h4>Fitur Unggulan</h4><p>Kabel ini dirancang untuk penggunaan komersial dengan kekuatan yang andal dan kompatibilitas luas.</p>', 1, 0, 0, '2026-02-20 01:04:29', '2026-02-20 01:04:30'),
(58, 1, 1, 'Logitech Sync', 'logitech-sync', '<h4>Deskripsi Produk</h4><p>Logitech Sync adalah platform manajemen perangkat berbasis cloud yang memungkinkan tim IT memantau, mengelola, dan memperbarui ribuan perangkat konferensi video Logitech dari satu dasbor terpusat. Sync tidak hanya tentang manajemen perangkat, tetapi juga memberikan wawasan (Insights) tentang bagaimana ruang rapat digunakan, membantu perusahaan membuat keputusan berbasis data tentang properti dan fasilitas kantor mereka.</p><h4>Fitur Unggulan</h4><ul><li><strong>Remote Management:</strong> Lakukan update firmware, restart perangkat, dan ubah pengaturan konfigurasi dari mana saja.</li><li><strong>Real-Time Monitoring:</strong> Dapatkan notifikasi instan jika ada perangkat yang offline atau mengalami masalah (misalnya, mikrofon terputus).</li><li><strong>Sync Insights:</strong> Analisis data okupansi ruangan (dengan Rally Bar/Spot) untuk memahami pola penggunaan ruang rapat.</li><li><strong>Skalabilitas:</strong> Arsitektur cloud yang aman dan dapat menangani penyebaran global.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Akses: Browser web (Cloud) atau Aplikasi Desktop</li><li>Kompatibilitas: Mendukung hampir semua perangkat VC Logitech (Rally, MeetUp, Tap, Dock, dll)</li><li>Integrasi: API tersedia untuk integrasi dengan platform tiket IT (ServiceNow)</li></ul>', 'products/logitech-sync/logitech-sync-2026-1771574670.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', NULL, NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/whitepaper-logitech-sync.pdf', '[\"video conferencing\",\"logitech sync\",\"remote management\",\"workspace management\",\"hybrid work\",\"room booking\",\"desk booking\"]', '{\"Dimensi\":{\"Tinggi\":\"N\\/A\",\"Lebar\":\"N\\/A\",\"Panjang\":\"N\\/A\"},\"Berat\":\"N\\/A\",\"Persyaratan Sistem\":\"N\\/A\",\"Kompatibilitas\":{\"Windows\":\"N\\/A\",\"Mac\":\"N\\/A\"},\"Sertifikasi\":\"N\\/A\",\"Daya\":\"N\\/A\",\"Lingkungan\":\"N\\/A\"}', '<h4>Logitech Sync adalah solusi manajemen perangkat video conferencing yang memungkinkan pengelolaan jarak jauh dan kontrol maksimal atas perangkat dan ruang.</h4>', '[{\"name\":\"Manajemen Jarak Jauh\",\"value\":\"Mengonfigurasi dan memperbarui perangkat dari jarak jauh.\",\"additional\":\"Memastikan perangkat selalu beroperasi dalam kinerja puncak.\"},{\"name\":\"Automasi dengan Peringatan\",\"value\":\"Integrasi ServiceNow dan notifikasi email.\",\"additional\":\"Memberikan peringatan instan tentang masalah ruang atau perangkat.\"},{\"name\":\"Reservasi Ruangan\",\"value\":\"Memudahkan reservasi dan pencarian ruangan.\",\"additional\":\"Pemesanan dapat dilakukan dengan mudah di Tap Scheduler atau aplikasi kalender.\"},{\"name\":\"Desk Booking\",\"value\":\"Memudahkan karyawan untuk menemukan meja yang sempurna.\",\"additional\":\"Pemesanan dapat dilakukan melalui aplikasi Logi Tune.\"},{\"name\":\"Kelola Peta Denah Lantai\",\"value\":\"Atur dan kelola peta denah lantai Anda.\",\"additional\":\"Menambahkan meja, ruangan, dan titik menarik lainnya.\"},{\"name\":\"Keamanan Standar Perusahaan\",\"value\":\"Menggunakan enkripsi end-to-end.\",\"additional\":\"Data meeting tetap privat dan aman.\"},{\"name\":\"Integrasi Partner\",\"value\":\"Terhubung ke platform manajemen perangkat multivendor.\",\"additional\":\"Memberikan fleksibilitas dalam mengelola sistem video conferencing.\"}]', '<h4>Fitur unggulan termasuk manajemen jarak jauh, automasi dengan peringatan, dan kemudahan reservasi ruang.</h4>', 1, 0, 0, '2026-02-20 01:04:30', '2026-02-20 01:04:31'),
(59, 1, 1, 'Logitech Tap Riser Mount', 'logitech-tap-riser-mount', '<h4>Deskripsi Produk</h4><p>Logitech Tap Riser Mount adalah dudukan meja yang ditinggikan untuk pengontrol sentuh Logitech Tap. Mount ini mengangkat layar Tap sebesar 30 derajat, memberikan sudut pandang dan jangkauan yang lebih ergonomis bagi peserta yang duduk di meja. Bagian bawahnya memiliki mekanisme putar (swivel) 180 derajat, memungkinkan pengguna di kedua sisi meja untuk mengoperasikan layar dengan mudah, sambil menjaga kabel tetap tersembunyi di dalamnya.</p><h4>Fitur Unggulan</h4><ul><li><strong>Sudut Ergonomis:</strong> Mengangkat layar 30° untuk visibilitas yang lebih baik dari posisi duduk.</li><li><strong>Swivel 180°:</strong> Memudahkan berbagi kontrol dengan rekan di seberang meja.</li><li><strong>Manajemen Kabel:</strong> Menyembunyikan kabel melalui grommet meja untuk tampilan bersih.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Logitech Tap, Logitech Tap IP</li><li>Sudut Tampilan: 30 derajat</li><li>Warna: Graphite</li></ul>', 'products/logitech-tap-riser-mount/logitech-tap-riser-mount-2026-1771574671.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000080', NULL, 'https://www.logitech.com/content/dam/logitech/vc/en_nz/resource-center/datasheets/tap-accessories-datasheet-web.pdf', '[\"logitech tap riser mount\",\"elevated table mount\",\"video conferencing\",\"touch controller\",\"meeting room accessories\",\"cable management\",\"Logitech Tap IP\"]', '{\"Dimensi\":{\"Tinggi\":\"102 mm\",\"Lebar\":\"244 mm\",\"Tebal\":\"174 mm\"},\"Sudut Layar\":{\"Sudut layar\":\"30\\u00b0\",\"Dapat berputar\":\"180\\u00b0\"},\"Meja\\/Grommet\":{\"Ketebalan Meja\":\"20 - 50 mm\",\"Diameter Grommet\":\"51 - 89 mm\"},\"Kompatibilitas\":{\"Touch Controller\":\"Logitech Tap IP, Logitech Tap\"},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Riser Mount untuk Logitech Tap dirancang untuk meningkatkan pengalaman rapat dengan manajemen kabel yang rapi dan sudut layar yang dapat disesuaikan.</p>', '[{\"name\":\"Manajemen Kabel\",\"value\":\"Ya\",\"additional\":\"Penataan kabel melalui grommet untuk penampilan yang bersih.\"},{\"name\":\"Rotasi\",\"value\":\"180\\u00b0\",\"additional\":\"Dapat berputar untuk kemudahan pengoperasian.\"},{\"name\":\"Desain\",\"value\":\"Elevated table mount\",\"additional\":\"Menjaga touch controller di tempatnya.\"},{\"name\":\"Kompatibilitas Meja\",\"value\":\"20 - 50 mm\",\"additional\":\"Dapat disesuaikan untuk meja dengan ketebalan maksimal.\"}]', '<h4>Fitur Unggulan</h4><p>Dengan kemampuan berputar dan desain yang elegan, Riser Mount ini memastikan touch controller Anda selalu dalam jangkauan dan terlihat jelas.</p>', 1, 0, 0, '2026-02-20 01:04:31', '2026-02-20 01:04:31'),
(60, 1, 1, 'Logitech Tap Scheduler Angle Mount', 'logitech-tap-scheduler-angle-mount', '<h4>Deskripsi Produk</h4><p>Logitech Tap Scheduler Angle Mount adalah aksesori pemasangan khusus yang menempatkan panel Tap Scheduler pada sudut pandang yang nyaman. Mount ini sangat berguna ketika panel dipasang pada posisi yang lebih rendah dari tingkat mata standar. Dengan memiringkan layar ke atas, informasi ketersediaan ruangan menjadi lebih mudah dibaca oleh orang yang berdiri di depan pintu.</p><h4>Fitur Unggulan</h4><ul><li><strong>Keterbacaan Lebih Baik:</strong> Memberikan sudut pandang yang optimal untuk instalasi rendah.</li><li><strong>Konstruksi Kokoh:</strong> Material logam tahan lama yang mengamankan panel.</li><li><strong>Instalasi Bersih:</strong> Jalur kabel terintegrasi.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Logitech Tap Scheduler</li><li>Warna: Putih (White)</li></ul>', 'products/logitech-tap-scheduler-angle-mount/logitech-tap-scheduler-angle-mount-2026-1771574671.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000127', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/tap-scheduler-angle-mount.pdf', '[\"logitech\",\"tap scheduler\",\"angle mount\",\"video conferencing\",\"meeting room\",\"accessories\",\"flexible mounting\"]', '{\"Dimensi\":{\"Angle Plinth\":{\"Tinggi\":\"132,1 mm\",\"Lebar\":\"213,4 mm\",\"Tebal\":\"54,8 mm\",\"Sudut\":\"Saat terpasang, Tap Scheduler dipasang pada sudut layar 14\\u00b0\"},\"Antarmuka yang Dapat Dibalik\":{\"Tinggi\":\"121,7 mm\",\"Lebar\":\"208,1 mm\",\"Tebal\":\"10,5 mm\"}},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\",\"Isi Kemasan\":[\"Angle Plinth\",\"Antarmuka yang Dapat Dibalik\",\"Hardware pemasangan\",\"Dokumentasi\"]}', '<h4>Spesifikasi Utama</h4><p>Tap Scheduler Angle Mount dirancang untuk memberikan fleksibilitas dalam pemasangan dan kemudahan akses untuk melihat jadwal rapat.</p>', '[{\"name\":\"Sudut Kemiringan Terintegrasi\",\"value\":\"Menambahkan sudut kemiringan 20 derajat pada pemasangan Logitech Tap Scheduler.\",\"additional\":\"Meningkatkan visibilitas dan kenyamanan saat berinteraksi dengan panel dari posisi berdiri.\"},{\"name\":\"Opsi Pemasangan Serbaguna\",\"value\":\"Dapat dipasang di atas kusen pintu atau langsung pada permukaan dinding.\",\"additional\":\"Memberikan fleksibilitas penempatan perangkat di luar ruang rapat.\"},{\"name\":\"Manajemen Kabel Tersembunyi\",\"value\":\"Desain yang memungkinkan kabel ditarik melalui bagian belakang bracket.\",\"additional\":\"Menjaga tampilan instalasi tetap bersih, rapi, dan profesional tanpa kabel yang menjuntai.\"},{\"name\":\"Kompatibilitas Material Dinding\",\"value\":\"Mendukung pemasangan pada berbagai jenis permukaan termasuk kaca, drywall, dan beton.\",\"additional\":\"Memastikan instalasi yang kokoh dan aman di berbagai desain kantor modern.\"}]', '<h4>Fitur Unggulan</h4><p>Menawarkan sudut pemasangan yang nyaman dan desain yang elegan untuk ruang rapat.</p>', 1, 0, 0, '2026-02-20 01:04:31', '2026-02-20 01:04:31'),
(61, 1, 1, 'Logitech Tap Table Mount', 'logitech-tap-table-mount', '<h4>Deskripsi Produk</h4><p>Logitech Tap Table Mount adalah dudukan profil rendah (low profile) yang mengamankan pengontrol Logitech Tap rata di atas meja. Mount ini memberikan sudut pandang 14 derajat yang nyaman dan sangat stabil. Dengan fitur manajemen kabel internal dan mekanisme putar (swivel) 180 derajat, mount ini menjaga meja tetap rapi sambil memberikan fleksibilitas akses bagi semua peserta rapat.</p><h4>Fitur Unggulan</h4><ul><li><strong>Low Profile:</strong> Menjaga tampilan meja tetap ramping dan tidak menghalangi pandangan.</li><li><strong>Swivel 180°:</strong> Memutar layar dengan mudah untuk akses bersama.</li><li><strong>Keamanan Kabel:</strong> Mencegah ketegangan pada port koneksi Tap.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Logitech Tap, Logitech Tap IP</li><li>Sudut Tampilan: 14 derajat</li></ul>', 'products/logitech-tap-table-mount/logitech-tap-table-mount-2026-1771574671.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '939-001811', NULL, 'https://www.logitech.com/content/dam/logitech/vc/en_nz/resource-center/datasheets/tap-accessories-datasheet-web.pdf', '[\"logitech tap\",\"table mount\",\"video conferencing\",\"meeting room\",\"cable management\",\"touch controller\",\"Logitech Tap IP\"]', '{\"Dimensi\":{\"Tinggi\":\"61 mm\",\"Lebar\":\"244 mm\",\"Tebal\":\"179 mm\"},\"Sudut Layar\":{\"Sudut layar\":\"14\\u00b0\",\"Dapat berputar\":\"180\\u00b0\"},\"Meja\\/Grommet\":{\"Ketebalan Meja\":\"20 - 50 mm\",\"Diameter Grommet\":\"51 - 89 mm\"},\"Kompatibilitas\":{\"Touch Controller\":\"Logitech Tap IP, Logitech Tap\"},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Tap Table Mount dirancang untuk meja ruang konferensi dengan lubang grommet, menjaga touch controller tetap di tempatnya dan terlihat sederhana.</p>', '[{\"name\":\"Tampilan Sederhana\",\"value\":\"Menjaga penampilan Tap yang ramping dan sudut layar 14\\u00b0.\"},{\"name\":\"Rotasi\",\"value\":\"Dapat berputar 180\\u00b0 untuk pengoperasian yang nyaman dari kedua sisi meja.\"},{\"name\":\"Penataan Kabel\",\"value\":\"Manajemen kabel terintegrasi untuk penataan kabel di bagian bawah.\"},{\"name\":\"Kompatibilitas Meja\",\"value\":\"Cocok untuk meja dengan ketebalan maksimal 50 mm dan melalui lubang grommet dengan diameter antara 51 - 89 mm.\"}]', '<h4>Fitur Unggulan</h4><p>Menjaga penampilan ramping dan memungkinkan rotasi 180° untuk akses mudah dari berbagai sisi meja.</p>', 1, 0, 0, '2026-02-20 01:04:31', '2026-02-20 01:04:31'),
(62, 1, 1, 'Logitech Tap Wall Mount', 'logitech-tap-wall-mount', '<h4>Deskripsi Produk</h4><p>Logitech Tap Wall Mount dirancang untuk menghemat ruang meja di ruang rapat kecil (huddle rooms) dengan memasang pengontrol sentuh Logitech Tap langsung di dinding. Desainnya yang kokoh dan rata dengan dinding memberikan akses mudah ke kontrol rapat tanpa memakan tempat berharga di meja kecil. Ideal untuk ruangan di mana meja digunakan secara fleksibel atau tidak ada meja permanen.</p><h4>Fitur Unggulan</h4><ul><li><strong>Hemat Ruang:</strong> Membebaskan permukaan meja sepenuhnya.</li><li><strong>Konstruksi Kokoh:</strong> Plate logam tebal dengan penutup kabel yang rapi.</li><li><strong>Akses Mudah:</strong> Menempatkan kontrol pada ketinggian yang nyaman untuk penggunaan berdiri atau duduk (kursi tinggi).</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Logitech Tap, Logitech Tap IP</li><li>Warna: Graphite</li></ul>', 'products/logitech-tap-wall-mount/logitech-tap-wall-mount-2026-1771574671.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '939-001817', NULL, 'https://www.logitech.com/content/dam/logitech/vc/en_nz/resource-center/datasheets/tap-accessories-datasheet-web.pdf', '[\"logitech tap\",\"wall mount\",\"video conferencing\",\"meeting room\",\"touch controller\",\"cable management\",\"tap ip\"]', '{\"Dimensi\":{\"Tinggi\":\"58 mm\",\"Lebar\":\"244 mm\",\"Tebal\":\"179 mm\"},\"Sudut Layar\":\"14\\u00b0\",\"Meja\\/Grommet\":{\"Ketebalan Meja\":\"20 - 50 mm\",\"Diameter Grommet\":\"51 - 89 mm\"},\"Kompatibilitas\":{\"Touch Controller\":\"Logitech Tap IP, Logitech Tap\"},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Dirancang untuk menghemat ruang meja di ruang berkumpul dan penggunaan sambil berdiri di lorong dan area terbuka.</p>', '[{\"name\":\"Mendukung Penataan Kabel di Dinding\",\"value\":\"Kompatibel dengan ujung kabel belakang dan bawah touch controller.\",\"additional\":\"\"},{\"name\":\"Mount Flush and Stays Put\",\"value\":\"Konstruksi plate dan cleat yang kokoh.\",\"additional\":\"Menopang controller dengan aman di tempatnya.\"},{\"name\":\"Menyembunyikan Kabel\",\"value\":\"Dock dan klip kabel magnetik menjaga kabel HDMI tetap dalam jangkauan.\",\"additional\":\"\"},{\"name\":\"Berbagi Konten dengan Nyaman\",\"value\":\"Dock kabel magnetik untuk berbagi konten berkabel.\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Logitech Tap Wall Mount menawarkan akses yang nyaman pada kontrol sentuh dengan manajemen kabel yang rapi.</p>', 1, 0, 0, '2026-02-20 01:04:31', '2026-02-20 01:04:31'),
(63, 1, 1, 'Logitech TV Mount for MeetUp', 'logitech-tv-mount-for-meetup', '<h4>Deskripsi Produk</h4><p>Logitech TV Mount for MeetUp adalah solusi pemasangan yang memungkinkan perangkat MeetUp dipasang langsung di atas atau di bawah layar TV menggunakan pola VESA standar.</p><h4>Fitur Utama</h4><ul><li><strong>VESA Compatible:</strong> Cocok untuk sebagian besar TV layar datar.</li><li><strong>Instalasi Fleksibel:</strong> Di atas atau di bawah layar.</li><li><strong>Konstruksi Kokoh:</strong> Stabil dan aman.</li><li><strong>Integrasi Rapi:</strong> Tampilan profesional.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Logitech MeetUp</li><li>Mounting: VESA standard</li><li>Material: Baja</li></ul>', 'products/logitech-tv-mount-for-meetup/logitech-tv-mount-for-meetup-2026-1771574672.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '939-001498', NULL, 'https://activ.co.id/datasheet/logitech/tv-mount-for-meetup.pdf', '[\"logitech tv mount\",\"meetUp conferencecam\",\"video conferencing\",\"VESA mount\",\"TV mount\",\"conference camera\",\"mounting solutions\"]', '{\"Dimensi\":{\"TV Mount\":{\"Tinggi\":\"400 mm\",\"Lebar\":\"83 mm\",\"Tebal\":\"16 mm\",\"Berat\":\"280 g\"},\"TV Mount XL\":{\"Tinggi\":\"700 mm\",\"Lebar\":\"83 mm\",\"Tebal\":\"16 mm\",\"Berat\":\"825 g\"}},\"Spesifikasi Teknis\":{\"Pola mounting\":\"Standar VESA dengan lubang alternatif 8 mm dan 6 mm\",\"Garansi\":\"Hardware Terbatas 2 Tahun\"},\"Kompatibilitas\":{\"Produk\":\"Logitech MeetUp\"}}', '<h4>Spesifikasi Utama</h4><p>Logitech TV Mount dirancang untuk memberikan opsi pemasangan yang aman dan fleksibel untuk MeetUp ConferenceCam.</p>', '[{\"name\":\"Desain Unik\",\"value\":\"Memungkinkan MeetUp untuk dipasang di atas atau di bawah monitor.\"},{\"name\":\"Kompatibilitas TV\",\"value\":\"Dapat digunakan dengan sebagian besar TV layar datar.\"},{\"name\":\"Ukuran Layar\",\"value\":\"Ideal untuk layar hingga 1397 mm atau TV Mount XL untuk layar hingga 2286 mm.\"}]', '<h4>Fitur Unggulan</h4><p>Desain yang memungkinkan pemasangan di atas atau di bawah monitor, kompatibilitas dengan sebagian besar TV layar datar, dan ukuran yang ideal untuk berbagai layar.</p>', 1, 0, 0, '2026-02-20 01:04:32', '2026-02-20 01:04:32'),
(64, 1, 1, 'Logitech TV Mount for Video Bars', 'logitech-tv-mount-for-video-bars', '<h4>Deskripsi Produk</h4><p>Logitech TV Mount for Video Bars adalah solusi pemasangan serbaguna yang memungkinkan Anda memasang Rally Bar, Rally Bar Mini, atau Rally Camera di atas atau di bawah layar TV/Monitor. Mount ini memanfaatkan pola lubang VESA di belakang TV, sehingga tidak perlu mengebor dinding. Desain lengan ayunnya memungkinkan penyesuaian kedalaman dan sudut, memastikan kamera sejajar sempurna dengan layar untuk kontak mata yang natural.</p><h4>Fitur Unggulan</h4><ul><li><strong>Pemasangan VESA:</strong> Kompatibel dengan sebagian besar TV dan monitor layar datar.</li><li><strong>Posisi Fleksibel:</strong> Bisa dipasang di atas atau di bawah layar.</li><li><strong>Tampilan Melayang:</strong> Memberikan kesan video bar \"melayang\" menyatu dengan TV.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Rally Bar, Rally Bar Mini, Rally Camera</li><li>Pola VESA: Mendukung berbagai ukuran VESA standar</li></ul>', 'products/logitech-tv-mount-for-video-bars/logitech-tv-mount-for-video-bars-2026-1771574672.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000041', NULL, 'https://activ.co.id/datasheet/logitech/rally-bar-tv-mount-guide.pdf', '[\"logitech tv mount\",\"video bar mount\",\"rally bar\",\"video conferencing\",\"vesa mount\",\"wall mount\",\"conference room equipment\"]', '{\"Dimensi\":{\"Tinggi\":\"\",\"Lebar\":\"\",\"Kedalaman\":\"\"},\"Berat\":\"\",\"Persyaratan Sistem\":\"\",\"Kompatibilitas\":{\"Perangkat\":[\"Rally Bar\",\"Rally Bar Mini\",\"Rally Bar Huddle\",\"Rally Camera\"]},\"Sertifikasi\":{\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"},\"Daya\":\"\",\"Lingkungan\":\"\"}', '<h4>Spesifikasi Utama</h4><p>TV Mount untuk Video Bar dirancang untuk memudahkan pemasangan perangkat video konferensi dengan titik pemasangan VESA.</p>', '[{\"name\":\"Melayang Di Bawah Layar\",\"value\":\"Hemat ruang dan kosongkan kredenza dengan melayangkan Rally Bar, Rally Bar Mini, Rally Bar Huddle, atau kamera Rally di bawah layar.\",\"additional\":\"\"},{\"name\":\"Dengan Sudut yang Tepat\",\"value\":\"Adaptor video bar dengan kemiringan 10\\u00b0 menghadirkan bidang pandang yang menjangkau seluruh ruangan.\",\"additional\":\"\"},{\"name\":\"Paralel dengan Sempurna\",\"value\":\"Penyesuaian sudut internal memungkinkan menyelaraskan video bar dengan layar secara akurat.\",\"additional\":\"\"},{\"name\":\"Fleksibel dan Mewah\",\"value\":\"Sesuaikan ketebalan pemasangan hingga 50 mm agar cocok dengan berbagai ketebalan layar dan dinding.\",\"additional\":\"\"},{\"name\":\"Cocok untuk Hampir Semua Layar\",\"value\":\"Kompatibel dengan layar yang dipasang di dinding dan cart-mounted display (CMD) berukuran maksimal 248,92 cm.\",\"additional\":\"\"},{\"name\":\"Penataan Kabel yang Rapi\",\"value\":\"Penataan kabel yang cermat menjaga kabel tetap terhubung dengan aman dan tersembunyi.\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Fleksibilitas dan kemudahan pemasangan menjadi keunggulan utama dari TV Mount ini, cocok untuk berbagai jenis layar.</p>', 1, 0, 0, '2026-02-20 01:04:32', '2026-02-20 01:04:32'),
(65, 1, 1, 'Logitech USB-C To Ethernet Adapter', 'logitech-usb-c-to-ethernet-adapter', '<h4>Deskripsi Produk</h4><p>Logitech USB-C to Ethernet Adapter adalah adaptor jaringan kompak namun berkinerja tinggi yang dirancang untuk memberikan konektivitas internet kabel yang stabil ke perangkat Logi Dock atau laptop. Di lingkungan kantor yang padat di mana WiFi bisa tidak stabil, adaptor ini memastikan panggilan video Anda tetap lancar dan bebas lag dengan kecepatan Gigabit Ethernet yang andal.</p><h4>Fitur Unggulan</h4><ul><li><strong>Koneksi Stabil:</strong> Ideal untuk video conferencing yang membutuhkan bandwidth konsisten.</li><li><strong>Plug-and-Play:</strong> Bekerja langsung tanpa driver rumit.</li><li><strong>Desain Kompak:</strong> Ukuran kecil, mudah dibawa atau disembunyikan di belakang dock.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kecepatan: 10/100/1000 Mbps (Gigabit)</li><li>Konektor: USB-C (Male) ke RJ45 (Female)</li><li>Panjang Kabel: 15 cm</li></ul>', 'products/logitech-usb-c-to-ethernet-adapter/logitech-usb-c-to-ethernet-adapter-2026-1771574672.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000149', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/logi-dock-accessories.pdf', '[\"usb-c ethernet adapter\",\"logitech\",\"ethernet connectivity\",\"logi dock\",\"usb-c adapter\",\"reliable connection\",\"video conferencing\"]', '{\"Dimensi\":{\"Tinggi\":\"15 mm\",\"Lebar\":\"20 mm\",\"Tebal\":\"150 mm\"},\"Berat\":\"16,5 g\",\"Jenis Koneksi\":\"USB-C\",\"Kecepatan Koneksi\":\"1000 Mbps\",\"Garansi\":\"Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Adaptor ini menawarkan konektivitas Ethernet yang mudah dan andal untuk pengguna Logi Dock.</p>', '[{\"name\":\"Konektivitas Ethernet Stabil\",\"value\":\"Menyediakan koneksi jaringan kabel yang andal dan stabil melalui port USB-C.\",\"additional\":\"Menghindari interferensi sinyal Wi-Fi untuk transmisi data yang lebih konsisten saat video conferencing.\"},{\"name\":\"Kecepatan Gigabit\",\"value\":\"Mendukung bandwidth hingga 10\\/100\\/1000 Mbps.\",\"additional\":\"Memastikan transfer data berkecepatan tinggi untuk streaming video kualitas 4K tanpa buffering.\"},{\"name\":\"Sertifikasi Plug-and-Play\",\"value\":\"Dapat langsung digunakan tanpa perlu instalasi driver tambahan pada perangkat Logitech.\",\"additional\":\"Kompatibel sepenuhnya dengan Logitech Tap, Rally Bar, dan sistem operasi utama seperti Windows, macOS, dan ChromeOS.\"},{\"name\":\"Desain Ringkas dan Tahan Lama\",\"value\":\"Bentuk yang ultra-kompak sehingga mudah ditempatkan di belakang layar atau di dalam cable management box.\",\"additional\":\"Dibuat dengan standar build quality Logitech untuk penggunaan jangka panjang di lingkungan bisnis.\"}]', '<h4>Fitur Unggulan</h4><p>Adaptor ini dirancang untuk memberikan koneksi yang stabil dan cepat ke jaringan berkabel.</p>', 1, 0, 0, '2026-02-20 01:04:32', '2026-02-20 01:04:32'),
(66, 1, 1, 'Logitech Wall Mount for Video Bars', 'logitech-wall-mount-for-video-bars', '<h4>Deskripsi Produk</h4><p>Logitech Wall Mount for Video Bars adalah kit pemasangan dinding yang didedikasikan untuk Rally Bar dan Rally Bar Mini. Dirancang untuk memberikan instalasi yang sangat presisi dan stabil, mount ini memungkinkan video bar dimiringkan ke bawah (hingga 10 derajat) untuk mendapatkan sudut pandang terbaik di ruangan. Desainnya yang minimalis menyembunyikan perangkat keras pemasangan di belakang unit untuk tampilan yang bersih.</p><h4>Fitur Unggulan</h4><ul><li><strong>Tilt Adjustment:</strong> Mekanisme miring yang dapat disesuaikan untuk sudut kamera optimal.</li><li><strong>Anti-Getaran:</strong> Konstruksi kokoh meminimalkan getaran dari dinding atau pintu.</li><li><strong>Instalasi Mudah:</strong> Termasuk template pemasangan dan level spirit (waterpas) bawaan.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Rally Bar, Rally Bar Mini</li><li>Kemiringan: Hingga 10 derajat ke bawah</li></ul>', 'products/logitech-wall-mount-for-video-bars/logitech-wall-mount-for-video-bars-2026-1771574672.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000044', NULL, 'https://www.logitech.com/assets/66133/rally-bar-wall-mount-guide.pdf', '[\"logitech wall mount\",\"video conferencing\",\"rally bar\",\"rally bar mini\",\"vesa mount\",\"wall mount video bar\",\"video meeting\"]', '{\"Dimensi\":{\"Tinggi\":\"100 mm\",\"Lebar\":\"236 mm\",\"Tebal\":\"84 mm\"},\"Kompatibilitas\":{\"Perangkat\":[\"Rally Bar\",\"Rally Bar Mini\"]},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Mounting kit yang kompatibel dengan VESA untuk Rally Bar dan Rally Bar Mini, dirancang untuk pemasangan yang efisien dan estetis.</p>', '[{\"name\":\"Isi Kemasan\",\"value\":\"Wall Mount, Adaptor yang Bisa Dimiringkan, Sekrup, Dokumentasi\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Adaptor yang bisa dimiringkan dan manajemen kabel yang cermat untuk pengalaman video meeting yang lebih baik.</p>', 1, 0, 0, '2026-02-20 01:04:32', '2026-02-20 01:04:33'),
(67, 1, 1, 'Logitech Zone True Wireless Earbuds', 'logitech-zone-true-wireless-earbuds', '<h4>Deskripsi Produk</h4><p>Logitech Zone True Wireless adalah earbud Bluetooth kelas bisnis yang dirancang khusus untuk profesional. Earbud ini bersertifikat untuk platform bisnis utama (Teams, Zoom, Google Voice), menjamin kualitas audio yang andal dan integrasi kontrol panggilan yang mulus. Dengan Hybrid ANC (Active Noise Cancellation) dan mikrofon noise-canceling berkualitas tinggi, earbud ini memungkinkan Anda tetap fokus dan terdengar jelas di lingkungan kerja yang bising.</p><h4>Fitur Unggulan</h4><ul><li><strong>Sertifikasi Bisnis:</strong> Kualitas audio dan konektivitas yang diuji untuk Microsoft Teams, Zoom, dan lainnya.</li><li><strong>Hybrid ANC:</strong> Memblokir kebisingan yang mengganggu untuk fokus yang lebih baik.</li><li><strong>Multipoint Bluetooth:</strong> Terhubung ke komputer (via USB receiver) dan smartphone secara bersamaan.</li><li><strong>Desain Premium:</strong> Tersedia dalam warna Graphite dan Rose, dengan fitting telinga yang nyaman untuk penggunaan seharian.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Baterai: Hingga 6 jam (ANC on), 10 jam (ANC off)</li><li>Rating IP: IP68 (Earbuds tahan air/debu), IP54 (Case)</li><li>Koneksi: Bluetooth 5.0 + USB-C Receiver</li></ul>', 'products/logitech-zone-true-wireless-earbuds/logitech-zone-true-wireless-earbuds-2026-1771574673.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '985-001093', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/zone-true-wireless-earbuds.pdf', '[\"earbud bluetooth\",\"logitech zone\",\"noise-canceling\",\"audio berkualitas\",\"pengisian daya wireless\",\"aplikasi logi tune\",\"koneksi multipoint\"]', '{\"Dimensi\":{\"Earbud\":{\"Tinggi\":\"15,9 mm\",\"Lebar\":\"27,4 mm\",\"Tebal\":\"26,3 mm\",\"Berat\":\"13 g\"},\"Charging case\":{\"Tinggi\":\"25,0 mm\",\"Lebar\":\"39,8 mm\",\"Tebal\":\"74,5 mm\",\"Berat\":\"46 g\"},\"Zone True Wireless Receiver\":{\"Tinggi\":\"21,5 mm\",\"Lebar\":\"13,6 mm\",\"Tebal\":\"6,0 mm\"},\"Adaptor Zone True Wireless USB-C\":{\"Tinggi\":\"25,2 mm\",\"Lebar\":\"16,5 mm\",\"Tebal\":\"9,5 mm\"}},\"Mikrofon\":{\"Jenis\":\"Omni-directional, dual MEMS mics array dengan beamforming plus mikrofon yang menghadap ke dalam\",\"Respons Frekuensi\":\"100-8 kHz\"},\"Speaker\":{\"Respons frekuensi (mode musik)\":\"20-20 kHz\",\"Respons frekuensi (mode berbicara)\":\"100-8 kHz\",\"Kepatuhan audio\":\"Sesuai dengan EN 50332\"},\"Baterai\":{\"Tipe\":\"Baterai internal (Lithium ion)\",\"Daya tahan baterai (waktu berbicara)\":\"Maksimum 5 jam (ANC on), maksimum 6 jam (ANC off)\"}}', '<h4>Spesifikasi Utama</h4><p>Zone True Wireless Earbuds menawarkan mikrofon noise-canceling, audio berkualitas tinggi, dan koneksi multipoint untuk pengalaman mendengarkan yang optimal.</p>', '[{\"name\":\"Mikrofon Noise-Canceling\",\"value\":\"Mikrofon bersertifikat dengan teknologi noise-canceling\"},{\"name\":\"Audio Berkualitas Tinggi\",\"value\":\"Kualitas audio yang menakjubkan dengan ANC Hibrida\"},{\"name\":\"Koneksi Multipoint\",\"value\":\"Hubungkan ke dua perangkat secara bersamaan\"},{\"name\":\"Aplikasi Logi Tune\",\"value\":\"Kustomisasi dan kontrol earbud\"},{\"name\":\"Daya Tahan Baterai\",\"value\":\"Maksimum 5 jam waktu bicara dengan ANC aktif\"},{\"name\":\"Pengisian Daya Qi Wireless\",\"value\":\"Dukungan untuk pengisian daya wireless\"},{\"name\":\"Desain Ergonomis\",\"value\":\"Tersedia dalam berbagai ukuran ear gel untuk kenyamanan\"}]', '<h4>Fitur Unggulan</h4><p>Dengan desain ergonomis dan aplikasi Logi Tune, earbud ini memberikan kontrol penuh atas pengalaman audio Anda.</p>', 1, 0, 0, '2026-02-20 01:04:33', '2026-02-20 01:04:33'),
(68, 1, 1, 'Logitech Zone USB-C Receiver', 'logitech-zone-usb-c-receiver', '<h4>Deskripsi Produk</h4><p>Logitech Zone USB-C Receiver adalah dongle penerima nirkabel pengganti atau tambahan untuk headset seri Logitech Zone. Receiver ini menggunakan konektivitas nirkabel canggih untuk menghubungkan headset Zone Wireless atau Zone Vibe ke komputer dengan latensi rendah dan keandalan tinggi, jauh lebih stabil daripada koneksi Bluetooth standar laptop. Sangat penting di lingkungan kantor dengan banyak gangguan sinyal.</p><h4>Fitur Unggulan</h4><ul><li><strong>Koneksi Stabil:</strong> Mengurangi putus-nyambung audio saat rapat penting.</li><li><strong>Jangkauan Luas:</strong> Mendukung jangkauan nirkabel hingga 30 meter.</li><li><strong>Indikator LED:</strong> Lampu status koneksi dan mute.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Konektor: USB-C</li><li>Kompatibilitas: Zone Wireless, Zone Vibe 100/125/Wireless</li></ul>', 'products/logitech-zone-usb-c-receiver/logitech-zone-usb-c-receiver-2026-1771574673.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '989-001141', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/zone-usb-c-receiver-datasheet.pdf', '[\"receiver usb-c\",\"logitech zone\",\"audio receiver\",\"wireless headset\",\"microsoft teams\",\"video conferencing\",\"usb-c receiver\"]', '{\"Dimensi\":{\"Tinggi\":\"26,8 mm\",\"Lebar\":\"12,4 mm\",\"Tebal\":\"6,2 mm\"},\"Kompatibilitas\":{\"Perangkat yang Didukung\":[\"Zone Wireless 2\",\"Zone Wireless 2 ES for Business\",\"Zone Vibe Wireless\",\"Zone 305\",\"Zone 950\"]},\"Jenis Koneksi\":\"USB-C\",\"Versi Bluetooth\":\"5.2\",\"Jangkauan wireless\":\"Hingga 50 m (garis pandang lapangan terbuka)\",\"Garansi\":\"Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Receiver USB-C Zone menghubungkan headset Zone ke audio komputer Anda dengan andal dan kompatibel dengan UC atau Microsoft Teams.</p>', '[{\"name\":\"Tetap Terhubung dengan Audio Anda\",\"value\":\"Zone USB-C Receiver menggunakan enumerasi cerdas untuk secara cerdas berganti-ganti antara audio headset dan audio komputer.\",\"additional\":\"Receiver tetap terhubungkan sepanjang waktu.\"},{\"name\":\"Jangkauan Koneksi Wireless\",\"value\":\"Menyediakan koneksi yang andal dan stabil untuk headset Zone hingga 50 m.\",\"additional\":\"Jangkauan wireless mungkin bervariasi berdasarkan spesifikasi perangkat individu.\"},{\"name\":\"Isyarat Visual\",\"value\":\"Lampu LED pada receiver menunjukkan panggilan, mute, konektivitas, dan status Microsoft Teams.\",\"additional\":\"\"},{\"name\":\"Dioptimalkan untuk Musik dan Panggilan\",\"value\":\"Receiver memiliki kecerdasan internal untuk mengenali saat Anda sedang menelepon dan mendengarkan musik.\",\"additional\":\"Secara otomatis mengoptimalkan suara.\"},{\"name\":\"Kompatibilitas dengan Beberapa Headset\",\"value\":\"Kompatibel dengan beberapa headset Zone.\",\"additional\":\"Hubungkan satu headset pada satu waktu ke receiver.\"},{\"name\":\"Pairing Mudah\",\"value\":\"Pairing Zone USB-C Receiver baru dengan mulus ke headset Zone Anda menggunakan aplikasi desktop Logi Tune.\",\"additional\":\"Upgrade firmware dengan mudah.\"}]', '<h4>Fitur Unggulan</h4><p>Receiver ini menawarkan koneksi yang stabil, isyarat visual, dan dioptimalkan untuk musik dan panggilan.</p>', 1, 0, 0, '2026-02-20 01:04:33', '2026-02-20 01:04:33'),
(69, 1, 1, 'Logitech Zone Vibe Wireless', 'logitech-zone-vibe-wireless', '<h4>Deskripsi Produk</h4><p>Logitech Zone Vibe Wireless adalah headphone over-the-ear yang ringan dan bergaya, dirancang untuk karyawan hibrida yang bekerja dari rumah atau kantor. Headset ini memadukan kinerja audio kelas bisnis dengan kenyamanan dan desain modern. Dilengkapi dengan boom mic yang dapat disembunyikan (flip-to-mute) dan bahan kain rajut yang lembut, Zone Vibe Wireless sangat nyaman dipakai untuk panggilan konferensi panjang maupun mendengarkan musik.</p><h4>Fitur Unggulan</h4><ul><li><strong>Desain Ringan:</strong> Berat hanya 185 gram dengan earpad memory foam yang lembut.</li><li><strong>Flip-to-Mute Mic:</strong> Mikrofon boom yang membatalkan kebisingan; cukup angkat ke atas untuk mematikan suara (mute).</li><li><strong>Audio Imersif:</strong> Driver speaker 40mm yang menghadirkan bass yang dalam dan nada tinggi yang renyah.</li><li><strong>Konektivitas Ganda:</strong> Terhubung via USB receiver ke PC/Mac dan Bluetooth ke perangkat mobile.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Driver: 40mm</li><li>Baterai: Hingga 18 jam waktu bicara, 20 jam waktu dengar</li><li>Jangkauan: Hingga 30m di ruang terbuka</li><li>Koneksi: USB-C receiver + adapter USB-A, Bluetooth 5.2</li></ul>', 'products/logitech-zone-vibe-wireless/logitech-zone-vibe-wireless-2026-1771574673.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '981-001200', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/zone-vibe-wireless-datasheet.pdf', '[\"headset wireless\",\"logitech zone vibe\",\"bluetooth headset\",\"noise-canceling microphone\",\"business headset\",\"hybrid work\",\"audio quality\"]', '{\"Dimensi\":{\"Headset\":{\"Tinggi\":\"183 mm\",\"Lebar\":\"169.7 mm\",\"Tebal\":\"73 mm\",\"Berat\":\"185 g\"},\"Receiver USB-C\":{\"Tinggi\":\"26.8 mm\",\"Lebar\":\"12.4 mm\",\"Tebal\":\"6.2 mm\"},\"Adaptor USB-A\":{\"Tinggi\":\"24.5 mm\",\"Lebar\":\"15.4 mm\",\"Tebal\":\"8.7 mm\"},\"Kemasan\":{\"Tinggi\":\"198 mm\",\"Lebar\":\"196 mm\",\"Tebal\":\"82 mm\",\"Berat\":\"359 g\"}},\"Spesifikasi Teknis\":{\"Driver\":\"40 mm\",\"Respons Frekuensi Headphone (mode musik)\":\"20-20 kHz\",\"Respons Frekuensi Headphone (mode bicara)\":\"100-8 kHz\",\"Impedansi Headphone\":\"45 \\u03a9 Ohm\",\"Sensitivitas Headphone\":\"118.0\\u00b13 dB at 1mW @1kHz\",\"Kepatuhan Audio Headphone\":\"Sesuai dengan EN 50332-2; Kepatuhan alat bantu dengar ADA (TIA-1083)\"},\"Mikrofon\":{\"Jenis mikrofon\":\"Mikrofon dual omni-directional MEMS mics dengan directional beamforming dan DSP\",\"Respons Frekuensi Mikrofon\":\"100-8 kHz\"},\"Baterai & Pengisian Daya\":{\"Jenis baterai\":\"Baterai internal (Lithium ion)\",\"Daya tahan baterai (waktu berbicara)\":\"Hingga 18 jam\",\"Daya tahan baterai (waktu mendengarkan)\":\"Hingga 20 Jam\",\"Jenis pengisian daya\":\"USB-C\",\"Kabel pengisian daya\":\"100 cm\"},\"Konektivitas\":{\"Jenis Koneksi Konektivitas\":\"Bluetooth 5.2\",\"Jangkauan Nirkabel Konektivitas\":\"Hingga 30 m \\/ 100 ft (garis pandang lapangan terbuka) untuk versi Bluetooth asli dan hingga 50 m \\/ 170 ft (garis pandang lapangan terbuka) untuk versi penerima\"},\"Persyaratan Sistem\":{\"Kompatibilitas\":\"Telah disertifikasi untuk Microsoft Teams, Zoom, Google Meet, Google Voice. Bekerja dengan komputer berbasis Windows, macOS, atau ChromeOS melalui USB-C, USB-A, Bluetooth, dan perangkat Bluetooth yang diaktifkan iOS atau Android\",\"Penting\":\"Sertifikasi untuk Microsoft Teams melalui Bluetooth asli didukung di Windows 11 dengan aplikasi Microsoft Teams yang baru\"},\"Keberlanjutan\":{\"Kemasan yang Ramah Lingkungan\":\"Bersertifikasi FSC\\u2122, Sertifikasi Carbon Clarity\",\"Plastik Daur Ulang\":\"Terbuat dari Plastik Daur Ulang (Kandungan plastik headset: 25% plastik post-consumer recycled)\"}}', '<h4>Spesifikasi Utama</h4><p>Zone Vibe Wireless menawarkan desain modern dan fitur canggih untuk pengalaman audio yang luar biasa.</p>', '[{\"name\":\"Mikrofon Noise-Canceling\",\"value\":\"Mikrofon noise-canceling ganda dengan teknologi beamforming\",\"additional\":\"Menangkap ucapan dengan jelas\"},{\"name\":\"Audio yang Memukau\",\"value\":\"Driver speaker 40 mm\",\"additional\":\"Bass yang menggelegar dan frekuensi lebih tinggi yang tajam\"},{\"name\":\"Kenyamanan dan Gaya Sepanjang Hari\",\"value\":\"Desain ringan dan earpad memory foam\",\"additional\":\"Memberikan kenyamanan berjam-jam\"},{\"name\":\"Bluetooth Multipoint\",\"value\":\"Beralih dengan mudah di antara sumber audio aktif\",\"additional\":\"Koneksi wireless yang kuat\"},{\"name\":\"Daya Tahan Baterai yang Panjang\",\"value\":\"Hingga 20 jam waktu mendengarkan dan 18 jam waktu bicara\",\"additional\":\"Memberi kebebasan tanpa mengkhawatirkan daya tahan baterai\"},{\"name\":\"Disesuaikan dengan Aplikasi Logi Tune\",\"value\":\"Kustomisasi pengalaman pengguna\",\"additional\":\"Melalui komputer atau ponsel\"},{\"name\":\"Tampilan Penerapan Terpusat dengan Sync\",\"value\":\"Portal manajemen berbasis cloud\",\"additional\":\"Memungkinkan pemantauan penerapan dan pembaruan firmware\"}]', '<h4>Fitur Unggulan</h4><p>Dengan mikrofon noise-canceling dan audio berkualitas tinggi, headset ini ideal untuk pekerjaan hybrid.</p>', 1, 0, 0, '2026-02-20 01:04:33', '2026-02-20 01:04:33'),
(70, 1, 1, 'Logitech Zone Wired Earbuds', 'logitech-zone-wired-earbuds', '<h4>Deskripsi Produk</h4><p>Logitech Zone Wired Earbuds adalah earbud kabel profesional yang dirancang untuk panggilan video dan komunikasi bisnis. Dilengkapi mikrofon noise-canceling dan kontrol in-line, earbud ini memberikan kejernihan suara tinggi di lingkungan kerja yang sibuk.</p><h4>Fitur Utama</h4><ul><li><strong>Noise-Canceling Mic:</strong> Mengurangi kebisingan latar belakang.</li><li><strong>Kontrol In-Line:</strong> Akses cepat ke volume dan mute.</li><li><strong>Plug-and-Play:</strong> Koneksi langsung ke perangkat.</li><li><strong>Kenyamanan Seharian:</strong> Desain ergonomis ringan.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Koneksi: USB-C atau 3.5mm (tergantung varian)</li><li>Mikrofon: Built-in noise-reducing</li><li>Kompatibilitas: Windows, macOS</li></ul>', 'products/logitech-zone-wired-earbuds/logitech-zone-wired-earbuds-2026-1771574674.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '981-001095', NULL, 'https://www.logitech.com/content/dam/logitech/en_us/video-collaboration/pdf/headsets-portfolio.pdf', '[\"zone wired earbuds\",\"logitech earbuds\",\"noise-canceling earbuds\",\"business earbuds\",\"audio quality\",\"plug-and-play\",\"UC compatible\"]', '{\"Dimensi\":{\"Earbud\":{\"Tinggi\":\"23,4 mm\",\"Lebar\":\"23,1 mm\",\"Tebal\":\"27,3 mm\",\"Berat\":\"33 g\"},\"Kabel\":\"1,45 m\",\"Adaptor USB-C\":{\"Tinggi\":\"24,5 mm\",\"Lebar\":\"16,5 mm\",\"Tebal\":\"8,6 mm\"}},\"Kompatibilitas\":{\"Windows\":\"Kompatibel dengan komputer berbasis Windows, Mac, atau Chrome dan perangkat seluler berbasis Android atau iOS via port 3,5 mm, USB-C, atau USB-A yang kosong.\",\"Mac\":\"Kompatibel dengan komputer berbasis Windows, Mac, atau Chrome dan perangkat seluler berbasis Android atau iOS via port 3,5 mm, USB-C, atau USB-A yang kosong.\",\"Android\":\"Kompatibel dengan komputer berbasis Windows, Mac, atau Chrome dan perangkat seluler berbasis Android atau iOS via port 3,5 mm, USB-C, atau USB-A yang kosong.\",\"iOS\":\"Kompatibel dengan komputer berbasis Windows, Mac, atau Chrome dan perangkat seluler berbasis Android atau iOS via port 3,5 mm, USB-C, atau USB-A yang kosong.\"},\"Sertifikasi\":\"Sertifikasi untuk Microsoft Teams, Google Meet, Google Voice, Zoom, dan aplikasi populer lainnya.\",\"Daya\":\"Plug-and-play dengan konektor 3,5 mm, USB-A, atau USB-C.\",\"Lingkungan\":\"Didesain untuk penggunaan di lingkungan kerja yang berisik.\"}', '<h4>Spesifikasi Utama</h4><p>Zone Wired Earbuds menawarkan mikrofon noise-canceling dan audio berkualitas studio, ideal untuk video call dan lingkungan kerja yang berisik.</p>', '[{\"name\":\"Mikrofon Noise-Canceling\",\"value\":\"Dual mikrofon omni-directional\",\"additional\":\"Menangkap setiap kata dengan jelas.\"},{\"name\":\"Audio Berkualitas Studio\",\"value\":\"Driver PET+PU\",\"additional\":\"Mengurangi distorsi dan meningkatkan kualitas suara.\"},{\"name\":\"Desain In-Ear\",\"value\":\"Mengurangi noise eksternal\",\"additional\":\"Minimalkan kebocoran suara.\"},{\"name\":\"Kontrol In-Line\",\"value\":\"Volume, mute, dan kontrol panggilan\",\"additional\":\"Mudah diakses.\"},{\"name\":\"Kustomisasi dengan Logi Tune\",\"value\":\"Modulasi kontrol sidetone dan EQ 5-band\",\"additional\":\"Hanya di Windows.\"},{\"name\":\"Panjang Kabel\",\"value\":\"1,45 m\",\"additional\":\"Cukup panjang untuk kenyamanan.\"},{\"name\":\"Penyimpanan Mudah\",\"value\":\"Tas neoprene\",\"additional\":\"Menyimpan earbud dan kabel dengan rapi.\"}]', '<h4>Fitur Unggulan</h4><p>Didesain untuk kenyamanan dan kualitas suara, dengan kontrol intuitif dan kompatibilitas luas.</p>', 1, 0, 0, '2026-02-20 01:04:33', '2026-02-20 01:04:34'),
(71, 1, 1, 'Logitech Zone Wired', 'logitech-zone-wired', '<h4>Deskripsi Produk</h4><p>Logitech Zone Wired adalah headset USB premium yang dirancang untuk ruang kerja terbuka yang sibuk. Headset ini dilengkapi dengan teknologi mikrofon noise-canceling canggih yang mengisolasi suara Anda dari kebisingan di sekitar (seperti suara keyboard atau percakapan rekan kerja). Dengan kontrol in-line yang intuitif dan driver audio berukuran besar, headset ini sangat ideal untuk panggilan konferensi intensif dan mendengarkan musik dengan kualitas tinggi.</p><h4>Fitur Unggulan</h4><ul><li><strong>Noise-Canceling Mic:</strong> Teknologi mikrofon ganda yang menekan kebisingan latar belakang hingga 60dB.</li><li><strong>Kontrol In-Line:</strong> Akses mudah ke volume, mute, jawab/akhiri panggilan, dan tombol khusus Microsoft Teams (pada versi Teams).</li><li><strong>Kenyamanan Premium:</strong> Headband berlapis silikon dan earpad yang nyaman serta kabel anti-kusut.</li><li><strong>Dukungan Logi Tune:</strong> Kustomisasi EQ dan sidetone melalui aplikasi desktop.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Konektor: USB-C (disertakan adaptor USB-A)</li><li>Mikrofon: Dual MEMS array</li><li>Kabel: Panjang 1.9 meter</li><li>Sertifikasi: Microsoft Teams, Zoom, Google Meet</li></ul>', 'products/logitech-zone-wired/logitech-zone-wired-2026-1771574674.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '981-001097', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/zone-wired-uc-datasheet.pdf', '[\"headset\",\"logitech zone wired\",\"noise canceling\",\"usb headset\",\"audio premium\",\"video conference\",\"business headset\"]', '{\"Dimensi\":{\"Headset\":{\"Tinggi\":\"165.93 mm\",\"Lebar\":\"179.73 mm\",\"Tebal\":\"66.77 mm\",\"Berat\":\"211 g\"},\"Earpad\":{\"Tinggi\":\"65.84 mm\",\"Lebar\":\"65.84 mm\",\"Tebal\":\"18.75 mm\"},\"Adaptor USB-C\":{\"Tinggi\":\"21.5 mm\",\"Lebar\":\"16.5 mm\",\"Tebal\":\"7.9 mm\"}},\"Spesifikasi Teknis\":{\"Headphone\":{\"Driver\":\"40 mm\",\"Respons Frekuensi\":\"20-16 kHz\",\"Impedansi\":\"32 Ohm\",\"Sensitivitas\":\"99 dB\\u00b13 dB at 1000 Hz @30 mW,1 cm\",\"Kepatuhan Audio\":\"Sesuai dengan EN 50332\"},\"Mikrofon\":{\"Jenis\":\"Mikrofon Utama: Uni-directional, Mikrofon Sekunder: Omni-directional\",\"Respons Frekuensi\":\"150Hz-7KHz\",\"Panjang Kabel\":\"190 cm\",\"Sensitivitas\":\"Mikrofon Utama: -48 dBV\\/Pa, Mikrofon Sekunder: -40 dBV\\/Pa\"},\"Konektivitas\":{\"Jenis Koneksi\":\"USB-C berkabel atau USB-A\"},\"Persyaratan Sistem\":{\"Kompatibilitas\":\"Komputer berbasis Windows, Mac, atau Chrome yang dilengkapi port USB-C atau USB-A. Fungsionalitas untuk perangkat seluler dengan USB-C tergantung pada perangkatnya.\"},\"Keberlanjutan\":{\"Jejak karbon produk\":\"7,68 kg CO2e\"}}}', '<h4>Spesifikasi Utama</h4><p>Zone Wired menghadirkan audio premium dan kejelasan panggilan yang andal dengan teknologi noise-canceling mic terbaik.</p>', '[{\"name\":\"Driver\",\"value\":\"40 mm\",\"additional\":\"\"},{\"name\":\"Respons Frekuensi Headphone\",\"value\":\"20-16 kHz\",\"additional\":\"\"},{\"name\":\"Impedansi Headphone\",\"value\":\"32 Ohm\",\"additional\":\"\"},{\"name\":\"Sensitivitas Headphone\",\"value\":\"99 dB\\u00b13 dB at 1000 Hz @30 mW,1 cm\",\"additional\":\"\"},{\"name\":\"Mikrofon Utama\",\"value\":\"Uni-directional\",\"additional\":\"\"},{\"name\":\"Mikrofon Sekunder\",\"value\":\"Omni-directional\",\"additional\":\"\"},{\"name\":\"Respons Frekuensi Mikrofon\",\"value\":\"150Hz-7KHz\",\"additional\":\"\"},{\"name\":\"Panjang Kabel\",\"value\":\"190 cm\",\"additional\":\"\"},{\"name\":\"Sensitivitas Mikrofon Utama\",\"value\":\"-48 dBV\\/Pa\",\"additional\":\"\"},{\"name\":\"Sensitivitas Mikrofon Sekunder\",\"value\":\"-40 dBV\\/Pa\",\"additional\":\"\"},{\"name\":\"Jenis Koneksi\",\"value\":\"USB-C berkabel atau USB-A\",\"additional\":\"\"},{\"name\":\"Kompatibilitas\",\"value\":\"Komputer berbasis Windows, Mac, atau Chrome yang dilengkapi port USB-C atau USB-A.\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Driver 40 mm untuk suara yang jernih dan mikrofon dual noise-canceling untuk panggilan yang jelas.</p>', 1, 0, 0, '2026-02-20 01:04:34', '2026-02-20 01:04:34');
INSERT INTO `products` (`id`, `service_id`, `brand_id`, `name`, `slug`, `description`, `image_path`, `thumbnail_path`, `price`, `link_accommerce`, `whatsapp_note`, `sku`, `solution_type`, `datasheet_url`, `tags`, `specs`, `specification_text`, `features`, `features_text`, `is_active`, `is_featured`, `is_new`, `created_at`, `updated_at`) VALUES
(72, 1, 1, 'Logitech Zone Wireless 2 Charging Stand', 'logitech-zone-wireless-2-charging-stand', '<h4>Deskripsi Produk</h4><p>Logitech Zone Wireless 2 Charging Stand adalah dudukan pengisian daya yang elegan untuk headset Zone Wireless 2. Dudukan ini memastikan headset Anda selalu terisi penuh dan siap digunakan setiap saat. Dengan desain minimalis dan berat yang pas, dudukan ini juga berfungsi sebagai tempat penyimpanan headset yang rapi di atas meja, mencegah meja kerja berantakan.</p><h4>Fitur Unggulan</h4><ul><li><strong>Pengisian Kontak:</strong> Cukup letakkan headset di dudukan, magnet akan memposisikannya untuk pengisian.</li><li><strong>Organisasi Meja:</strong> Menjaga headset tetap tegak dan mudah dijangkau.</li><li><strong>Indikator Pengisian:</strong> Lampu LED menunjukkan status baterai.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Kompatibilitas: Eksklusif untuk Zone Wireless 2</li><li>Koneksi Daya: USB-C</li></ul>', 'products/logitech-zone-wireless-2-charging-stand/logitech-zone-wireless-2-charging-stand-2026-1771574674.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '989-001211', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/zone-wireless-2-charging-stand-datasheet.pdf', '[\"zone wireless 2\",\"charging stand\",\"headset charger\",\"logitech accessories\",\"USB-A charging\",\"wireless headset\",\"office accessories\"]', '{\"Dimensi\":{\"Tinggi\":\"29.5 mm\",\"Diameter\":\"85.9 mm\"},\"Berat\":\"152 g\",\"Spesifikasi Umum\":{\"Panjang kabel\":\"1,3 m\",\"Indikator lampu\":\"Ya\",\"Bahan\":\"Alas karet non-slip\",\"Jenis koneksi\":\"USB-A\",\"Perangkat yang didukung\":\"Zone Wireless 2\"},\"Listrik & Lingkungan\":{\"Daya tahan baterai\":\"2 jam untuk pengisian penuh; pengisian cepat 5 menit = hingga 1 jam waktu bicara (Daya tahan baterai dapat bervariasi berdasarkan kondisi lingkungan dan komputasi.)\"},\"Garansi\":\"Garansi Hardware Terbatas 2 Tahun\"}', '<h4>Spesifikasi Utama</h4><p>Dudukan pengisian daya yang praktis untuk headset Zone Wireless 2 dengan indikator lampu dan desain non-slip.</p>', '[{\"name\":\"Daya Tahan Baterai\",\"value\":\"2 jam untuk pengisian penuh\",\"additional\":\"Pengisian cepat 5 menit = hingga 1 jam waktu bicara\"},{\"name\":\"Indikator Lampu\",\"value\":\"Ya\",\"additional\":\"\"},{\"name\":\"Bahan\",\"value\":\"Alas karet non-slip\",\"additional\":\"\"},{\"name\":\"Jenis Koneksi\",\"value\":\"USB-A\",\"additional\":\"\"},{\"name\":\"Panjang Kabel\",\"value\":\"1,3 m\",\"additional\":\"\"},{\"name\":\"Perangkat yang Didukung\",\"value\":\"Zone Wireless 2\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Pengisian cepat dan daya tahan baterai yang optimal untuk pengalaman penggunaan headset yang lebih baik.</p>', 1, 0, 0, '2026-02-20 01:04:34', '2026-02-20 01:04:34'),
(73, 1, 1, 'Logitech Zone Wireless', 'logitech-zone-wireless', '<h4>Deskripsi Produk</h4><p>Logitech Zone Wireless adalah headset Bluetooth on-ear yang dirancang untuk membantu Anda menguasai lingkungan akustik ruang kerja terbuka. Headset ini memiliki fitur Active Noise Cancellation (ANC) yang efektif mengurangi kebisingan latar belakang, memungkinkan fokus yang lebih baik. Salah satu fitur uniknya adalah kemampuan pengisian daya nirkabel Qi, sehingga Anda tidak perlu repot dengan kabel saat mengisi daya di meja kerja.</p><h4>Fitur Unggulan</h4><ul><li><strong>Active Noise Cancellation:</strong> Mengurangi suara frekuensi rendah seperti AC atau hiruk pikuk kantor.</li><li><strong>Qi Wireless Charging:</strong> Kompatibel dengan charger nirkabel Qi standar (bisa dilipat untuk pengisian mudah).</li><li><strong>Multipoint Pairing:</strong> Beralih mulus antara audio komputer dan panggilan telepon masuk.</li><li><strong>Mikrofon Flip-to-Mute:</strong> Desain intuitif untuk privasi instan saat rapat.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Baterai: Hingga 14 jam (ANC on)</li><li>Konektivitas: Bluetooth 5.0, USB-A Unifying + Audio Receiver</li><li>Jangkauan: Hingga 30m</li><li>Aplikasi: Logi Tune untuk kontrol audio penuh</li></ul>', 'products/logitech-zone-wireless/logitech-zone-wireless-2026-1771574674.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '981-000915', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/zone-wireless-datasheet.pdf', '[\"headset bluetooth\",\"logitech zone wireless\",\"noise cancellation\",\"wireless headset\",\"microsoft teams\",\"audio quality\",\"business headset\"]', '{\"Dimensi\":{\"Headset\":{\"Tinggi\":\"174.7 mm\",\"Lebar\":\"176.7 mm\",\"Tebal\":\"70.7 mm\",\"Berat\":\"180.8 g\"},\"Dimensi ear pad\":{\"Tinggi\":\"70.7 mm\",\"Lebar\":\"70.7 mm\",\"Tebal\":\"16.4 mm\"},\"Zone Wireless Receiver\":{\"Tinggi\":\"21.5 mm\",\"Lebar\":\"13.6 mm\",\"Tebal\":\"6 mm\"},\"Adaptor USB-C Zone Wireless\":{\"Tinggi\":\"25.2 mm\",\"Lebar\":\"16.5 mm\",\"Tebal\":\"9.5 mm\"},\"Zone Wireless Plus Receiver\":{\"Tinggi\":\"35.5 mm\",\"Lebar\":\"16.2 mm\",\"Tebal\":\"5.3 mm\"},\"Zone Wireless Plus USB-C adapter\":{\"Tinggi\":\"106.7 mm\",\"Lebar\":\"17.5 mm\",\"Tebal\":\"10.1 mm\"}},\"Spesifikasi Teknis\":{\"Headphone\":{\"Respons Frekuensi Headphone (mode musik)\":\"30 ~ 13 KHz @ -10dB\",\"Respons Frekuensi Headphone (mode bicara)\":\"100 ~ 8 KHz per TIA920\",\"Kepatuhan Audio Headphone\":\"Sesuai dengan EN 50332\"},\"Mikrofon\":{\"Jenis mikrofon\":\"Omni-directional dual MEMS mic array\",\"Respons Frekuensi Mikrofon\":\"85 ~ 20 KHz @-3dB (MEMS mic freq resp)\"},\"Baterai & Pengisian Daya\":{\"Jenis baterai\":\"Baterai internal (Lithium ion)\",\"Daya tahan baterai (waktu berbicara)\":\"14 jam (ANC on), 15 jam (ANC off)\",\"Daya tahan baterai (waktu mendengarkan)\":\"14 jam (ANC on), 16 jam (ANC off)\",\"Jenis pengisian daya\":\"Pengisian daya nirkabel Qi diaktifkan\",\"Kabel pengisian daya\":\"130 cm\"},\"Konektivitas\":{\"Jenis Koneksi Konektivitas\":\"USB-A, USB-C, Bluetooth\",\"Versi Bluetooth\":\"5.0\",\"Jangkauan Nirkabel Konektivitas\":\"Maksimal 30 m (bidang pandang terbuka)\"},\"Persyaratan Sistem\":{\"Kompatibilitas\":\"Kompatibel dengan aplikasi panggilan umum yang ditemui di hampir semua platform dan sistem operasi. Kompatibel dengan komputer berbasis Windows, Mac, atau Chrome via USB-C, USB-A, Bluetooth, dan perangkat iOS atau Android berkemampuan Bluetooth.\"},\"Keberlanjutan\":{\"Jejak karbon produk\":\"9,3 kg CO2e\"}}}', '<h4>Spesifikasi Utama</h4><p>Zone Wireless adalah headset Bluetooth yang dirancang untuk memberikan pengalaman audio yang luar biasa dengan fitur pengisian daya nirkabel dan mikrofon flip-to-mute.</p>', '[{\"name\":\"Active Noise Cancellation\",\"value\":\"Mengurangi suara yang tidak diinginkan di sekitar.\"},{\"name\":\"Mikrofon Flip-to-Mute\",\"value\":\"Mikrofon dapat dimatikan dengan mudah.\"},{\"name\":\"Pengisian Daya Qi Wireless\",\"value\":\"Dapat diisi daya secara nirkabel.\"},{\"name\":\"Konektivitas Multi-Perangkat\",\"value\":\"Dapat terhubung ke beberapa perangkat secara bersamaan.\"},{\"name\":\"Kompatibilitas Microsoft Teams\",\"value\":\"Bersertifikasi untuk penggunaan dengan Microsoft Teams.\"},{\"name\":\"Kontrol Sederhana\",\"value\":\"Antarmuka intuitif untuk kontrol volume dan panggilan.\"},{\"name\":\"Audio Premium\",\"value\":\"Kualitas audio tinggi untuk musik dan panggilan.\"}]', '<h4>Fitur Unggulan</h4><p>Dengan Active Noise Cancellation dan konektivitas multi-perangkat, Zone Wireless memastikan kamu tetap fokus dan terhubung di mana saja.</p>', 1, 0, 0, '2026-02-20 01:04:34', '2026-02-20 01:04:34'),
(74, 1, 1, 'Logitech Scribe', 'logitech-scribe', '<h4>Deskripsi Produk</h4><p>Logitech Scribe adalah kamera whiteboard bertenaga AI yang didedikasikan untuk berbagi papan tulis fisik ke dalam rapat video dengan kejernihan luar biasa. Scribe \"melihat melalui\" presenter, membuat mereka transparan sehingga peserta jarak jauh dapat melihat tulisan di papan tulis tanpa terhalang punggung presenter. Kamera ini juga secara otomatis meningkatkan kontras warna spidol dan mendeteksi catatan tempel (sticky notes), mendigitalkan konten analog secara real-time.</p><h4>Fitur Unggulan</h4><ul><li><strong>AI Transparency:</strong> Efek transparansi presenter memungkinkan audiens melihat konten papan tulis tanpa halangan.</li><li><strong>Content Enhancement:</strong> Meningkatkan warna dan kontras tulisan spidol agar mudah dibaca di layar.</li><li><strong>Share Button:</strong> Tombol nirkabel ungu yang unik memungkinkan presenter memulai/menghentikan berbagi papan tulis dengan satu sentuhan jari atau siku.</li><li><strong>Desain Elegan:</strong> Menyatu dengan kantor modern, dipasang di dinding tepat di atas papan tulis.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Resolusi Output: 1080p pada 15fps</li><li>AI: Built-in AI processor untuk koreksi gambar</li><li>Area Papan Tulis: Mendukung papan hingga ukuran 2m x 1.2m</li><li>Koneksi: Kabel Cat5e (Power over Ethernet injector disertakan)</li></ul>', 'products/logitech-scribe/logitech-scribe-2026-1771574674.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001332', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/scribe.pdf', '[\"webcam\",\"logitech scribe\",\"video conferencing\",\"whiteboard camera\",\"AI camera\",\"collaboration tools\",\"business solutions\"]', '{\"Dimensi\":{\"Kamera\":{\"Tinggi\":\"149 mm\",\"Lebar\":\"119 mm\",\"Tebal\":\"573 mm\",\"Berat\":\"1,1 kg\"},\"Tombol Berbagi\":{\"Tinggi\":\"12,7 mm\",\"Diameter\":\"71,8 mm\",\"Berat\":\"108 g\"},\"Injektor Daya\":{\"Tinggi\":\"91 mm\",\"Lebar\":\"60,2 mm\",\"Tebal\":\"36,3 mm\"},\"Dongle Transceiver\":{\"Tinggi\":\"22,5 mm\",\"Lebar\":\"31 mm\",\"Tebal\":\"83,7 mm\",\"Panjang kabel\":\"500 mm\"},\"Termasuk Penataan Kabel (x2)\":{\"Panjang\":\"5 m\"}},\"Sertifikasi & Kompatibilitas\":{\"Informasi\":\"Kunjungi www.logitech.com\\/support\\/scribe-compatibility untuk sertifikasi yang sudah didapatkan dan masih tertunda, serta pembaruan kompatibilitas.\",\"Kompatibilitas\":\"Kompatibel dengan setiap aplikasi video conferencing sebagai kamera yang terhubung dengan USB.\"},\"Kamera\":{\"Resolusi Output\":\"1080p pada 15 fps\",\"FoV\":\"148\\u00b0\",\"AI internal\":\"Broadcast streaming gambar yang didukung AI ke video meeting\"},\"Tombol Berbagi\":{\"Daya\":\"2 x baterai CR2032\",\"Mounting\":\"Perekat\",\"Dukungan\":\"Dukungan tombol berbagi mungkin bervariasi tergantung pada penyedia layanan video conferencing.\"},\"Whiteboard\":{\"Dimensi Maksimum\":{\"Tinggi\":\"1,2 m\",\"Lebar\":\"1,8 m\"}},\"Antarmuka\":{\"Kamera\":\"Port Kabel Kategori\",\"Tombol Berbagi\":\"Bluetooth\\u00ae Low Energy\"},\"Daya & Kabel\":{\"Catu daya\":\"Catu daya auto-switching 100-240V dengan set adaptor internasional\"},\"Lingkungan\":{\"Suhu Pengoperasian\":\"0 hingga 40\\u00b0C\",\"Suhu Penyimpanan\":\"-40-70\\u00b0C\",\"Kelembapan\":\"10-95%\"},\"Keamanan\":{\"Full Disk Encryption\":\"Port USB yang kosong\"},\"Manajemen Perangkat\":{\"Sistem\":\"Logitech Sync\"}}', '<h4>Spesifikasi Utama</h4><p>Logitech Scribe adalah kamera whiteboard yang dirancang untuk video conferencing, dengan kemampuan AI untuk meningkatkan pengalaman berbagi konten.</p>', '[{\"name\":\"AI Internal\",\"value\":\"Menghapus presenter dari tampilan video.\",\"additional\":\"Memungkinkan peserta melihat whiteboard tanpa terhalang.\"},{\"name\":\"Peningkatan Konten\",\"value\":\"Secara otomatis meningkatkan warna dan kontras spidol whiteboard.\",\"additional\":\"Memudahkan peserta untuk membaca teks dan gambar.\"},{\"name\":\"Deteksi Sticky Note\",\"value\":\"Mengenali dan menunjukkan bentuk konten lainnya.\",\"additional\":\"Termasuk sticky note.\"},{\"name\":\"Penggunaan yang Sederhana\",\"value\":\"Tombol berbagi wireless untuk berbagi whiteboard.\",\"additional\":\"Dapat digunakan dengan touch controller seperti Logitech Tap.\"}]', '<h4>Fitur Unggulan</h4><p>Dari penghapusan presenter hingga peningkatan konten, Scribe menawarkan berbagai fitur untuk meningkatkan kolaborasi dalam pertemuan.</p>', 1, 0, 0, '2026-02-20 01:04:34', '2026-02-20 01:04:34'),
(75, 1, 1, 'Logitech C505e Business Webcam', 'logitech-c505e-business-webcam', '<h4>Deskripsi Produk</h4><p>Logitech C505e adalah webcam bisnis 720p yang dirancang untuk penggunaan profesional sehari-hari. Dengan mikrofon omnidirectional jarak jauh dan koneksi USB-A plug-and-play, C505e menghadirkan solusi video conference yang sederhana dan andal untuk ruang kerja hybrid maupun kantor.</p><h4>Fitur Utama</h4><ul><li><strong>Video HD 720p:</strong> Kualitas gambar tajam untuk meeting online.</li><li><strong>Long-Range Microphone:</strong> Menangkap suara hingga jarak 3 meter.</li><li><strong>Plug-and-Play:</strong> Koneksi mudah melalui USB-A.</li><li><strong>Mount Fleksibel:</strong> Klip universal untuk monitor atau laptop.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Resolusi: 720p/30fps</li><li>Field of View: 60° diagonal</li><li>Koneksi: USB-A</li><li>Kabel: 2 meter</li></ul>', 'products/logitech-c505e-business-webcam/logitech-c505e-business-webcam-2026-1771574674.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001372', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/c505e-datasheet.pdf', '[\"webcam 720p\",\"logitech c505e\",\"video conference\",\"business webcam\",\"streaming camera\",\"HD webcam\",\"omnidirectional microphone\"]', '{\"Dimensi\":{\"Tinggi\":\"31,91 mm\",\"Lebar\":\"72,91 mm\",\"Tebal\":\"66,64 mm\",\"Panjang kabel\":\"2 m\",\"Berat\":\"75 g\"},\"Kompatibilitas\":{\"Windows\":\"Windows\\u00ae 8 or later\",\"Mac\":\"macOS 10.10 or later\",\"ChromeOS\":\"ChromeOS\"},\"Spesifikasi Teknis\":{\"Resolusi Maks\":\"720p\\/30fps\",\"Kamera mega pixel\":\"1.2\",\"Jenis fokus\":\"Fixed\",\"Jenis lensa\":\"plastik\",\"Mikrofon internal\":\"Mono\",\"Jangkauan mikrofon\":\"Maksimal 2,74 m\",\"Bidang pandang diagonal\":\"60\\u00b0\"},\"Daya\":{\"Port\":\"USB-A\"},\"Sertifikasi\":{\"Garansi\":\"Garansi hardware terbatas 3 tahun\"}}', '<h4>Spesifikasi Utama</h4><p>C505e adalah webcam HD dengan kualitas video 720p dan mikrofon berdaya jangkau panjang, ideal untuk aplikasi panggilan video.</p>', '[{\"name\":\"Video HD Widescreen\",\"value\":\"720p\\/30fps\",\"additional\":\"Kualitas video yang jelas dan mulus.\"},{\"name\":\"Mikrofon Omnidirectional\",\"value\":\"Daya jangkau hingga 3 meter\",\"additional\":\"Teknologi noise-reduction.\"},{\"name\":\"Kabel Panjang\",\"value\":\"2 m\",\"additional\":\"Memungkinkan berbagai opsi pemasangan.\"},{\"name\":\"Universal Mounting Clip\",\"value\":\"Cocok untuk berbagai laptop dan layar\",\"additional\":\"Mudah dipasang.\"}]', '<h4>Fitur Unggulan</h4><p>Webcam ini dilengkapi dengan teknologi noise-reduction dan kabel USB-A ekstra panjang untuk fleksibilitas pemasangan.</p>', 1, 0, 0, '2026-02-20 01:04:34', '2026-02-20 01:04:34'),
(76, 1, 1, 'Logitech C925e 1080p Business Webcam', 'logitech-c925e-1080p-business-webcam', '<h4>Deskripsi Produk</h4><p>Logitech C925e adalah webcam Full HD 1080p yang dirancang untuk penggunaan bisnis profesional. Dilengkapi dual stereo microphones dan bidang pandang lebar, kamera ini memberikan kualitas video yang jernih dan audio yang natural untuk meeting jarak jauh.</p><h4>Fitur Utama</h4><ul><li><strong>Full HD 1080p:</strong> Video tajam dan profesional.</li><li><strong>Stereo Microphones:</strong> Audio natural dengan noise reduction.</li><li><strong>RightLight™ 2:</strong> Penyesuaian pencahayaan otomatis.</li><li><strong>Privacy Shutter:</strong> Penutup lensa terintegrasi.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Resolusi: 1080p/30fps</li><li>Field of View: 78° diagonal</li><li>Koneksi: USB-A</li><li>Mount: Universal clip</li></ul>', 'products/logitech-c925e-1080p-business-webcam/logitech-c925e-1080p-business-webcam-2026-1771574674.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001075', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/c925e-datasheet.pdf', '[\"webcam 1080p\",\"logitech c925e\",\"video conferencing\",\"business webcam\",\"HD webcam\",\"streaming camera\",\"dual microphone\",\"RightLight technology\"]', '{\"Dimensi\":{\"Tinggi\":\"73 mm\",\"Lebar\":\"126 mm\",\"Tebal\":\"45 mm\",\"Panjang kabel\":\"1,83 m\"},\"Berat\":\"170 g\",\"Kompatibilitas\":{\"Windows\":\"Windows\\u00ae 8 or later\",\"Mac\":\"macOS 10.7 or later\",\"ChromeOS\":\"ChromeOS\"},\"Sertifikasi\":\"Disertifikasi untuk Google Meet\",\"Persyaratan Sistem\":{\"USB\":\"Satu port USB-A\",\"Kompatibilitas\":\"Kompatibel dengan Microsoft Directshow dan platform panggilan populer\"},\"Spesifikasi Teknis\":{\"Resolusi\":{\"1080p\":\"30fps (hingga 1920 x 1080 piksel)\",\"720p\":\"60fps (maksimal 1280 x 720 piksel)\"},\"Kamera mega pixel\":\"3\",\"Jenis fokus\":\"Autofocus\",\"Jenis lensa\":\"Kaca\",\"Mikrofon internal\":\"stereo, dual omni-directional\",\"Jangkauan mikrofon\":\"Maksimal 1 m\",\"Bidang pandang diagonal (dFoV)\":\"78\\u00b0\",\"Digital zoom\":\"1.2x\",\"Konektivitas USB\":\"USB-A plug-and-play\",\"Teknologi\":{\"H.264\":\"Mendukung H.264 dengan Scalable Video Coding dan UVC 1.1 encoding\",\"RightLight\":\"Teknologi RightLight\\u2122 2 untuk kejernihan dalam berbagai lingkungan pencahayaan\",\"Shutter\":\"Shutter privasi internal\"},\"Clip\":\"Universal clip yang kompatibel dengan tripod\"},\"Garansi\":\"Garansi hardware terbatas 3 tahun\"}', '<h4>Spesifikasi Utama</h4><p>C925e adalah webcam HD 1080p yang menghadirkan video dan audio yang profesional, dengan dukungan H.264 dan teknologi RightLight™ 2 untuk kejernihan dalam berbagai lingkungan pencahayaan.</p>', '[{\"name\":\"Video Quality\",\"value\":\"1080p\\/30 fps\",\"additional\":\"HD autofocus untuk kejelasan sangat nyata\"},{\"name\":\"Audio Quality\",\"value\":\"Dual omnidirectional microphones\",\"additional\":\"Mampu menangkap audio dengan jelas dari jarak satu meter\"},{\"name\":\"Privacy Shade\",\"value\":\"Integrated privacy shade\",\"additional\":\"Slider tab untuk membuka atau menutup lensa\"},{\"name\":\"Compatibility\",\"value\":\"Compatible with popular video calling platforms\",\"additional\":\"Termasuk Microsoft Teams, Zoom, dan lainnya\"},{\"name\":\"Installation Options\",\"value\":\"Versatile mounting options\",\"additional\":\"Dapat dipasang di laptop, layar, atau tripod\"},{\"name\":\"Logi Tune\",\"value\":\"Control and customize your webcam\",\"additional\":\"Aplikasi Logi Tune Desktop untuk pengaturan\"}]', '<h4>Fitur Unggulan</h4><p>C925e menyediakan HD 1080p/30 fps dan dual mikrofon omnidirectional untuk audio yang jelas, serta opsi pemasangan yang fleksibel untuk berbagai kebutuhan.</p>', 1, 0, 0, '2026-02-20 01:04:34', '2026-02-20 01:04:34'),
(77, 1, 1, 'Logitech C930e 1080p Business Webcam', 'logitech-c930e-1080p-business-webcam', '<h4>Deskripsi Produk</h4><p>Logitech C930e adalah webcam bisnis premium dengan video Full HD 1080p dan bidang pandang lebar 90°. Dirancang untuk profesional yang membutuhkan performa tinggi, C930e menawarkan kualitas optik superior dan dukungan H.264 encoding untuk performa bandwidth yang efisien.</p><h4>Fitur Utama</h4><ul><li><strong>Full HD 1080p:</strong> Kualitas video profesional.</li><li><strong>Wide Field of View 90°:</strong> Cakupan lebih luas untuk kolaborasi.</li><li><strong>H.264 Encoding:</strong> Performa video lebih efisien.</li><li><strong>Privacy Shutter:</strong> Kontrol privasi manual.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Resolusi: 1080p/30fps</li><li>Field of View: 90° diagonal</li><li>Koneksi: USB-A</li><li>Microphone: Dual stereo</li></ul>', 'products/logitech-c930e-1080p-business-webcam/logitech-c930e-1080p-business-webcam-2026-1771574675.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-000976', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/c930e-datasheet.pdf', '[\"webcam 1080p\",\"logitech c930e\",\"video conference\",\"business webcam\",\"streaming camera\",\"h.264 webcam\",\"high definition webcam\"]', '{\"Dimensi\":{\"Tinggi\":\"43 mm\",\"Lebar\":\"94 mm\",\"Tebal\":\"71 mm\",\"Panjang kabel\":\"1,5 m\",\"Berat\":\"162 g\"},\"Kompatibilitas\":{\"Windows\":\"Windows\\u00ae 8 or later\",\"Mac\":\"macOS 10.7 or later\",\"ChromeOS\":\"Versi 29.0.1547.70 dan versi terbaru\",\"RAM\":\"Memerlukan RAM sekurang-kurangnya 2 GB untuk video streaming 1080p, biasanya memerlukan 1 GB untuk streaming 720p\"},\"Sertifikasi\":\"Disertifikasi untuk Google Meet, kompatibel dengan Microsoft Teams, BlueJeans, GoTo Meeting, Pexip, RingCentral, dan Zoom\",\"Daya\":{\"Konektivitas\":\"USB-A plug-and-play\"},\"Lingkungan\":{\"Teknologi\":\"RightLight\\u2122 2 untuk kejernihan dalam berbagai lingkungan pencahayaan\"}}', '<h4>Spesifikasi Utama</h4><p>C930e adalah webcam HD 1080p terbaik yang mampu menghadirkan video beresolusi tinggi di setiap lingkungan, termasuk dalam cahaya redup maupun kondisi yang sangat terang.</p>', '[{\"name\":\"Resolusi\",\"value\":\"1080p\\/30fps (hingga 1920 x 1080 piksel), 720p\\/30fps (maksimal 1280 x 720 piksel)\",\"additional\":\"\"},{\"name\":\"Kamera mega pixel\",\"value\":\"3\",\"additional\":\"\"},{\"name\":\"Jenis fokus\",\"value\":\"Autofocus\",\"additional\":\"\"},{\"name\":\"Jenis lensa\",\"value\":\"Kaca\",\"additional\":\"\"},{\"name\":\"Mikrofon internal\",\"value\":\"Stereo, dual omni-directional\",\"additional\":\"\"},{\"name\":\"Jangkauan mikrofon\",\"value\":\"Maksimal 1 m\",\"additional\":\"\"},{\"name\":\"Bidang pandang diagonal (dFoV)\",\"value\":\"90\\u00b0\",\"additional\":\"\"},{\"name\":\"Digital zoom\",\"value\":\"4x\",\"additional\":\"\"},{\"name\":\"Shutter privasi\",\"value\":\"Fleksibel\",\"additional\":\"\"},{\"name\":\"Universal clip\",\"value\":\"Kompatibel dengan tripod\",\"additional\":\"Tripod tidak disertakan\"}]', '<h4>Fitur Unggulan</h4><p>C930e menghadirkan pengalaman video-conferencing yang profesional dan andal dengan kualitas video HD 1080p/30 fps.</p>', 1, 0, 0, '2026-02-20 01:04:34', '2026-02-20 01:04:35'),
(78, 1, 1, 'Logitech Swytch', 'logitech-swytch', '<h4>Deskripsi Produk</h4><p>Logitech Swytch adalah solusi BYOD (Bring Your Own Device) yang memungkinkan pengguna menghubungkan laptop ke sistem konferensi ruang meeting dengan satu kabel USB tunggal. Swytch memberikan fleksibilitas tinggi tanpa perlu mengganti sistem ruang yang sudah ada.</p><h4>Fitur Utama</h4><ul><li><strong>Single-Cable BYOD:</strong> Satu kabel untuk kamera, mikrofon, dan display.</li><li><strong>Kompatibilitas Universal:</strong> Bekerja dengan hampir semua sistem konferensi Logitech.</li><li><strong>Instalasi Rapi:</strong> Hub terintegrasi untuk manajemen kabel.</li><li><strong>Mendukung USB-A & USB-C:</strong> Fleksibel untuk berbagai laptop.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Koneksi: USB-A & USB-C</li><li>Kompatibilitas: Rally, MeetUp, RoomMate</li><li>Tipe: BYOD Hub System</li></ul>', 'products/logitech-swytch/logitech-swytch-2026-1771574675.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000009', NULL, 'https://www.logitech.com/content/dam/logitech/vc/en/pdf/swytch-datasheet-web.pdf', '[\"video conferencing\",\"logitech swytch\",\"meeting room solutions\",\"USB-C connector\",\"plug-and-display\",\"remote management\",\"power delivery\"]', '{\"Dimensi\":{\"Panjang\":\"N\\/A\",\"Lebar\":\"N\\/A\",\"Tinggi\":\"N\\/A\"},\"Berat\":\"N\\/A\",\"Persyaratan Sistem\":\"USB 3.0 or higher Type A or Type C port\",\"Kompatibilitas\":{\"Windows\":\"Windows 10 or later\",\"Mac\":\"macOS 10.14 or later\",\"Chromebook\":\"Supported\"},\"Sertifikasi\":\"N\\/A\",\"Daya\":{\"Daya Output\":\"60 watts\",\"Tipe Koneksi\":\"USB-C\"},\"Lingkungan\":{\"Suhu Operasional\":\"N\\/A\",\"Kelembapan\":\"N\\/A\"}}', '<h4>Logitech Swytch</h4><p>Connect a laptop to a room system’s AV equipment for use with any video meeting or webinar.</p>', '[{\"name\":\"Power Delivery\",\"value\":\"60 watts of power to laptops that charge via USB-C.\",\"additional\":\"\"},{\"name\":\"Plug-and-Display\",\"value\":\"Single connection for both USB devices and HDMI display.\",\"additional\":\"Utilizes DisplayLink technology.\"},{\"name\":\"Full Motion Video + Audio\",\"value\":\"Play full-motion video and audio from a laptop on the room\\u2019s display and speakers.\",\"additional\":\"* Works with video conferencing services that support content sharing with audio.\"},{\"name\":\"Works with Most Laptops\",\"value\":\"Compatible with USB Type A and Type C connectors.\",\"additional\":\"Supports Chromebooks, Windows, and Mac laptops.\"},{\"name\":\"Remote Management\",\"value\":\"Monitor and manage Swytch and other meeting room devices.\",\"additional\":\"Compatible with Logitech Sync.\"},{\"name\":\"Deployment Resources\",\"value\":\"Includes wiring diagrams and quick reference cards.\",\"additional\":\"Simplifies installation and user introduction.\"}]', '<h4>Key Features</h4><p>Logitech Swytch offers a seamless connection for video conferencing, ensuring compatibility with various devices and systems.</p>', 1, 0, 0, '2026-02-20 01:04:35', '2026-02-20 01:04:35'),
(79, 1, 1, 'Logitech Tap IP', 'logitech-tap-ip', '<h4>Deskripsi Produk</h4><p>Logitech Tap IP adalah pengontrol sentuh berbasis jaringan (PoE) untuk ruang meeting modern. Dirancang untuk Microsoft Teams Rooms dan Zoom Rooms, Tap IP menghadirkan pengalaman one-touch join dengan instalasi yang rapi dan fleksibel.</p><h4>Fitur Utama</h4><ul><li><strong>Power over Ethernet (PoE):</strong> Satu kabel untuk daya dan jaringan.</li><li><strong>Layar 10.1”:</strong> Responsif dan anti sidik jari.</li><li><strong>One-Touch Join:</strong> Akses cepat ke meeting terjadwal.</li><li><strong>Desain Profesional:</strong> Manajemen kabel internal.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Layar: 10.1” IPS</li><li>Koneksi: Ethernet (PoE)</li><li>Platform: Teams Rooms & Zoom Rooms</li></ul>', 'products/logitech-tap-ip/logitech-tap-ip-2026-1771574675.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', NULL, NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/tap-ip.pdf', '[\"logitech tap\",\"video conferencing\",\"touch controller\",\"meeting room solutions\",\"power over ethernet\",\"google meet\",\"microsoft teams\",\"zoom rooms\"]', '{\"Dimensi\":{\"Tinggi\":\"10.1 inch\",\"Lebar\":\"1280x800 pixels\"},\"Berat\":\"N\\/A\",\"Persyaratan Sistem\":{\"Kompatibilitas\":[\"Google Meet di Android\",\"Microsoft Teams Rooms di Android\",\"Zoom Rooms Appliances\",\"Zoom Rooms untuk Mac\",\"Zoom Rooms untuk PC\"]},\"Kompatibilitas\":{\"Windows\":\"Microsoft Teams Rooms\",\"Mac\":\"Zoom Rooms\"},\"Sertifikasi\":\"N\\/A\",\"Daya\":\"Power over Ethernet\",\"Lingkungan\":\"N\\/A\"}', '<h4>Spesifikasi Utama</h4><p>Logitech Tap IP adalah touch controller untuk ruang meeting dengan konektivitas PoE, memungkinkan pengalaman meeting yang mulus.</p>', '[{\"name\":\"Layar Sentuh\",\"value\":\"Capacitive Touch dengan Oleophobic Coating\",\"additional\":\"10.1 inch\"},{\"name\":\"Konektivitas\",\"value\":\"Ethernet atau Wi-Fi\",\"additional\":\"Power over Ethernet\"},{\"name\":\"Warna\",\"value\":\"Graphite, White\",\"additional\":\"N\\/A\"},{\"name\":\"Sensor Gerakan\",\"value\":\"Ya\",\"additional\":\"N\\/A\"},{\"name\":\"Penyimpanan Kabel Internal\",\"value\":\"Ya\",\"additional\":\"N\\/A\"},{\"name\":\"Jack Headphone\",\"value\":\"Tidak\",\"additional\":\"N\\/A\"},{\"name\":\"Aksesori yang Kompatibel\",\"value\":\"Riser, Table, Wall Mount\",\"additional\":\"N\\/A\"}]', '<h4>Fitur Unggulan</h4><p>Dengan layar sentuh 10.1 inch dan konektivitas yang fleksibel, Tap IP memudahkan partisipasi dalam video meeting.</p>', 1, 0, 0, '2026-02-20 01:04:35', '2026-02-20 01:04:35'),
(80, 1, 1, 'Logitech Tap Scheduler', 'logitech-tap-scheduler', '<h4>Deskripsi Produk</h4><p>Logitech Tap Scheduler adalah panel penjadwalan ruangan yang dipasang di luar ruang meeting. Perangkat ini memungkinkan pengguna melihat ketersediaan ruangan dan memesan ruang secara langsung melalui layar sentuh intuitif.</p><h4>Fitur Utama</h4><ul><li><strong>LED Status Indicator:</strong> Lampu hijau/merah untuk status ruangan.</li><li><strong>Integrasi Kalender:</strong> Microsoft 365 & Google Workspace.</li><li><strong>Instalasi PoE:</strong> Satu kabel untuk daya dan data.</li><li><strong>Desain Minimalis:</strong> Cocok untuk kantor modern.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Layar: 10.1” Touchscreen</li><li>Koneksi: Ethernet (PoE)</li><li>Platform: Teams, Zoom, Robin, Appspace</li></ul>', 'products/logitech-tap-scheduler/logitech-tap-scheduler-2026-1771574675.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '952-000091', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/tap-scheduler-datasheet.pdf', '[\"logitech tap scheduler\",\"scheduling panel\",\"meeting room solutions\",\"video conferencing\",\"room booking\",\"collaboration tools\",\"touch controller\"]', '{\"Dimensi\":{\"Tinggi\":\"165 mm\",\"Lebar\":\"246,2 mm\",\"Tebal\":\"28,5 mm\",\"Berat\":\"0,7 kg\"},\"Kompatibilitas\":{\"Logitech Tap Scheduler\":\"terintegrasi dengan room scheduling solutions terkemuka\",\"Microsoft Teams\":\"Panel\",\"Zoom Rooms\":\"Scheduling Display\",\"Robin\":\"Powered scheduling panel\",\"Appspace\":\"\",\"RICOH\":\"Spaces\",\"Envoy\":\"Ruang\",\"Korbyt\":\"Pemesanan\",\"Comeen\":\"\"},\"Sertifikasi\":{\"Platform\":\"Logitech CollabOS\",\"Manajemen\":\"Jarak Jauh Logitech Sync\"},\"Daya\":{\"Power over Ethernet\":\"PoE, IEEE 802.3af Type 1, Perangkat Class 3\",\"Kebutuhan\":\"jaringan berkemampuan PoE atau PoE Injector dan kabel ethernet (Tidak disertakan)\"},\"Lingkungan\":{\"Suhu pengoperasian\":\"0 hingga 40\\u00b0C\",\"Suhu Penyimpanan\":\"-40 hingga 70\\u00b0C\",\"Kelembapan\":\"10-95%\"},\"Keamanan\":{\"Full Disk Encryption\":\"Port USB yang kosong\",\"Enkripsi Data\":\"Tombol Simetris, PKI\",\"Identitas Perangkat\":\"Dilindungi oleh atestasi perangkat\",\"Perlindungan Tombol\":\"Arm TrustZone\"},\"Keberlanjutan\":{\"Plastik Graphite\":\"54% bahan Post Consumer Recycled (PCR)\"}}', '<h4>Spesifikasi Utama</h4><p>Logitech Tap Scheduler dirancang untuk memudahkan pemesanan ruang meeting dengan layar sentuh yang responsif dan integrasi dengan berbagai platform.</p>', '[{\"name\":\"Layar\",\"value\":\"Diagonal 10.1\\u201d\",\"additional\":\"IPS (In-Plane Switching), Panel LCD dengan Cahaya Latar LED\"},{\"name\":\"Resolusi\",\"value\":\"1280 x 800\",\"additional\":\"Kecerahan 400 nit, Kontras 1000:1\"},{\"name\":\"Touch\",\"value\":\"Capacitive, 10 points multi-touch\",\"additional\":\"Anti Fingerprint: Oleophobic coating\"},{\"name\":\"Sudut menonton\",\"value\":\"85 derajat (U\\/D\\/L\\/R)\",\"additional\":\"Sudut posisi: 0 derajat (datar di permukaan pemasangan)\"},{\"name\":\"Accelerometer\",\"value\":\"terintegrasi\",\"additional\":\"\"},{\"name\":\"Sensor cahaya\",\"value\":\"lingkungan sekitar terintegrasi\",\"additional\":\"\"},{\"name\":\"Lubang keluar kabel\",\"value\":\"horizontal \\/ vertikal \\/ tengah\",\"additional\":\"\"}]', '<h4>Fitur Unggulan</h4><p>Dengan desain yang ramping dan fungsional, Tap Scheduler menawarkan kemudahan dalam mengelola jadwal meeting dan ketersediaan ruang.</p>', 1, 0, 0, '2026-02-20 01:04:35', '2026-02-20 01:04:35'),
(81, 1, 1, 'Logitech Tap Meeting Room Touch Controller', 'logitech-tap-meeting-room-touch-controller', '<h4>Deskripsi Produk</h4><p>Logitech Tap adalah pengontrol sentuh untuk ruang meeting berbasis PC. Dengan koneksi USB langsung ke komputer ruang, Tap menyediakan kontrol meeting yang intuitif dengan fitur one-touch join dan berbagi konten HDMI.</p><h4>Fitur Utama</h4><ul><li><strong>One-Touch Join:</strong> Mulai meeting dengan satu sentuhan.</li><li><strong>HDMI Ingest:</strong> Berbagi konten dari laptop secara instan.</li><li><strong>Layar 10.1”:</strong> Resolusi tinggi dan responsif.</li><li><strong>Mounting Fleksibel:</strong> Table, Riser, dan Wall mount.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Layar: 10.1”</li><li>Koneksi: USB ke PC + HDMI ingest</li><li>Platform: Teams Rooms & Zoom Rooms (PC-based)</li></ul>', 'products/logitech-tap-meeting-room-touch-controller/logitech-tap-meeting-room-touch-controller-2026-1771574676.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', NULL, NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/tap.pdf', '[\"logitech tap\",\"meeting room controller\",\"video conferencing\",\"touch controller\",\"USB connectivity\",\"Cat5e kit\",\"collaboration tools\"]', '{\"Dimensi\":{\"Tinggi\":\"10.1 inch\",\"Lebar\":\"1280x800 pixels\"},\"Berat\":\"N\\/A\",\"Persyaratan Sistem\":{\"Kompatibilitas\":{\"Google Meet\":\"ChromeOS, Android\",\"Microsoft Teams Rooms\":\"Windows\",\"Zoom Rooms\":\"Appliances, PC\"}},\"Sertifikasi\":\"N\\/A\",\"Daya\":{\"Catu Daya\":\"Inline via Cat5e\"},\"Lingkungan\":\"N\\/A\"}', '<h4>Spesifikasi Utama</h4><p>Logitech Tap menghadirkan pengalaman one-touch-join yang konsisten di berbagai macam ukuran dan bentuk ruangan.</p>', '[{\"name\":\"Layar Sentuh\",\"value\":\"Capacitive Touch dengan Oleophobic Coating\",\"additional\":\"Diagonal 10.1\\u201d\"},{\"name\":\"Konektivitas\",\"value\":\"HDMI Ingest\",\"additional\":\"Kit ethernet Cat5e (2,97 m dan 7,0 m kabel Cat5e)\"},{\"name\":\"Warna\",\"value\":\"Graphite\",\"additional\":\"N\\/A\"},{\"name\":\"Sensor Gerakan\",\"value\":\"N\\/A\",\"additional\":\"N\\/A\"},{\"name\":\"Penyimpanan Kabel\",\"value\":\"Internal dan strain relief\",\"additional\":\"N\\/A\"}]', '<h4>Fitur Unggulan</h4><p>Pengontrol sentuh yang terhubung ke USB dengan Cat5e Kit untuk pemasangan kabel yang fleksibel.</p>', 1, 0, 0, '2026-02-20 01:04:35', '2026-02-20 01:04:36'),
(82, 1, 1, 'Logitech Rally AI Camera Pro', 'logitech-rally-ai-camera-pro', '<h4>Deskripsi Produk</h4><p>Logitech Rally Camera Pro adalah kamera konferensi PTZ premium dengan kualitas video 4K dan kontrol presisi tinggi. Dirancang untuk ruang meeting profesional, kamera ini menghadirkan optik superior dan teknologi otomatisasi pintar untuk pengalaman video conference terbaik.</p><h4>Fitur Utama</h4><ul><li><strong>Video 4K Ultra HD:</strong> Gambar tajam dan detail.</li><li><strong>PTZ Presisi:</strong> Gerakan pan, tilt, dan zoom halus.</li><li><strong>RightSight™:</strong> Auto-framing berbasis AI.</li><li><strong>Desain Profesional:</strong> Cocok untuk ruang konferensi besar.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Resolusi: 4K</li><li>Zoom: 15x HD zoom</li><li>Koneksi: USB</li><li>Field of View: Wide-angle adjustable</li></ul>', 'products/logitech-rally-ai-camera-pro/logitech-rally-ai-camera-pro-2026-1771574677.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001758', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/rally-ai-camera-pro-datasheet.pdf', '[\"webcam 4k\",\"logitech rally\",\"video conference\",\"AI camera\",\"streaming camera\",\"business webcam\",\"video conferencing\"]', '{\"Dimensi\":{\"Tinggi\":\"231 mm\",\"Lebar\":\"224 mm\",\"Tebal\":\"146 mm\"},\"Berat\":\"2.5 kg\",\"Persyaratan Sistem\":{\"Sertifikasi\":\"Kunjungi https:\\/\\/hub.sync.logitech.com\\/collabosguides\\/post\\/video-conferencing-platform-certifications-and-compatibility-Fa5oyWsqo5Dpx8B\",\"Resolusi lebih tinggi dari 1080p\":\"4K pada 30 fps\"},\"Keberlanjutan\":{\"Kemasan yang Ramah Lingkungan\":\"Terobosan baru yang kreatif. Kami mengutamakan penggunaan lebih sedikit plastik dalam kemasan kami, dan lebih banyak kertas yang bersumber dari hutan bersertifikasi FSC\\u2122 dan sumber daya terkendali lainnya.\"},\"Video\":{\"Resolusi\":\"4K, 1440p, 1080p, 900p, 720p, and SD at 30 fps\",\"Zoom\":\"15x (5x optik \\/ 3x digital)\",\"Pan (Geser)\":\"\\u00b190\\u00b0\",\"Tilt (Miring)\":\"+50\\u00b0 \\/ \\u201390\\u00b0\",\"Bidang Pandang Diagonal\":\"90\\u00b0\",\"Bidang Pandang Horizontal\":\"82\\u00b0\",\"Bidang Pandang Vertikal\":\"52\\u00b0\"},\"Audio\":{\"Sampling Rate\":\"48 kHz\",\"Respons Frekuensi Mikrofon\":\"90 Hz \\u2013 16 kHz\",\"Sensitivitas Mikrofon\":\"48 kHz\",\"Unsur Beamforming\":\"8 MEMS digital semua arah\",\"Pemrosesan audio\":\"USB: Beamforming + Arah Kedatangan (digunakan untuk pengaturan kamera)\"},\"Port & Antarmuka\":{\"USB\":\"3.2 Gen 1\",\"WiFi\":\"802.11 a\\/b\\/g\\/n\\/ac\\/ax\",\"Bluetooth Low Energy\":\"5,3%\"},\"Listrik & Lingkungan\":{\"Catu daya\":\"POE++\",\"Voltase operasi \\/ daya\":\"100\\u2013240V\",\"Dimensi catu daya\":\"140mm \\u00d7 35mm \\u00d7 53mm\",\"Kabel AC\":\"1 m\",\"USB-C ke USB-C\":\"2 m USB 3.2 Gen 1\",\"Kabel CAT\":\"3 m CAT6a\",\"Suhu pengoperasian\":\"0 hingga 35\\u00b0C\",\"Suhu Penyimpanan\":\"\\u201340 hingga 70\\u00b0C\",\"Kelembapan\":\"10 hingga 95%\"}}', '<h4>Spesifikasi Utama</h4><p>Rally AI Camera Pro mengubah pertemuan video di ruang besar dan kompleks dengan sistem lensa ganda canggih dan fitur cerdas yang maju.</p>', '[{\"name\":\"WiFi\",\"value\":\"802.11 a\\/b\\/g\\/n\\/ac\\/ax\",\"additional\":null},{\"name\":\"Manajemen Perangkat\",\"value\":\"Logitech Sync\",\"additional\":null},{\"name\":\"Resolusi Layar\",\"value\":\"4K, 1440p, 1080p, 900p, 720p, and SD at 30 fps\",\"additional\":null},{\"name\":\"Enkripsi Berbasis File\",\"value\":\"AES-128\",\"additional\":null},{\"name\":\"Enkripsi Data\",\"value\":\"Tombol Simetris, PKI\",\"additional\":null},{\"name\":\"Identitas Perangkat\",\"value\":\"Dilindungi oleh atestasi perangkat\",\"additional\":null},{\"name\":\"Akses Perangkat\",\"value\":\"Diautentikasi menggunakan API\",\"additional\":null},{\"name\":\"Perlindungan Tombol\",\"value\":\"Arm TrustZone, Penyimpanan Aman\",\"additional\":null},{\"name\":\"Ketebalan Lensa\",\"value\":\"113 mm\",\"additional\":null}]', '<h4>Fitur Unggulan</h4><p>Dengan teknologi RightSight 2, Rally AI Camera Pro secara intuitif memfokuskan setiap peserta atau pembawa acara yang aktif.</p>', 1, 0, 1, '2026-02-20 01:04:36', '2026-02-22 23:15:02'),
(83, 1, 1, 'Logitech Rally AI Camera', 'logitech-rally-ai-camera', '<h4>Deskripsi Produk</h4><p>Logitech Rally Camera adalah puncak dari teknologi video mandiri (standalone) untuk ruang rapat profesional. Berbeda dengan webcam biasa, kamera ini menggunakan sistem pencitraan Ultra-HD 4K dengan optik canggih dan desain industrial premium yang cocok untuk ruang direksi. Dilengkapi dengan teknologi RightSense™, kamera ini secara otomatis menggerakkan lensa (Pan/Tilt/Zoom) untuk membingkai peserta rapat dengan presisi, baik itu satu orang atau seluruh tim di meja panjang.</p><h4>Fitur Unggulan</h4><ul><li><strong>Optik Kelas Studio:</strong> Sistem lensa 4K dengan ketajaman luar biasa, rendering warna yang akurat, dan kompensasi cahaya (WDR) untuk wajah yang jelas bahkan dengan latar belakang jendela terang.</li><li><strong>Teknologi RightSight™:</strong> Kontrol kamera otomatis yang mendeteksi peserta manusia, bukan hanya wajah, untuk pembingkaian yang halus dan natural tanpa perlu remote control.</li><li><strong>Pemasangan Fleksibel:</strong> Mendukung pemasangan di atas meja, tripod standar, atau dipasang terbalik di langit-langit dengan koreksi orientasi gambar dan kontrol otomatis.</li><li><strong>Privasi Terjamin:</strong> Saat tidak digunakan, lensa akan menunduk ke bawah (park position) untuk menjamin privasi visual secara fisik.</li></ul><h4>Spesifikasi Teknis</h4><ul><li>Resolusi: 4K, 1440p, 1080p, 900p, 720p, dan SD pada 30fps; 1080p, 720p pada 30fps dan 60fps</li><li>Zoom: 15x HD Zoom (5x Optik + 3x Digital)</li><li>Gerakan: Pan ±90°, Tilt +50°/-90°</li><li>Field of View: Diagonal 90°, Horizontal 82°, Vertikal 52°</li><li>Konektivitas: USB Type-C Plug-and-Play</li></ul>', 'products/logitech-rally-ai-camera/logitech-rally-ai-camera-2026-1771574678.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', '960-001808', NULL, 'https://www.logitech.com/content/dam/logitech/en/video-collaboration/pdf/rally-camera.pdf', '[\"webcam 4k\",\"logitech rally\",\"video conference\",\"ai camera\",\"business webcam\",\"streaming camera\",\"conference camera\"]', '{\"Dimensi\":{\"Tinggi\":\"91 mm\",\"Lebar\":\"224 mm\",\"Tebal\":\"101 mm\"},\"Berat\":\"2 kg\",\"Persyaratan Sistem\":{\"Resolusi lebih tinggi dari 1080p\":\"4K pada 30 fps\"},\"Kompatibilitas\":{\"WiFi\":\"802.11 a\\/b\\/g\\/n\\/ac\\/ax\",\"Bluetooth\":\"5.3%\"},\"Sertifikasi\":{\"Enkripsi Berbasis File\":\"AES-128\",\"Enkripsi Data\":\"Tombol Simetris, PKI\",\"Identitas Perangkat\":\"Dilindungi oleh atestasi perangkat\",\"Akses Perangkat\":\"Diautentikasi menggunakan API\"},\"Daya\":{\"Catu daya\":\"POE +\",\"Voltase Operasi\\/Daya\":\"100\\u2013240V\",\"Dimensi Catu Daya\":\"60mm \\u00d7 35mm \\u00d7 90mm\",\"Kabel AC\":\"1 m\",\"USB-C ke USB-C\":\"2 m USB 3.2 Gen 1\",\"Kabel CAT\":\"3 m CAT6a\"},\"Lingkungan\":{\"Suhu pengoperasian\":\"0 hingga 35\\u00b0C\",\"Suhu Penyimpanan\":\"\\u201340 hingga 70\\u00b0C\",\"Kelembapan\":\"10 hingga 95%\"}}', '<h4>Spesifikasi Utama</h4><p>Rally AI Camera menawarkan resolusi tinggi dan fitur cerdas untuk pengalaman konferensi yang optimal.</p>', '[{\"name\":\"Resolusi Layar\",\"value\":\"4K, 1440p, 1080p, 900p, 720p, and SD at 30 fps\",\"additional\":null},{\"name\":\"Zoom\",\"value\":\"Zoom digital 4X HD\",\"additional\":null},{\"name\":\"Bidang Pandang Diagonal\",\"value\":\"115.7\\u00b0\",\"additional\":null},{\"name\":\"Bidang Pandang Horizontal\",\"value\":\"103.3\\u00b0\",\"additional\":null},{\"name\":\"Bidang Pandang Vertikal\",\"value\":\"60.7\\u00b0\",\"additional\":null},{\"name\":\"Sampling Rate\",\"value\":\"48 kHz\",\"additional\":null},{\"name\":\"Respons Frekuensi Mikrofon\",\"value\":\"90 Hz \\u2013 16 kHz\",\"additional\":null},{\"name\":\"Sensitivitas Mikrofon\",\"value\":\"\\u201336 dBFS \\u00b11 dB @ 1 Pa\",\"additional\":null},{\"name\":\"Unsur Beamforming\",\"value\":\"8 MEMS digital semua arah\",\"additional\":null},{\"name\":\"Pemrosesan audio\",\"value\":\"USB: Beamforming + Arah Kedatangan (digunakan untuk pengaturan kamera)\",\"additional\":null}]', '<h4>Fitur Unggulan</h4><p>Dengan teknologi AI, Rally AI Camera secara otomatis membingkai peserta untuk interaksi yang lebih baik.</p>', 1, 0, 1, '2026-02-20 01:04:37', '2026-02-22 23:14:53'),
(84, 3, 2, 'Custom AI Companion', 'zoom-addon-custom-ai-companion', '<h4>Deskripsi Produk</h4><p>Custom AI Companion adalah solusi kecerdasan buatan tingkat lanjut yang dirancang secara eksklusif untuk memaksimalkan potensi platform Zoom Workplace Anda. Di era kerja hibrida yang serba cepat, add-on ini hadir untuk mengotomatiskan tugas-tugas administratif yang menyita waktu, memungkinkan tim Anda untuk berfokus pada pekerjaan yang benar-benar strategis. Dengan mengintegrasikan agen AI yang dapat disesuaikan, Anda dapat menciptakan asisten virtual yang memahami konteks dan kebutuhan spesifik bisnis Anda.</p><h4>Fungsionalitas dan Fitur Cerdas</h4><p>Lebih dari sekadar pencatat notulensi, fitur ini memberdayakan seluruh alur kerja Anda. Buat ringkasan rapat yang sangat spesifik dan akurat, hasilkan wawasan bisnis komprehensif dengan dukungan hingga 10 kueri riset mendalam setiap bulannya, dan bangun basis pengetahuan internal langsung dari data riwayat rapat Anda. Anda bahkan dapat mengembangkan agen khusus yang dilatih dengan pedoman perusahaan Anda sendiri.</p><h4>Transformasi Produktivitas</h4><p>Ini adalah alat definitif untuk mengubah setiap percakapan menjadi tindakan yang terukur. Dengan Custom AI Companion, tidak ada lagi detail penting yang terlewat; seluruh diskusi secara otomatis diolah menjadi <em>action items</em> yang siap ditindaklanjuti oleh tim, memastikan efisiensi maksimal di setiap lini operasional.</p>', 'products/zoom-addon-custom-ai-companion/zoom-addon-custom-ai-companion-2026-1771947963.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', 'Add-On', NULL, NULL, '[\"zoom add-on\",\"custom ai companion\",\"zoom meeting\",\"video conferencing\",\"zoom ai companion\"]', '{\"Persyaratan Sistem\":{\"Kompatibilitas\":\"Zoom Workplace Required\"},\"Fitur Tambahan\":{\"Integrasi Agen\":\"Mendukung agen pihak ketiga (Segera hadir)\",\"Penelitian\":\"Mendukung 10 kueri riset per bulan\"},\"Lisensi\":{\"Biaya Tambahan\":\"Contact Sales\"}}', '<h4>Spesifikasi Utama</h4><p>Tailor AI agents and skills to address your unique needs.</p>', '[{\"name\":\"Meeting Summaries\",\"value\":\"Create custom meeting summaries\",\"additional\":\"Included in add-on\"},{\"name\":\"Research Queries\",\"value\":\"Generate comprehensive insights with access to 10 deep research queries each month\",\"additional\":\"Included in add-on\"},{\"name\":\"Actionable Outcomes\",\"value\":\"Turn conversations into outcomes\",\"additional\":\"Included in add-on\"},{\"name\":\"Knowledge Collections\",\"value\":\"Build knowledge collections with your data\",\"additional\":\"Included in add-on\"},{\"name\":\"Custom Agents\",\"value\":\"Develop custom agents\",\"additional\":\"Included in add-on\"},{\"name\":\"Meeting Summaries\",\"value\":\"Create your own custom meeting summary templates so your attendees get the information they need\",\"additional\":\"Included in add-on\"},{\"name\":\"Third-Party Integration\",\"value\":\"Add third-party AI agents to Zoom (Coming soon)\",\"additional\":\"Included in add-on\"},{\"name\":\"Avatars\",\"value\":\"Use 6 minutes of custom avatars for Zoom Clips monthly\",\"additional\":\"Included in add-on\"}]', '<h4>Fitur Unggulan</h4><p>Create custom meeting summaries and generate comprehensive insights.</p>', 1, 0, 0, '2026-02-24 04:12:02', '2026-02-24 08:46:03'),
(85, 3, 2, 'Custom Avatars', 'zoom-addon-custom-avatars', '<h4>Deskripsi Produk</h4><p>Custom Avatars membawa presentasi virtual Anda ke level berikutnya dengan memungkinkan Anda membuat versi AI digital yang luar biasa realistis dari diri Anda sendiri. Add-on mutakhir ini menawarkan kemampuan replikasi suara dan komunikasi multibahasa yang secara khusus dirancang untuk menghemat waktu serta biaya produksi konten video Anda, sekaligus menjaga konsistensi identitas merek atau persona Anda.</p><h4>Kemudahan Produksi Konten</h4><p>Bebaskan diri Anda dari kelelahan tampil di depan kamera (<em>video fatigue</em>). Anda dapat merancang hingga 3 avatar digital per bulan yang mereplikasi penampilan visual dan nuansa vokal Anda secara presisi. Gunakan avatar tersebut untuk membacakan skrip presentasi atau demonstrasi berdurasi hingga 3 menit secara otomatis melalui AI Companion.</p><h4>Fleksibilitas Tanpa Batas</h4><p>Jika Anda membutuhkan solusi instan, add-on ini juga menyediakan pilihan 18 avatar pra-desain untuk pembuatan video berkualitas tinggi yang super cepat. Semuanya terintegrasi sempurna dengan dukungan latar belakang virtual, memberikan Anda kontrol penuh atas narasi visual di setiap sesi Zoom Anda.</p>', 'products/zoom-addon-custom-avatars/zoom-addon-custom-avatars-2026-1771947963.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', 'Add-On', NULL, NULL, '[\"zoom add-on\",\"custom avatars\",\"zoom meeting\",\"video conferencing\",\"zoom ai companion\"]', '{\"Persyaratan Sistem\":{\"Kompatibilitas\":\"Zoom Workplace Required\"},\"Kapasitas Penggunaan\":{\"Durasi Maksimal\":\"3 Menit skrip via AI Companion\",\"Batas Overage\":\"Biaya tambahan per menit jika melewati batas (Rp24,000.00)\"},\"Visual & Audio\":{\"Kloning Suara\":\"Didukung\",\"Latar Virtual\":\"Didukung\"}}', '<h4>Spesifikasi Utama</h4><p>Create a lifelike AI version of yourself with voice replication.</p>', '[{\"name\":\"Avatars\",\"value\":\"Create up to 3 lifelike digital avatars each month that replicate your appearance and voice for presentations and demos\",\"additional\":\"Included in add-on\"},{\"name\":\"Script Delivery\",\"value\":\"Use your avatar to deliver scripts up to 3 minutes long with AI Companion\",\"additional\":\"Included in add-on\"},{\"name\":\"Pre-Designed Avatars\",\"value\":\"Choose from 18 pre-designed avatars for quick, high-quality video creation\",\"additional\":\"Included in add-on\"},{\"name\":\"Virtual Background\",\"value\":\"Enjoy virtual background support\",\"additional\":\"Included in add-on\"},{\"name\":\"Overage Fee\",\"value\":\"*Overage fee of Rp24,000.00 per minute are charged when Clips minutes generated by Custom Avatar are exceeded\",\"additional\":\"Included in add-on\"}]', '<h4>Fitur Unggulan</h4><p>Replicate your appearance and voice for presentations and demos.</p>', 1, 0, 0, '2026-02-24 04:12:03', '2026-02-24 08:46:03');
INSERT INTO `products` (`id`, `service_id`, `brand_id`, `name`, `slug`, `description`, `image_path`, `thumbnail_path`, `price`, `link_accommerce`, `whatsapp_note`, `sku`, `solution_type`, `datasheet_url`, `tags`, `specs`, `specification_text`, `features`, `features_text`, `is_active`, `is_featured`, `is_new`, `created_at`, `updated_at`) VALUES
(86, 3, 2, 'Large Meeting', 'zoom-500-participants-meeting-annual', '<h4>Deskripsi Produk</h4><p>Add-on Large Meeting adalah solusi ideal bagi organisasi berskala menengah hingga enterprise yang kerap menyelenggarakan acara besar seperti *Town Hall*, sosialisasi perusahaan, atau kuliah umum. Layanan ini mendobrak batasan ruang pertemuan virtual reguler di Zoom Workplace Anda dengan meningkatkan kapasitas peserta interaktif secara masif, tanpa mengurangi kualitas maupun stabilitas jaringan.</p><h4>Kolaborasi Skala Masif</h4><p>Dengan mengaktifkan add-on ini, Anda dapat memperluas kapasitas ruang virtual untuk menampung minimal 500 peserta hingga batas maksimum 5.000 peserta interaktif secara bersamaan. Ini bukan sekadar siaran satu arah; setiap peserta tetap mempertahankan kemampuan kolaboratif penuh untuk menghidupkan audio, menyalakan video, serta membagikan layar presentasi mereka.</p><h4>Keandalan dan Inklusivitas</h4><p>Memastikan setiap suara di perusahaan Anda terdengar. Large Meeting memberikan pengalaman pertemuan akbar yang tetap terasa intim dan inklusif, memastikan bahwa penyampaian informasi penting oleh jajaran eksekutif dapat langsung ditanggapi secara dinamis oleh seluruh lapisan tim.</p>', 'products/zoom-addon-large-meeting/zoom-addon-large-meeting-2026-1771947963.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', 'Add-On', NULL, NULL, '[\"zoom add-on\",\"large meeting\",\"zoom meeting\",\"video conferencing\",\"zoom premium\"]', '{\"Persyaratan Sistem\":{\"Kompatibilitas\":\"Zoom Workplace Required\"},\"Kapasitas Rapat\":{\"Peserta Tambahan\":\"Meningkatkan interaktif hingga 5,000 peserta\",\"Interaksi Peserta\":\"Semua dapat berbagi audio, video, dan layar\"}}', '<h4>Spesifikasi Utama</h4><p>Increase participant capacity up to 5,000 participants.</p>', '[{\"name\":\"Participant Capacity\",\"value\":\"Increase the meeting capacity to support up to 500 live interactive participants\",\"additional\":\"Included in add-on\"},{\"name\":\"Interactive Sharing\",\"value\":\"All participants can share their audio, video, and screen\",\"additional\":\"Included in add-on\"}]', '<h4>Fitur Unggulan</h4><p>Support up to 500 live interactive participants sharing audio and video.</p>', 1, 0, 0, '2026-02-24 04:12:03', '2026-02-24 15:38:21'),
(87, 3, 2, 'Cloud Storage', 'zoom-addon-cloud-storage', '<h4>Deskripsi Produk</h4><p>Zoom Cloud Storage memberikan kebebasan mutlak bagi tim Anda untuk menyimpan, melakukan streaming, dan mengelola unduhan rekaman video rapat langsung dari infrastruktur cloud Zoom yang sangat aman dan memiliki ketersediaan tinggi. Ini adalah jawaban bagi perusahaan yang membutuhkan repositori arsip rapat berkapasitas ekstra tanpa membebani server fisik lokal (on-premise).</p><h4>Manajemen File yang Fleksibel</h4><p>Sesuaikan ruang penyimpanan dengan ritme kerja Anda. Dengan opsi kuota tambahan yang membentang hingga 5TB setiap bulannya, Anda tak perlu lagi merasa khawatir kehilangan momen penting karena kehabisan ruang. Seluruh sesi rapat Anda secara otomatis diolah dan tersimpan dalam format standar industri (MP4 untuk video dan M4A untuk audio).</p><h4>Aksesibilitas Tinggi</h4><p>Sistem penyimpanan cloud ini memudahkan proses distribusi hasil rapat. Anda dapat langsung membagikan tautan rekaman dengan aman kepada rekan tim yang berhalangan hadir, yang kemudian dapat memutarnya di perangkat apa pun, kapan pun, dan di mana pun mereka berada.</p>', 'products/zoom-addon-cloud-storage/zoom-addon-cloud-storage-2026-1771947964.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', 'Add-On', NULL, NULL, '[\"zoom add-on\",\"cloud storage\",\"zoom meeting\",\"video conferencing\",\"zoom cloud storage\"]', '{\"Persyaratan Sistem\":{\"Kompatibilitas\":\"Zoom Workplace Required\"},\"Kapasitas Penyimpanan\":{\"Rentang Penyimpanan\":\"Tersedia hingga 5TB\\/Bulan\"},\"Dukungan Format File\":{\"Format Audio\":\"M4A\",\"Format Video\":\"MP4\"}}', '<h4>Spesifikasi Utama</h4><p>Store, stream, and download your video recordings directly from the Zoom Cloud.</p>', '[{\"name\":\"File Formats\",\"value\":\"MP4 or M4A file formats available\",\"additional\":\"Included in add-on\"},{\"name\":\"Storage Options\",\"value\":\"Storage options include up to 5TB\\/month\",\"additional\":\"Included in add-on\"},{\"name\":\"Plan Inclusion\",\"value\":\"Cloud storage is included in select Zoom Workplace plans: Pro (10 GB), Business (10 GB), Business Plus (15 GB), and Enterprise (Unlimited)\",\"additional\":\"Included in add-on\"}]', '<h4>Fitur Unggulan</h4><p>Storage options include up to 5TB/month with MP4 or M4A file formats.</p>', 1, 0, 0, '2026-02-24 04:12:03', '2026-02-24 08:46:04'),
(88, 3, 2, 'Translated Captions', 'zoom-addon-translated-captions', '<h4>Deskripsi Produk</h4><p>Translated Captions adalah kunci utama Anda untuk meruntuhkan batasan bahasa dalam dunia kolaborasi global masa kini. Add-on inovatif ini menyajikan pengalaman teks terjemahan otomatis (<em>closed captioning</em>) secara <em>real-time</em> ke dalam beragam pilihan bahasa, memastikan kelancaran komunikasi selama sesi Zoom Meetings maupun Zoom Webinars Anda berlangsung.</p><h4>Aksesibilitas dan Inklusivitas</h4><p>Tidak perlu lagi bergantung pada jasa penerjemah pihak ketiga. Setiap partisipan rapat diberikan otonomi penuh untuk mengaktifkan teks terjemahan di layar mereka masing-masing dan secara bebas beralih ke bahasa ibu yang paling mereka pahami tanpa mengganggu antarmuka peserta lain.</p><h4>Meningkatkan Sinergi Global</h4><p>Fitur yang sangat inklusif ini menjamin bahwa seluruh anggota tim internasional, klien lintas negara, atau mitra bisnis multinasional Anda dapat menangkap setiap nuansa dan konteks percakapan secara akurat. Keputusan diambil lebih cepat ketika semua orang berada di halaman pemahaman yang sama.</p>', 'products/zoom-addon-translated-captions/zoom-addon-translated-captions-2026-1771947964.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', 'Add-On', NULL, NULL, '[\"zoom add-on\",\"translated captions\",\"zoom meeting\",\"video conferencing\",\"zoom premium\"]', '{\"Persyaratan Sistem\":{\"Kompatibilitas\":\"Zoom Workplace Required\",\"Mendukung Layanan\":\"Zoom Meetings dan Webinars\"},\"Kemampuan Terjemahan\":{\"Pengaturan Sendiri\":\"Peserta dapat mengaktifkan caption sendiri dan berpindah bahasa\"}}', '<h4>Spesifikasi Utama</h4><p>Automated captions in your preferred language.</p>', '[{\"name\":\"Self-Service Captions\",\"value\":\"Participants can self-enable captions and switch languages\",\"additional\":\"Included in add-on\"},{\"name\":\"Supported Languages\",\"value\":\"View supported languages\",\"additional\":\"Included in add-on\"},{\"name\":\"Availability\",\"value\":\"Available in Zoom Meetings and Webinars\",\"additional\":\"Included in add-on\"}]', '<h4>Fitur Unggulan</h4><p>Participants can self-enable captions and switch languages during meetings.</p>', 1, 0, 0, '2026-02-24 04:12:03', '2026-02-24 08:46:04'),
(89, 3, 2, 'Audio Conferencing', 'zoom-addon-audio-conferencing', '<h4>Deskripsi Produk</h4><p>Zoom Audio Conferencing menghadirkan fleksibilitas tanpa tanding bagi partisipan rapat Anda untuk terhubung ke dalam panggilan melalui jaringan telepon tradisional (PSTN) atau telepon seluler. Add-on ini merupakan sabuk pengaman esensial untuk menjaga konektivitas rapat Anda tetap berjalan sempurna, bahkan ketika peserta sedang berada di area terpencil atau mengalami masalah koneksi internet <em>broadband</em> yang tidak stabil.</p><h4>Konektivitas Tingkat Premium</h4><p>Perluas opsi bergabung ke rapat secara dramatis. Layanan ini mencakup fitur <em>call-out</em> (menghubungi peserta secara langsung ke nomor telepon mereka), dukungan nomor bebas pulsa (<em>toll-free</em>) global, dan ketersediaan nomor panggilan lokal di berbagai negara premium. Ini membangun citra profesional yang solid bagi perusahaan Anda.</p><h4>Kenyamanan Tanpa Biaya</h4><p>Dengan mengelola nomor bebas pulsa, Anda memastikan bahwa kolega atau klien Anda dapat menelepon masuk ke ruang rapat Zoom Anda dari telepon kabel atau seluler mana pun tanpa dikenakan biaya pulsa sepeser pun. Semua kontrol wilayah akses bebas pulsa dapat diatur dengan mudah oleh administrator.</p>', 'products/zoom-addon-audio-conferencing/zoom-addon-audio-conferencing-2026-1771947965.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', 'Add-On', NULL, NULL, '[\"zoom add-on\",\"audio conferencing\",\"zoom meeting\",\"video conferencing\",\"audio conferencing\"]', '{\"Persyaratan Sistem\":{\"Kompatibilitas\":\"Zoom Workplace Required\"},\"Dukungan Panggilan\":{\"Jangkauan Telepon\":\"Panggilan keluar, bebas pulsa global, dan nomor lokal\",\"Bebas Biaya\":\"Gratis untuk peserta dari perangkat manapun\"}}', '<h4>Spesifikasi Utama</h4><p>Dial into meetings with phone numbers from around the world.</p>', '[{\"name\":\"Call Options\",\"value\":\"Expand your call options with call out, global toll-free, and local dial-in for premium countries\",\"additional\":\"Included in add-on\"},{\"name\":\"Participant Cost\",\"value\":\"No cost for participants to call in from any device\",\"additional\":\"Included in add-on\"},{\"name\":\"Toll-Free Selection\",\"value\":\"Easily select one or multiple countries for toll-free call-in\",\"additional\":\"Included in add-on\"}]', '<h4>Fitur Unggulan</h4><p>Expand your call options with global toll-free and local dial-in.</p>', 1, 0, 0, '2026-02-24 04:12:03', '2026-02-24 08:46:05'),
(90, 3, 2, 'Zoom Compliance Manager powered by Theta Lake', 'zoom-addon-zoom-compliance-manager-powered-by-theta-lake', '<h4>Deskripsi Produk</h4><p>Zoom Compliance Manager, yang ditenagai oleh mesin Theta Lake yang andal, adalah solusi terpadu tingkat enterprise untuk tata kelola keamanan informasi. Alat ini secara khusus direkayasa untuk membantu instansi keuangan, kesehatan, dan perusahaan korporat memastikan kepatuhan mutlak terhadap regulasi industri yang ketat, kebijakan Pencegahan Kehilangan Data (DLP), dan persyaratan Penahanan Hukum (<em>Legal Hold</em>).</p><h4>Arsip Keamanan dan E-Discovery</h4><p>Sederhanakan kerumitan proses pengarsipan. Sistem ini secara otomatis dan aman mengarsipkan seluruh jejak komunikasi mulai dari Zoom Meetings, Zoom Webinars, hingga obrolan harian di Zoom Team Chat. Berbekal alokasi penyimpanan awal 10 GB per lisensi yang siap di-<em>scale-up</em>.</p><h4>Pencarian Legal yang Sigap</h4><p>Didukung oleh fungsionalitas pencarian <em>eDiscovery</em> mutakhir yang terintegrasi sepenuhnya ke dalam Zoom Web Portal. Tim hukum (legal) dan departemen kepatuhan Anda dapat dengan kecepatan tinggi melacak, menemukan, mengaudit, dan mengamankan rekaman komunikasi sensitif guna memitigasi risiko bisnis harian.</p>', 'products/zoom-addon-zoom-compliance-manager-powered-by-theta-lake/zoom-addon-zoom-compliance-manager-powered-by-theta-lake-2026-1771947965.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', 'Add-On', NULL, NULL, '[\"zoom add-on\",\"zoom compliance manager powered by theta lake\",\"zoom meeting\",\"video conferencing\",\"zoom compliance\"]', '{\"Persyaratan Sistem\":{\"Kompatibilitas\":\"Zoom Workplace Required\"},\"Manajemen Data\":{\"Penyimpanan Terintegrasi\":\"10 GB per lisensi (dapat diperluas)\",\"Kemudahan E-Discovery\":\"Tersedia langsung pada Zoom Web Portal\"},\"Dukungan Pengarsipan\":{\"Ruang Lingkup\":\"Meetings, Webinars, dan Team Chat\"}}', '<h4>Spesifikasi Utama</h4><p>Meet compliance, DLP and legal hold requirements for your organization.</p>', '[{\"name\":\"Archiving\",\"value\":\"Streamline communication and collaboration archiving for Meetings, Webinars, Team Chat, and more\",\"additional\":\"Included in add-on\"},{\"name\":\"eDiscovery\",\"value\":\"Easily find important communication records with eDiscovery\'s search capabilities\",\"additional\":\"Included in add-on\"},{\"name\":\"Compliance Processes\",\"value\":\"Simplify archiving, eDiscovery and legal hold processes directly within the Zoom web portal\",\"additional\":\"Included in add-on\"},{\"name\":\"Included Storage\",\"value\":\"Access 10 GB of storage per license (with the option to buy more as needed)\",\"additional\":\"Included in add-on\"}]', '<h4>Fitur Unggulan</h4><p>Streamline archiving for Meetings, Webinars, and Team Chat with eDiscovery capabilities.</p>', 1, 0, 0, '2026-02-24 04:12:04', '2026-02-24 08:46:05'),
(91, 3, 2, 'Conference Room Connector', 'zoom-addon-conference-room-connector', '<h4>Deskripsi Produk</h4><p>Conference Room Connector (CRC) beroperasi sebagai gerbang penyambung (<em>gateway</em>) vital yang menjembatani sistem perangkat keras ruang konferensi tradisional yang Anda miliki saat ini dengan ekosistem konferensi cloud Zoom yang modern dan canggih. Add-on ini menjamin bahwa tidak ada investasi teknologi yang terbuang sia-sia.</p><h4>Proteksi Investasi Perangkat Keras</h4><p>Bawalah perangkat titik akhir (<em>endpoint</em>) video standar berbasis protokol SIP atau H.323 ke era modern. CRC menjamin interopabilitas yang mulus (<em>seamless</em>) dengan merek-merek kelas berat peninggalan masa lalu, termasuk sistem dari Polycom, Cisco, hingga Lifesize.</p><h4>Fleksibilitas Penerapan</h4><p>Bergabung ke pertemuan Zoom Workplace kini dapat dilakukan semudah memencet tombol pada remote perangkat ruang rapat lama Anda. Zoom memberikan kebebasan arsitektur kepada tim TI Anda untuk mengimplementasikan konektor ruang ini, baik melalui hosting <em>Cloud-based</em> maupun penempatan <em>On-premise</em> menggunakan infrastruktur mesin virtual (VM) di lokasi Anda.</p>', 'products/zoom-addon-conference-room-connector/zoom-addon-conference-room-connector-2026-1771947966.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', 'Add-On', NULL, NULL, '[\"zoom add-on\",\"conference room connector\",\"zoom meeting\",\"video conferencing\",\"room connector\"]', '{\"Persyaratan Sistem\":{\"Kompatibilitas\":\"Zoom Workplace Required\",\"Protokol Standar\":\"SIP\\/H.323\"},\"Infrastruktur\":{\"Mendukung Titik Akhir Lama\":\"Polycom, Cisco, Lifesize\",\"Opsi Penerapan\":\"Berbasis cloud atau on-premise (VM)\"}}', '<h4>Spesifikasi Utama</h4><p>Enables any standards based SIP/H.323 video conferencing endpoint.</p>', '[{\"name\":\"Legacy Compatibility\",\"value\":\"Works with many legacy endpoints including Polycom, Cisco, Lifesize and others\",\"additional\":\"Included in add-on\"},{\"name\":\"Deployment Options\",\"value\":\"Cloud-based or on-premise (VM) room connector\",\"additional\":\"Included in add-on\"}]', '<h4>Fitur Unggulan</h4><p>Works with legacy endpoints including Polycom, Cisco, and Lifesize.</p>', 1, 0, 0, '2026-02-24 04:12:04', '2026-02-24 08:46:06'),
(92, 3, 2, 'Zoom Developer Pack', 'zoom-addon-zoom-developer-pack', '<h4>Deskripsi Produk</h4><p>Zoom Developer Pack adalah paket peralatan (<em>toolkit</em>) tingkat enterprise yang didedikasikan secara khusus bagi para insinyur perangkat lunak dan tim arsitek TI yang bermisi membangun integrasi kustom berskala besar. Paket ini menyodorkan kunci utama (<em>master key</em>) yang membuka seluruh kapabilitas tersembunyi dari ekosistem layanan Zoom.</p><h4>Akses Data dan Media Transparan</h4><p>Dapatkan saluran komunikasi VIP melalui serangkaian Application Programming Interface (API) canggih. Anda berhak mendapatkan aliran informasi terkait data Quality of Service (QoS) serta Realtime Media Streams (RTMS). Ini adalah fondasi krusial yang menyajikan visibilitas transparan terhadap performa jaringan di belakang layar.</p><h4>Pemberdayaan Workflow AI/ML</h4><p>Lebih jauh lagi, akses langsung ke aliran media mentah (<em>raw media streams</em>) ini memungkinkan korporasi Anda untuk memproses data suara dan video tersebut ke dalam alur kerja (<em>pipelines</em>) Artificial Intelligence atau Machine Learning mandiri. Manfaatkan kredit API yang fleksibel untuk memicu inovasi tanpa batas di perusahaan Anda.</p>', 'products/zoom-addon-zoom-developer-pack/zoom-addon-zoom-developer-pack-2026-1771947966.webp', NULL, NULL, NULL, 'Halo, saya tertarik dengan produk {Product Name}. Mohon info harga terbaik.', 'Add-On', NULL, NULL, '[\"zoom add-on\",\"zoom developer pack\",\"zoom meeting\",\"video conferencing\",\"zoom premium\"]', '{\"Persyaratan Sistem\":{\"Kompatibilitas\":\"Diperuntukkan Integrasi API Eksternal\"},\"Akses Data\":{\"Realtime Media\":\"Akses Realtime Media Streams (RTMS)\",\"Kualitas Layanan\":\"Transparansi performa jaringan dan workflow AI\\/ML\"},\"Fleksibilitas\":{\"Penggunaan Kredit\":\"Kredit fleksibel lintas layanan\"}}', '<h4>Spesifikasi Utama</h4><p>Unlock the full potential of our APIs with versatile access to Zoom\'s core service data.</p>', '[{\"name\":\"Credit Flexibility\",\"value\":\"Flexibility to use credits across different services as needed and benefit from volume discounts\",\"additional\":\"Included in add-on\"},{\"name\":\"API Access\",\"value\":\"Access Quality of Service (QoS) data and Realtime Media Streams (RTMS) through our APIs to gain full network performance transparency and power your AI\\/ML workflows\",\"additional\":\"Included in add-on\"},{\"name\":\"Enterprise Integration\",\"value\":\"Ideal for enterprises seeking advanced API integration capabilities\",\"additional\":\"Included in add-on\"}]', '<h4>Fitur Unggulan</h4><p>Access Quality of Service (QoS) data and Realtime Media Streams (RTMS) through APIs.</p>', 1, 0, 0, '2026-02-24 04:12:04', '2026-02-24 08:46:07');
