INSERT INTO `projects` (`id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `published_at`, `created_at`, `updated_at`, `is_featured`, `client`, `category`, `project_date`, `address`, `download_brochures`, `whatsapp_note`, `tags`) VALUES
(2, 1, 'Pengadaan Sistem Audio Video Conference PT Kalbe Blackmores Nutrition Jakarta', 'pengadaan-sistem-audio-video-conference-pt-kalbe-blackmores-nutrition-jakarta', 'Instalasi sistem audio video conference PT Kalbe Blackmores Nutrition, Jakarta menggunakan Logitech Rally Camera dan Shure MXA920 ceiling microphone untuk meeting hybrid profesional.', '<p><strong>Pengadaan Sistem Audio Video Conference PT Kalbe Blackmores Nutrition Jakarta</strong></p><p>ACTiV dipercaya untuk melakukan pengadaan, instalasi, dan konfigurasi sistem <strong>Audio &amp; Video Conference</strong> di PT Kalbe Blackmores Nutrition, Jakarta . Project ini dirancang untuk mendukung kebutuhan meeting hybrid dengan kualitas audio jernih, video 4K tajam, serta integrasi sistem yang stabil dan profesional.</p><p>Sistem dirancang menggunakan konsep instalasi ceiling agar tampilan ruangan tetap rapi, modern, dan minim perangkat di meja meeting.</p><h3>Kebutuhan &amp; Tantangan</h3><p>PT Kalbe Blackmores Nutrition Jakarta membutuhkan:</p><ul><li><p>Sistem video conference profesional untuk ruang meeting</p></li><li><p>Distribusi suara merata tanpa mikrofon meja</p></li><li><p>Integrasi dengan platform meeting online</p></li><li><p>Instalasi yang estetis dan minim kabel terlihat</p></li></ul><h3>Solusi yang Diberikan</h3><p><img src=\"https://staging.activ.co.id/storage/projects/pengadaan-sistem-audio-video-conference-pt-kalbe-blackmores-nutrition-jakarta/media-contents/kXAMr90p0EjVdoTbcWJ7ZNalveBcBAWx2LvQXPW4.webp\" alt=\"Logitech Rally Camera Ceiling - ACTiV\" data-id=\"projects/pengadaan-sistem-audio-video-conference-pt-kalbe-blackmores-nutrition-jakarta/media-contents/kXAMr90p0EjVdoTbcWJ7ZNalveBcBAWx2LvQXPW4.webp\"></p><p>ACTiV menghadirkan solusi terintegrasi menggunakan:</p><h4>🎥 Video Conference System</h4><ul><li><p>Logitech Rally Camera</p></li><li><p>Logitech Strong USB Cable 25m</p></li></ul><p>Logitech Rally Camera menghadirkan kualitas video 4K dengan fitur PTZ (Pan-Tilt-Zoom) presisi untuk menangkap seluruh peserta meeting secara optimal.</p><h4>🎤 Professional Audio System</h4><ul><li><p>Shure MXA920W-S-60CM Ceiling Array Microphone</p></li><li><p>Shure ANIUSB-MATRIX</p></li><li><p>Martin Audio C6.8T (Multiple Units)</p></li><li><p>Martin Audio C6.8</p></li><li><p>QSC GX3 Power Amplifier</p></li></ul><p>Shure MXA920 menggunakan teknologi beamforming untuk menangkap suara secara otomatis dan merata di seluruh ruangan tanpa perlu mikrofon tambahan di meja.</p><p>Speaker Martin Audio memastikan distribusi suara yang jelas dan seimbang, didukung amplifier QSC GX3 untuk performa stabil.</p><h4>🌐 Network &amp; Infrastructure</h4><ul><li><p>NetgearAV GSM4210PD-100UKS PoE Switch</p></li></ul><p>Switch PoE ini mendukung instalasi perangkat audio jaringan secara efisien dan stabil.</p><h3>Scope of Work</h3><ul><li><p>Survey &amp; perencanaan sistem AV</p></li><li><p>Instalasi ceiling microphone &amp; speaker</p></li><li><p>Instalasi kamera video conference</p></li><li><p>Manajemen kabel &amp; integrasi jaringan</p></li><li><p>Konfigurasi perangkat</p></li><li><p>Testing &amp; commissioning</p></li><li><p>Training user</p></li></ul><hr><h3>Hasil Implementasi</h3><p>✔ Audio jernih tanpa noise<br>✔ Video conference 4K profesional<br>✔ Distribusi suara merata<br>✔ Instalasi rapi dan modern<br>✔ Mendukung meeting hybrid &amp; kolaborasi jarak jauh</p><p>Project ini menunjukkan komitmen ACTiV sebagai penyedia solusi Audio Video Conference profesional di Jakarta.</p>', 'projects/pengadaan-sistem-audio-video-conference-pt-kalbe-blackmores-nutrition-jakarta/projects-pengadaan-sistem-audio-video-conference-pt-kalbe-blackmores-nutrition-jakarta-pt-kalbe-blackmores-nutrition-jakarta-activ-teknologi-2026-3744.webp', 'published', '2026-02-14 05:23:07', '2026-02-10 02:41:02', '2026-02-22 22:43:11', 1, 'PT Kalbe Blackmores Nutrition Jakarta', 'Enterprise', '2026-02-14', 'Altira Business Park, Jl. Yos Sudarso Kav 85 Sunter Blok G No.1-2, RT.10/RW.11, Sunter Jaya, Kec. Tj. Priok, Jkt Utara, Daerah Khusus Ibukota Jakarta 14350', '[]', 'Hi, saya tertarik dengan solusi Audio Video Conference seperti di PT Kalbe Blackmores Nutrition Jakarta. Bisa konsultasi untuk kebutuhan ruang meeting saya?', '[\"audio video conference\",\"instalasi video conference jakarta\",\"logitech rally camera\",\"shure mxa920 ceiling microphone\",\"meeting room system\",\"av integrator jakarta\",\"audio visual system jakarta\",\"project audio visual\"]');
