INSERT INTO `services` (`id`, `name`, `slug`, `description`, `thumbnail`, `icon`, `hero_subtitle`, `grid_title`, `content`, `excerpt`, `featured_image`, `created_at`, `updated_at`, `sort_order`) VALUES
(1, 'Audio & Video Konferensi', 'audio-video-konferensi', 'Solusi Audio & Video Konferensi profesional untuk ruang meeting, ruang kelas, auditorium, hingga hybrid workspace dengan kualitas suara jernih dan visual tajam.', 'services/audio-video-konferensi/thumbnails/audio-video-konferensi-thumbnails-thumbnail-vicon-activ-teknologi-2026-4426.webp', 'services/audio-video-konferensi/icons/audio-video-konferensi-icons-audio-video-konferensi-activ-teknologi-2026-4426.webp', 'Solusi Meeting Modern dengan Kualitas Audio Visual Profesional', 'AV Conference Solution', '<p>Solusi Audio &amp; Video Konferensi menghadirkan pengalaman komunikasi yang jernih, stabil, dan profesional untuk berbagai kebutuhan bisnis, pemerintahan, maupun pendidikan. Kami menyediakan perangkat video conference camera, speakerphone, microphone array, interactive display, hingga sistem integrasi ruang meeting skala kecil hingga besar. Didukung teknologi dari brand global seperti Logitech, Yealink, Poly, dan Zoom, sistem kami dirancang untuk mendukung kolaborasi hybrid yang efisien dan modern. Layanan kami meliputi konsultasi, desain sistem AV terintegrasi, instalasi, training, serta maintenance dan after sales support.</p>', 'Solusi video conference profesional untuk ruang meeting modern dengan kualitas audio visual terbaik.', 'services/audio-video-konferensi/featured/audio-video-konferensi-featured-thumbnail-vicon-activ-teknologi-2026-4426.webp', '2026-02-12 02:42:02', '2026-02-12 02:44:26', 1),
(2, 'AV Pro', 'av-pro', 'Solusi Audio Visual Profesional untuk auditorium, command center, ruang kontrol, dan kebutuhan skala enterprise.', 'services/av-pro/thumbnails/av-pro-thumbnails-audio-professional-activ-teknologi-2026-4526.webp', 'services/av-pro/icons/av-pro-icons-av-pro-activ-teknologi-2026-4526.webp', 'Teknologi Audio Visual Enterprise untuk Skala Profesional', 'Professional AV System', '<p>AV Pro merupakan solusi Audio Visual tingkat lanjut untuk kebutuhan profesional dan enterprise. Cocok untuk auditorium, ruang sidang, command center, ruang kontrol, hingga event skala besar. Kami menghadirkan sistem terintegrasi yang mencakup LED Video Wall, Interactive Panel, Professional Sound System, Digital Signal Processing (DSP), Wireless Presentation System, dan Control System Automation. Setiap proyek dirancang sesuai kebutuhan teknis untuk memastikan performa maksimal serta pengalaman visual dan audio terbaik.</p>', 'Solusi AV profesional untuk auditorium, ruang sidang, dan command center.', 'services/av-pro/featured/av-pro-featured-audio-professional-activ-teknologi-2026-4525.webp', '2026-02-12 02:42:02', '2026-02-12 02:45:26', 2),
(3, 'Platform Meeting', 'platform-meeting', 'Platform meeting online dan hybrid untuk kolaborasi tim yang fleksibel dan aman, mendukung berbagai perangkat dan integrasi.', 'services/platform-meeting/thumbnails/platform-meeting-thumbnails-platform-zoom-meeting-activ-teknologi-2026-4554.webp', 'services/platform-meeting/icons/platform-meeting-icons-platform-meeting-activ-teknologi-2026-4554.webp', 'Platform Kolaborasi Digital untuk Meeting Tanpa Batas', 'Meeting Platform', '<p>Platform Meeting menghadirkan solusi kolaborasi digital terintegrasi untuk kebutuhan enterprise yang menuntut skalabilitas, keamanan, dan keandalan tinggi. Dirancang untuk mendukung komunikasi jarak jauh, hybrid workforce, serta operasional multi-lokasi, solusi ini mencakup implementasi berbasis cloud, private cloud, maupun on-premise deployment sesuai standar kebijakan dan regulasi organisasi.ACTiV menyediakan implementasi dan integrasi platform terkemuka seperti Zoom, Microsoft Teams, dan Google Meet, serta solusi server lokal dan secure deployment menggunakan TrueConf dan Jitsi (Custom Deployment) untuk kebutuhan kontrol data dan keamanan tingkat lanjut.</p>', 'Solusi platform meeting online untuk kebutuhan kolaborasi modern dan hybrid.', 'services/platform-meeting/featured/platform-meeting-featured-platform-zoom-meeting-activ-teknologi-2026-4553.webp', '2026-02-12 02:42:02', '2026-02-12 02:45:54', 3),
(4, 'IOT & Room Automation', 'iot-room-automation', 'Solusi Internet of Things dan otomasi ruang untuk meningkatkan efisiensi, kenyamanan, dan kontrol terintegrasi.', NULL, NULL, 'Smart Control & Automation Solution', 'IOT & Automation', '<p>IOT &amp; Room Automation menghadirkan sistem otomatisasi pintar untuk ruang meeting, kantor, gedung, dan fasilitas publik. Solusi ini mencakup smart control system, sensor otomatis, lighting control, HVAC integration, serta integrasi perangkat AV dan meeting system. Dirancang untuk efisiensi energi, keamanan, dan kemudahan pengelolaan ruang secara terpusat.</p>', 'Solusi smart automation dan kontrol ruang terintegrasi.', 'services/iot-room-automation/featured/iot-room-automation-featured-product-acuseek-nvr-activ-teknologi-2026-5048.webp', '2026-02-13 00:51:02', '2026-02-20 03:50:48', 4),
(5, 'LED & Video Wall', 'led-video-wall', 'Solusi LED display dan video wall profesional untuk kebutuhan visual skala besar dan digital signage.', NULL, NULL, 'Professional Display & Video Wall', 'LED & Video Wall', '<p>LED &amp; Video Wall menyediakan solusi tampilan visual beresolusi tinggi untuk auditorium, command center, ruang kontrol, corporate lobby, dan event space. Kami menghadirkan instalasi LED indoor &amp; outdoor, video wall controller, dan integrasi sistem display untuk kebutuhan enterprise.</p>', 'Solusi display LED dan video wall profesional.', 'services/led-video-wall/featured/led-video-wall-featured-solution-detail-led-layout-detail-maxhub-activ-teknologi-2026-5104.webp', '2026-02-13 00:51:02', '2026-02-20 03:51:04', 5),
(6, 'Network Security', 'network-security', 'Solusi keamanan jaringan untuk melindungi infrastruktur IT dari ancaman siber.', NULL, NULL, 'Enterprise Network Protection', 'Network Security', '<p>Network Security menghadirkan sistem perlindungan jaringan enterprise termasuk firewall, intrusion prevention system, VPN, endpoint security, dan monitoring terpusat. Dirancang untuk menjaga integritas data, akses aman, dan perlindungan dari ancaman cyber.</p>', 'Solusi keamanan jaringan enterprise.', 'services/network-security/featured/network-security-featured-ruijie-unified-networking-activ-teknologi-2026-5121.webp', '2026-02-13 00:51:02', '2026-02-20 03:51:21', 6),
(7, 'Server & Storage', 'server-storage', 'Solusi server dan storage untuk mendukung operasional bisnis dan pengelolaan data skala enterprise.', NULL, NULL, 'Enterprise Server & Storage', 'Server & Storage', '<p>Server &amp; Storage menyediakan infrastruktur server, virtualisasi, dan sistem penyimpanan data yang andal dan scalable. Mendukung kebutuhan data center, backup system, disaster recovery, serta integrasi cloud dan hybrid infrastructure.</p>', 'Solusi server dan penyimpanan data enterprise.', 'services/server-storage/featured/server-storage-featured-server-storage-thumbnails-service-2-2-activ-teknologi-2026-0417-activ-teknologi-2026-5529.webp', '2026-02-13 00:51:02', '2026-02-20 03:55:29', 7),
(8, 'IT Infrastruktur', 'it-infrastruktur', 'Solusi infrastruktur IT terintegrasi untuk mendukung transformasi digital perusahaan.', NULL, NULL, 'Integrated IT Infrastructure', 'IT Infrastruktur', '<p>IT Infrastruktur mencakup desain dan implementasi jaringan, sistem komunikasi, rack server, structured cabling, serta integrasi perangkat IT dan AV. Dirancang untuk menciptakan fondasi teknologi yang stabil, aman, dan scalable.</p>', 'Solusi infrastruktur IT terintegrasi.', 'services/it-infrastruktur/featured/it-infrastruktur-featured-it-infrastruktur-featured-it-infrastruktur-activ-activ-teknologi-2026-3806-activ-teknologi-2026-5609.webp', '2026-02-13 00:51:02', '2026-02-20 03:56:09', 8),
(9, 'Periferal & Aksesoris', 'periferal-aksesoris', 'Penyediaan periferal dan aksesoris IT untuk mendukung produktivitas dan kolaborasi.', NULL, NULL, 'IT Peripheral Solution', 'Periferal & Aksesoris', '<p>Periferal &amp; Aksesoris mencakup webcam, headset, speakerphone, docking station, interactive device, dan perangkat pendukung lainnya untuk kebutuhan meeting dan workstation modern.</p>', 'Perangkat pendukung produktivitas dan kolaborasi.', 'services/periferal-aksesoris/featured/periferal-aksesoris-featured-periferal-aksesoris-featured-advanced-portfolio-hero-desktop-logitech-activ-teknologi-2026-2013-activ-teknologi-2026-5815.webp', '2026-02-13 00:51:02', '2026-02-20 03:58:15', 9),
(10, 'Call Center IPPBX', 'call-center-ippbx', 'Solusi sistem komunikasi Call Center dan IP PBX untuk operasional terpusat.', NULL, NULL, 'Call Center Communication System', 'Call Center IPPBX', '<p>Call Center IPPBX menyediakan sistem komunikasi berbasis IP untuk customer service, contact center, dan komunikasi internal perusahaan. Mendukung fitur IVR, call recording, monitoring, dan integrasi CRM.</p>', 'Solusi sistem komunikasi Call Center berbasis IP.', 'services/call-center-ippbx/featured/call-center-ippbx-featured-call-center-console-img-yeastar-ippbx-activ-teknologi-2026-5900.webp', '2026-02-13 00:51:02', '2026-02-20 03:59:00', 10),
(11, 'Software Developer', 'software-developer', 'Layanan pengembangan software dan aplikasi sesuai kebutuhan bisnis.', NULL, NULL, 'Custom Software Development', 'Software Developer', '<p>Software Developer menghadirkan solusi pengembangan aplikasi web, sistem internal, integrasi API, serta custom enterprise system. Dirancang untuk mendukung digitalisasi dan efisiensi proses bisnis.</p>', 'Solusi pengembangan software custom enterprise.', 'services/software-developer/featured/software-developer-featured-software-developer-activ-teknologi-2026-5924.webp', '2026-02-13 00:51:02', '2026-02-20 03:59:24', 11),
(12, 'Instalasi & Maintenance', 'instalasi-maintenance', 'Layanan instalasi, konfigurasi, dan maintenance sistem IT dan AV.', NULL, NULL, 'Installation & Maintenance Service', 'Instalasi & Maintenance', '<p>Instalasi &amp; Maintenance mencakup pemasangan perangkat, konfigurasi sistem, preventive maintenance, troubleshooting, serta dukungan teknis berkelanjutan untuk memastikan sistem berjalan optimal.</p>', 'Layanan instalasi dan dukungan teknis profesional.', 'services/instalasi-maintenance/featured/instalasi-maintenance-featured-instalasi-dan-maintenance-activ-teknologi-2026-5946.webp', '2026-02-13 00:51:02', '2026-02-20 03:59:46', 12);
