(1, 1, 'Huddle Room', 'huddle-room', 'Compact Collaboration Space', 'Solusi video conference untuk ruang meeting kecil 2-4 orang dengan kamera auto framing dan audio jernih untuk kolaborasi cepat dan efisien.', 'services/solutions/huddle-room/solutions-huddle-room-huddle-room-thumbnail-cisco-webex-activ-teknologi-2026-1729.webp', '[]', NULL, 0, 'Halo, saya ingin konsultasi solusi Huddle Room untuk perusahaan kami.', 'huddle-room', 1, '2026-02-12 02:52:02', '2026-02-12 03:17:29'),
(2, 1, 'Small Room', 'small-room', 'Efficient Small Meeting Room', 'Sistem AV terintegrasi untuk ruang meeting kecil dengan kualitas video HD dan audio noise cancellation.', 'services/solutions/small-room/solutions-small-room-small-room-thumbnail-cisco-webex-activ-teknologi-2026-1751.webp', '[]', NULL, 0, 'Halo, saya ingin solusi Small Meeting Room.', 'small-room', 2, '2026-02-12 02:52:02', '2026-02-12 03:17:51'),
(3, 1, 'Medium Room', 'medium-room', 'Hybrid Collaboration Room', 'Solusi video conference untuk ruang meeting 6-10 orang dengan sistem multi-mic dan kamera wide angle.', 'services/solutions/medium-room/solutions-medium-room-medium-room-thumbnail-cisco-webex-activ-teknologi-2026-1806.webp', '[]', NULL, 0, 'Halo, saya ingin konsultasi Medium Room.', 'medium-room', 3, '2026-02-12 02:52:02', '2026-02-12 03:18:06'),
(4, 1, 'Large Room', 'large-room', 'Enterprise Collaboration Space', 'Solusi AV untuk ruang meeting besar dengan multi-camera system dan DSP audio profesional.', 'services/solutions/large-room/solutions-large-room-large-room-thumbnail-cisco-webex-activ-teknologi-2026-1819.webp', '[]', NULL, 0, 'Halo, saya ingin solusi Large Meeting Room.', 'large-room', 4, '2026-02-12 02:52:02', '2026-02-12 03:18:19'),
(5, 1, 'Executive Boardroom', 'executive-boardroom', 'Premium Boardroom Experience', 'Sistem video conference premium untuk ruang direksi dengan tampilan profesional dan audio presisi tinggi.', 'services/solutions/executive-boardroom/solutions-executive-boardroom-executive-room-thumbnail-cisco-webex-activ-teknologi-2026-1829.webp', '[]', NULL, 0, 'Halo, saya ingin solusi Executive Boardroom.', 'executive-boardroom', 5, '2026-02-12 02:52:02', '2026-02-12 03:18:29'),
(6, 1, 'Contact Center', 'contact-center', 'Integrated Communication Hub', 'Solusi komunikasi terintegrasi untuk contact center dengan headset profesional dan sistem monitoring.', 'services/solutions/contact-center/solutions-contact-center-contact-center-room-thumbnail-cisco-webex-activ-teknologi-2026-1840.webp', '[]', NULL, 0, 'Halo, saya ingin solusi Contact Center.', 'contact-center', 6, '2026-02-12 02:52:02', '2026-02-12 03:18:40'),
(7, 1, 'Frontline Spaces', 'frontline-spaces', 'Operational Collaboration Space', 'Solusi komunikasi visual untuk area operasional dan frontline staff.', 'services/solutions/frontline-spaces/solutions-frontline-spaces-frontline-spaces-room-thumbnail-cisco-webex-activ-teknologi-2026-1857.webp', '[]', NULL, 0, 'Halo, saya ingin solusi Frontline Spaces.', 'frontline-spaces', 7, '2026-02-12 02:52:02', '2026-02-12 03:18:57'),
